insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('mt',12,5,'crampon1923','Ou n''avez-vous pas lu dans la Loi que, le jour du sabbat, les prêtres violent le sabbat dans le temple sans commettre de péché?'),
('mt',12,6,'crampon1923','Or, je vous dis qu''il y a ici quelqu''un plus grand que le temple.'),
('mt',12,7,'crampon1923','Si vous compreniez cette parole: " Je veux la miséricorde, et non le sacrifice ", vous n''auriez jamais condamné des innocents.'),
('mt',12,8,'crampon1923','Car le Fils de l''homme est maître même du sabbat. "'),
('mt',12,9,'crampon1923','Jésus, ayant quitté ce lieu, entra dans leur synagogue.'),
('mt',12,10,'crampon1923','Or, il se trouvait là un homme qui avait la main desséchée, et ils demandèrent à Jésus: " Est-il permis de guérir, le jour du sabbat? " C''était pour avoir un prétexte de l''accuser.'),
('mt',12,11,'crampon1923','Il leur répondit: " Quel est celui d''entre vous qui, n''ayant qu''une brebis, si elle tombe dans une fosse un jour de sabbat, ne la prend et ne l''en retire?'),
('mt',12,12,'crampon1923','Or, combien un homme ne vaut-il pas plus qu''une brebis? Il est donc permis de faire du bien les jours de sabbat. "'),
('mt',12,13,'crampon1923','Alors il dit à cet homme: " Étends ta main. " Il l''étendit, et elle redevint saine comme l''autre.'),
('mt',12,14,'crampon1923','Les Pharisiens, étant sortis, tinrent conseil contre lui sur les moyens de le perdre.'),
('mt',12,15,'crampon1923','Mais Jésus, en ayant eu connaissance, s''éloigna de ces lieux. Une grande foule le suivit, et il guérit tous leurs malades.'),
('mt',12,16,'crampon1923','Et il leur commanda de ne pas le faire connaître:'),
('mt',12,17,'crampon1923','afin que s''accomplît la parole du prophète Isaïe:'),
('mt',12,18,'crampon1923','" Voici mon serviteur que j''ai choisi, mon bien-aimé, en qui j''ai mis toute mon affection. Je ferai reposer sur lui mon Esprit, et il annoncera la justice aux nations.'),
('mt',12,19,'crampon1923','Il ne disputera point, il ne criera point, et on n''entendra pas sa voix dans les places publiques.'),
('mt',12,20,'crampon1923','Il ne brisera point le roseau froissé et n''éteindra point la mèche qui fume encore, jusqu''à ce qu''il ait fait triompher la justice.'),
('mt',12,21,'crampon1923','En son nom, les nations mettront leur espérance. "'),
('mt',12,22,'crampon1923','On lui présenta alors un possédé aveugle et muet, et il le guérit, de sorte que cet homme parlait et voyait.'),
('mt',12,23,'crampon1923','Et tout le peuple, saisi d''étonnement, disait: " N''est-ce point là le fils de David? "'),
('mt',12,24,'crampon1923','Mais les Pharisiens, entendant cela, dirent: " Il ne chasse les démons que par Béelzébub, prince des démons. "'),
('mt',12,25,'crampon1923','Jésus, qui connaissait leurs pensées, leur dit: " Tout royaume divisé contre lui-même sera désolé, et toute ville ou maison divisée contre elle-même ne pourra subsister.'),
('mt',12,26,'crampon1923','Si Satan chasse Satan, il est divisé contre lui-même: comment donc son royaume subsistera-t-il?'),
('mt',12,27,'crampon1923','Et si moi je chasse les démons par Béelzébub, par qui vos fils les chassent-ils? C''est pourquoi ils seront eux-mêmes vos juges.'),
('mt',12,28,'crampon1923','Que si c''est par l''Esprit de Dieu que je chasse les démons, le royaume de Dieu est donc venu à vous.'),
('mt',12,29,'crampon1923','Et comment peut-on entrer dans la maison de l''homme fort et piller ses meubles, sans avoir auparavant lié cet homme fort? Alors seulement on pillera sa maison.'),
('mt',12,30,'crampon1923','Qui n''est pas avec moi est contre moi, et qui n''amasse pas avec moi disperse.'),
('mt',12,31,'crampon1923','" C''est pourquoi je vous dis: Tout péché et tout blasphème sera remis aux hommes; mais le blasphème contre l''Esprit ne leur sera pas remis.'),
('mt',12,32,'crampon1923','Et quiconque aura parlé contre le Fils de l''homme, on le lui remettra; mais à celui qui aura parlé contre l''Esprit-Saint, on ne le lui remettra ni dans ce siècle, ni dans le siècle à venir.'),
('mt',12,33,'crampon1923','Ou dites que l''arbre est bon, et son fruit bon; ou dites que l''arbre est mauvais, et son fruit mauvais: car c''est par son fruit qu''on connaît l''arbre.'),
('mt',12,34,'crampon1923','Race de vipères, comment pourriez-vous dire des choses bonnes, méchants comme vous l''êtes? Car la bouche parle de l''abondance du cœur.'),
('mt',12,35,'crampon1923','L''homme bon tire du bon trésor de son cœur des choses bonnes, et l''homme mauvais, d''un mauvais trésor, tire des choses mauvaises.'),
('mt',12,36,'crampon1923','Je vous le dis: au jour du jugement, les hommes rendront compte de toute parole vaine qu''ils auront dite.'),
('mt',12,37,'crampon1923','Car tu seras justifié par tes paroles, et tu seras condamné par tes paroles "'),
('mt',12,38,'crampon1923','Alors quelques-uns des Scribes et des Pharisiens prirent la parole et dirent: " Maître, nous voudrions voir un signe de vous. "'),
('mt',12,39,'crampon1923','Il leur répondit: " Cette race méchante et adultère demande un signe, et il ne lui sera pas donné d''autre signe que celui du prophète Jonas:'),
('mt',12,40,'crampon1923','de même que Jonas fut trois jours et trois nuits dans le ventre du poisson, ainsi le Fils de l''homme sera dans le sein de la terre trois jours et trois nuits.'),
('mt',12,41,'crampon1923','Les hommes de Ninive se dresseront, au jour du jugement, avec cette génération et la condamneront, parce qu''ils ont fait pénitence à la voix de Jonas, et il y a ici plus que Jonas.'),
('mt',12,42,'crampon1923','La reine du Midi s''élèvera, au jour du jugement, avec cette génération et la condamnera, parce qu''elle est venue des extrémités de la terre pour entendre la sagesse de Salomon, et il y a ici plus que Salomon.'),
('mt',12,43,'crampon1923','" Lorsque l''esprit impur est sorti d''un homme, il va par des lieux arides, cherchant du repos, et il n''en trouve point.'),
('mt',12,44,'crampon1923','Alors il dit: Je retournerai dans ma maison, d''où je suis sorti. Et revenant, il la trouve vide, nettoyée et ornée.'),
('mt',12,45,'crampon1923','Alors il s''en va prendre sept autres esprits plus méchants que lui, et, entrant dans cette maison, ils y fixent leur demeure, et le dernier état de cet homme est pire que le premier. Ainsi en sera-t-il de cette génération méchante. "'),
('mt',12,46,'crampon1923','Comme il parlait encore au peuple, sa mère et ses frères étaient dehors, cherchant à lui parler.'),
('mt',12,47,'crampon1923','Quelqu''un lui dit: " Voici votre mère et vos frères qui sont là dehors, et ils cherchent à vous parler. "'),
('mt',12,48,'crampon1923','Jésus répondit à l''homme qui lui disait cela: " Qui est ma mère et qui sont mes frères? "'),
('mt',12,49,'crampon1923','Et étendant la main vers ses disciples, il dit: " Voici ma mère et mes frères.'),
('mt',12,50,'crampon1923','Car quiconque fait la volonté de mon Père qui est dans les cieux, celui-là est mon frère, et ma sœur, et ma mère. "'),
('mt',13,1,'crampon1923','Ce jour-là, Jésus sortit de la maison et s''assit au bord de la mer.'),
('mt',13,2,'crampon1923','Une grande foule s''étant assemblée autour de lui, il dut monter dans une barque, où il s''assit, tandis que la foule se tenait sur le rivage;'),
('mt',13,3,'crampon1923','et il leur dit beaucoup de choses en paraboles: — le semeur, dit-il, sortit pour semer.'),
('mt',13,4,'crampon1923','Et pendant qu''il semait, des grains tombèrent le long du chemin, et les oiseaux du ciel vinrent et les mangèrent.'),
('mt',13,5,'crampon1923','D''autres grains tombèrent sur un sol pierreux, où ils n''avaient pas beaucoup de terre, et ils levèrent aussitôt, parce que la terre était peu profonde.'),
('mt',13,6,'crampon1923','Mais le soleil s''étant levé, la plante, frappée de ses feux et n''ayant pas de racine, sécha.'),
('mt',13,7,'crampon1923','D''autres tombèrent parmi les épines, et les épines crûrent et les étouffèrent.'),
('mt',13,8,'crampon1923','D''autres tombèrent dans la bonne terre, et ils produisirent du fruit, l''un cent, un autre soixante, et un autre trente.'),
('mt',13,9,'crampon1923','Que celui qui a des oreilles entende! "'),
('mt',13,10,'crampon1923','Alors ses disciples s''approchant lui dirent: " Pourquoi leur parlez-vous en paraboles? "'),
('mt',13,11,'crampon1923','Il leur répondit: " A vous, il a été donné de connaître les mystères du royaume des cieux; mais à eux, cela n''a pas été donné.'),
('mt',13,12,'crampon1923','Car on donnera à celui qui a, et il sera dans l''abondance; mais à celui qui n''a pas, on ôtera même ce qu''il a.'),
('mt',13,13,'crampon1923','C''est pourquoi je leur parle en paraboles, parce qu''en voyant, ils ne voient pas, et qu''en entendant, ils n''entendent ni ne comprennent.'),
('mt',13,14,'crampon1923','Pour eux s''accomplit la prophétie d''Isaïe: " Vous entendrez de vos oreilles et vous ne comprendrez point; vous verrez de vos yeux, et vous ne verrez point.'),
('mt',13,15,'crampon1923','Car le cœur de ce peuple s''est appesanti; ils ont endurci leurs oreilles et fermé leurs yeux: de peur que leurs yeux ne voient, que leurs oreilles n''entendent, que leur cœur ne comprenne, qu''ils ne se convertissent et que je ne les guérisse. "'),
('mt',13,16,'crampon1923','Pour vous, heureux vos yeux parce qu''ils voient, et vos oreilles parce qu''elles entendent!'),
('mt',13,17,'crampon1923','Je vous le dis en vérité, beaucoup de prophètes et de justes ont désiré voir ce que vous voyez, et ne l''ont pas vu; entendre ce que vous entendez, et ne l''ont pas entendu.'),
('mt',13,18,'crampon1923','Vous donc, écoutez ce que signifie la parabole du semeur:'),
('mt',13,19,'crampon1923','" Quiconque entend la parole du royaume et ne la comprend pas, le Malin vient, et il enlève ce qui a été semé dans son cœur: c''est le chemin qui a reçu la semence.'),
('mt',13,20,'crampon1923','Le terrain pierreux où elle est tombée, c''est celui qui entend la parole et la reçoit aussitôt avec joie:'),
('mt',13,21,'crampon1923','mais il n''y a pas en lui de racines; il est inconstant; dès que survient la tribulation ou la persécution à cause de la parole, aussitôt il succombe.'),
('mt',13,22,'crampon1923','Les épines qui ont reçu la semence, c''est celui qui entend la parole; mais les sollicitudes de ce siècle et la séduction des richesses étouffent la parole, et elle ne porte point de fruit.'),
('mt',13,23,'crampon1923','La bonne terre ensemencée, c''est celui qui entend la parole et la comprend; il porte du fruit, et donne l''un cent, un autre soixante, un autre trente pour un. "'),
('mt',13,24,'crampon1923','Il leur proposa une autre parabole, en disant: " Le royaume des cieux est semblable à un homme qui avait semé de bon grain dans son champ.'),
('mt',13,25,'crampon1923','Mais, pendant que les hommes dormaient, son ennemi vint et sema de l''ivraie au milieu du froment, et s''en alla.'),
('mt',13,26,'crampon1923','Quand l''herbe eut poussé et donné son fruit, alors apparut aussi l''ivraie.'),
('mt',13,27,'crampon1923','Et les serviteurs du père de famille vinrent lui dire: Seigneur, n''avez-vous pas semé de bon grain dans votre champ? D''où vient donc qu''il s''y trouve de l''ivraie?'),
('mt',13,28,'crampon1923','Il leur répondit: C''est un ennemi qui a fait cela. Les serviteurs lui dirent: Voulez-vous que nous allions la cueillir?'),
('mt',13,29,'crampon1923','Non, leur dit-il, de peur qu''avec l''ivraie vous n''arrachiez aussi le froment.'),
('mt',13,30,'crampon1923','Laissez croître l''un et l''autre jusqu''à la moisson, et au temps de la moisson je dirai aux moissonneurs: Cueillez d''abord l''ivraie, et liez-la en gerbes pour la brûler, et amassez le froment dans mon grenier. "'),
('mt',13,31,'crampon1923','Il leur proposa une autre parabole, en disant: " Le royaume des cieux est semblable à un grain de sénevé, qu''un homme a pris et semé dans son champ.'),
('mt',13,32,'crampon1923','C''est la plus petite de toutes les semences; mais, lorsqu''il a poussé, il est plus grand que toutes les plantes potagères, et devient un arbre, de sorte que les oiseaux du ciel viennent s''abriter dans ses rameaux. "'),
('mt',13,33,'crampon1923','Il leur dit encore cette parabole: " Le royaume des cieux est semblable au levain qu''une femme prend et mêle dans trois mesures de farine, pour faire lever toute la pâte. "'),
('mt',13,34,'crampon1923','Jésus dit à la foule toutes ces choses en paraboles, et il ne lui parlait qu''en paraboles,'),
('mt',13,35,'crampon1923','accomplissant ainsi la parole du prophète: " J''ouvrirai ma bouche en paraboles, et je révélerai des choses cachées depuis la création du monde. "'),
('mt',13,36,'crampon1923','Puis, ayant renvoyé le peuple, il revint dans la maison; ses disciples s''approchèrent et lui dirent: " Expliquez-nous la parabole de l''ivraie dans le champ. "'),
('mt',13,37,'crampon1923','Il répondit: " Celui qui sème le bon grain, c''est le Fils de l''homme;'),
('mt',13,38,'crampon1923','le champ, c''est le monde; le bon grain, ce sont les fils du royaume; l''ivraie, les fils du Malin;'),
('mt',13,39,'crampon1923','l''ennemi qui l''a semé, c''est le diable; la moisson, la fin du monde; les moissonneurs, ce sont les anges.'),
('mt',13,40,'crampon1923','Comme on cueille l''ivraie et qu''on la brûle dans le feu, ainsi en sera-t-il à la fin du monde.'),
('mt',13,41,'crampon1923','Le Fils de Dieu enverra ses anges, et ils enlèveront de son royaume tous les scandales, et ceux qui commettent l''iniquité,'),
('mt',13,42,'crampon1923','et ils les jetteront dans la fournaise ardente: c''est là qu''il y aura des pleurs et des grincements de dents.'),
('mt',13,43,'crampon1923','Alors les justes resplendiront comme le soleil dans le royaume de leur Père. Que celui qui a des oreilles entende!'),
('mt',13,44,'crampon1923','" Le royaume des cieux est encore semblable à un trésor enfoui dans un champ; l''homme qui l''a trouvé l''y cache de nouveau, et, dans sa joie, il s''en va, vend tout ce qu''il a, et achète ce champ.'),
('mt',13,45,'crampon1923','" le royaume des cieux est encore semblable à un marchand qui cherchait de belles perles.'),
('mt',13,46,'crampon1923','Ayant trouvé une perle de grand prix, il s''en alla vendre tout ce qu''il avait, et l''acheta.'),
('mt',13,47,'crampon1923','" le royaume des cieux est encore semblable à un filet qu''on a jeté dans la mer et qui ramasse des poissons de toutes sortes.'),
('mt',13,48,'crampon1923','Lorsqu''il est plein, les pêcheurs le retirent, et, s''asseyant sur le rivage, ils choisissent les bons pour les mettre dans des vases, et jettent les mauvais.'),
('mt',13,49,'crampon1923','Il en sera de même à la fin du monde: les anges viendront et sépareront les méchants d''avec les justes,'),
('mt',13,50,'crampon1923','et ils les jetteront dans la fournaise ardente: c''est là qu''il y aura des pleurs et des grincements de dents.'),
('mt',13,51,'crampon1923','" Avez-vous compris toutes ces choses? " Ils lui dirent: " Oui, Seigneur. "'),
('mt',13,52,'crampon1923','Et il ajouta: " C''est pourquoi tout Scribe versé dans ce qui regarde le royaume des cieux, ressemble à un père de famille qui tire de son trésor des choses nouvelles et des choses anciennes. "'),
('mt',13,53,'crampon1923','Après que Jésus eut achevé ces paraboles, il partit de là.'),
('mt',13,54,'crampon1923','Etant venu dans sa patrie, il enseignait dans la synagogue; de sorte que, saisis d''étonnement, ils disaient: " D''où viennent à celui-ci cette sagesse et ces miracles?'),
('mt',13,55,'crampon1923','N''est-ce pas le fils du charpentier? Sa mère ne s''appelle-t-elle pas Marie, et ses frères Jacques, Joseph, Simon et Jude?'),
('mt',13,56,'crampon1923','Et ses sœurs ne sont-elles pas toutes parmi nous? D''où lui viennent donc toutes ces choses? "'),
('mt',13,57,'crampon1923','Et il était pour eux une pierre d''achoppement. Mais Jésus leur dit: " Un prophète n''est sans honneur que dans sa patrie et dans sa maison. "'),
('mt',13,58,'crampon1923','Et il ne fit pas beaucoup de miracles dans ce lieu, à cause de leur incrédulité.'),
('mt',14,1,'crampon1923','En ce temps-là, Hérode le Tétrarque apprit ce qui se publiait de Jésus.'),
('mt',14,2,'crampon1923','Et il dit à ses serviteurs: " C''est Jean-Baptiste! Il est ressuscité des morts: voilà pourquoi des miracles s''opèrent par lui. "'),
('mt',14,3,'crampon1923','Car Hérode ayant fait arrêter Jean, l''avait chargé de chaînes et jeté en prison, à cause d''Hérodiade, femme de son frère Philippe,'),
('mt',14,4,'crampon1923','parce que Jean lui disait: " Il ne t''est pas permis de l''avoir pour femme. "'),
('mt',14,5,'crampon1923','Volontiers il l''eût fait mourir, mais il craignait le peuple, qui regardait Jean comme un prophète.'),
('mt',14,6,'crampon1923','Or, comme on célébrait le jour de naissance d''Hérode, la fille d''Hérodiade dansa devant les convives et plut à Hérode,'),
('mt',14,7,'crampon1923','de sorte qu''il promit avec serment de lui donner tout ce qu''elle demanderait.'),
('mt',14,8,'crampon1923','Elle, instruite d''abord par sa mère: " Donne-moi, dit-elle, ici sur un plateau, la tête de Jean-Baptiste. "'),
('mt',14,9,'crampon1923','Le roi fut contristé; mais à cause de son serment et de ses convives, il commanda qu''on la lui donnât,'),
('mt',14,10,'crampon1923','et il envoya décapiter Jean dans sa prison.'),
('mt',14,11,'crampon1923','Et la tête, apportée sur un plateau, fut donnée à la jeune fille, qui la porta à sa mère.'),
('mt',14,12,'crampon1923','Les disciples de Jean vinrent prendre le corps et lui donnèrent la sépulture; puis ils allèrent en informer Jésus.'),
('mt',14,13,'crampon1923','Jésus l''ayant appris, partit de là dans une barque et se retira à l''écart, dans un lieu solitaire; mais le peuple le sut, et le suivit à pied des villes voisines.'),
('mt',14,14,'crampon1923','Quand il débarqua, il vit une grande foule, et il en eut compassion, et il guérit leurs malades.'),
('mt',14,15,'crampon1923','Sur le soir, ses disciples s''approchèrent de lui en disant: " Ce lieu est désert, et déjà l''heure est avancée; renvoyez cette foule, afin qu''ils aillent dans les villages s''acheter des vivres. "'),
('mt',14,16,'crampon1923','Mais Jésus leur dit: " Ils n''ont pas besoin de s''en aller; donnez-leur vous-mêmes à manger. "'),
('mt',14,17,'crampon1923','Ils lui répondirent: " Nous n''avons ici que cinq pains et deux poissons. "'),
('mt',14,18,'crampon1923','" Apportez-les-moi ici, " leur dit-il.'),
('mt',14,19,'crampon1923','Après avoir fait asseoir cette multitude sur l''herbe, il prit les cinq pains et les deux poissons, et levant les yeux au ciel, il prononça une bénédiction; puis, rompant les pains, il les donna a ses disciples, et les disciples les donnèrent au peuple.'),
('mt',14,20,'crampon1923','Tous mangèrent et furent rassasiés, et l''on emporta douze corbeilles pleines des morceaux qui restaient.'),
('mt',14,21,'crampon1923','Or, le nombre de ceux qui avaient mangé était environ de cinq mille hommes, sans les femmes et les enfants.'),
('mt',14,22,'crampon1923','Aussitôt après, Jésus obligea ses disciples à monter dans la barque et à passer avant lui sur le bord opposé du lac, pendant qu''il renverrait la foule.'),
('mt',14,23,'crampon1923','Quand il l''eut renvoyée, il monta sur la montagne pour prier à l''écart; et, le soir étant venu, il était là seul.'),
('mt',14,24,'crampon1923','Cependant la barque, déjà au milieu de la mer, était battue par les flots, car le vent était contraire.'),
('mt',14,25,'crampon1923','A la quatrième veille de la nuit, Jésus alla vers ses disciples, en marchant sur la mer.'),
('mt',14,26,'crampon1923','Eux, le voyant marcher sur la mer, furent troublés, et dirent: " C''est un fantôme, " et ils poussèrent des cris de frayeur.'),
('mt',14,27,'crampon1923','Jésus leur parla aussitôt: " Ayez confiance, dit-il, c''est moi, ne craignez point. "'),
('mt',14,28,'crampon1923','Pierre prenant la parole: " Seigneur, dit-il, si c''est vous, ordonnez que j''aille à vous sur les eaux. "'),
('mt',14,29,'crampon1923','Il lui dit: " Viens; " et Pierre étant sorti de la barque marchait sur les eaux pour aller à Jésus.'),
('mt',14,30,'crampon1923','Mais voyant la violence du vent, il eut peur, et comme il commençait à enfoncer, il cria: " Seigneur, sauvez-moi! "'),
('mt',14,31,'crampon1923','Aussitôt Jésus étendant la main le saisit et lui dit: " Homme de peu de foi, pourquoi as-tu douté? "'),
('mt',14,32,'crampon1923','Et lorsqu''ils furent montés dans la barque, le vent s''apaisa.'),
('mt',14,33,'crampon1923','Alors ceux qui étaient dans la barque, vinrent se prosterner devant lui en disant: " Vous êtes vraiment le Fils de Dieu. "'),
('mt',14,34,'crampon1923','Ayant traversé le lac, ils abordèrent à la terre de Génésareth.'),
('mt',14,35,'crampon1923','Les gens de l''endroit, l''ayant reconnu, envoyèrent des messagers dans tous les environs, et on lui amena tous les malades.'),
('mt',14,36,'crampon1923','Et ils le priaient de leur laisser seulement toucher la houppe de son manteau, et tous ceux qui la touchèrent furent guéris.'),
('mt',15,1,'crampon1923','Alors des Scribes et des Pharisiens venus de Jérusalem s''approchèrent de Jésus, et lui dirent:'),
('mt',15,2,'crampon1923','" Pourquoi vos disciples transgressent-ils la tradition des anciens? Car ils ne se lavent pas les mains lorsqu''ils prennent leur repas. "'),
('mt',15,3,'crampon1923','Il leur répondit: " Et vous, pourquoi transgressez-vous le commandement de Dieu par votre tradition?'),
('mt',15,4,'crampon1923','Car Dieu a dit: Honore ton père et ta mère; et: Quiconque maudira son père ou sa mère, qu''il soit puni de mort.'),
('mt',15,5,'crampon1923','Mais vous, vous dites: Quiconque dit à son père ou à sa mère: Ce dont j''aurais pu vous assister, j''en ait fait offrande, —'),
('mt',15,6,'crampon1923','n''a pas besoin d''honorer autrement son père ou sa mère. Et vous mettez ainsi à néant le commandement de Dieu par votre tradition.'),
('mt',15,7,'crampon1923','Hypocrites, Isaïe a bien prophétisé de vous quand il a dit:'),
('mt',15,8,'crampon1923','Ce peuple m''honore des lèvres, mais son cœur est loin de moi.'),
('mt',15,9,'crampon1923','C''est en vain qu''ils m''honorent, en donnant des préceptes qui ne sont que des commandements venant des hommes. "'),
('mt',15,10,'crampon1923','Puis, ayant fait approcher la foule, il leur dit: " Écoutez et comprenez.'),
('mt',15,11,'crampon1923','Ce n''est pas ce qui entre dans la bouche qui souille l''homme; mais ce qui sort de la bouche, voilà ce qui souille l''homme. "'),
('mt',15,12,'crampon1923','Alors ses disciples venant à lui, lui dirent: " Savez-vous que les Pharisiens, en entendant cette parole, se sont scandalisés? "'),
('mt',15,13,'crampon1923','Il répondit: " Toute plante que n''a pas plantée mon Père céleste, sera arrachée.'),
('mt',15,14,'crampon1923','Laissez-les; ce sont des aveugles qui conduisent des aveugles. Or, si un aveugle conduit un aveugle, ils tomberont tous deux dans la fosse. "'),
('mt',15,15,'crampon1923','Pierre, prenant la parole, lui dit: " Expliquez-nous cette parabole. "'),
('mt',15,16,'crampon1923','Jésus répondit: " Êtes-vous encore, vous aussi, sans intelligence?'),
('mt',15,17,'crampon1923','Ne comprenez-vous pas que tout ce qui entre dans la bouche va au ventre, et est rejeté au lieu secret?'),
('mt',15,18,'crampon1923','Mais ce qui sort de la bouche vient du cœur, et c''est là ce qui souille l''homme.'),
('mt',15,19,'crampon1923','Car c''est du cœur que viennent les mauvaises pensées, les meurtres, les adultères, les impudicités, les vols, les faux témoignages, les paroles injurieuses.'),
('mt',15,20,'crampon1923','Voilà ce qui souille l''homme; mais manger sans s''être lavé les mains, cela ne souille point l''homme. "'),
('mt',15,21,'crampon1923','Jésus étant parti de là, se retira du côté de Tyr et de Sidon.'),
('mt',15,22,'crampon1923','Et voilà qu''une femme cananéenne, de ce pays-là, sortit en criant à haute voix: " Ayez pitié de moi, Seigneur, fils de David; ma fille est cruellement tourmentée par le démon. "'),
('mt',15,23,'crampon1923','Jésus ne lui répondit pas un mot. Alors ses disciples, s''étant approchés, le prièrent en disant: " Renvoyez-la, car elle nous poursuit de ses cris. "'),
('mt',15,24,'crampon1923','Il répondit: " Je n''ai été envoyé qu''aux brebis perdues de la maison d''Israël. "'),
('mt',15,25,'crampon1923','Mais cette femme vint se prosterner devant lui, en disant: " Seigneur, secourez-moi. "'),
('mt',15,26,'crampon1923','Il répondit: " Il n''est pas bien de prendre le pain des enfants pour le jeter aux petits chiens. "'),
('mt',15,27,'crampon1923','" Il est vrai, Seigneur, dit-elle; mais les petits chiens mangent au moins les miettes qui tombent de la table de leur maître. "'),
('mt',15,28,'crampon1923','Alors Jésus lui dit: " O femme, votre foi est grande: qu''il vous soit fait selon votre désir. " Et sa fille fut guérie à l''heure même.'),
('mt',15,29,'crampon1923','Jésus quitta ces lieux et vint près de la mer de Galilée. Étant monté sur la montagne, il s''y assit.'),
('mt',15,30,'crampon1923','Et de grandes troupes de gens s''approchèrent de lui, ayant avec eux des boiteux, des aveugles, des sourds-muets, des estropiés et beaucoup d''autres malades. Ils les mirent à ses pieds, et il les guérit;'),
('mt',15,31,'crampon1923','de sorte que la multitude était dans l''admiration, en voyant les muets parler, les estropiés guéris, les boiteux marcher, les aveugles voir, et elle glorifiait le Dieu d''Israël.'),
('mt',15,32,'crampon1923','Cependant Jésus, ayant appelé ses disciples, leur dit: " J''ai compassion de cette foule; car voilà déjà trois jours qu''ils restent près de moi, et ils n''ont rien à manger. Je ne veux pas les renvoyer à jeun, de peur que les forces ne leur manquent en chemin. "'),
('mt',15,33,'crampon1923','Les disciples lui dirent: " Où trouver dans un désert assez de pains pour rassasier une si grande foule? "'),
('mt',15,34,'crampon1923','Jésus leur demanda: " Combien avez-vous de pains? " " Sept, lui dirent-ils, et quelques petits poissons. "'),
('mt',15,35,'crampon1923','Alors il fit asseoir la foule par terre,'),
('mt',15,36,'crampon1923','prit les sept pains et les poissons, et, ayant rendu grâces, il les rompit et les donna à ses disciples, et ceux-ci au peuple.'),
('mt',15,37,'crampon1923','Tous mangèrent et furent rassasiés, et des morceaux qui restaient, on emporta sept corbeilles pleines.'),
('mt',15,38,'crampon1923','Or le nombre de ceux qui avaient mangé s''élevait à quatre mille, sans compter les femmes et les enfants.'),
('mt',15,39,'crampon1923','Après avoir renvoyé le peuple, Jésus monta dans la barque et vint dans le pays de Magédan.'),
('mt',16,1,'crampon1923','Les Pharisiens et les Sadducéens abordèrent Jésus, et, pour le tenter, ils lui demandèrent de leur faire voir un signe venant du ciel.'),
('mt',16,2,'crampon1923','Il leur répondit: " Le soir vous dites: Il fera beau, car le ciel est rouge;'),
('mt',16,3,'crampon1923','et le matin: Il y aura aujourd''hui de l''orage, car le ciel est d''un rouge sombre.'),
('mt',16,4,'crampon1923','Hypocrites, vous savez donc discerner les aspects du ciel, et vous ne savez pas reconnaître les signes des temps! Une race méchante et adultère demande un signe, et il ne lui sera pas donné d''autre signe que celui du prophète Jonas. " Et les laissant, il s''en alla.'),
('mt',16,5,'crampon1923','En passant de l''autre côté du lac, ses disciples avaient oublié de prendre des pains.'),
('mt',16,6,'crampon1923','Jésus leur dit: " Gardez-vous avec soin du levain des Pharisiens et des Sadducéens. "'),
('mt',16,7,'crampon1923','Et ils pensaient et disaient en eux-mêmes: " C''est parce que nous n''avons pas pris de pains. "'),
('mt',16,8,'crampon1923','Mais Jésus, qui voyait leur pensée, leur dit: " Hommes de peu de foi, pourquoi vous entretenez-vous en vous-mêmes de ce que vous n''avez pas pris de pains?'),
('mt',16,9,'crampon1923','Êtes-vous encore sans intelligence, et ne vous rappelez-vous pas les cinq pains distribués à cinq mille hommes, et combien de paniers vous avez emportés?'),
('mt',16,10,'crampon1923','Ni les sept pains distribués à quatre mille hommes, et combien de corbeilles vous avez emportées?'),
('mt',16,11,'crampon1923','Comment ne comprenez-vous pas que je ne parlais pas de pains quand je vous ai dit: Gardez-vous du levain des Pharisiens et des Sadducéens? "'),
('mt',16,12,'crampon1923','Alors ils comprirent qu''il avait dit de se garder, non du levain qu''on met dans le pain, mais de la doctrine des Pharisiens et des Sadducéens.'),
('mt',16,13,'crampon1923','Jésus étant venu dans le territoire de Césarée de Philippe, demanda à ses disciples: " Qui dit-on qu''est le Fils de l''homme? "'),
('mt',16,14,'crampon1923','Ils lui répondirent: " Les uns disent que vous êtes Jean-Baptiste, d''autres Élie, d''autres Jérémie ou quelqu''un des prophètes. —'),
('mt',16,15,'crampon1923','Et vous, leur dit-il, qui dites-vous que je suis? "'),
('mt',16,16,'crampon1923','Simon Pierre, prenant la parole, dit: " Vous êtes le Christ, le Fils du Dieu vivant. "'),
('mt',16,17,'crampon1923','Jésus lui répondit: " Tu es heureux, Simon, fils de Jean, car ce n''est pas la chair et le sang qui te l''ont révélé, mais c''est mon Père qui est dans les cieux.'),
('mt',16,18,'crampon1923','Et moi je te dis que tu es Pierre, et sur cette pierre je bâtirai mon Eglise, et les portes de l''enfer ne prévaudront point contre elle.'),
('mt',16,19,'crampon1923','Et je te donnerai les clefs du royaume des cieux: et tout ce que tu lieras sur la terre sera lié dans les cieux, et tout ce que tu délieras sur la terre sera délié dans les cieux. "'),
('mt',16,20,'crampon1923','Alors il défendit à ses disciples de dire à personne qu''il était le Christ.'),
('mt',16,21,'crampon1923','Jésus commença dès lors à découvrir à ses disciples qu''il fallait qu''il allât à Jérusalem, qu''il souffrît beaucoup de la part des Anciens, des Scribes et des Princes des prêtres, qu''il fût mis à mort et qu''il ressuscitât le troisième jour.'),
('mt',16,22,'crampon1923','Pierre, le prenant à part, se mit à le reprendre, en disant: " A Dieu ne plaise, Seigneur! Cela ne vous arrivera pas. "'),
('mt',16,23,'crampon1923','Mais Jésus, se retournant, dit à Pierre: " Retire-toi de moi, Satan, tu m''es un scandale; car tu n''as pas l''intelligence des choses de Dieu; tu n''as que des pensées humaines. "'),
('mt',16,24,'crampon1923','Alors Jésus dit à ses disciples: " Si quelqu''un veut venir à ma suite, qu''il renonce à soi-même, qu''il prenne sa croix et me suive.'),
('mt',16,25,'crampon1923','Car celui qui voudra sauver sa vie, la perdra; et celui qui perdra sa vie à cause de moi, la trouvera.'),
('mt',16,26,'crampon1923','Et que sert à un homme de gagner le monde entier, s''il vient à perdre son âme? Ou que donnera un homme en échange de son âme?'),
('mt',16,27,'crampon1923','Car le Fils de l''homme doit venir dans la gloire de son Père avec ses anges, et alors il rendra à chacun selon ses œuvres.'),
('mt',16,28,'crampon1923','Je vous le dis en vérité, plusieurs de ceux qui sont ici présents ne goûteront point la mort, qu''ils n''aient vu le Fils de l''homme venant dans son règne. "'),
('mt',17,1,'crampon1923','Six jours après, Jésus prit avec lui Pierre, Jacques et Jean son frère, et les conduisit à l''écart sur une haute montagne.'),
('mt',17,2,'crampon1923','Et il fut transfiguré devant eux: son visage resplendit comme le soleil, et ses vêtements devinrent blancs comme la lumière.'),
('mt',17,3,'crampon1923','Et voilà que Moïse et Elie leur apparurent conversant avec lui.'),
('mt',17,4,'crampon1923','Prenant la parole, Pierre dit à Jésus: " Seigneur, il nous est bon d''être ici; si vous le voulez, faisons-y trois tentes, une pour vous, une pour Moïse et une pour Elie. "'),
('mt',17,5,'crampon1923','Il parlait encore, lorsqu''une nuée lumineuse les couvrit, et du sein de la nuée une voix se fit entendre, disant: " Celui-ci est mon Fils bien-aimé, en qui j''ai mis toutes mes complaisances: écoutez-le. "'),
('mt',17,6,'crampon1923','En entendant cette voix, les disciples tombèrent la face contre terre, et furent saisis d''une grande frayeur.'),
('mt',17,7,'crampon1923','Mais Jésus, s''approchant, les toucha et leur dit: " Levez-vous, ne craignez point. "'),
('mt',17,8,'crampon1923','Alors, levant les yeux, ils ne virent plus que Jésus seul.'),
('mt',17,9,'crampon1923','Comme ils descendaient de la montagne, Jésus leur fit ce commandement: " Ne parlez à personne de cette vision, jusqu''à ce que le Fils de l''homme soit ressuscité des morts. "'),
('mt',17,10,'crampon1923','Ses disciples l''interrogèrent alors, et lui dirent: " Pourquoi donc les Scribes disent-ils qu''il faut qu''Elie vienne auparavant? "'),
('mt',17,11,'crampon1923','Il leur répondit: " Elie doit venir, en effet, et rétablir toutes choses.'),
('mt',17,12,'crampon1923','Mais je vous le dis, Elie est déjà venu; ils ne l''ont pas connu, et ils l''ont traité comme ils ont voulu: ils feront souffrir de même le Fils de l''homme. "'),
('mt',17,13,'crampon1923','Les disciples comprirent alors qu''il leur avait parlé de Jean-Baptiste.'),
('mt',17,14,'crampon1923','Jésus étant retourné vers le peuple, un homme s''approcha, et, tombant à genoux devant lui, il lui dit: " Seigneur, ayez pitié de mon fils qui est lunatique et qui souffre cruellement; il tombe souvent dans le feu et souvent dans l''eau.'),
('mt',17,15,'crampon1923','Je l''ai présenté à vos disciples, et ils n''ont pas su le guérir. "'),
('mt',17,16,'crampon1923','Jésus répondit: " O race incrédule et perverse, jusques à quand serai-je avec vous? Jusques à quand vous supporterai-je? Amenez-le-moi ici. "'),
('mt',17,17,'crampon1923','Et Jésus commanda au démon avec menace, et le démon sortit de l''enfant, qui fut guéri à l''heure même.'),
('mt',17,18,'crampon1923','Alors les disciples vinrent trouver Jésus en particulier, et lui dirent: " Pourquoi n''avons-nous pas pu le chasser? "'),
('mt',17,19,'crampon1923','Jésus leur dit: " A cause de votre manque de foi. En vérité, je vous le dis, si vous avez de la foi comme un grain de sénevé, vous direz à cette montagne: Passe d''ici là, et elle y passera, et rien ne vous sera impossible.'),
('mt',17,20,'crampon1923','Mais ce genre de démon n''est chassé que par le jeûne et la prière. "'),
('mt',17,21,'crampon1923','Comme ils parcouraient la Galilée, Jésus leur dit: " Le Fils de l''homme doit être livré entre les mains des hommes,'),
('mt',17,22,'crampon1923','et ils le mettront à mort, et il ressuscitera le troisième jour. " Et ils en furent vivement attristés.'),
('mt',17,23,'crampon1923','Lorsqu''ils furent de retour à Capharnaüm, ceux qui recueillaient les didrachmes s''approchèrent de Pierre et lui dirent: " Votre Maître ne paie-t-il pas les didrachmes? " —'),
('mt',17,24,'crampon1923','" Oui, " dit Pierre. Et comme ils entraient dans la maison, Jésus le prévenant, lui dit: " Que t''en semble, Simon? De qui les rois de la terre perçoivent-ils des tributs ou le cens? De leurs fils, ou des étrangers? "'),
('mt',17,25,'crampon1923','Pierre répondit: " Des étrangers, — Les fils, lui dit Jésus, en sont donc exempts.'),
('mt',17,26,'crampon1923','Mais pour ne pas les scandaliser, va à la mer, jette l''hameçon, tire le premier poisson qui montera; puis, ouvrant sa bouche, tu y trouveras un statère. Prends-le et donne-le-leur pour moi et pour toi. "'),
('mt',17,27,'crampon1923',''),
('mt',18,1,'crampon1923','En ce moment-là, les disciples s''approchèrent de Jésus et lui dirent: " Qui donc est le plus grand dans le royaume des cieux? "'),
('mt',18,2,'crampon1923','Jésus, faisant venir un petit enfant, le plaça au milieu d''eux'),
('mt',18,3,'crampon1923','et leur dit: " Je vous le dis, en vérité, si vous ne vous changez de façon à devenir comme les petits enfants, vous n''entrerez point dans le royaume des cieux.'),
('mt',18,4,'crampon1923','Celui donc qui se fera humble comme ce petit enfant, est le plus grand dans le royaume des cieux.'),
('mt',18,5,'crampon1923','Et celui qui reçoit en mon nom un petit enfant comme celui-ci, c''est moi qu''il reçoit.'),
('mt',18,6,'crampon1923','Mais celui qui scandalisera un de ces petits qui croient en moi, il vaudrait mieux pour lui qu''on lui attachât au cou la meule qu''un âne tourne, et qu''on le précipitât au fond de la mer.'),
('mt',18,7,'crampon1923','" Malheur au monde à cause des scandales! Il est nécessaire qu''il arrive des scandales; mais malheur à l''homme par qui le scandale arrive!'),
('mt',18,8,'crampon1923','Si ta main ou ton pied est pour toi une occasion de chute, coupe-les et jette-les loin de toi: il vaut mieux pour toi entrer dans la vie mutilé ou boiteux, que d''être jeté, ayant deux pieds ou deux mains, dans le feu éternel.'),
('mt',18,9,'crampon1923','Et si ton œil est pour toi une occasion de chute, arrache-le et jette-le loin de toi: il vaut mieux pour toi entrer dans la vie avec un seul œil, que d''être jeté, ayant deux yeux, dans la géhenne du feu.'),
('mt',18,10,'crampon1923','" Prenez garde de mépriser aucun de ces petits, car je vous dis que leurs anges dans le ciel voient sans cesse la face de mon Père qui est dans les cieux.'),
('mt',18,11,'crampon1923','" (Car le Fils de l''homme est venu sauver ce qui était perdu.)'),
('mt',18,12,'crampon1923','" Que vous en semble? Si un homme a cent brebis, et qu''une d''elles s''égare, ne laisse-t-il pas dans la montagne les quatre-vingt-dix-neuf autres, pour aller chercher celle qui s''est égarée?'),
('mt',18,13,'crampon1923','Et s''il a le bonheur de la trouver, je vous le dis en vérité, il a plus de joie pour elle que pour les quatre-vingt-dix-neuf qui ne se sont pas égarées.'),
('mt',18,14,'crampon1923','De même c''est la volonté de votre Père qui est dans les cieux, qu''il ne se perde pas un seul de ces petits.'),
('mt',18,15,'crampon1923','" Si ton frère a péché contre toi, va et reprends-le entre toi et lui seul; s''il t''écoute, tu auras gagné ton frère.'),
('mt',18,16,'crampon1923','S''il ne t''écoute pas, prends avec toi encore une ou deux personnes, afin que toute cause se décide sur la parole de deux ou trois témoins.'),
('mt',18,17,'crampon1923','S''il ne les écoute pas, dis-le à l''Eglise; et s''il n''écoute pas non plus l''Eglise, qu''il soit pour toi comme un païen et un publicain.'),
('mt',18,18,'crampon1923','En vérité, je vous le dis, tout ce que vous lierez sur la terre sera lié dans le ciel, et tout ce que vous délierez sur la terre sera délié dans le ciel.'),
('mt',18,19,'crampon1923','" Je vous le dis encore, si deux d''entre vous s''accordent sur la terre, quelque chose qu''ils demandent, ils l''obtiendront de mon Père qui est dans les cieux.'),
('mt',18,20,'crampon1923','Car là où deux ou trois sont assemblés en mon nom, je suis au milieu d''eux. "'),
('mt',18,21,'crampon1923','Alors Pierre s''approchant de lui: " Seigneur, dit-il, si mon frère pèche contre moi, combien de fois lui pardonnerai-je? Sera-ce jusqu''à sept fois? "'),
('mt',18,22,'crampon1923','Jésus lui dit: " Je ne te dis pas jusqu''à sept fois, mais jusqu''à septante fois sept fois.'),
('mt',18,23,'crampon1923','" C''est pourquoi le royaume des cieux est semblable à un roi qui voulut régler ses comptes avec ses serviteurs.'),
('mt',18,24,'crampon1923','Le règlement des comptes étant commencé, on lui amena un homme qui lui devait dix mille talents.'),
('mt',18,25,'crampon1923','Comme il n''avait pas de quoi payer, son maître ordonna qu''on le vendît, lui, sa femme, ses enfants et tout ce qu''il avait pour acquitter sa dette.'),
('mt',18,26,'crampon1923','Le serviteur, se jetant à ses pieds, le conjurait en disant: Aie patience envers moi, et je te paierai tout.'),
('mt',18,27,'crampon1923','Touché de compassion, le maître de ce serviteur le laissa aller et lui remit sa dette.'),
('mt',18,28,'crampon1923','Le serviteur, à peine sorti, rencontra un de ses compagnons qui lui devait cent deniers. Le saisissant à la gorge, il l''étouffait en disant: Paie ce que tu dois.'),
('mt',18,29,'crampon1923','Son compagnon, se jetant à ses pieds, le conjurait en disant: Aie patience envers moi, et je te paierai tout.'),
('mt',18,30,'crampon1923','Mais lui, sans vouloir l''entendre, s''en alla et le fit mettre en prison jusqu''à ce qu''il payât sa dette.'),
('mt',18,31,'crampon1923','Ce que voyant, les autres serviteurs en furent tout contristés, et ils vinrent raconter à leur maître ce qui s''était passé.'),
('mt',18,32,'crampon1923','Alors le maître l''appela et lui dit: Serviteur méchant, je t''avais remis toute ta dette, parce que tu m''en avais supplié.'),
('mt',18,33,'crampon1923','Ne devais-tu pas avoir pitié de ton compagnon, comme j''ai eu pitié de toi?'),
('mt',18,34,'crampon1923','Et son maître irrité le livra aux exécuteurs, jusqu''à ce qu''il eût payé toute sa dette.'),
('mt',18,35,'crampon1923','Ainsi vous traitera mon Père céleste, si chacun de vous ne pardonne à son frère du fond de son cœur. "'),
('mt',19,1,'crampon1923','Jésus ayant achevé ces discours, quitta la Galilée, et vint aux frontières de la Judée, au delà du Jourdain.'),
('mt',19,2,'crampon1923','Une grande multitude le suivit, et là il guérit les malades.'),
('mt',19,3,'crampon1923','Alors les Pharisiens l''abordèrent pour le tenter; ils lui dirent: " Est-il permis à un homme de répudier sa femme pour quelque motif que ce soit? "'),
('mt',19,4,'crampon1923','Il leur répondit: " N''avez-vous pas lu que le Créateur, au commencement, les fit homme et femme, et qu''il dit:'),
('mt',19,5,'crampon1923','A cause de cela, l''homme quittera son père et sa mère, et s''attachera à sa femme, et ils deviendront les deux une seule chair. —'),
('mt',19,6,'crampon1923','Ainsi ils ne sont plus deux, mais une seule chair. Que l''homme ne sépare donc pas ce que Dieu a uni. "'),
('mt',19,7,'crampon1923','" Pourquoi donc, lui dirent-ils, Moïse a-t-il prescrit de donner un acte de divorce et de renvoyer la femme? "'),
('mt',19,8,'crampon1923','Il leur répondit: " C''est à cause de la dureté de vos cœurs que Moïse vous a permis de répudier vos femmes: au commencement, il n''en fut pas ainsi.'),
('mt',19,9,'crampon1923','Mais je vous le dis, celui qui renvoie sa femme, si ce n''est pour impudicité, et en épouse une autre, commet un adultère; et celui qui épouse une femme renvoyée, se rend adultère. "'),
('mt',19,10,'crampon1923','Ses disciples lui dirent: " Si telle est la condition de l''homme à l''égard de la femme, il vaut mieux ne pas se marier. "'),
('mt',19,11,'crampon1923','Il leur dit: " Tous ne comprennent pas cette parole, mais seulement ceux à qui cela a été donné.'),
('mt',19,12,'crampon1923','Car il y a des eunuques qui le sont de naissance, dès le sein de leur mère; il y a aussi des eunuques qui le sont devenus par la main des hommes; et il y en a qui se sont faits eunuques eux-mêmes à cause du royaume des cieux. Que celui qui peut comprendre, comprenne! "'),
('mt',19,13,'crampon1923','Alors on lui présenta de petits enfants pour qu''il leur imposât les mains et priât pour eux. Et comme les disciples reprenaient ces gens,'),
('mt',19,14,'crampon1923','Jésus leur dit: " Laissez ces petits enfants, et ne les empêchez pas de venir à moi, car le royaume des cieux est pour ceux qui leur ressemblent. "'),
('mt',19,15,'crampon1923','Et, leur ayant imposé les mains, il continua sa route.'),
('mt',19,16,'crampon1923','Et voici qu''un jeune homme, l''abordant, lui dit: " Bon Maître, quel bien dois-je faire pour avoir la vie éternelle? "'),
('mt',19,17,'crampon1923','Jésus lui répondit: " Pourquoi m''appelles-tu bon? Dieu seul est bon. Que si tu veux entrer dans la vie, garde les commandements. " —'),
('mt',19,18,'crampon1923','" Lesquels? " dit-il. Jésus répondit: " Tu ne tueras point; tu ne commettras point d''adultère; tu ne déroberas point; tu ne rendras point de faux témoignage.'),
('mt',19,19,'crampon1923','Honore ton père et ta mère, et aime ton prochain comme toi-même. "'),
('mt',19,20,'crampon1923','Le jeune homme lui dit: " J''ai observé tous ces commandements depuis mon enfance; que me manque-t-il encore? "'),
('mt',19,21,'crampon1923','Jésus lui dit: " Si tu veux être parfait, va, vends ce que tu as, donne-le aux pauvres, et tu auras un trésor dans le ciel; puis viens et suis-moi. "'),
('mt',19,22,'crampon1923','Lorsqu''il eut entendu ces paroles, le jeune homme s''en alla triste; car il avait de grands biens.'),
('mt',19,23,'crampon1923','Et Jésus dit à ses disciples: " Je vous le dis en vérité, difficilement un riche entrera dans le royaume des cieux.'),
('mt',19,24,'crampon1923','Je vous le dis encore une fois, il est plus aisé qu''un chameau passe par le trou d''une aiguille, qu''il ne l''est à un riche d''entrer dans le royaume des cieux. "'),
('mt',19,25,'crampon1923','En entendant ces paroles, les disciples étaient fort étonnés, et ils dirent: " Qui peut donc être sauvé? "'),
('mt',19,26,'crampon1923','Jésus les regarda et leur dit: " Cela est impossible aux hommes; mais tout est possible à Dieu. "'),
('mt',19,27,'crampon1923','Alors Pierre, prenant la parole: " Voici, dit-il, que nous avons tout quitté pour vous suivre; qu''avons-nous donc à attendre? "'),
('mt',19,28,'crampon1923','Jésus leur répondit: " Je vous le dis en vérité, lorsque, au jour du renouvellement, le Fils de l''homme sera assis sur le trône de sa gloire, vous qui m''avez suivi, vous siégerez aussi sur douze trônes, et vous jugerez les douze tribus d''Israël.'),
('mt',19,29,'crampon1923','Et quiconque aura quitté des maisons, ou des frères, ou des sœurs, ou un père, ou une mère, ou une femme, ou des enfants, ou des champs à cause de mon nom, il recevra le centuple et possédera la vie éternelle. "'),
('mt',19,30,'crampon1923','" Et plusieurs qui sont les premiers seront les derniers, et plusieurs qui sont les derniers seront les premiers. "'),
('mt',20,1,'crampon1923','" Car le royaume des cieux est semblable à un père de famille qui sortit de grand matin afin de louer des ouvriers pour sa vigne.'),
('mt',20,2,'crampon1923','Étant convenu avec les ouvriers d''un denier par jour, il les envoya à sa vigne.'),
('mt',20,3,'crampon1923','Il sortit vers la troisième heure et en vit d''autres qui se tenaient sur la place sans rien faire.'),
('mt',20,4,'crampon1923','Il leur dit: Allez aussi à ma vigne, et je vous donnerai ce qui sera juste;'),
('mt',20,5,'crampon1923','et ils y allèrent. Il sortit encore vers la sixième et vers la neuvième heure, et fit la même chose.'),
('mt',20,6,'crampon1923','Enfin, étant sorti vers la onzième heure, il en trouva d''autres qui étaient là oisifs, et il leur dit: Pourquoi vous tenez-vous ici toute la journée sans rien faire?'),
('mt',20,7,'crampon1923','Ils lui répondirent: C''est que personne ne nous a loués. Il leur dit: Allez, vous aussi, à ma vigne.'),
('mt',20,8,'crampon1923','Le soir étant venu, le maître de la vigne dit à son intendant: Appelle les ouvriers et paie leur salaire, en allant des derniers aux premiers.'),
('mt',20,9,'crampon1923','Ceux de la onzième heure vinrent et reçurent chacun un denier.'),
('mt',20,10,'crampon1923','Les premiers, venant à leur tour, pensaient qu''ils recevraient davantage; mais ils reçurent aussi chacun un denier.'),
('mt',20,11,'crampon1923','En le recevant, ils murmuraient contre le père de famille,'),
('mt',20,12,'crampon1923','en disant: Ces derniers n''ont travaillé qu''une heure, et tu leur donnes autant qu''à nous, qui avons porté le poids du jour et de la chaleur.'),
('mt',20,13,'crampon1923','Mais le Maître s''adressant à l''un d''eux, répondit: Mon ami, je ne te fais point d''injustice: n''es-tu pas convenu avec moi d''un denier?'),
('mt',20,14,'crampon1923','Prends ce qui te revient, et va-t''en. Pour moi, je veux donner à ce dernier autant qu''à toi.'),
('mt',20,15,'crampon1923','Ne m''est-il pas permis de faire de mon bien ce que je veux? Et ton œil sera-t-il mauvais parce que je suis bon?'),
('mt',20,16,'crampon1923','Ainsi les derniers seront les premiers, et les premiers, les derniers; car il y a beaucoup d''appelés, mais peu d''élus. "'),
('mt',20,17,'crampon1923','Pendant que Jésus montait à Jérusalem, il prit à part les douze disciples et leur dit en chemin:'),
('mt',20,18,'crampon1923','" Voici que nous montons à Jérusalem, et le Fils de l''homme sera livré aux Princes des prêtres et aux Scribes. Ils le condamneront à mort,'),
('mt',20,19,'crampon1923','et le livreront aux Gentils pour être moqué, flagellé et crucifié; et il ressuscitera le troisième jour. "'),
('mt',20,20,'crampon1923','Alors la mère des fils de Zébédée s''approcha de Jésus avec ses fils, et se prosterna devant lui pour lui demander quelque chose.'),
('mt',20,21,'crampon1923','Il lui dit: " Que voulez-vous? " Elle répondit: " Ordonnez que mes deux fils, que voici, soient assis l''un à votre droite, l''autre à votre gauche, dans votre royaume. "'),
('mt',20,22,'crampon1923','Jésus leur dit: " Vous ne savez pas ce que vous demandez. Pouvez-vous boire le calice que je dois boire? — Nous le pouvons ", lui dirent-ils.'),
('mt',20,23,'crampon1923','Il leur répondit: " Vous boirez en effet mon calice; quant à être assis à ma droite ou à ma gauche, ce n''est pas à moi de l''accorder; si ce n''est à ceux à qui mon Père l''a préparé. "'),
('mt',20,24,'crampon1923','Ayant entendu cela, les dix autres furent indignés contre les deux frères.'),
('mt',20,25,'crampon1923','Mais Jésus les appela et leur dit: " Vous savez que les chefs des nations leur commandent en maîtres, et que les grands exercent l''empire sur elles.'),
('mt',20,26,'crampon1923','Il n''en sera pas ainsi parmi vous; mais quiconque veut être grand parmi vous, qu''il se fasse votre serviteur;'),
('mt',20,27,'crampon1923','et quiconque veut être le premier parmi vous, qu''il se fasse votre esclave.'),
('mt',20,28,'crampon1923','C''est ainsi que le Fils de l''homme est venu, non pour être servi, mais pour servir, et donner sa vie pour la rançon de la multitude. "'),
('mt',20,29,'crampon1923','Comme ils sortaient de Jéricho, une grande foule le suivit.'),
('mt',20,30,'crampon1923','Et voilà que deux aveugles, qui étaient assis sur le bord du chemin, entendant dire que Jésus passait, se mirent à crier: " Seigneur, fils de David, ayez pitié de nous. "'),
('mt',20,31,'crampon1923','La foule les gourmandait pour les faire taire; mais ils criaient plus fort: " Seigneur, fils de David, ayez pitié de nous. "'),
('mt',20,32,'crampon1923','Jésus, s''étant arrêté, les appela et dit: " Que voulez-vous que je vous fasse? —'),
('mt',20,33,'crampon1923','Seigneur, lui dirent-ils, que nos yeux s''ouvrent. "'),
('mt',20,34,'crampon1923','Emu de compassion, Jésus toucha leurs yeux, et aussitôt ils recouvrèrent la vue et le suivirent.'),
('mt',21,1,'crampon1923','Lorsqu''ils approchèrent de Jérusalem, et furent arrivés à Bethphagé, vers le mont des Oliviers, Jésus envoya deux de ses disciples,'),
('mt',21,2,'crampon1923','en leur disant: " Allez au village qui est devant vous; vous trouverez aussitôt une ânesse attachée et un ânon avec elle; détachez-les, et amenez-les-moi.'),
('mt',21,3,'crampon1923','Et si l''on vous dit quelque chose, répondez que le Seigneur en a besoin, et à l''instant on les laissera aller. "'),
('mt',21,4,'crampon1923','Or ceci arriva, afin que s''accomplît la parole du prophète:'),
('mt',21,5,'crampon1923','" Dites à la fille de Sion: Voici que ton roi vient à toi plein de douceur, assis sur une ânesse et sur un ânon, le petit de celle qui porte le joug. "'),
('mt',21,6,'crampon1923','Les disciples allèrent donc et firent ce que Jésus leur avait commandé.'),
('mt',21,7,'crampon1923','Ils amenèrent l''ânesse et l''ânon, mirent dessus leurs manteaux, et l''y firent asseoir.'),
('mt',21,8,'crampon1923','Le peuple en grand nombre étendit ses manteaux le long de la route; d''autres coupaient des branches d''arbres et en jonchaient le chemin.'),
('mt',21,9,'crampon1923','Et toute cette multitude, en avant de Jésus et derrière lui, criait: " Hosanna au fils de David! Béni soit celui qui vient au nom du Seigneur! Hosanna au plus haut des cieux! "'),
('mt',21,10,'crampon1923','Lorsqu''il entra dans Jérusalem, toute la ville fut en émoi; on disait: " Qui est-ce? "'),
('mt',21,11,'crampon1923','Et le peuple répondait: " C''est Jésus le prophète, de Nazareth en Galilée. "'),
('mt',21,12,'crampon1923','Jésus étant entré dans le temple, chassa tous ceux qui vendaient et achetaient dans le temple; il renversa les tables des changeurs et les sièges de ceux qui vendaient les colombes,'),
('mt',21,13,'crampon1923','et leur dit: " Il est écrit: Ma maison sera appelée une maison de prière, et vous en faites une caverne de voleurs. "'),
('mt',21,14,'crampon1923','Des aveugles et des boiteux vinrent à lui dans le temple, et il les guérit.'),
('mt',21,15,'crampon1923','Mais les Princes des prêtres et les Scribes, voyant les miracles qu''il faisait, et les enfants qui criaient dans le temple et disaient: " Hosanna au fils de David, " s''indignèrent,'),
('mt',21,16,'crampon1923','et ils lui dirent: " Entendez-vous ce qu''ils disent? — Oui, leur répondit Jésus; n''avez-vous jamais lu: De la bouche des enfants et de ceux qui sont à la mamelle, vous vous êtes préparé une louange? "'),
('mt',21,17,'crampon1923','Et les ayant laissés là, il sortit de la ville, et s''en alla dans la direction de Béthanie, où il passa la nuit en plein air.'),
('mt',21,18,'crampon1923','Le lendemain matin, comme il retournait à la ville, il eut faim.'),
('mt',21,19,'crampon1923','Voyant un figuier près du chemin, il s''en approcha; mais il n''y trouva que des feuilles, et il lui dit: " Que jamais aucun fruit ne naisse de toi! " Et à l''instant le figuier sécha.'),
('mt',21,20,'crampon1923','A cette vue, les disciples dirent avec étonnement: " Comment a-t-il séché en un instant? "'),
('mt',21,21,'crampon1923','Jésus leur répondit: " En vérité, je vous le dis, si vous avez de la foi et que vous n''hésitiez point, non seulement vous ferez comme il a été fait à ce figuier; mais quand même vous diriez à cette montagne: Ote-toi de là et jette-toi dans la mer, cela se ferait.'),
('mt',21,22,'crampon1923','Tout ce que vous demanderez avec foi dans la prière, vous l''obtiendrez. "'),
('mt',21,23,'crampon1923','Étant entré dans le temple, comme il enseignait, les Princes des prêtres et les Anciens s''approchèrent de lui et lui dirent: " De quel droit faites-vous ces choses, et qui vous a donné ce pouvoir? "'),
('mt',21,24,'crampon1923','Jésus leur répondit: " Je vous ferai, moi aussi, une question, et, si vous y répondez, je vous dirai de quel droit je fais ces choses:'),
('mt',21,25,'crampon1923','Le baptême de Jean, d''où était-il? du ciel, ou des hommes? " Mais ils faisaient en eux-mêmes cette réflexion:'),
('mt',21,26,'crampon1923','" Si nous répondons: Du ciel, il nous dira: Pourquoi donc n''avez-vous pas cru en lui? Et si nous répondons: Des hommes, nous avons à craindre le peuple: car tout le monde tient Jean pour un prophète. "'),
('mt',21,27,'crampon1923','Ils répondirent à Jésus: " Nous ne savons. — Et moi, dit Jésus, je ne vous dis pas non plus de quel droit je fais ces choses. "'),
('mt',21,28,'crampon1923','" Mais que vous en semble? Un homme avait deux fils; s''adressant au premier, il lui dit: Mon fils, va travailler aujourd''hui à ma vigne.'),
('mt',21,29,'crampon1923','Celui-ci répondit: Je ne veux pas; mais ensuite, touché de repentir, il y alla.'),
('mt',21,30,'crampon1923','Puis, s''adressant à l''autre, il lui fit le même commandement. Celui-ci répondit: J''y vais, seigneur; et il n''y alla point.'),
('mt',21,31,'crampon1923','Lequel des deux a fait la volonté de son père? — Le premier, " lui dirent-ils. Alors Jésus: " Je vous le dis en vérité, les publicains et les courtisanes vous devancent dans le royaume de Dieu.'),
('mt',21,32,'crampon1923','Car Jean est venu à vous dans la voie de la justice, et vous n''avez pas cru en lui; mais les publicains et les courtisanes ont cru en lui, et vous, qui avez vu cela, vous ne vous êtes pas encore repentis pour croire en lui.'),
('mt',21,33,'crampon1923','" Écoutez une autre parabole. Il y avait un père de famille qui planta une vigne. Il l''entoura d''une haie, y creusa un pressoir et y bâtit une tour; et l''ayant louée à des vignerons, il partit pour un voyage.'),
('mt',21,34,'crampon1923','Quand vint le temps des fruits, il envoya aux vignerons ses serviteurs pour recevoir le produit de sa vigne.'),
('mt',21,35,'crampon1923','Les vignerons s''étant saisis de ses serviteurs, battirent l''un, tuèrent l''autre et lapidèrent le troisième.'),
('mt',21,36,'crampon1923','Il envoya de nouveau d''autres serviteurs en plus grand nombre que les premiers, et ils les traitèrent de même.'),
('mt',21,37,'crampon1923','Enfin il leur envoya son fils, en disant: ils respecteront mon fils.'),
('mt',21,38,'crampon1923','Mais quand les vignerons virent le fils, ils se dirent entre eux: Voici l''héritier; venez, tuons-le, et nous aurons son héritage.'),
('mt',21,39,'crampon1923','Et s''étant saisis de lui, ils le jetèrent hors de la vigne et le tuèrent.'),
('mt',21,40,'crampon1923','Maintenant, lorsque le maître de la vigne viendra, que fera-t-il à ces vignerons? "'),
('mt',21,41,'crampon1923','Ils lui répondirent: " Il frappera sans pitié ces misérables, et louera sa vigne à d''autres vignerons, qui lui en donneront les fruits en leur temps. "'),
('mt',21,42,'crampon1923','Jésus leur dit: " N''avez-vous jamais lu dans les Écritures: La pierre qu''ont rejetée ceux qui bâtissaient, est devenue le sommet de l''angle? C''est le Seigneur qui a fait cela, et c''est un prodige à nos yeux. —'),
('mt',21,43,'crampon1923','C''est pourquoi je vous dis que le royaume de Dieu vous sera ôté et qu''il sera donné à un peuple qui en produira les fruits.'),
('mt',21,44,'crampon1923','Celui qui tombera sur cette pierre se brisera, et celui sur qui elle tombera sera écrasé. "'),
('mt',21,45,'crampon1923','Les Princes des prêtres et les Pharisiens ayant entendu ces paraboles, comprirent que Jésus parlait d''eux.'),
('mt',21,46,'crampon1923','Et ils cherchaient à se saisir de lui; mais ils craignaient le peuple, qui le regardait comme un prophète.'),
('mt',22,1,'crampon1923','Jésus, prenant la parole, leur parla de nouveau en paraboles, et il dit:'),
('mt',22,2,'crampon1923','" Le royaume des cieux est semblable à un roi qui faisait les noces de son fils.'),
('mt',22,3,'crampon1923','Il envoya ses serviteurs appeler ceux qui avaient été invités aux noces, et ils ne voulurent pas venir.'),
('mt',22,4,'crampon1923','Il envoya encore d''autres serviteurs, en disant: Dites aux conviés: Voilà que j''ai préparé mon festin; on a tué mes bœufs et mes animaux engraissés; tout est prêt, venez aux noces.'),
('mt',22,5,'crampon1923','Mais ils n''en tinrent pas compte, et ils s''en allèrent, l''un à son champ, l''autre à son négoce;'),
('mt',22,6,'crampon1923','et les autres se saisirent des serviteurs, et après les avoir injuriés, ils les tuèrent.'),
('mt',22,7,'crampon1923','Le roi, l''ayant appris, entra en colère; il envoya ses armées, extermina ces meurtriers et brûla leur ville.'),
('mt',22,8,'crampon1923','Alors il dit à ses serviteurs: le festin des noces est prêt, mais les conviés n''en étaient pas dignes.'),
('mt',22,9,'crampon1923','Allez donc dans les carrefours, et tous ceux que vous trouverez, invitez-les aux noces.'),
('mt',22,10,'crampon1923','Ces serviteurs, s''étant répandus par les chemins, rassemblèrent tous ceux qu''ils trouvèrent, bons ou mauvais; et la salle des noces fut remplie de convives.'),
('mt',22,11,'crampon1923','Le roi entra pour voir ceux qui étaient à table et ayant aperçu là un homme qui n''était point revêtu d''une robe nuptiale,'),
('mt',22,12,'crampon1923','il lui dit: Mon ami, comment es-tu entré ici sans avoir une robe de noces? Et cet homme resta muet.'),
('mt',22,13,'crampon1923','Alors le roi dit à ses serviteurs: Liez-lui les mains et les pieds, et jetez-le dans les ténèbres extérieures: c''est là qu''il y aura des pleurs et des grincements de dents.'),
('mt',22,14,'crampon1923','Car il y a beaucoup d''appelés, mais peu d''élus. "'),
('mt',22,15,'crampon1923','Alors les Pharisiens s''étant retirés, se concertèrent pour surprendre Jésus dans ses paroles.'),
('mt',22,16,'crampon1923','Et ils lui envoyèrent quelques-uns de leurs disciples, avec des Hérodiens, lui dire: " Maître, nous savons que vous êtes vrai, et que vous enseignez la voie de Dieu dans la vérité, sans souci de personne; car vous ne regardez pas à l''apparence des hommes.'),
('mt',22,17,'crampon1923','Dites-nous donc ce qu''il vous semble: Est-il permis, ou non, de payer le tribut à César? "'),
('mt',22,18,'crampon1923','Jésus, connaissant leur malice, leur dit: " Hypocrites, pourquoi me tentez-vous?'),
('mt',22,19,'crampon1923','Montrez-moi la monnaie du tribut. " Ils lui présentèrent un denier.'),
('mt',22,20,'crampon1923','Et Jésus leur dit: " De qui est cette image et cette inscription?'),
('mt',22,21,'crampon1923','— De César, " lui dirent-ils. Alors Jésus leur répondit: " Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu. "'),
('mt',22,22,'crampon1923','Cette réponse les remplit d''admiration, et, le quittant, ils s''en allèrent.'),
('mt',22,23,'crampon1923','Le même jour, des Sadducéens, qui nient la résurrection, vinrent à lui et lui proposèrent cette question:'),
('mt',22,24,'crampon1923','" Maître, Moïse a dit: Si un homme meurt sans laisser d''enfant, que son frère épouse sa femme et suscite des enfants à son frère.'),
('mt',22,25,'crampon1923','Or, il y avait parmi nous sept frères; le premier prit une femme et mourut, et comme il n''avait pas d''enfant, il laissa sa femme à son frère.'),
('mt',22,26,'crampon1923','La même chose arriva au second, puis au troisième, jusqu''au septième.'),
('mt',22,27,'crampon1923','Après eux tous, la femme aussi mourut.'),
('mt',22,28,'crampon1923','Au temps de la résurrection, duquel des sept frères sera-t-elle la femme? Car tous l''ont eue? "'),
('mt',22,29,'crampon1923','Jésus leur répondit: " Vous êtes dans l''erreur, ne comprenant ni les Ecritures, ni la puissance de Dieu.'),
('mt',22,30,'crampon1923','Car, à la résurrection, les hommes n''ont point de femmes, ni les femmes de maris; mais ils sont comme les anges de Dieu dans le ciel.'),
('mt',22,31,'crampon1923','Quant à la résurrection des morts, n''avez-vous pas lu ce que Dieu vous a dit, en ces termes:'),
('mt',22,32,'crampon1923','Je suis le Dieu d''Abraham, le Dieu d''Isaac, et le Dieu de Jacob? Or Dieu n''est pas le Dieu des morts, mais des vivants. "'),
('mt',22,33,'crampon1923','Et le peuple, en l''écoutant, était rempli d''admiration pour sa doctrine.'),
('mt',22,34,'crampon1923','Les Pharisiens ayant appris que Jésus avait réduit au silence les Sadducéens, s''assemblèrent.'),
('mt',22,35,'crampon1923','Et l''un d''eux, docteur de la loi, lui demanda pour le tenter:'),
('mt',22,36,'crampon1923','" Maître, quel est le plus grand commandement de la Loi? "'),
('mt',22,37,'crampon1923','Jésus lui dit: " Tu aimeras le Seigneur ton Dieu de tout ton cœur, de toute ton âme et de tout ton esprit.'),
('mt',22,38,'crampon1923','C''est là le plus grand et le premier commandement.'),
('mt',22,39,'crampon1923','Le second lui est semblable: Tu aimeras ton prochain comme toi-même.'),
('mt',22,40,'crampon1923','A ces deux commandements se rattachent toute la Loi, et les Prophètes. "'),
('mt',22,41,'crampon1923','Les Pharisiens étant assemblés, Jésus leur fit cette question:'),
('mt',22,42,'crampon1923','" Que vous semble du Christ? De qui est-il fils? " Ils lui répondirent: " De David. " —'),
('mt',22,43,'crampon1923','" Comment donc, leur dit-il, David inspiré d''en haut l''appelle-t-il Seigneur, en disant:'),
('mt',22,44,'crampon1923','Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite, jusqu''à ce que je fasse de tes ennemis l''escabeau de tes pieds?'),
('mt',22,45,'crampon1923','Si donc David l''appelle Seigneur, comment est-il son fils? "'),
('mt',22,46,'crampon1923','Nul ne pouvait rien lui répondre, et, depuis ce jour, personne n''osa plus l''interroger.'),
('mt',23,1,'crampon1923','Alors Jésus, s''adressant au peuple et à ses disciples, parla ainsi:'),
('mt',23,2,'crampon1923','" Les Scribes et les Pharisiens sont assis dans la chaire de Moïse.'),
('mt',23,3,'crampon1923','Faites donc et observez tout ce qu''ils vous disent; mais n''imitez pas leurs œuvres, car ils disent et ne font pas.'),
('mt',23,4,'crampon1923','Ils lient des fardeaux pesants et difficiles à porter, et les mettent sur les épaules des hommes, mais ils ne veulent pas les remuer du doigt.'),
('mt',23,5,'crampon1923','Ils font toutes leurs actions pour être vus des hommes, portant de plus larges phylactères et des houppes plus longues.'),
('mt',23,6,'crampon1923','Ils aiment la première place dans les festins, les premiers sièges dans les synagogues,'),
('mt',23,7,'crampon1923','les salutations dans les places publiques, et à s''entendre appeler par les hommes Rabbi.'),
('mt',23,8,'crampon1923','Pour vous, ne vous faites point appeler Rabbi; car vous n''avez qu''un seul Maître, et vous êtes tous frères.'),
('mt',23,9,'crampon1923','Et ne donnez à personne sur la terre le nom de Père; car vous n''avez qu''un seul Père, celui qui est dans les cieux.'),
('mt',23,10,'crampon1923','Qu''on ne vous appelle pas non plus Maître; car vous n''avez qu''un Maître, le Christ.'),
('mt',23,11,'crampon1923','Le plus grand parmi vous sera votre serviteur.'),
('mt',23,12,'crampon1923','Mais quiconque s''élèvera sera abaissé, et quiconque s''abaissera sera élevé.'),
('mt',23,13,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, parce que vous fermez aux hommes le royaume des cieux! Vous n''y entrez pas vous-mêmes, et vous n''y laissez pas entrer ceux qui y viennent.'),
('mt',23,14,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, parce que, sous le semblant de vos longues prières, vous dévorez les maisons des veuves! C''est pourquoi vous subirez une plus forte condamnation.'),
('mt',23,15,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, parce que vous courez les mers et la terre pour faire un prosélyte, et, quand il l''est devenu, vous faites de lui un fils de la géhenne, deux fois plus que vous!'),
('mt',23,16,'crampon1923','" Malheur à vous, guides aveugles, qui dites: Si un homme jure par le temple, ce n''est rien; mais s''il jure par l''or du temple, il est lié.'),
('mt',23,17,'crampon1923','Insensés et aveugles! lequel est le plus grand, l''or, ou le temple qui sanctifie l''or?'),
('mt',23,18,'crampon1923','Et encore: Si un homme jure par l''autel, ce n''est rien; mais s''il jure par l''offrande qui est déposée sur l''autel, il est lié.'),
('mt',23,19,'crampon1923','Aveugles! lequel est le plus grand, l''offrande, ou l''autel qui sanctifie l''offrande?'),
('mt',23,20,'crampon1923','Celui donc qui jure par l''autel, jure par l''autel et par tout ce qui est dessus;'),
('mt',23,21,'crampon1923','et celui qui jure par le temple, jure par le temple et par celui qui y habite;'),
('mt',23,22,'crampon1923','et celui qui jure par le ciel, jure par le trône de Dieu et par celui qui y est assis.'),
('mt',23,23,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, qui payez la dîme de la menthe, de l''aneth et du cumin, et qui négligez les points les plus graves de la Loi, la justice, la miséricorde et la bonne foi! Ce sont ces choses qu''il fallait pratiquer, sans omettre les autres.'),
('mt',23,24,'crampon1923','Guides aveugles, qui filtrez le moucheron, et avalez le chameau!'),
('mt',23,25,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, parce que vous nettoyez le dehors de la coupe et du plat, tandis que le dedans est rempli de rapine et d''intempérance.'),
('mt',23,26,'crampon1923','Pharisien aveugle, nettoie d''abord le dedans de la coupe et du plat, afin que le dehors aussi soit pur.'),
('mt',23,27,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, parce que vous ressemblez à des sépulcres blanchis, qui au dehors paraissent beaux, mais au dedans sont pleins d''ossements de morts et de toute sorte de pourriture.'),
('mt',23,28,'crampon1923','Ainsi vous, au dehors, vous paraissez justes aux hommes, mais au dedans vous êtes pleins d''hypocrisie et d''iniquité.'),
('mt',23,29,'crampon1923','" Malheur à vous, Scribes et Pharisiens hypocrites, qui bâtissez les tombeaux des prophètes et ornez les monuments des justes,'),
('mt',23,30,'crampon1923','et qui dites: Si nous avions vécu aux jours de nos pères, nous n''aurions pas été leurs complices pour verser le sang des prophètes.'),
('mt',23,31,'crampon1923','Ainsi vous rendez contre vous-mêmes ce témoignage, que vous êtes les fils de ceux qui ont tué les prophètes.'),
('mt',23,32,'crampon1923','Comblez donc la mesure de vos pères!'),
('mt',23,33,'crampon1923','Serpents, race de vipères, comment éviterez-vous d''être condamnés à la géhenne?'),
('mt',23,34,'crampon1923','C''est pourquoi voici que je vous envoie des prophètes, des sages et des docteurs. Vous tuerez et crucifierez les uns, vous battrez de verges les autres dans vos synagogues, et vous les poursuivrez de ville en ville:'),
('mt',23,35,'crampon1923','afin que retombe sur vous tout le sang innocent répandu sur la terre, depuis le sang du juste Abel jusqu''au sang de Zacharie, fils de Barachie, que vous avez tué entre le temple et l''autel.'),
('mt',23,36,'crampon1923','En vérité, je vous le dis, tout cela viendra sur cette génération.'),
('mt',23,37,'crampon1923','" Jérusalem, Jérusalem, qui tue les prophètes et lapides ceux qui lui sont envoyés! Que de fois j''ai voulu rassembler tes enfants, comme une poule rassemble ses poussins sous ses ailes, et vous ne l''avez pas voulu!'),
('mt',23,38,'crampon1923','Voici que votre maison vous est laissée solitaire.'),
('mt',23,39,'crampon1923','Car, je vous le dis, vous ne me verrez plus désormais jusqu''à ce que vous disiez: " Béni soit celui qui vient au nom du Seigneur! "'),
('mt',24,1,'crampon1923','Comme Jésus s''en allait, au sortir du temple, ses disciples s''approchèrent de lui pour lui en faire remarquer les constructions.'),
('mt',24,2,'crampon1923','Mais, prenant la parole, il leur dit: " Voyez-vous tous ces bâtiments? Je vous le dis en vérité, il n''y sera pas laissé pierre sur pierre qui ne soit renversée. "'),
('mt',24,3,'crampon1923','Lorsqu''il se fut assis sur la montagne des Oliviers, ses disciples s''approchèrent, et, seuls avec lui, lui dirent: " Dites-nous quand ces choses arriveront, et quel sera le signe de votre avènement et de la fin du monde? "'),
('mt',24,4,'crampon1923','Jésus leur répondit: " Prenez garde que nul ne vous séduise.'),
('mt',24,5,'crampon1923','Car plusieurs viendront sous mon nom, disant: C''est moi qui suis le Christ, et ils en séduiront un grand nombre.'),
('mt',24,6,'crampon1923','Vous entendrez parler de guerres et de bruits de guerre; n''en soyez pas troublés, car il faut que ces choses arrivent; mais ce ne sera pas encore la fin.'),
('mt',24,7,'crampon1923','On verra s''élever nation contre nation, royaume contre royaume, et il y aura des pestes, des famines et des tremblements de terre en divers lieux.'),
('mt',24,8,'crampon1923','Tout cela ne sera que le commencement des douleurs.'),
('mt',24,9,'crampon1923','Alors on vous livrera aux tortures et on vous fera mourir, et vous serez en haine à toutes les nations, à cause de mon nom.'),
('mt',24,10,'crampon1923','Alors aussi beaucoup failliront; ils se trahiront et se haïront les uns les autres.'),
('mt',24,11,'crampon1923','Et il s''élèvera plusieurs faux prophètes qui en séduiront un grand nombre.'),
('mt',24,12,'crampon1923','Et à cause des progrès croissants de l''iniquité, la charité d''un grand nombre se refroidira.'),
('mt',24,13,'crampon1923','Mais celui qui persévérera jusqu''à la fin sera sauvé.'),
('mt',24,14,'crampon1923','Cet évangile du royaume sera prêché dans le monde entier, pour être un témoignage à toutes les nations; alors viendra la fin.'),
('mt',24,15,'crampon1923','" Quand donc vous verrez l''abomination de la désolation, annoncée par le prophète Daniel, établie en lieu saint, — que celui qui lit, entende! —'),
('mt',24,16,'crampon1923','alors que ceux qui sont dans la Judée s''enfuient dans les montagnes;'),
('mt',24,17,'crampon1923','et que celui qui est sur le toit ne descende pas pour prendre ce qu''il a dans sa maison;'),
('mt',24,18,'crampon1923','et que celui qui est dans les champs ne revienne pas pour prendre son vêtement.'),
('mt',24,19,'crampon1923','Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là!'),
('mt',24,20,'crampon1923','Priez pour que votre fuite n''arrive pas en hiver, ni un jour de sabbat;'),
('mt',24,21,'crampon1923','car il y aura alors une si grande détresse, qu''il n''y en a point eu de semblable depuis le commencement du monde jusqu''ici, et qu''il n''y en aura jamais.'),
('mt',24,22,'crampon1923','Et si ces jours n''étaient abrégés, nul n''échapperait; mais, à cause des élus, ces jours seront abrégés.'),
('mt',24,23,'crampon1923','Alors, si quelqu''un vous dit: Le Christ est ici, ou: Il est là, ne le croyez point.'),
('mt',24,24,'crampon1923','Car il s''élèvera de faux Christs et de faux prophètes, et ils feront de grands prodiges et des choses extraordinaires, jusqu''à séduire, s''il se pouvait, les élus mêmes.'),
('mt',24,25,'crampon1923','Voilà que je vous l''ai prédit.'),
('mt',24,26,'crampon1923','Si donc on vous dit: Le voici dans le désert, ne sortez point; le voici dans le lieu le plus retiré de la maison, ne le croyez point.'),
('mt',24,27,'crampon1923','Car, comme l''éclair part de l''orient et brille jusqu''à l''occident, ainsi en sera-t-il de l''avènement du Fils de l''homme.'),
('mt',24,28,'crampon1923','Partout où sera le cadavre, là s''assembleront les aigles.'),
('mt',24,29,'crampon1923','" Aussitôt après ces jours d''affliction, le soleil s''obscurcira, la lune ne donnera plus sa lumière, les étoiles tomberont du ciel, et les puissances des cieux seront ébranlées.'),
('mt',24,30,'crampon1923','Alors apparaîtra dans le ciel le signe du Fils de l''homme, et toutes les tribus de la terre se frapperont la poitrine, et elles verront le Fils de l''homme venant sur les nuées du ciel avec une grande puissance et une grande majesté.'),
('mt',24,31,'crampon1923','Et il enverra ses anges avec la trompette retentissante, et ils rassembleront ses élus des quatre vents, depuis une extrémité du ciel jusqu''à l''autre.'),
('mt',24,32,'crampon1923','" Écoutez une comparaison prise du figuier. Dès que ses rameaux deviennent tendres, et qu''il pousse ses feuilles, vous savez que l''été est proche.'),
('mt',24,33,'crampon1923','Ainsi, lorsque vous verrez toutes ces choses, sachez que le Fils de l''homme est proche, qu''il est à la porte.'),
('mt',24,34,'crampon1923','Je vous le dis en vérité, cette génération ne passera point que toutes ces choses n''arrivent.'),
('mt',24,35,'crampon1923','Le ciel et la terre passeront, mais mes paroles ne passeront point.'),
('mt',24,36,'crampon1923','" Quant au jour et à l''heure, nul ne les connaît, pas même les anges du ciel, mais le Père seul.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('mt',24,37,'crampon1923','" Tels furent les jours de Noé, tel sera l''avènement du Fils de l''homme.'),
('mt',24,38,'crampon1923','Car dans les jours qui précédèrent le déluge, les hommes mangeaient et buvaient, se mariaient et mariaient leur filles, jusqu''au jour où Noé entra dans l''arche;'),
('mt',24,39,'crampon1923','et ils ne surent rien, jusqu''à ce que le déluge survînt, qui les emporta tous: ainsi en sera-t-il à l''avènement du Fils de l''homme.'),
('mt',24,40,'crampon1923','Alors, de deux hommes qui seront dans un champ, l''un sera pris, l''autre laissé;'),
('mt',24,41,'crampon1923','de deux femmes qui seront à moudre à la meule, l''une sera prise, l''autre laissée.'),
('mt',24,42,'crampon1923','Veillez donc, puisque vous ne savez à quel moment votre Seigneur doit venir.'),
('mt',24,43,'crampon1923','Sachez-le bien, si le père de famille savait à quelle heure le voleur doit venir, il veillerait et ne laisserait pas percer sa maison.'),
('mt',24,44,'crampon1923','Tenez-vous donc prêts, vous aussi; car le Fils de l''homme viendra à l''heure où vous n''y penserez pas.'),
('mt',24,45,'crampon1923','" Quel est donc le serviteur fidèle et prudent que son maître a établi sur les gens de sa maison, pour leur distribuer la nourriture en son temps?'),
('mt',24,46,'crampon1923','Heureux ce serviteur que son maître, à son retour, trouvera agissant ainsi!'),
('mt',24,47,'crampon1923','En vérité, je vous le dis, il l''établira sur tous ses biens.'),
('mt',24,48,'crampon1923','Mais, si c''est un méchant serviteur, et que, disant en lui-même: Mon maître tarde à venir,'),
('mt',24,49,'crampon1923','il se mette à battre ses compagnons, à manger et à boire avec des gens adonnés au vin,'),
('mt',24,50,'crampon1923','le maître de ce serviteur viendra le jour où il ne l''attend pas, et à l''heure qu''il ne sait pas,'),
('mt',24,51,'crampon1923','et il le fera déchirer de coups, et lui assignera son lot avec les hypocrites: c''est là qu''il y aura des pleurs et des grincements de dents.'),
('mt',25,1,'crampon1923','" Alors le royaume des cieux sera semblable à dix vierges qui, ayant pris leurs lampes, s''en allèrent au-devant de l''époux.'),
('mt',25,2,'crampon1923','Il y en avait cinq qui étaient folles, et cinq qui étaient sages.'),
('mt',25,3,'crampon1923','Les cinq folles, ayant pris leurs lampes, ne prirent pas d''huile avec elles;'),
('mt',25,4,'crampon1923','mais les sages prirent de l''huile dans leurs vases avec leurs lampes.'),
('mt',25,5,'crampon1923','Comme l''époux tardait à venir, elles s''assoupirent toutes et s''endormirent.'),
('mt',25,6,'crampon1923','Au milieu de la nuit, un cri s''éleva: Voici l''époux qui vient, allez au-devant de lui.'),
('mt',25,7,'crampon1923','Alors toutes ces vierges se levèrent et préparèrent leurs lampes.'),
('mt',25,8,'crampon1923','Et les folles dirent aux sages: Donnez-nous de votre huile, car nos lampes s''éteignent.'),
('mt',25,9,'crampon1923','Les sages répondirent: De crainte qu''il n''y en ait pas assez pour nous et pour vous; allez plutôt chez ceux qui en vendent, et achetez-en pour vous.'),
('mt',25,10,'crampon1923','Mais, pendant qu''elles allaient en acheter, l''époux arriva, et celles qui étaient prêtes entrèrent avec lui dans la salle des noces, et la porte fut fermée.'),
('mt',25,11,'crampon1923','Plus tard, les autres vierges vinrent aussi, disant: Seigneur, Seigneur, ouvrez-nous.'),
('mt',25,12,'crampon1923','Il leur répondit: En vérité, je vous le dis, je ne vous connais pas.'),
('mt',25,13,'crampon1923','" Veillez donc, car vous ne savez ni le jour, ni l''heure.'),
('mt',25,14,'crampon1923','" Car il en sera comme d''un homme qui, partant pour un voyage, appela ses serviteurs et leur remit ses biens.'),
('mt',25,15,'crampon1923','A l''un il donna cinq talents, à un autre deux, à un autre un, selon la capacité de chacun, et il partit aussitôt.'),
('mt',25,16,'crampon1923','Celui qui avait reçu cinq talents, s''en étant allé, les fit valoir, et en gagna cinq autres.'),
('mt',25,17,'crampon1923','De la même manière, celui qui en avait reçu deux, en gagna deux autres.'),
('mt',25,18,'crampon1923','Mais celui qui n''en avait reçu qu''un, s''en alla creuser la terre, et y cacha l''argent de son maître.'),
('mt',25,19,'crampon1923','Longtemps après, le maître de ces serviteurs étant revenu, leur fit rendre compte.'),
('mt',25,20,'crampon1923','Celui qui avait reçu cinq talents s''approcha et lui en présenta cinq autres, en disant: Seigneur, vous m''aviez remis cinq talents; en voici de plus cinq autres que j''ai gagnés.'),
('mt',25,21,'crampon1923','Son maître lui dit: C''est bien, serviteur bon et fidèle; parce que tu as été fidèle en peu de choses, je t''établirai sur beaucoup: entre dans la joie de ton maître.'),
('mt',25,22,'crampon1923','Celui qui avait reçu deux talents, vint aussi, et dit: Seigneur, vous m''aviez remis deux talents, en voici deux autres que j''ai gagnés.'),
('mt',25,23,'crampon1923','Son maître lui dit: C''est bien, serviteur bon et fidèle, parce que tu as été fidèle en peu de choses, je t''établirai sur beaucoup: entre dans la joie de ton maître.'),
('mt',25,24,'crampon1923','S''approchant à son tour, celui qui n''avait reçu qu''un talent, dit: Seigneur, je savais que vous êtes un homme dur, qui moissonnez où vous n''avez pas semé, et recueillez où vous n''avez pas vanné.'),
('mt',25,25,'crampon1923','J''ai eu peur, et j''ai été cacher votre talent dans la terre; le voici, je vous rends ce qui est à vous.'),
('mt',25,26,'crampon1923','Son maître lui répondit: Serviteur méchant et paresseux, tu savais que je moissonne où je n''ai pas semé, et que je recueille où je n''ai pas vanné;'),
('mt',25,27,'crampon1923','il te fallait donc porter mon argent aux banquiers, et, à mon retour, j''aurais retiré ce qui m''appartient avec un intérêt.'),
('mt',25,28,'crampon1923','Otez-lui ce talent, et donnez-le à celui qui en a dix.'),
('mt',25,29,'crampon1923','Car on donnera à celui qui a, et il sera dans l''abondance; mais à celui qui n''a pas, on ôtera même ce qu''il a.'),
('mt',25,30,'crampon1923','Et ce serviteur inutile, jetez-le dans les ténèbres extérieures: c''est là qu''il y aura des pleurs et des grincements de dents.'),
('mt',25,31,'crampon1923','" Lorsque le Fils de l''homme viendra dans sa gloire, et tous les anges avec lui, il s''assiéra sur le trône de sa gloire.'),
('mt',25,32,'crampon1923','Et, toutes les nations étant rassemblées devant lui, il séparera les uns d''avec les autres, comme le pasteur sépare les brebis d''avec les boucs.'),
('mt',25,33,'crampon1923','Et il mettra les brebis à sa droite, et les boucs à sa gauche.'),
('mt',25,34,'crampon1923','Alors le Roi dira à ceux qui sont à sa droite: Venez, les bénis de mon Père: prenez possession du royaume qui vous a été préparé dès l''origine du monde.'),
('mt',25,35,'crampon1923','Car j''ai eu faim, et vous m''avez donné à manger; j''ai eu soif, et vous m''avez donné à boire; j''étais étranger, et vous m''avez recueilli;'),
('mt',25,36,'crampon1923','nu, et vous m''avez vêtu; malade, et vous m''avez visité; en prison, et vous êtes venus à moi.'),
('mt',25,37,'crampon1923','Les justes lui répondront: Seigneur, quand vous avons-nous vu avoir faim, et vous avons-nous donné à manger; avoir soif, et vous avons-nous donné à boire?'),
('mt',25,38,'crampon1923','Quand vous avons-nous vu étranger, et vous avons-nous recueilli; nu, et vous avons-nous vêtu?'),
('mt',25,39,'crampon1923','Quand vous avons-nous vu malade ou en prison, et sommes-nous venus à vous?'),
('mt',25,40,'crampon1923','Et le Roi leur répondra: En vérité, je vous le dis, toutes les fois que vous l''avez fait à l''un de ces plus petits de mes frères, c''est à moi que vous l''avez fait.'),
('mt',25,41,'crampon1923','S''adressant ensuite à ceux qui seront à sa gauche, il dira: Retirez-vous de moi, maudits, allez au feu éternel, qui a été préparé pour le diable et ses anges.'),
('mt',25,42,'crampon1923','Car j''ai eu faim, et vous ne m''avez pas donné à manger; j''ai eu soif, et vous ne m''avez pas donné à boire;'),
('mt',25,43,'crampon1923','j''étais étranger, et vous ne m''avez pas recueilli; nu, et vous ne m''avez pas vêtu; malade et en prison, et vous ne m''avez pas visité.'),
('mt',25,44,'crampon1923','Alors eux aussi lui diront: Seigneur, quand vous avons-nous vu avoir faim ou soif, ou être étranger, ou nu, ou malade, ou en prison, et ne vous avons-nous pas assisté?'),
('mt',25,45,'crampon1923','Et il leur répondra: En vérité, je vous le dis, chaque fois que vous ne l''avez pas fait à l''un de ces plus petits, c''est à moi que vous ne l''avez pas fait.'),
('mt',25,46,'crampon1923','Et ceux-ci s''en iront à l''éternel supplice, et les justes à la vie éternelle. "'),
('mt',26,1,'crampon1923','Jésus ayant achevé tous ces discours, dit à ses disciples:'),
('mt',26,2,'crampon1923','" Vous savez que la Pâque a lieu dans deux jours, et que le Fils de l''homme va être livré pour être crucifié. "'),
('mt',26,3,'crampon1923','Alors les Princes des prêtres et les Anciens du peuple se réunirent dans la cour du grand-prêtre, appelé Caïphe,'),
('mt',26,4,'crampon1923','et ils délibérèrent sur les moyens de s''emparer de Jésus par ruse et de le faire mourir.'),
('mt',26,5,'crampon1923','" Mais, disaient-ils, il ne faut pas que ce soit pendant la fête, de peur qu''il ne s''élève quelque tumulte parmi le peuple. "'),
('mt',26,6,'crampon1923','Comme Jésus était à Béthanie, dans la maison de Simon le lépreux,'),
('mt',26,7,'crampon1923','une femme s''approcha de lui, avec un vase d''albâtre contenant un parfum de grand prix; et pendant qu''il était à table, elle répandit le parfum sur sa tête.'),
('mt',26,8,'crampon1923','Ce que voyant, les disciples dirent avec indignation: " A quoi bon cette perte?'),
('mt',26,9,'crampon1923','On aurait pu vendre ce parfum très cher et en donner le prix aux pauvres. "'),
('mt',26,10,'crampon1923','Jésus, s''en étant aperçu, leur dit: " Pourquoi faites-vous de la peine à cette femme? C''est une bonne action qu''elle a faite à mon égard.'),
('mt',26,11,'crampon1923','Car vous avez toujours les pauvres avec vous; mais moi, vous ne m''avez pas toujours.'),
('mt',26,12,'crampon1923','En répandant ce parfum sur mon corps, elle l''a fait pour ma sépulture.'),
('mt',26,13,'crampon1923','Je vous le dis, en vérité, partout où sera prêché cet évangile, dans le monde entier, ce qu''elle a fait sera raconté en mémoire d''elle. "'),
('mt',26,14,'crampon1923','Alors l''un des Douze, appelé Judas Iscariote, alla trouver les Princes des prêtres,'),
('mt',26,15,'crampon1923','et leur dit: " Que voulez-vous me donner, et je vous le livrerai? " Et ils lui comptèrent trente pièces d''argent.'),
('mt',26,16,'crampon1923','Depuis ce moment, il cherchait une occasion favorable pour livrer Jésus.'),
('mt',26,17,'crampon1923','Le premier jour des Azymes, les disciples vinrent trouver Jésus, et lui dirent: " Où voulez-vous que nous préparions le repas pascal? "'),
('mt',26,18,'crampon1923','Jésus leur répondit: " Allez à la ville chez un tel, et dites-lui: Le Maître te fait dire: Mon temps est proche, je ferai chez toi la Pâque avec mes disciples. "'),
('mt',26,19,'crampon1923','Les disciples firent ce que Jésus leur avait commandé, et ils préparèrent la Pâque.'),
('mt',26,20,'crampon1923','Le soir étant venu, il se mit à table avec les Douze.'),
('mt',26,21,'crampon1923','Pendant qu''ils mangeaient, il dit: " Je vous le dis en vérité, l''un de vous me trahira. "'),
('mt',26,22,'crampon1923','Ils en furent profondément attristés et chacun se mit à lui dire,: " Est-ce moi, Seigneur? "'),
('mt',26,23,'crampon1923','Il répondit: " Celui qui a mis avec moi la main au plat, celui-là me trahira!'),
('mt',26,24,'crampon1923','Le Fils de l''homme s''en va selon ce qui est écrit de lui; mais malheur à l''homme par qui le Fils de l''homme est trahi! Mieux vaudrait pour lui que cet homme-là ne fût pas né. "'),
('mt',26,25,'crampon1923','Judas, qui le trahissait, prit la parole et dit: " Est-ce moi, Maître? " — " Tu l''as dit, " répondit Jésus.'),
('mt',26,26,'crampon1923','Pendant le repas, Jésus prit le pain; et, ayant prononcé une bénédiction, il le rompit et le donna à ses disciples, en disant: " Prenez et mangez, ceci est mon corps. "'),
('mt',26,27,'crampon1923','Il prit ensuite la coupe, et, ayant rendu grâces, il la leur donna en disant: " Buvez-en tous:'),
('mt',26,28,'crampon1923','car ceci est mon sang, le sang de la nouvelle l''alliance, répandu pour la multitude en rémission des péchés.'),
('mt',26,29,'crampon1923','Je vous le dis, je ne boirai plus désormais de ce fruit de la vigne, jusqu''au jour où je le boirai nouveau avec vous dans le royaume de mon Père. "'),
('mt',26,30,'crampon1923','Après le chant de l''hymne, ils s''en allèrent au mont des Oliviers.'),
('mt',26,31,'crampon1923','Alors Jésus leur dit: " Je vous serai à tous, cette nuit, une occasion de chute; car il est écrit: Je frapperai le pasteur, et les brebis du troupeau seront dispersées.'),
('mt',26,32,'crampon1923','Mais après que je serai ressuscité, je vous précéderai en Galilée. "'),
('mt',26,33,'crampon1923','Pierre, prenant la parole, lui dit: " Quand vous seriez pour tous une occasion de chute, vous ne le serez jamais pour moi. "'),
('mt',26,34,'crampon1923','Jésus lui dit: " Je te le dis en vérité, cette nuit-même, avant que le coq chante, tu me renieras trois fois. "'),
('mt',26,35,'crampon1923','Pierre lui répondit: " Quand il me faudrait mourir avec vous, je ne vous renierai pas. " Et tous les autres disciples dirent de même.'),
('mt',26,36,'crampon1923','Alors Jésus arriva avec eux dans un domaine appelé Gethsémani, et il dit à ses disciples: " Asseyez-vous ici, pendant que je m''éloignerai pour prier. "'),
('mt',26,37,'crampon1923','Ayant pris avec lui Pierre et les deux fils de Zébédée, il commença à éprouver de la tristesse et de l''angoisse.'),
('mt',26,38,'crampon1923','Et il leur dit: " Mon âme est triste jusqu''à la mort; demeurez ici et veillez avec moi. "'),
('mt',26,39,'crampon1923','Et s''étant un peu avancé, il se prosterna la face contre terre, priant et disant: " Mon Père, s''il est possible, que ce calice passe loin de moi! Cependant, non pas comme je veux, mais comme vous voulez. "'),
('mt',26,40,'crampon1923','Il vint ensuite à ses disciples, et, les trouvant endormis, il dit à Pierre: " Ainsi, vous n''avez pu veiller une heure avec moi!'),
('mt',26,41,'crampon1923','Veillez et priez, afin que vous n''entriez point en tentation; l''esprit est prompt, mais la chair est faible. "'),
('mt',26,42,'crampon1923','Il s''éloigna une seconde fois et pria ainsi: " Mon Père, si ce calice ne peut passer sans que je le boive, que votre volonté soit faite! "'),
('mt',26,43,'crampon1923','Étant venu de nouveau, il les trouva encore endormis, car leurs yeux étaient appesantis.'),
('mt',26,44,'crampon1923','Il les laissa, et s''en alla encore prier pour la troisième fois, disant les mêmes paroles.'),
('mt',26,45,'crampon1923','Puis il revint à ses disciples et leur dit: " Dormez maintenant et reposez-vous; voici que l''heure est proche, où le Fils de l''homme va être livré aux mains des pécheurs. —'),
('mt',26,46,'crampon1923','Levez-vous, allons, celui qui me trahit est près d''ici. "'),
('mt',26,47,'crampon1923','Il parlait encore, lorsque Judas, l''un des Douze, arriva, et avec lui une troupe nombreuse de gens armés d''épées et de bâtons, envoyée par les Princes des prêtres et les Anciens du peuple.'),
('mt',26,48,'crampon1923','Le traître leur avait donné ce signe: " Celui que je baiserai, c''est lui, arrêtez-le. "'),
('mt',26,49,'crampon1923','Et aussitôt, s''approchant de Jésus, il dit: " Salut, Maître ", et il le baisa.'),
('mt',26,50,'crampon1923','Jésus lui dit: " Mon ami, pourquoi est-tu ici? " En même temps, ils s''avancèrent, mirent la main sur Jésus et le saisirent.'),
('mt',26,51,'crampon1923','Et voilà qu''un de ceux qui étaient avec Jésus, mettant l''épée à la main, en frappa le serviteur du grand prêtre et lui emporta l''oreille.'),
('mt',26,52,'crampon1923','Alors Jésus lui dit: " Remets ton épée à sa place; car tous ceux qui se serviront de l''épée, périront par l''épée.'),
('mt',26,53,'crampon1923','Penses-tu que je ne puisse pas sur l''heure prier mon Père, qui me donnerait plus de douze légions d''anges?'),
('mt',26,54,'crampon1923','Comment donc s''accompliront les Ecritures, qui attestent qu''il en doit être ainsi? "'),
('mt',26,55,'crampon1923','En même temps, Jésus dit à la foule: " Vous êtes venus, comme à un voleur, avec des épées et des bâtons pour me prendre. J''étais tous les jours assis parmi vous, enseignant dans le temple, et vous ne m''avez pas saisi;'),
('mt',26,56,'crampon1923','mais tout cela s''est fait, afin que s''accomplissent les oracles des prophètes. " Alors tous les disciples l''abandonnèrent et prirent la fuite.'),
('mt',26,57,'crampon1923','Ceux qui avaient arrêté Jésus l''emmenèrent chez Caïphe, le grand prêtre, où s''étaient assemblés les Scribes et les Anciens du peuple.'),
('mt',26,58,'crampon1923','Pierre le suivit de loin jusqu''à la cour du grand prêtre, y entra, et s''assit avec les serviteurs pour voir la fin.'),
('mt',26,59,'crampon1923','Cependant les Princes des prêtres et tout le Conseil cherchaient quelque faux témoignage contre Jésus afin de le faire mourir;'),
('mt',26,60,'crampon1923','et ils n''en trouvèrent point, quoique plusieurs faux témoins se fussent présentés. Enfin il en vint deux'),
('mt',26,61,'crampon1923','qui dirent: " Cet homme a dit: Je puis détruire le temple de Dieu et le rebâtir en trois jours. "'),
('mt',26,62,'crampon1923','Le grand prêtre, se levant, dit à Jésus: " Ne réponds-tu rien à ce que ces hommes déposent contre toi? "'),
('mt',26,63,'crampon1923','Jésus gardait le silence. Et le grand prêtre lui dit: " Je t''adjure par le Dieu vivant de nous dire si tu es le Christ, le Fils de Dieu? "'),
('mt',26,64,'crampon1923','Jésus lui répondit: " Tu l''as dit; de plus, je vous le dis, dès ce jour vous verrez le Fils de l''homme siéger à la droite du Tout-Puissant et venir sur les nuées du ciel. "'),
('mt',26,65,'crampon1923','Alors le grand prêtre déchira ses vêtements, en disant: " Il a blasphémé, qu''avons-nous encore besoin de témoins? Vous venez d''entendre son blasphème:'),
('mt',26,66,'crampon1923','que vous en semble? " Ils répondirent: " Il mérite la mort. "'),
('mt',26,67,'crampon1923','Alors ils lui crachèrent au visage, et le frappèrent avec le poing; d''autres le souffletèrent,'),
('mt',26,68,'crampon1923','en disant: " Christ, devine qui t''a frappé. "'),
('mt',26,69,'crampon1923','Cependant Pierre était dehors, assis dans la cour. Une servante l''aborda et lui dit: " Toi aussi, tu étais avec Jésus le Galiléen. "'),
('mt',26,70,'crampon1923','Mais il le nia devant tous en disant: " Je ne sais ce que tu veux dire. "'),
('mt',26,71,'crampon1923','Comme il se dirigeait vers le vestibule, pour s''en aller, une autre servante le vit et dit à ceux qui se trouvaient là: " Celui-ci était aussi avec Jésus de Nazareth. "'),
('mt',26,72,'crampon1923','Et Pierre le nia une seconde fois avec serment: " Je ne connais pas cet homme. "'),
('mt',26,73,'crampon1923','Peu après, ceux qui étaient là s''approchèrent de Pierre, et lui dirent: " Certainement, tu es aussi de ces gens-là; car ton langage même te faire reconnaître. "'),
('mt',26,74,'crampon1923','Alors il se mit à faire des imprécations et à jurer qu''il ne connaissait pas cet homme. Aussitôt le coq chanta.'),
('mt',26,75,'crampon1923','Et Pierre se souvint de la parole que Jésus lui avait dite: " Avant que le coq chante, tu me renieras trois fois; " et étant sorti, il pleura amèrement.'),
('mt',27,1,'crampon1923','Dès le matin, tous les Princes des prêtres et les Anciens du peuple tinrent conseil contre Jésus pour le faire mourir.'),
('mt',27,2,'crampon1923','Et, l''ayant lié, ils l''emmenèrent et le livrèrent au gouverneur Ponce Pilate.'),
('mt',27,3,'crampon1923','Alors Judas, qui l''avait livré, voyant qu''il était condamné, fut touché de repentir, et rapporta les trente pièces d''argent aux Princes des prêtres et aux Anciens,'),
('mt',27,4,'crampon1923','disant: " J''ai péché en livrant le sang innocent. " Ils répondirent: " Que nous importe? Cela te regarde. "'),
('mt',27,5,'crampon1923','Alors, ayant jeté les pièces d''argent dans le Sanctuaire, il se retira et alla se pendre.'),
('mt',27,6,'crampon1923','Mais les Princes des prêtres ramassèrent l''argent et dirent: " Il n''est pas permis de le mettre dans le trésor sacré, puisque c''est le prix du sang. "'),
('mt',27,7,'crampon1923','Et, après s''être consultés entre eux, ils achetèrent avec cet argent le champ du Potier pour la sépulture des étrangers.'),
('mt',27,8,'crampon1923','C''est pourquoi ce champ est encore aujourd''hui appelé Champ du sang.'),
('mt',27,9,'crampon1923','Alors fut accomplie la parole du prophète Jérémie: " Ils ont reçu trente pièces d''argent, prix de celui dont les enfants d''Israël ont estimé la valeur;'),
('mt',27,10,'crampon1923','et ils les ont données pour le champ du Potier, comme le Seigneur me l''a ordonné. "'),
('mt',27,11,'crampon1923','Jésus comparut devant le gouverneur, et le gouverneur l''interrogea, en disant: " Es-tu le roi des Juifs? " Jésus lui répondit: " Tu le dis. "'),
('mt',27,12,'crampon1923','Mais il ne répondait rien aux accusations des Princes des prêtres et des Anciens.'),
('mt',27,13,'crampon1923','Alors Pilate lui dit: " N''entends-tu pas de combien de choses ils t''accusent? "'),
('mt',27,14,'crampon1923','Mais il ne lui répondit sur aucun grief, de sorte que le gouverneur était dans un grand étonnement.'),
('mt',27,15,'crampon1923','A chaque fête de Pâque, le gouverneur avait coutume de relâcher un prisonnier, celui que demandait la foule.'),
('mt',27,16,'crampon1923','Or ils avaient alors un prisonnier fameux, nommé Barabbas.'),
('mt',27,17,'crampon1923','Pilate, ayant fait assembler le peuple, lui dit: " Lequel voulez-vous que je vous délivre, Barabbas ou Jésus qu''on appelle Christ? "'),
('mt',27,18,'crampon1923','Car il savait que c''était par envie qu''ils avaient livré Jésus.'),
('mt',27,19,'crampon1923','Pendant qu''il siégeait sur son tribunal, sa femme lui envoya dire: " Qu''il n''y ait rien entre toi et ce juste; car j''ai été aujourd''hui fort tourmentée en songe à cause de lui. "'),
('mt',27,20,'crampon1923','Mais les Princes des prêtres et les Anciens persuadèrent au peuple de demander Barabbas, et de faire périr Jésus.'),
('mt',27,21,'crampon1923','Le gouverneur, prenant la parole, leur dit: " Lequel des deux voulez-vous que je vous délivre? " Ils répondirent: " Barabbas. "'),
('mt',27,22,'crampon1923','Pilate leur dit: " Que ferai-je donc de Jésus, appelé Christ? "'),
('mt',27,23,'crampon1923','Ils lui répondirent: " Qu''il soit crucifié! " Le gouverneur leur dit: " Quel mal a-t-il donc fait? " Et ils crièrent encore plus fort: " Qu''il soit crucifié! "'),
('mt',27,24,'crampon1923','Pilate, voyant qu''il ne gagnait rien, mais que le tumulte allait croissant, prit de l''eau et se lava les mains devant le peuple, en disant: " Je suis innocent du sang de ce juste; à vous d''en répondre. "'),
('mt',27,25,'crampon1923','Et tout le peuple dit: " Que son sang soit sur nous et sur nos enfants! "'),
('mt',27,26,'crampon1923','Alors il leur relâcha Barabbas; et, après avoir fait battre de verges Jésus, il le livra pour être crucifié.'),
('mt',27,27,'crampon1923','Les soldats du gouverneur emmenèrent Jésus dans le prétoire, et ils assemblèrent autour de lui toute la cohorte.'),
('mt',27,28,'crampon1923','L''ayant dépouillé de ses vêtements, ils jetèrent sur lui un manteau d''écarlate.'),
('mt',27,29,'crampon1923','Ils tressèrent une couronne d''épines, qu''ils posèrent sur sa tête, et lui mirent un roseau dans la main droite; puis, fléchissant le genou devant lui, ils lui disaient par dérision: " Salut, roi des Juifs. "'),
('mt',27,30,'crampon1923','Ils lui crachaient aussi au visage, et prenant le roseau, ils en frappaient sa tête.'),
('mt',27,31,'crampon1923','Après s''être ainsi joués de lui, ils lui ôtèrent le manteau, lui remirent ses vêtements et l''emmenèrent pour le crucifier.'),
('mt',27,32,'crampon1923','Comme ils sortaient, ils rencontrèrent un homme de Cyrène, nommé Simon, qu''ils réquisitionnèrent pour porter la croix de Jésus.'),
('mt',27,33,'crampon1923','Puis, étant arrivés au lieu appelé Golgotha, c''est-à-dire, le lieu du Crâne,'),
('mt',27,34,'crampon1923','ils lui donnèrent à boire du vin mêlé de fiel; mais, l''ayant goûté, il ne voulut pas le boire.'),
('mt',27,35,'crampon1923','Quand ils l''eurent crucifié, ils se partagèrent ses vêtements en les tirant au sort, afin que s''accomplit la parole du Prophète: " Ils se sont partagés mes vêtements, et ils ont tiré ma robe au sort. "'),
('mt',27,36,'crampon1923','Et, s''étant assis, ils le gardaient.'),
('mt',27,37,'crampon1923','Au-dessus de sa tête ils mirent un écriteau indiquant la cause de son supplice: " Celui-ci est Jésus, le roi des Juifs. "'),
('mt',27,38,'crampon1923','En même temps, on crucifia avec lui deux brigands, l''un à sa droite et l''autre à sa gauche.'),
('mt',27,39,'crampon1923','Et les passants l''injuriaient, branlant la tête'),
('mt',27,40,'crampon1923','et disant: " Toi, qui détruis le temple et le rebâtis en trois jours, sauve-toi toi-même! Si tu es Fils de Dieu, descends de la croix! "'),
('mt',27,41,'crampon1923','Les Princes des prêtres, avec les Scribes et les Anciens, le raillaient aussi et disaient:'),
('mt',27,42,'crampon1923','" Il en a sauvé d''autres, et il ne peut se sauver lui-même; s''il est roi d''Israël, qu''il descende maintenant de la croix, et nous croirons en lui.'),
('mt',27,43,'crampon1923','Il s''est confié en Dieu; si Dieu l''aime, qu''il le délivre maintenant; car il a dit: Je suis Fils de Dieu. "'),
('mt',27,44,'crampon1923','Les brigands qui étaient en croix avec lui, l''insultaient de la même manière.'),
('mt',27,45,'crampon1923','Depuis la sixième heure jusqu''à la neuvième, il y eut des ténèbres sur toute la terre.'),
('mt',27,46,'crampon1923','Vers la neuvième heure, Jésus cria d''une voix forte: " Eli, Eli, lamma sabacthani, c''est-à-dire, mon Dieu, mon Dieu, pourquoi m''avez-vous abandonné? "'),
('mt',27,47,'crampon1923','Quelques-uns de ceux qui étaient là, l''ayant entendu, dirent: " Il appelle Elie. "'),
('mt',27,48,'crampon1923','Et aussitôt l''un d''eux courut prendre une éponge qu''il emplit de vinaigre, et, l''ayant mise au bout d''un roseau, il lui présenta à boire.'),
('mt',27,49,'crampon1923','Les autres disaient: " Laisse; voyons si Elie viendra le sauver. "'),
('mt',27,50,'crampon1923','Jésus poussa de nouveau un grand cri et rendit l''esprit.'),
('mt',27,51,'crampon1923','Et voilà que le voile du sanctuaire se déchira en deux, depuis le haut jusqu''en bas, la terre trembla, les rochers se fendirent,'),
('mt',27,52,'crampon1923','les sépulcres s''ouvrirent, et plusieurs saints, dont les corps y étaient couchés, ressuscitèrent.'),
('mt',27,53,'crampon1923','Etant sortis de leur tombeau, ils entrèrent, après la résurrection de Jésus, dans la ville sainte et apparurent à plusieurs.'),
('mt',27,54,'crampon1923','Le centurion et ceux qui étaient avec lui pour garder Jésus, voyant le tremblement de terre et tout ce qui se passait, furent saisis d''une grande frayeur, et dirent: " Cet homme était vraiment Fils de Dieu. "'),
('mt',27,55,'crampon1923','Il y avait là aussi plusieurs femmes qui regardaient de loin; elles avaient suivi Jésus depuis la Galilée, pour le servir.'),
('mt',27,56,'crampon1923','Parmi elles étaient Marie-Madeleine, Marie mère de Jacques et de Joseph, et la mère des fils de Zébédée.'),
('mt',27,57,'crampon1923','Sur le soir, arriva un homme riche d''Arimathie, nommé Joseph, qui était aussi un disciple de Jésus.'),
('mt',27,58,'crampon1923','Il alla trouver Pilate, et lui demanda le corps de Jésus. Et Pilate ordonna qu''on le lui remît.'),
('mt',27,59,'crampon1923','Joseph prit le corps, l''enveloppa d''un linceul blanc,'),
('mt',27,60,'crampon1923','et le déposa dans le sépulcre neuf, qu''il avait fait tailler dans le roc pour lui-même; puis, ayant roulé une grosse pierre à l''entrée du sépulcre, il s''en alla.'),
('mt',27,61,'crampon1923','Or Marie-Madeleine et l''autre Marie étaient là, assises vis-à-vis du sépulcre.'),
('mt',27,62,'crampon1923','Le lendemain, qui était le samedi, les Princes des prêtres et les Pharisiens allèrent ensemble trouver Pilate,'),
('mt',27,63,'crampon1923','et lui dirent: " Seigneur, nous nous sommes rappelés que cet imposteur, lorsqu''il vivait encore, a dit: Après trois jours je ressusciterai;'),
('mt',27,64,'crampon1923','commandez donc que son sépulcre soit gardé jusqu''au troisième jour, de peur que ses disciples ne viennent dérober le corps et ne disent au peuple: Il est ressuscité des morts. Cette dernière imposture serait pire que la première. "'),
('mt',27,65,'crampon1923','Pilate leur répondit: " Vous avez une garde; allez, gardez-le comme vous l''entendez. "'),
('mt',27,66,'crampon1923','Ils s''en allèrent donc et ils s''assurèrent du sépulcre en scellant la pierre et en y mettant des gardes.'),
('mt',28,1,'crampon1923','Après le sabbat, dès l''aube du premier jour de la semaine, Marie-Madeleine et l''autre Marie allèrent visiter le sépulcre.'),
('mt',28,2,'crampon1923','Et voilà qu''il se fit un grand tremblement de terre; car un ange du Seigneur, étant descendu du ciel, vint rouler la pierre, et s''assit dessus.'),
('mt',28,3,'crampon1923','Son aspect ressemblait à l''éclair, et son vêtement était blanc comme la neige.'),
('mt',28,4,'crampon1923','A sa vue, les gardes furent frappés d''épouvante, et devinrent comme morts.'),
('mt',28,5,'crampon1923','Et l''ange, s''adressant aux femmes, dit: " Vous, ne craignez pas; car je sais que vous cherchez Jésus qui a été crucifié.'),
('mt',28,6,'crampon1923','Il n''est point ici; il est ressuscité comme il l''avait dit. Venez, et voyez le lieu où le Seigneur avait été mis;'),
('mt',28,7,'crampon1923','et hâtez-vous d''aller dire à ses disciples qu''il est ressuscité des morts. Voici qu''il va se mettre à votre tête en Galilée; là, vous le verrez; je vous l''ai dit. "'),
('mt',28,8,'crampon1923','Aussitôt elles sortirent du sépulcre avec crainte et grande joie, et elles coururent porter la nouvelle aux disciples.'),
('mt',28,9,'crampon1923','Et voilà que Jésus se présenta devant elles et leur dit: " Salut! " Elles s''approchèrent, et embrassèrent ses pieds, se prosternant devant lui.'),
('mt',28,10,'crampon1923','Alors Jésus leur dit: " Ne craignez point; allez dire à mes frères de se rendre en Galilée: c''est là qu''ils me verront. "'),
('mt',28,11,'crampon1923','Pendant qu''elles étaient en chemin, quelques-uns des gardes vinrent dans la ville et annoncèrent aux Princes des prêtres tout ce qui était arrivé.'),
('mt',28,12,'crampon1923','Ceux-ci rassemblèrent les Anciens, et, ayant tenu conseil, ils donnèrent une grosse somme d''argent aux soldats,'),
('mt',28,13,'crampon1923','en leur disant: " Publiez que ses disciples sont venus de nuit, et l''ont enlevé pendant que vous dormiez.'),
('mt',28,14,'crampon1923','Et si le gouverneur vient à le savoir, nous l''apaiserons, et nous vous mettrons à couvert. "'),
('mt',28,15,'crampon1923','Les soldats prirent l''argent, et firent ce qu''on leur avait dit; et ce bruit qu''ils répandirent se répète encore aujourd''hui parmi les Juifs.'),
('mt',28,16,'crampon1923','Les onze disciples s''en allèrent en Galilée, sur la montagne que Jésus leur avait désignée.'),
('mt',28,17,'crampon1923','En le voyant, ils l''adorèrent, eux qui avaient hésité à croire.'),
('mt',28,18,'crampon1923','Et Jésus s''approchant, leur parla ainsi: " Toute puissance m''a été donnée dans le ciel et sur la terre.'),
('mt',28,19,'crampon1923','Allez donc, enseignez toutes les nations, les baptisant au nom du Père, et du Fils et du Saint-Esprit,'),
('mt',28,20,'crampon1923','leur apprenant à garder tout ce que je vous ai commandé: et voici que je suis avec vous tous les jours jusqu''à la fin du monde. "'),
('mc',1,1,'crampon1923','Commencement de l''Évangile de Jésus-Christ, Fils de Dieu.'),
('mc',1,2,'crampon1923','Selon ce qui est écrit dans le prophète Isaïe: " Voilà que j''envoie mon messager devant vous, pour vous frayer le chemin.'),
('mc',1,3,'crampon1923','Une voix crie dans le désert: Préparez le chemin du Seigneur, aplanissez ses sentiers. "'),
('mc',1,4,'crampon1923','Jean parut, baptisant dans le désert, et prêchant le baptême de pénitence pour la rémission des péchés.'),
('mc',1,5,'crampon1923','Tout le pays de Judée et tous les habitants de Jérusalem venaient à lui, et, confessant leurs péchés, ils recevaient de lui le baptême dans le fleuve du Jourdain.'),
('mc',1,6,'crampon1923','Or, Jean était vêtu de poils de chameau; il avait autour de ses reins une ceinture de cuir, et se nourrissait de sauterelles et de miel sauvage. Et il prêchait ainsi:'),
('mc',1,7,'crampon1923','" Il vient après moi, celui qui est plus puissant que moi, et je ne suis pas digne de délier, en me baissant, les cordons de sa chaussure.'),
('mc',1,8,'crampon1923','Moi, je vous ai baptisés dans l''eau, mais lui vous baptisera dans le Saint-Esprit. "'),
('mc',1,9,'crampon1923','Or, il arriva en ces jours-là que Jésus vint de Nazareth, ville de Galilée, et il fut baptisé par Jean dans le Jourdain.'),
('mc',1,10,'crampon1923','Et, comme il sortait de l''eau, il vit les cieux s''ouvrir et l''Esprit-Saint descendre sur lui comme une colombe.'),
('mc',1,11,'crampon1923','Et du ciel une voix se fit entendre: " Tu es mon Fils bien-aimé, en toi j''ai mis mes complaisances. "'),
('mc',1,12,'crampon1923','Et aussitôt L''Esprit poussa Jésus au désert.'),
('mc',1,13,'crampon1923','Et il y demeura quarante jours, tenté par Satan; il était parmi les bêtes sauvages, et les anges le servaient.'),
('mc',1,14,'crampon1923','Après que Jean eut été mis en prison, Jésus vint en Galilée, prêchant l''Évangile du royaume de Dieu.'),
('mc',1,15,'crampon1923','Il disait: " Le temps est accompli, et le royaume de Dieu est proche; repentez-vous et croyez à l''Évangile. "'),
('mc',1,16,'crampon1923','Passant le long de la mer de Galilée, il vit Simon et André son frère qui jetaient leurs filets dans la mer, car ils étaient pêcheurs.'),
('mc',1,17,'crampon1923','Jésus leur dit: " Venez à ma suite, et je vous ferai devenir pêcheurs d''hommes. "'),
('mc',1,18,'crampon1923','Aussitôt, laissant leurs filets, ils le suivirent.'),
('mc',1,19,'crampon1923','Un peu plus loin, il vit Jacques, fils de Zébédée, et Jean son frère, qui étaient, eux aussi, dans une barque, réparant leurs filets.'),
('mc',1,20,'crampon1923','Il les appela aussitôt; et, laissant leur père Zébédée dans la barque avec les mercenaires, ils le suivirent.'),
('mc',1,21,'crampon1923','Ils se rendirent à Capharnaüm, et dès le premier sabbat, Jésus entrant dans la synagogue, se mit à enseigner.'),
('mc',1,22,'crampon1923','Et ils étaient frappés de sa doctrine, car il les enseignait comme ayant autorité, et non comme les Scribes.'),
('mc',1,23,'crampon1923','Or il se trouva dans leur synagogue un homme possédé d''un esprit impur, qui s''écria:'),
('mc',1,24,'crampon1923','" Qu''avons-nous à faire avec vous, Jésus de Nazareth? Vous êtes venu pour nous perdre! Je sais qui vous êtes, le Saint de Dieu. "'),
('mc',1,25,'crampon1923','Mais Jésus, lui parlant avec menace: " Tais-toi, dit-il, et sors de cet homme. "'),
('mc',1,26,'crampon1923','Et l''esprit impur, l''agitant violemment, sortit de lui en jetant un grand cri.'),
('mc',1,27,'crampon1923','Tous furent saisis d''étonnement, de sorte qu''ils se demandaient entre eux: " Qu''est-ce que ceci? Quelle est cette doctrine nouvelle? Car il commande en maître, même aux esprits impurs, et ils lui obéissent. "'),
('mc',1,28,'crampon1923','Et sa renommée se répandit aussitôt dans tout le pays qui avoisine la Galilée.'),
('mc',1,29,'crampon1923','En sortant de la synagogue, ils allèrent aussitôt dans la maison de Simon et d''André, avec Jacques et Jean.'),
('mc',1,30,'crampon1923','Or, la belle-mère de Simon était au lit, ayant la fièvre; aussitôt ils parlèrent d''elle à Jésus.'),
('mc',1,31,'crampon1923','Il s''approcha et la fit lever, en la prenant par la main; au même instant la fièvre la quitta, et elle se mit à les servir.'),
('mc',1,32,'crampon1923','Sur le soir, après le coucher du soleil, il lui amenèrent tous les malades et les démoniaques,'),
('mc',1,33,'crampon1923','et toute la ville se pressait devant la porte.'),
('mc',1,34,'crampon1923','Il guérit beaucoup de malades affligés de diverses infirmités, et il chassa beaucoup de démons; mais il ne leur permettait pas de parler, parce qu''ils le connaissaient.'),
('mc',1,35,'crampon1923','Le lendemain, s''étant levé longtemps avant le jour, il sortit, alla dans un lieu solitaire, et il y pria.'),
('mc',1,36,'crampon1923','Simon et ceux qui étaient avec lui se mirent à sa recherche;'),
('mc',1,37,'crampon1923','et l''ayant trouvé, ils lui dirent: " Tout le monde vous cherche. "'),
('mc',1,38,'crampon1923','Il leur répondit: " Allons ailleurs dans les bourgades voisines, afin que j''y prêche aussi; car c''est pour cela que je suis sorti. "'),
('mc',1,39,'crampon1923','Et il prêchait dans leurs synagogues, parcourant la Galilée entière, et chassait les démons.'),
('mc',1,40,'crampon1923','Un lépreux vint à lui, et se jetant à ses genoux, il lui dit d''un ton suppliant: " Si vous voulez, vous pouvez me guérir. "'),
('mc',1,41,'crampon1923','Emu de compassion, Jésus étendit la main, et le toucha, en disant: " Je le veux, sois guéri. "'),
('mc',1,42,'crampon1923','Et dès qu''il eut parlé, la lèpre quitta cet homme, et il fut guéri.'),
('mc',1,43,'crampon1923','Aussitôt Jésus le renvoya, en lui disant d''un ton sévère:'),
('mc',1,44,'crampon1923','" Garde-toi d''en parler à personne; mais va te montrer au prêtre, et offre pour ta guérison ce que Moïse a ordonné pour l''attester au peuple. "'),
('mc',1,45,'crampon1923','Mais cet homme étant parti, se mit à raconter et à publier partout ce qui s''était passé: de sorte que Jésus ne pouvait plus entrer publiquement dans une ville; il se tenait dehors, dans des lieux solitaires, et l''on venait à lui de tous côtés.'),
('mc',2,1,'crampon1923','Quelque temps après, Jésus revint à Capharnaüm.'),
('mc',2,2,'crampon1923','Lorsqu''on sut qu''il était dans la maison, il s''y assembla aussitôt un si grand nombre de personnes, qu''elles ne pouvaient trouver place, même aux abords de la porte; et il leur prêchait la parole.'),
('mc',2,3,'crampon1923','Alors on lui amena un paralytique porté par quatre hommes.'),
('mc',2,4,'crampon1923','Et, comme ils ne pouvaient l''aborder à cause de la foule, ils découvrirent le toit à l''endroit où il était, et par l''ouverture ils descendirent le grabat où gisait le paralytique.'),
('mc',2,5,'crampon1923','Jésus, voyant leur foi, dit au paralytique: " Mon fils, tes péchés te sont remis. "'),
('mc',2,6,'crampon1923','Or il y avait là quelques Scribes assis, qui pensaient dans leur cœur:'),
('mc',2,7,'crampon1923','" Comment cet homme parle-t-il ainsi? Il blasphème. Qui peut remettre les péchés sinon Dieu seul? "'),
('mc',2,8,'crampon1923','Jésus, ayant aussitôt connu par son esprit qu''ils pensaient ainsi en eux-mêmes, leur dit: " Pourquoi avez-vous de telles pensées dans vos cœurs?'),
('mc',2,9,'crampon1923','Lequel est le plus facile de dire au paralytique: Tes péchés te sont remis, ou de lui dire: Lève-toi, prends ton grabat et marche?'),
('mc',2,10,'crampon1923','Mais afin que vous sachiez que le Fils de l''homme a sur la terre, le pouvoir de remettre les péchés,'),
('mc',2,11,'crampon1923','je te le commande, dit-il au paralytique: lève-toi, prends ton grabat et va dans ta maison. "'),
('mc',2,12,'crampon1923','Et à l''instant celui-ci se leva, pris son grabat, et sortit en présence de tous, de sorte que tout le peuple était dans l''admiration et rendait gloire à Dieu, en disant: " Jamais nous n''avons rien vu de semblable. "'),
('mc',2,13,'crampon1923','Jésus sortit de nouveau le long de la mer; et tout le peuple venait à lui, et il les enseignait.'),
('mc',2,14,'crampon1923','En passant, il vit Lévi, fils d''Alphée, assis au bureau de péage; il lui dit: " Suis-moi. " Lévi se leva et le suivit.'),
('mc',2,15,'crampon1923','Il arriva que Jésus étant à table dans la maison de cet homme, plusieurs publicains et gens de mauvaise vie se trouvaient à table avec lui et ses disciples, car ils étaient nombreux à le suivre.'),
('mc',2,16,'crampon1923','Les Scribes et les Pharisiens, le voyant manger avec des pécheurs et des publicains, disaient à ses disciples: " D''où vient que votre Maître mange et boit avec des pécheurs et des publicains? "'),
('mc',2,17,'crampon1923','Entendant cela, Jésus leur dit: " Ce ne sont pas ceux qui se portent bien qui ont besoin de médecin, mais les malades; je ne suis pas venu appeler les justes, mais les pécheurs. "'),
('mc',2,18,'crampon1923','Les disciples de Jean et les Pharisiens avaient coutume de jeûner. Ils vinrent le trouver et lui dirent: " Pourquoi, tandis que les disciples de Jean et ceux des Pharisiens pratiquent le jeûne, vos disciples ne jeûnent-ils pas? "'),
('mc',2,19,'crampon1923','Jésus leur répondit: " Les compagnons de l''époux peuvent-ils jeûner pendant que l''époux est avec eux? Aussi longtemps qu''ils ont avec eux l''époux, ils ne peuvent pas jeûner.'),
('mc',2,20,'crampon1923','Mais les jours viendront où l''époux leur sera enlevé, et alors ils jeûneront en ces jours-là.'),
('mc',2,21,'crampon1923','Personne ne coud une pièce d''étoffe neuve à un vieux vêtement: autrement la pièce neuve emporte un morceau du vieux, et la déchirure devient pire.'),
('mc',2,22,'crampon1923','Et personne ne met du vin nouveau dans des outres vieilles: autrement, le vin fait rompre les outres et le vin se répand, et les outres sont perdues. Mais le vin nouveau doit se mettre dans des outres neuves. "'),
('mc',2,23,'crampon1923','Il arriva, un jour de sabbat, que Jésus traversait des champs de blé, et ses disciples, tout en s''avançant, se mirent à cueillir des épis.'),
('mc',2,24,'crampon1923','Les Pharisiens lui dirent: " Voyez donc! Pourquoi font-ils, le jour du sabbat, ce qui n''est pas permis? "'),
('mc',2,25,'crampon1923','Il leur répondit: " N''avez-vous jamais lu ce que fit David lorsqu''il fut dans le besoin, ayant faim, lui et ceux qui l''accompagnaient:'),
('mc',2,26,'crampon1923','comment il entra dans la maison de Dieu, au temps du grand prêtre Abiathar, et mangea les pains de proposition, qu''il n''est permis de manger qu''aux prêtres seuls, et en donna même à ceux qui étaient avec lui? "'),
('mc',2,27,'crampon1923','Il leur dit encore: " Le sabbat a été fait pour l''homme, et non l''homme pour le sabbat;'),
('mc',2,28,'crampon1923','c''est pourquoi le Fils de l''homme est maître même du sabbat. "'),
('mc',3,1,'crampon1923','Jésus étant entré une autre fois dans la synagogue, il s''y trouvait un homme qui avait la main desséchée.'),
('mc',3,2,'crampon1923','Et on l''observait pour voir s''il le guérirait le jour du sabbat, afin de pouvoir l''accuser.'),
('mc',3,3,'crampon1923','Jésus dit à l''homme qui avait la main desséchée: " Tiens-toi là debout au milieu ";'),
('mc',3,4,'crampon1923','puis il leur dit: " Est-il permis le jour du sabbat, de faire du bien ou de faire du mal, de sauver la vie ou de l''ôter? " Et ils se taisaient.'),
('mc',3,5,'crampon1923','Alors, les regardant avec indignation, et contristé de l''aveuglement de leur cœur, il dit à cet homme: " Etends ta main. " Il l''étendit, et sa main redevint saine.'),
('mc',3,6,'crampon1923','Les Pharisiens, étant sortis, allèrent aussitôt s''entendre contre lui avec les Hérodiens, pour tâcher de le perdre.'),
('mc',3,7,'crampon1923','Jésus se retira vers la mer avec ses disciples, et une foule nombreuse le suivit de la Galilée, de la Judée,'),
('mc',3,8,'crampon1923','de Jérusalem, de l''Idumée et d''au delà du Jourdain. Ceux des environs de Tyr et de Sidon, ayant appris les choses qu''il faisait, vinrent aussi à lui en grande foule.'),
('mc',3,9,'crampon1923','Et il dit à ses disciples de tenir toujours une barque à sa disposition, afin qu''il ne fût pas pressé par la foule.'),
('mc',3,10,'crampon1923','Car, comme il guérissait beaucoup de gens, tous ceux qui avaient quelque mal se jetaient sur lui pour le toucher.'),
('mc',3,11,'crampon1923','Les esprits impurs, en le voyant, se prosternaient devant lui et s''écriaient:'),
('mc',3,12,'crampon1923','" Vous êtes le Fils de Dieu "; mais il leur défendait avec de grandes menaces de faire connaître qui il était.'),
('mc',3,13,'crampon1923','Etant monté ensuite sur la montagne, il appela ceux que lui-même voulut; et ils vinrent à lui.'),
('mc',3,14,'crampon1923','Il en établit douze pour les avoir avec lui et pour les envoyer prêcher,'),
('mc',3,15,'crampon1923','avec le pouvoir de guérir les maladies et de chasser les démons.'),
('mc',3,16,'crampon1923','A Simon il donna le surnom de Pierre;'),
('mc',3,17,'crampon1923','puis il choisit Jacques, fils de Zébédée, et Jean, frère de Jacques, auxquels il donna le surnom de Boanergès, c''est-à-dire, fils du tonnerre;'),
('mc',3,18,'crampon1923','André, Philippe, Barthélemy, Matthieu, Thomas, Jacques fils d''Alphée, Thaddée, Simon le Zélé,'),
('mc',3,19,'crampon1923','et Judas Iscariote, qui le trahit.'),
('mc',3,20,'crampon1923','Ils revinrent à la maison, et la foule s''y assembla de nouveau, de sorte qu''ils ne pouvaient pas même prendre leur repas.'),
('mc',3,21,'crampon1923','Ce que ses parents ayant appris, ils vinrent pour se saisir de lui, car ils disaient: " Il est hors de sens. "'),
('mc',3,22,'crampon1923','Mais les Scribes, qui étaient venus de Jérusalem, disaient: " Il est possédé de Béelzébub; et c''est par le prince des démons qu''il chasse les démons. "'),
('mc',3,23,'crampon1923','Jésus les appela et leur dit en parabole: " Comment Satan peut-il chasser Satan?'),
('mc',3,24,'crampon1923','Si un royaume est divisé contre lui-même, ce royaume ne saurait subsister;'),
('mc',3,25,'crampon1923','et si une maison est divisée contre elle-même, cette maison ne saurait subsister.'),
('mc',3,26,'crampon1923','Si donc Satan s''élève contre lui-même, il est divisé, il ne pourra subsister, et sa puissance touche à sa fin.'),
('mc',3,27,'crampon1923','Nul ne peut entrer dans la maison du fort et enlever ses meubles, si auparavant il ne l''enchaîne; et alors il pillera sa maison.'),
('mc',3,28,'crampon1923','En vérité, je vous le dis, tous les péchés seront remis aux enfants des hommes, même les blasphèmes qu''ils auront proférés.'),
('mc',3,29,'crampon1923','Mais celui qui aura blasphémé contre l''Esprit-Saint n''obtiendra jamais de pardon; il est coupable d''un péché éternel. "'),
('mc',3,30,'crampon1923','Jésus parla ainsi, parce qu''ils disaient: " Il est possédé d''un esprit impur. "'),
('mc',3,31,'crampon1923','Sa mère et ses frères étant venus, ils se tinrent dehors et l''envoyèrent appeler.'),
('mc',3,32,'crampon1923','Or le peuple était assis autour de lui, et on lui dit: " Votre mère et vos frères sont là dehors, qui vous cherchent. "'),
('mc',3,33,'crampon1923','Il répondit: " Qui est ma mère et qui sont mes frères? "'),
('mc',3,34,'crampon1923','Puis, promenant ses regards sur ceux qui étaient assis autour de lui: " Voici, dit-il, ma mère et mes frères.'),
('mc',3,35,'crampon1923','Car quiconque fait la volonté de Dieu, celui-là est mon frère, et ma sœur et ma mère. "'),
('mc',4,1,'crampon1923','Jésus se mit de nouveau à enseigner au bord de la mer. Une si grande foule s''assembla auprès de lui, qu''il monta et s''assit dans la barque, sur la mer, et toute la foule était à terre le long du rivage.'),
('mc',4,2,'crampon1923','Et il leur enseignait beaucoup de choses en paraboles, et il leur disait dans son enseignement:'),
('mc',4,3,'crampon1923','" Ecoutez. — Le semeur sortit pour semer.'),
('mc',4,4,'crampon1923','Et comme il semait, des grains tombèrent le long du chemin, et les oiseaux vinrent et les mangèrent.'),
('mc',4,5,'crampon1923','D''autres tombèrent sur un sol pierreux, où ils n''avaient pas beaucoup de terre; ils levèrent aussitôt, parce que la terre était peu profonde.'),
('mc',4,6,'crampon1923','Mais le soleil s''étant levé, la plante, frappée de ses feux et n''ayant point de racine, sécha.'),
('mc',4,7,'crampon1923','D''autres grains tombèrent parmi les épines; et les épines montèrent et les étouffèrent, et il ne donnèrent point de fruit.'),
('mc',4,8,'crampon1923','D''autres tombèrent dans la bonne terre; montant et croissant, ils donnèrent leur fruit et rapportèrent l''un trente pour un, l''autre soixante et l''autre cent. "'),
('mc',4,9,'crampon1923','Et il ajouta: " Que celui qui a des oreilles, entende bien. "'),
('mc',4,10,'crampon1923','Lorsqu''il se trouva seul, ceux qui l''entouraient, avec les Douze, l''interrogèrent sur la parabole.'),
('mc',4,11,'crampon1923','Il leur dit: " A vous il a été donné de connaître le mystère du royaume de Dieu; mais pour eux, qui sont dehors, tout est annoncé en paraboles,'),
('mc',4,12,'crampon1923','afin qu''en regardant de leurs yeux ils ne voient point, qu''en entendant de leurs oreilles ils ne comprennent point: de peur qu''ils ne se convertissent et n''obtiennent le pardon de leurs péchés. "'),
('mc',4,13,'crampon1923','Il ajouta: " Vous ne comprenez pas cette parabole? Comment donc entendrez-vous toutes les paraboles?'),
('mc',4,14,'crampon1923','Le semeur sème la parole.'),
('mc',4,15,'crampon1923','Ceux qui sont sur le chemin, ce sont les hommes en qui on sème la parole, et ils ne l''ont pas plus tôt entendue, que Satan vient et enlève la parole semée dans leurs cœurs.'),
('mc',4,16,'crampon1923','Pareillement, ceux qui reçoivent la semence en un sol pierreux, ce sont ceux qui, dès qu''ils entendent la parole, la reçoivent avec joie;'),
('mc',4,17,'crampon1923','mais il n''y a pas en eux de racines; ils sont inconstants: que survienne la tribulation ou la persécution à cause de la parole, ils succombent aussitôt.'),
('mc',4,18,'crampon1923','Ceux qui reçoivent la semence dans les épines, ce sont ceux qui écoutent la parole;'),
('mc',4,19,'crampon1923','mais les sollicitudes du monde, et la séduction des richesses, et les autres convoitises entrant dans leurs cœurs, étouffent la parole, et elle ne porte point de fruit.'),
('mc',4,20,'crampon1923','Enfin ceux où la semence tombe en bonne terre, ce sont ceux qui entendent la parole et la reçoivent, et produisent du fruit, trente, soixante, et cent pour un. "'),
('mc',4,21,'crampon1923','Il leur dit encore: " Apporte-t-on la lampe pour la mettre sous le boisseau ou sous le lit? N''est-ce pas pour la mettre sur le chandelier?'),
('mc',4,22,'crampon1923','Car il n''y a rien de caché qui ne doive être révélé, rien ne se fait en secret qui ne doive venir au jour.'),
('mc',4,23,'crampon1923','Si quelqu''un a des oreilles, qu''il entende bien. "'),
('mc',4,24,'crampon1923','Et il ajouta: " Prenez garde à ce que vous entendez. Selon la mesure avec laquelle vous aurez mesuré, on vous mesurera, et on y ajoutera encore pour vous.'),
('mc',4,25,'crampon1923','Car on donnera à celui qui a déjà, et à celui qui n''a pas, même ce qu''il a, lui sera ôté. "'),
('mc',4,26,'crampon1923','Il dit encore: " Il en est du royaume de Dieu comme d''un homme qui jette en terre de la semence.'),
('mc',4,27,'crampon1923','Il dort et il se lève, la nuit et le jour, et la semence germe et croît, sans qu''il sache comment.'),
('mc',4,28,'crampon1923','Car la terre produit d''elle-même du fruit: d''abord de l''herbe, puis un épi, et l''épi ensuite s''emplit de froment.'),
('mc',4,29,'crampon1923','Et quand le fruit est mûr, aussitôt on y met la faucille, parce que c''est le temps de la moisson. "'),
('mc',4,30,'crampon1923','Il dit encore: " A quoi comparerons-nous le royaume de Dieu? ou par quelle parabole le représenterons-nous?'),
('mc',4,31,'crampon1923','Il est semblable à un grain de sénevé qui, lorsqu''on le sème en terre, est la plus petite de toutes les semences qu''il y ait sur la terre;'),
('mc',4,32,'crampon1923','et lorsqu''on l''a semé, il monte et devient plus grand que toutes les plantes potagères, et il étend si loin ses rameaux, que les oiseaux du ciel peuvent s''abriter sous son ombre. "'),
('mc',4,33,'crampon1923','Il les enseignait ainsi par diverses paraboles, selon qu''ils étaient capables de l''entendre.'),
('mc',4,34,'crampon1923','Il ne leur parlait point sans paraboles, mais, en particulier, il expliquait tout à ses disciples.'),
('mc',4,35,'crampon1923','Ce jour-là, sur le soir, il leur dit: " Passons à l''autre bord. "'),
('mc',4,36,'crampon1923','Ayant renvoyé la foule, ils prirent avec eux Jésus, tel qu''il était, dans la barque, et d''autres petites barques l''accompagnaient.'),
('mc',4,37,'crampon1923','Alors il s''éleva un tourbillon de vent impétueux qui poussait les flots contre la barque, de sorte que déjà elle s''emplissait d''eau.'),
('mc',4,38,'crampon1923','Lui cependant était à la poupe, dormant sur le coussin; ils le réveillèrent et lui dirent: " Maître, n''avez-vous point de souci que nous périssions? "'),
('mc',4,39,'crampon1923','Jésus étant réveillé tança le vent, et dit à la mer: " Tais-toi, calme-toi. " Et le vent s''apaisa, et il se fit un grand calme.'),
('mc',4,40,'crampon1923','Et il leur dit: " Pourquoi êtes-vous effrayés? N''avez-vous pas encore la foi? " Et ils furent saisis d''une grande crainte, et ils se disaient l''un à l''autre: " Qui donc est celui-ci, que le vent et la mer lui obéissent? "'),
('mc',4,41,'crampon1923',''),
('mc',5,1,'crampon1923','Ayant passé la mer, ils arrivèrent au pays des Géraséniens.'),
('mc',5,2,'crampon1923','Et comme Jésus sortait de la barque, tout à coup vint à lui, du milieu des sépulcres, un homme possédé d''un esprit impur.'),
('mc',5,3,'crampon1923','Il avait sa demeure dans les sépulcres; et nul ne pouvait plus le tenir attaché, même avec une chaîne.'),
('mc',5,4,'crampon1923','Car on l''avait souvent chargé de liens aux pieds et de chaînes, et il avait brisé les chaînes et rompu ses liens, de sorte que personne ne pouvait en être maître.'),
('mc',5,5,'crampon1923','Sans cesse, le jour et la nuit, il errait au milieu des sépulcres et sur les montagnes, criant et se meurtrissant avec des pierres.'),
('mc',5,6,'crampon1923','Ayant aperçu Jésus de loin, il accourut, se prosterna devant lui,'),
('mc',5,7,'crampon1923','et, ayant poussé un cri, il dit d''une voix forte: " Qu''avez-vous à faire avec moi, Jésus, fils du Dieu très haut? Je vous adjure au nom de Dieu, ne me tourmentez point. "'),
('mc',5,8,'crampon1923','Car Jésus lui disait: " Esprit impur, sors de cet homme. "'),
('mc',5,9,'crampon1923','Et il lui demanda: " Quel est ton nom? " Et il lui dit: " Mon nom est Légion, car nous sommes nombreux. "'),
('mc',5,10,'crampon1923','Et il le priait instamment de ne pas les envoyer hors de ce pays.'),
('mc',5,11,'crampon1923','Or, il y avait là, le long de la montagne, un grand troupeau de porcs qui paissaient.'),
('mc',5,12,'crampon1923','Et les démons suppliaient Jésus, disant: " Envoyez-nous dans ces pourceaux, afin que nous y entrions. "'),
('mc',5,13,'crampon1923','Il le leur permit aussitôt, et les esprits impurs, sortant du possédé, entrèrent dans les pourceaux, et le troupeau, qui était d''environ deux mille, se précipita des pentes escarpées dans la mer et s''y noya.'),
('mc',5,14,'crampon1923','Ceux qui les gardaient s''enfuirent, et répandirent la nouvelle dans la ville et dans les campagnes. Les gens allèrent voir ce qui était arrivé;'),
('mc',5,15,'crampon1923','ils vinrent à Jésus, et virent le démoniaque, celui qui avait eu la légion, assis, vêtu, et sain d''esprit, et ils furent saisis de frayeur.'),
('mc',5,16,'crampon1923','Et ceux qui en avaient été témoins leur ayant raconté ce qui était arrivé au possédé et aux pourceaux,'),
('mc',5,17,'crampon1923','ils se mirent à prier Jésus de s''éloigner de leurs frontières.'),
('mc',5,18,'crampon1923','Comme Jésus montait dans la barque, celui qui avait été possédé lui demanda la permission de le suivre.'),
('mc',5,19,'crampon1923','Jésus ne le lui permit pas, mais il lui dit: " Va dans ta maison, auprès des tiens, et raconte-leur tout ce que le Seigneur a fait pour toi, et comment il a eu pitié de toi. "'),
('mc',5,20,'crampon1923','Il s''en alla, et se mit à publier dans la Décapole tout ce que Jésus avait fait pour lui: et tous étaient dans l''admiration.'),
('mc',5,21,'crampon1923','Jésus ayant de nouveau traversé la mer dans la barque, comme il était près du rivage, une grande foule s''assembla autour de lui.'),
('mc',5,22,'crampon1923','Alors vint un des chefs de la synagogue, nommé Jaïre, qui en le voyant, se jeta à ses pieds,'),
('mc',5,23,'crampon1923','et le pria avec instance, disant: " Ma fille est à l''extrémité; venez, imposez votre main sur elle, afin qu''elle soit guérie et qu''elle vive. "'),
('mc',5,24,'crampon1923','Et il s''en alla avec lui, et une grande multitude le suivait et le pressait.'),
('mc',5,25,'crampon1923','Or il y avait une femme affligée d''un flux de sang depuis douze années;'),
('mc',5,26,'crampon1923','elle avait beaucoup souffert de plusieurs médecins, et dépensé tout son bien, et loin d''avoir éprouvé quelque soulagement, elle avait vu son mal empirer.'),
('mc',5,27,'crampon1923','Ayant entendu parler de Jésus, elle vint dans la foule et toucha par derrière son manteau.'),
('mc',5,28,'crampon1923','Car elle disait: " Si je touche seulement ses vêtements, je serai guérie. "'),
('mc',5,29,'crampon1923','Aussitôt le flux de sang s''arrêta et elle sentit en son corps qu''elle était guérie de son infirmité.'),
('mc',5,30,'crampon1923','Au même moment, Jésus connut en lui-même qu''une vertu était sortie de lui, et, se retournant au milieu de la foule, il dit: " Qui a touché mes vêtements? "'),
('mc',5,31,'crampon1923','Ses disciples lui dirent: " Vous voyez la foule qui vous presse de tous côtés, et vous demandez: Qui m''a touché? "'),
('mc',5,32,'crampon1923','Et il regardait autour de lui pour voir celle qui l''avait touché.'),
('mc',5,33,'crampon1923','Cette femme, tremblante de crainte, sachant ce qui s''était passé en elle, vint se jeter à ses pieds, et lui dit toute la vérité.'),
('mc',5,34,'crampon1923','Jésus lui dit: " Ma fille, ta foi t''a sauvée; va en paix, et sois guérie de ton infirmité. "'),
('mc',5,35,'crampon1923','Il parlait encore, lorsqu''on vint de la maison du chef de synagogue lui dire: " Ta fille est morte, pourquoi fatiguer davantage le Maître? "'),
('mc',5,36,'crampon1923','Mais Jésus entendant la parole qui venait d''être proférée, dit au chef de synagogue: " Ne crains rien, crois seulement. "'),
('mc',5,37,'crampon1923','Et il ne permit à personne de l''accompagner, si ce n''est à Pierre, à Jacques et à Jean, frère de Jacques.'),
('mc',5,38,'crampon1923','On arrive à la maison du chef de synagogue, et là il voit une troupe confuse de gens qui pleurent et poussent de grands cris.'),
('mc',5,39,'crampon1923','Il entre et leur dit: " Pourquoi tout ce bruit et ces pleurs? L''enfant n''est pas morte, mais elle dort. "'),
('mc',5,40,'crampon1923','Et ils se moquaient de lui. Mais lui, les ayant tous fait sortir, prit avec lui le père et la mère de l''enfant, et les disciples qui l''accompagnaient, et entra dans le lieu où l''enfant était couchée.'),
('mc',5,41,'crampon1923','Et lui prenant la main, il lui dit: " Talitha qoumi, " c''est à dire: " Jeune fille, lève-toi, je te le dis. "'),
('mc',5,42,'crampon1923','Aussitôt la jeune fille se leva et se mit à marcher, car elle avait douze ans; et ils furent frappés de stupeur.'),
('mc',5,43,'crampon1923','Et Jésus leur défendit fortement d''en rien faire savoir à personne; puis il dit de donner à manger à la jeune fille.'),
('mc',6,1,'crampon1923','Étant parti de là, Jésus vint dans sa patrie, et ses disciples le suivirent.'),
('mc',6,2,'crampon1923','Quand le sabbat fut venu, il se mit à enseigner dans la synagogue; et beaucoup de ceux qui l''entendaient, frappés d''étonnement, disaient: " D''où celui-ci tient-il ces choses? Quelle est cette sagesse qui lui a été donnée, et comment de tels miracles s''opèrent-ils par ses mains?'),
('mc',6,3,'crampon1923','N''est-ce pas le charpentier, le fils de Marie, le frère de Jacques, de Joseph, de Jude et de Simon? Ses sœurs ne sont-elles pas ici parmi nous? " Et il se scandalisaient de lui.'),
('mc',6,4,'crampon1923','Jésus leur dit: " Un prophète n''est sans honneur que dans sa patrie, dans sa maison et dans sa famille. "'),
('mc',6,5,'crampon1923','Et il ne put faire là aucun miracle, si ce n''est qu''il guérit quelques malades en leur imposant les mains.'),
('mc',6,6,'crampon1923','Et il était surpris de leur incrédulité. Ensuite Jésus parcourut les villages d''alentour en enseignant.'),
('mc',6,7,'crampon1923','Alors il appela près de lui les Douze, et commença à les envoyer deux à deux, en leur donnant pouvoir sur les esprits impurs.'),
('mc',6,8,'crampon1923','Il leur recommanda de ne rien prendre pour la route, qu''un bâton seulement, ni sac, ni pain, ni argent dans la ceinture;'),
('mc',6,9,'crampon1923','mais d''être chaussés de sandales, et de ne pas mettre deux tuniques.'),
('mc',6,10,'crampon1923','Et il leur dit: " Partout où vous serez entrés dans une maison, demeurez-y jusqu''à ce que vous partiez de ce lieu.'),
('mc',6,11,'crampon1923','Et si quelque part on refuse de vous recevoir et de vous écouter, sortez de là, et secouez la poussière de dessous vos pieds en témoignage pour eux. "'),
('mc',6,12,'crampon1923','Etant donc partis, ils prêchèrent la pénitence;'),
('mc',6,13,'crampon1923','ils chassaient beaucoup de démons, oignaient d''huile beaucoup de malades et les guérissaient.'),
('mc',6,14,'crampon1923','Or le roi Hérode entendit parler de Jésus, dont le nom était devenu célèbre, et il disait: " Jean-Baptiste est ressuscité: c''est pourquoi la puissance miraculeuse opère en lui. "'),
('mc',6,15,'crampon1923','Mais d''autres disaient: " C''est Elie "; et d''autres: " C''est un prophète, semblable à l''un des anciens prophètes. "'),
('mc',6,16,'crampon1923','Ce qu''Hérode ayant entendu, il dit: " C''est Jean, que j''ai fait décapiter, qui est ressuscité. "'),
('mc',6,17,'crampon1923','Car c''était lui, Hérode, qui avait envoyé prendre Jean, et l''avait fait mettre en prison chargé de fers, à cause d''Hérodiade, femme de Philippe, son frère, qu''il avait épousée;'),
('mc',6,18,'crampon1923','car Jean disait à Hérode: " Il ne t''est pas permis d''avoir la femme de ton frère. "'),
('mc',6,19,'crampon1923','Hérodiade lui était donc hostile, et voulait le faire périr; mais elle ne le pouvait pas.'),
('mc',6,20,'crampon1923','Car Hérode, sachant que c''était un homme juste et saint, le vénérait et veillait sur sa vie; il faisait beaucoup de choses d''après ses conseils et l''écoutait volontiers.'),
('mc',6,21,'crampon1923','Enfin il se présenta une occasion favorable. Le jour anniversaire de sa naissance, Hérode donna un festin aux grands de sa cour, à ses officiers et aux principaux de la Galilée.'),
('mc',6,22,'crampon1923','La fille d''Hérodiade étant entrée dans la salle, dansa, et plut tellement à Hérode et à ceux qui étaient à table avec lui, que le roi dit à la jeune fille: " Demande-moi ce que tu voudras, et je te le donnerai. "'),
('mc',6,23,'crampon1923','Et il ajouta avec serment: " Quoi que ce soit que tu me demandes, je te le donnerai, jusqu''à la moitié de mon royaume. "'),
('mc',6,24,'crampon1923','Elle sortit et dit à sa mère: " Que demanderai-je? " Sa mère lui répondit: " La tête de Jean-Baptiste. "'),
('mc',6,25,'crampon1923','Revenant aussitôt avec empressement auprès du roi, la jeune fille lui fit cette demande: " Je veux que tu me donnes, à l''instant, sur un plat, la tête de Jean-Baptiste. "'),
('mc',6,26,'crampon1923','Le roi fut contristé: néanmoins, à cause de son serment et de ses convives, il ne voulut point l''affliger d''un refus.'),
('mc',6,27,'crampon1923','Il envoya aussitôt un de ses gardes avec l''ordre d''apporter la tête de Jean sur un plat.'),
('mc',6,28,'crampon1923','Le garde alla décapiter Jean dans la prison, et apporta sa tête sur un plat; il la donna à la jeune fille, et la jeune fille la donna à sa mère.'),
('mc',6,29,'crampon1923','Les disciples de Jean l''ayant appris, vinrent prendre son corps et le mirent dans un sépulcre.'),
('mc',6,30,'crampon1923','De retour près de Jésus, les Apôtres lui rendirent compte de tout ce qu''ils avaient fait et de tout ce qu''ils avaient enseigné.'),
('mc',6,31,'crampon1923','Il leur dit: " Venez, vous autres, à l''écart, dans un lieu désert, et prenez un peu de repos. " Car il y avait tant de personnes qui allaient et venaient, que les Apôtres n''avaient pas même le temps de manger.'),
('mc',6,32,'crampon1923','Ils s''embarquèrent donc et se retirèrent à l''écart dans un lieu solitaire.'),
('mc',6,33,'crampon1923','On les vit partir, et beaucoup de gens ayant deviné où ils allaient, de toutes les villes on accourut par terre en ce lieu, et on y arriva avant eux.'),
('mc',6,34,'crampon1923','Lorsque Jésus débarqua, il vit une grande multitude, et il en eut compassion, parce qu''ils étaient comme des brebis sans pasteur, et il se mit à leur enseigner beaucoup de choses.'),
('mc',6,35,'crampon1923','Comme l''heure était déjà avancée, ses disciples vinrent lui dirent: " Ce lieu est désert et déjà l''heure est avancée;'),
('mc',6,36,'crampon1923','renvoyez-les, afin qu''ils aillent dans les fermes et les villages des environs, pour s''acheter de quoi manger. "'),
('mc',6,37,'crampon1923','Il leur répondit: " Donnez-leur vous-mêmes à manger. " Et ils lui dirent: " Irons-nous donc acheter pour deux cents deniers de pain, afin de leur donner à manger? "'),
('mc',6,38,'crampon1923','Il leur demanda: " Combien avez-vous de pains? Allez et voyez. " S''en étant instruits, ils lui dirent: " Cinq pains et deux poissons. "'),
('mc',6,39,'crampon1923','Alors il leur commanda de les faire tous asseoir, par compagnies, sur l''herbe verte;'),
('mc',6,40,'crampon1923','et ils s''assirent par groupes de cent et de cinquante.'),
('mc',6,41,'crampon1923','Jésus prit les cinq pains et les deux poissons, et, levant les yeux au ciel, il prononça la bénédiction. Puis il rompit les pains et les donna à ses disciples, pour qu''ils les distribuassent au peuple; il partagea aussi les deux poissons entre tous.'),
('mc',6,42,'crampon1923','Tous mangèrent et furent rassasiés,'),
('mc',6,43,'crampon1923','et l''on emporta douze corbeilles pleines de morceaux de pain et de ce qui restait des poissons.'),
('mc',6,44,'crampon1923','Or ceux qui avaient mangé étaient au nombre de cinq mille hommes.'),
('mc',6,45,'crampon1923','Aussitôt après, Jésus obligea ses disciples de monter dans la barque, et de passer avant lui de l''autre côté du lac, vers Bethsaïde, pendant que lui-même renverrait le peuple.'),
('mc',6,46,'crampon1923','Et après qu''il en eut pris congé, il alla sur la montagne pour prier.'),
('mc',6,47,'crampon1923','Le soir étant venu, la barque était au milieu de la mer, et Jésus était seul à terre.'),
('mc',6,48,'crampon1923','Voyant qu''ils avaient beaucoup de peine à ramer, (car le vent leur était contraire), vers la quatrième veille de la nuit, il alla vers eux, marchant sur la mer; et il voulait les dépasser.'),
('mc',6,49,'crampon1923','Mais eux, le voyant marcher sur la mer, crurent que c''était un fantôme et poussèrent des cris.'),
('mc',6,50,'crampon1923','Car ils le voyaient tous, et ils étaient bouleversés. Aussitôt il leur parla et leur dit: " Ayez confiance, c''est moi, ne craignez point. "'),
('mc',6,51,'crampon1923','Il monta ensuite auprès d''eux dans la barque, et le vent cessa; or leur étonnement était au comble et les mettait hors d''eux-mêmes;'),
('mc',6,52,'crampon1923','car ils n''avaient pas compris le miracle des pains, parce que leur cœur était aveuglé.'),
('mc',6,53,'crampon1923','Après avoir traversé le lac, ils vinrent au territoire de Génésareth et y abordèrent.'),
('mc',6,54,'crampon1923','Quand ils furent sortis de la barque, les gens du pays, ayant aussitôt reconnu Jésus,'),
('mc',6,55,'crampon1923','parcoururent tous les environs, et l''on se mit à lui apporter les malades sur leurs grabats, partout où l''on apprenait qu''il était.'),
('mc',6,56,'crampon1923','En quelque lieu qu''il arrivât, dans les villages, dans les villes et dans les campagnes, on mettait les malades sur les places publiques, et on le priait de les laisser seulement toucher la houppe de son manteau; et tous ceux qui pouvaient le toucher étaient guéris.'),
('mc',7,1,'crampon1923','Les Pharisiens et plusieurs Scribes venus de Jérusalem s''assemblèrent auprès de Jésus.'),
('mc',7,2,'crampon1923','Ayant vu quelques-uns de ses disciples prendre leur repas avec des mains impures, c''est-à-dire non lavées, ils les blâmèrent. —'),
('mc',7,3,'crampon1923','Car les Pharisiens et tous les Juifs ne mangent pas sans s''être lavé soigneusement les mains, suivant la tradition des anciens.'),
('mc',7,4,'crampon1923','Et lorsqu''ils reviennent de la place publique ils ne mangent pas sans avoir pratiqué des ablutions. Ils pratiquent encore beaucoup d''autres observances traditionnelles, la purification des coupes, des cruches, des vases d''airain, et des lits. —'),
('mc',7,5,'crampon1923','Les Pharisiens et les Scribes lui demandèrent donc: " Pourquoi vos disciples ne suivent-ils pas la tradition des anciens, et prennent-ils leur repas avec des mains impures? "'),
('mc',7,6,'crampon1923','Il leur répondit: " Isaïe a bien prophétisé de vous, hypocrites, ainsi qu''il est écrit: Ce peuple m''honore des lèvres, mais leur cœur est loin de moi.'),
('mc',7,7,'crampon1923','Vain est le culte qu''ils me rendent, enseignant des doctrines qui sont des préceptes d''hommes.'),
('mc',7,8,'crampon1923','Vous laissez de côté le commandement de Dieu, pour vous attacher à la tradition des hommes, purifiant les vases et les coupes, et faisant beaucoup d''autres choses semblables.'),
('mc',7,9,'crampon1923','Vous savez fort bien, ajouta-t-il, anéantir ainsi le commandement de Dieu, pour observer votre tradition!'),
('mc',7,10,'crampon1923','Car Moïse a dit: Honore ton père et ta mère; et: Celui qui maudira son père et sa mère, qu''il soit puni de mort.'),
('mc',7,11,'crampon1923','Et vous, vous dites: Si un homme dit à son père ou à sa mère: Le bien dont j''aurais pu t''assister est corban, c''est-à-dire un don fait à Dieu,'),
('mc',7,12,'crampon1923','vous ne le laissez plus rien faire pour son père ou sa mère, —'),
('mc',7,13,'crampon1923','anéantissant ainsi la parole de Dieu par la tradition que vous enseignez. Et vous faites beaucoup d''autres choses semblables. "'),
('mc',7,14,'crampon1923','Ayant rappelé le peuple, Jésus leur dit: " Ecoutez-moi tous, et comprenez.'),
('mc',7,15,'crampon1923','Rien de ce qui est hors de l''homme et qui entre dans l''homme ne peut le souiller; mais ce qui sort de l''homme, voilà ce qui souille l''homme.'),
('mc',7,16,'crampon1923','Que celui qui a des oreilles entende bien. "'),
('mc',7,17,'crampon1923','Lorsqu''il fut entré dans une maison, loin de la foule, ses disciples l''interrogèrent sur cette parabole.'),
('mc',7,18,'crampon1923','Il leur dit: " Vous aussi, avez-vous si peu d''intelligence? Ne comprenez-vous pas que tout ce qui du dehors entre dans l''homme ne peut le souiller,'),
('mc',7,19,'crampon1923','parce que cela n''entre pas dans son cœur, mais va au ventre, et est rejeté au lieu secret, ce qui purifie tous les aliments?'),
('mc',7,20,'crampon1923','Mais ajouta-t-il, ce qui sort de l''homme, voilà ce qui souille l''homme.'),
('mc',7,21,'crampon1923','Car c''est du dedans, du cœur des hommes, que sortent les pensées mauvaises, les adultères, les fornications, les homicides,'),
('mc',7,22,'crampon1923','les vols, l''avarice, les méchancetés, la fraude, le libertinage, l''œil malin, la calomnie, l''orgueil, la folie.'),
('mc',7,23,'crampon1923','Toutes ces choses mauvaises sortent du dedans et souillent l''homme. "'),
('mc',7,24,'crampon1923','Il partit ensuite de ce lieu, et s''en alla vers les confins de Tyr et de Sidon. Et étant entré dans une maison, il désirait que personne ne le sût, mais il ne put demeurer caché.'),
('mc',7,25,'crampon1923','Car une femme, dont la petite fille était possédée d''un esprit impur, n''eut pas plus tôt entendu parler de lui, qu''elle vint se jeter à ses pieds.'),
('mc',7,26,'crampon1923','Cette femme était païenne, syro-phénicienne de nation; elle le pria de chasser le démon hors de sa fille.'),
('mc',7,27,'crampon1923','Il lui dit: " Laissez d''abord les enfants se rassasier, car il n''est pas bien de prendre le pain des enfants et de le jeter aux petits chiens. —'),
('mc',7,28,'crampon1923','Il est vrai, Seigneur, répondit-elle; mais les petits chiens mangent sous la table les miettes des enfants. "'),
('mc',7,29,'crampon1923','Alors il lui dit: " A cause de cette parole, allez, le démon est sorti de votre fille. "'),
('mc',7,30,'crampon1923','Etant retournée à sa maison, elle trouva sa fille couchée sur son lit; le démon l''avait quittée.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('mc',7,31,'crampon1923','Sortant alors du pays de Tyr, Jésus revint par Sidon vers la mer de Galilée, au centre du pays de la Décapole.'),
('mc',7,32,'crampon1923','Là, on lui amena un sourd-muet, et on le pria de lui imposer les mains.'),
('mc',7,33,'crampon1923','Jésus, le tirant à part hors de la foule, lui mit les doigts dans les oreilles, et de sa salive sur la langue;'),
('mc',7,34,'crampon1923','puis levant les yeux au ciel, il poussa un soupir et lui dit: " Ephphéta, " c''est-à-dire, ouvre-toi.'),
('mc',7,35,'crampon1923','Et aussitôt les oreilles de cet homme s''ouvrirent, sa langue se délia, et il parlait distinctement.'),
('mc',7,36,'crampon1923','Jésus leur défendit d''en rien dire à personne. Mais plus il le leur défendait, plus ils le publiaient;'),
('mc',7,37,'crampon1923','et ravis d''une admiration sans bornes, ils disaient: " Tout ce qu''il a fait est merveilleux! Il fait entendre les sourds et parler les muets. "'),
('mc',8,1,'crampon1923','En ces jours-là, comme il y avait encore une grande foule qui n''avait pas de quoi manger, Jésus appela ses disciples et leur dit:'),
('mc',8,2,'crampon1923','" J''ai compassion de ce peuple, car voilà trois jours déjà qu''ils ne me quittent pas, et ils n''ont rien à manger.'),
('mc',8,3,'crampon1923','Si je les renvoie dans leur maison sans nourriture, ils tomberont de défaillance en chemin; car plusieurs d''entre eux sont venus de loin! "'),
('mc',8,4,'crampon1923','Ses disciples lui répondirent: " Comment pourrait-on trouver ici, dans un désert, assez de pain pour les rassasier? "'),
('mc',8,5,'crampon1923','Et il leur demanda: " Combien avez-vous de pains? " Ils dirent: " Sept. "'),
('mc',8,6,'crampon1923','Alors il fit asseoir la foule par terre, prit les sept pains, et, après avoir rendu grâces, il les rompit et les donna à ses disciples pour les distribuer; et ils les distribuèrent au peuple.'),
('mc',8,7,'crampon1923','Ils avaient en outre quelques petits poissons; après avoir prononcé une bénédiction, Jésus les fit aussi distribuer.'),
('mc',8,8,'crampon1923','Ils mangèrent et furent rassasiés, et l''on emporta sept corbeilles des morceaux qui restaient.'),
('mc',8,9,'crampon1923','Or ceux qui mangèrent étaient environ quatre mille. Ensuite Jésus les renvoya.'),
('mc',8,10,'crampon1923','Il monta aussitôt dans la barque avec ses disciples, et vint dans le pays de Dalmanutha.'),
('mc',8,11,'crampon1923','Survinrent les Pharisiens, qui commencèrent à discuter avec lui, lui demandant, pour l''éprouver, un signe du ciel.'),
('mc',8,12,'crampon1923','Jésus ayant poussé un profond soupir, dit: " Pourquoi cette génération demande-t-elle un signe? Je vous le dis, en vérité, il ne sera point donné de signe à cette génération. "'),
('mc',8,13,'crampon1923','Et les laissant, il remonta dans la barque et passa à l''autre bord.'),
('mc',8,14,'crampon1923','Or les disciples avaient oublié de prendre des pains; ils n''en avaient qu''un seul avec eux dans la barque.'),
('mc',8,15,'crampon1923','Jésus leur donna cet avertissement: " Gardez-vous avec soin du levain des Pharisiens et du levain d''Hérode. "'),
('mc',8,16,'crampon1923','Sur quoi ils faisaient réflexion entre eux, disant: " C''est que nous n''avons pas de pains. "'),
('mc',8,17,'crampon1923','Jésus, connaissant leur pensée, leur dit: " Pourquoi vous entretenez-vous de ce que vous n''avez pas de pains? N''avez-vous encore ni sens ni intelligence? Votre cœur est-il encore aveuglé?'),
('mc',8,18,'crampon1923','Avez-vous des yeux pour ne pas voir, des oreilles pour ne pas entendre? Et n''avez-vous point de mémoire?'),
('mc',8,19,'crampon1923','Quand j''ai rompu les cinq pains entre les cinq mille hommes, combien avez-vous emporté de corbeilles pleines de morceaux? " Ils lui dirent: " Douze. " —'),
('mc',8,20,'crampon1923','Et quand j''ai rompu les sept pains entre les quatre mille hommes, combien de paniers pleins de morceaux avez-vous emportés? " Ils lui dirent: " Sept. "'),
('mc',8,21,'crampon1923','Il leur dit: " Comment ne comprenez-vous pas encore? "'),
('mc',8,22,'crampon1923','Ils arrivèrent à Bethsaïde, et on lui amena un aveugle qu''on le pria de toucher.'),
('mc',8,23,'crampon1923','Prenant la main de l''aveugle, Jésus le conduisit hors du bourg, lui mit de sa salive sur les yeux, et, lui ayant imposé les mains, lui demanda s''il voyait quelque chose.'),
('mc',8,24,'crampon1923','L''aveugle leva les yeux et dit: " Je vois les hommes qui marchent, semblables à des arbres. "'),
('mc',8,25,'crampon1923','Jésus lui mit de nouveau les mains sur les yeux, et il le fit regarder. Alors il fut si bien guéri, qu''il voyait distinctement toutes choses.'),
('mc',8,26,'crampon1923','Alors Jésus le renvoya dans sa maison, en lui disant: " Va dans ta maison, sans entrer dans le bourg, ni parler de ceci à personne du bourg. "'),
('mc',8,27,'crampon1923','De là, Jésus se rendit avec ses disciples dans les villages qui entourent Césarée de Philippe, et sur le chemin il leur fit cette question: " Qui dit-on que je suis? "'),
('mc',8,28,'crampon1923','Ils lui répondirent: " Jean-Baptiste; d''autres, Elie; d''autres, un des prophètes. —'),
('mc',8,29,'crampon1923','Mais vous, leur demanda-t-il, qui dites-vous que je suis? " Pierre, prenant la parole, lui dit: " Vous êtes le Christ. "'),
('mc',8,30,'crampon1923','Et il leur défendit sévèrement de dire cela de lui à personne.'),
('mc',8,31,'crampon1923','Alors il commença à leur enseigner qu''il fallait que le Fils de l''homme souffrît beaucoup, qu''il fût rejeté par les Anciens, par les Princes des prêtres et les Scribes, qu''il fût mis à mort et qu''il ressuscitât trois jours après.'),
('mc',8,32,'crampon1923','Et il leur dit ces choses ouvertement. Pierre, le prenant à part, se mit à le reprendre.'),
('mc',8,33,'crampon1923','Mais Jésus, s''étant retourné et ayant regardé ses disciples, réprimanda Pierre, en disant: " Arrière! Satan; car tes sentiments ne sont pas ceux de Dieu, mais ceux des hommes. "'),
('mc',8,34,'crampon1923','Puis, ayant appelé le peuple avec ses disciples, il leur dit: " Si quelqu''un veut marcher à ma suite, qu''il se renonce lui-même, qu''il prenne sa croix et me suive.'),
('mc',8,35,'crampon1923','Car celui qui veut sauver sa vie, la perdra, et celui qui perdra sa vie à cause de moi et de l''Evangile, la sauvera.'),
('mc',8,36,'crampon1923','Que servira-t-il à l''homme de gagner le monde entier, s''il perd son âme?'),
('mc',8,37,'crampon1923','Car que donnera l''homme en échange de son âme?'),
('mc',8,38,'crampon1923','Celui qui aura rougi de moi et de mes paroles au milieu de cette génération adultère et pécheresse, le Fils de l''homme aussi rougira de lui, lorsqu''il viendra dans la gloire de son Père avec les anges saints. " Il ajouta: " Je vous le dis, en vérité, parmi ceux qui sont ici, quelques-uns ne goûteront point la mort, qu''ils n''aient vu le royaume de Dieu venir avec puissance. "'),
('mc',9,1,'crampon1923','Six jours après, Jésus prit avec lui Pierre, Jacques et Jean, et les conduisit seuls, à l''écart, sur une haute montagne, et il fut transfiguré devant eux.'),
('mc',9,2,'crampon1923','Ses vêtements devinrent étincelants, d''une blancheur aussi éclatante que la neige, et tels qu''aucun foulon sur la terre ne saurait blanchir ainsi.'),
('mc',9,3,'crampon1923','Puis Elie et Moïse leur apparurent, conversant avec Jésus.'),
('mc',9,4,'crampon1923','Pierre, prenant la parole, dit à Jésus: " Maître, il nous est bon d''être ici; dressons trois tentes, une pour vous, une pour Moïse, et une pour Elie. "'),
('mc',9,5,'crampon1923','Il ne savait ce qu''il disait, l''effroi les ayant saisis.'),
('mc',9,6,'crampon1923','Et une nuée les couvrit de son ombre, et de la nuée sortit une voix: " Celui-ci est mon Fils bien-aimé; écoutez-le. "'),
('mc',9,7,'crampon1923','Aussitôt, regardant tout autour, ils ne virent plus personne, si ce n''est Jésus, seul avec eux.'),
('mc',9,8,'crampon1923','Comme ils descendaient de la montagne, il leur défendit de raconter à personne ce qu''ils avaient vu, jusqu''à ce que le Fils de l''homme fût ressuscité des morts.'),
('mc',9,9,'crampon1923','Et ils gardèrent pour eux la chose, tout en se demandant entre eux ce que signifiait ce mot: " être ressuscité des morts! "'),
('mc',9,10,'crampon1923','Ils l''interrogèrent et lui dirent: " Pourquoi donc les Scribes disent-ils qu''il faut qu''Elie vienne auparavant? "'),
('mc',9,11,'crampon1923','Il leur répondit: " Elie doit venir auparavant, et rétablir toutes choses; et comment est-il écrit du Fils de l''homme qu''il doit souffrir beaucoup et être méprisé?'),
('mc',9,12,'crampon1923','Mais, je vous le dis, Elie est déjà venu, et ils l''ont traité comme ils ont voulu, selon qu''il est écrit de lui. "'),
('mc',9,13,'crampon1923','Etant retourné vers ses disciples, il vit une grande foule autour d''eux, et des Scribes qui discutaient avec eux.'),
('mc',9,14,'crampon1923','Toute la foule fut surprise de voir Jésus, et elle accourut aussitôt pour le saluer.'),
('mc',9,15,'crampon1923','Il leur demanda: " Sur quoi discutez-vous avec eux? "'),
('mc',9,16,'crampon1923','Un homme de la foule lui répondit: " Maître, je vous ai amené mon fils, qui est possédé d''un esprit muet.'),
('mc',9,17,'crampon1923','Partout où l''esprit s''empare de lui, il le jette contre terre, et l''enfant écume, et grince des dents et il se dessèche; j''ai prié vos disciples de le chasser, et ils ne l''ont pu. —'),
('mc',9,18,'crampon1923','O race incrédule, leur dit Jésus, jusques à quand serai-je avec vous? Jusques à quand vous supporterai-je? Amenez-le-moi. "'),
('mc',9,19,'crampon1923','On le lui amena. A sa vue, l''esprit agita soudain l''enfant avec violence; il tomba par terre et se roulait en écumant.'),
('mc',9,20,'crampon1923','Jésus demanda au père de l''enfant: " Combien y a-t-il de temps que cela lui arrive? — Depuis son enfance, répondit-il.'),
('mc',9,21,'crampon1923','Souvent l''esprit l''a jeté dans le feu et dans l''eau pour le faire périr; si vous pouvez quelque chose, ayez pitié de nous et secourez-nous. "'),
('mc',9,22,'crampon1923','Jésus lui dit: " Si vous pouvez (croire), tout est possible à celui qui croit. "'),
('mc',9,23,'crampon1923','Aussitôt le père de l''enfant s''écria, disant avec larmes: " Je crois (Seigneur); venez au secours de mon incrédulité "'),
('mc',9,24,'crampon1923','Jésus, voyant le peuple accourir en foule, menaça l''esprit impur, en disant: " Esprit sourd et muet, je te le commande, sors de cet enfant, et ne rentre plus en lui. "'),
('mc',9,25,'crampon1923','Alors, ayant poussé un grand cri, et l''ayant agité avec violence, il sortit, et l''enfant devint comme un cadavre, au point que plusieurs disaient: " Il est mort. "'),
('mc',9,26,'crampon1923','Mais Jésus, l''ayant pris par la main, le fit lever, et il se tint debout.'),
('mc',9,27,'crampon1923','Lorsqu''il fut entré dans la maison, ses disciples lui demandèrent en particulier: " Pourquoi n''avons-nous pu chasser cet esprit? "'),
('mc',9,28,'crampon1923','Il leur dit: " Ce genre de démon ne peut être chassé que par la prière et le jeûne. "'),
('mc',9,29,'crampon1923','Etant partis de là, ils cheminèrent à travers la Galilée, et Jésus ne voulait pas qu''on le sût,'),
('mc',9,30,'crampon1923','car il enseignait ses disciples et leur disait: " Le fils de l''homme sera livré entre les mains des hommes, et ils le feront mourir, et le troisième jour après sa mort il ressuscitera. "'),
('mc',9,31,'crampon1923','Mais ils ne comprenaient point cette parole, et ils craignaient de l''interroger.'),
('mc',9,32,'crampon1923','Ils arrivèrent à Capharnaüm. Lorsqu''il fut dans la maison, Jésus leur demanda: " De quoi parliez-vous en chemin? "'),
('mc',9,33,'crampon1923','Mais ils gardèrent le silence, car en chemin ils avaient discuté entre eux qui était le plus grand.'),
('mc',9,34,'crampon1923','Alors ils s''assit, appela les Douze et leur dit: " Si quelqu''un veut être le premier, il sera le dernier de tous, et le serviteur de tous. "'),
('mc',9,35,'crampon1923','Puis, prenant un petit enfant, il le mit au milieu d''eux; et après l''avoir embrassé, il leur dit:'),
('mc',9,36,'crampon1923','" Quiconque reçoit en mon nom un de ces petits enfants, me reçoit; et quiconque me reçoit, ce n''est pas moi qu''il reçoit, mais celui qui m''a envoyé. "'),
('mc',9,37,'crampon1923','Jean, prenant la parole, lui dit: " Maître, nous avons vu un homme qui ne va pas avec nous, chasser les démons en votre nom, et nous l''en avons empêché. —'),
('mc',9,38,'crampon1923','Ne l''en empêchez pas, dit Jésus; car personne ne peut faire de miracle en mon nom, et aussitôt après parler mal de moi.'),
('mc',9,39,'crampon1923','Qui n''est pas contre nous, est pour nous.'),
('mc',9,40,'crampon1923','Car quiconque vous donnera un verre d''eau en mon nom, parce que vous êtes au Christ, je vous le dis, en vérité, il ne perdra pas sa récompense.'),
('mc',9,41,'crampon1923','Et quiconque sera une occasion de chute pour un de ces petits qui croient en moi, il vaudrait mieux pour lui qu''on lui attachât au cou la meule qu''un âne tourne, et qu''on le jetât dans la mer.'),
('mc',9,42,'crampon1923','Si ta main est pour toi une occasion de chute, coupe-la: mieux vaut pour toi entrer mutilé dans la vie, que d''aller, ayant deux mains, dans la géhenne, dans le feu inextinguible,'),
('mc',9,43,'crampon1923','là où leur ver ne meurt point, et où le feu ne s''éteint point.'),
('mc',9,44,'crampon1923','Et si ton pied est pour toi une occasion de chute, coupe-le: mieux vaut pour toi entrer boiteux dans la vie, que d''être jeté, ayant deux pieds, dans la géhenne du feu inextinguible,'),
('mc',9,45,'crampon1923','là où leur ver ne meurt point, et où le feu ne s''éteint point.'),
('mc',9,46,'crampon1923','Et si ton œil est pour toi une occasion de chute, arrache-le: mieux vaut pour toi entrer avec un seul œil dans le royaume de Dieu, que d''être jeté, ayant deux yeux, dans la géhenne du feu,'),
('mc',9,47,'crampon1923','là où leur ver ne meurt point, et où le feu ne s''éteint point.'),
('mc',9,48,'crampon1923','Car tout homme sera salé par le feu, et toute offrande sera salée avec du sel.'),
('mc',9,49,'crampon1923','Le sel est bon; mais si le sel s''affadit, avec quoi lui donnerez-vous de la saveur? Gardez bien le sel en vous, et soyez en paix les uns avec les autres. "'),
('mc',9,50,'crampon1923',''),
('mc',10,1,'crampon1923','Etant parti de ce lieu, Jésus vint aux confins de la Judée, au delà du Jourdain; et le peuple s''assembla de nouveau près de lui, et, suivant sa coutume, il recommença à les enseigner.'),
('mc',10,2,'crampon1923','Les Pharisiens l''ayant abordé lui demandèrent s''il était permis à un mari de répudier sa femme: c''était pour le mettre à l''épreuve.'),
('mc',10,3,'crampon1923','Il leur répondit: " Que vous a ordonné Moïse? "'),
('mc',10,4,'crampon1923','Ils dirent: " Moïse a permis de dresser un acte de divorce et de répudier. "'),
('mc',10,5,'crampon1923','Jésus leur répondit: " C''est à cause de la dureté de votre cœur qu''il vous a donné cette loi.'),
('mc',10,6,'crampon1923','Mais au commencement de la création, Dieu les fit homme et femme.'),
('mc',10,7,'crampon1923','A cause de cela, l''homme quittera son père et sa mère, et s''attachera à sa femme,'),
('mc',10,8,'crampon1923','et les deux ne feront qu''une seule chair. " Ainsi ils ne sont plus deux, mais ils sont une seule chair.'),
('mc',10,9,'crampon1923','Que l''homme donc ne sépare pas ce que Dieu a uni! "'),
('mc',10,10,'crampon1923','Lorsqu''ils furent dans la maison, ses disciples l''interrogèrent encore sur ce sujet,'),
('mc',10,11,'crampon1923','et il leur dit: " Quiconque répudie sa femme et en épouse une autre, commet un adultère à l''égard de la première.'),
('mc',10,12,'crampon1923','Et si une femme répudie son mari et en épouse un autre, elle se rend adultère. "'),
('mc',10,13,'crampon1923','On lui amena des petits enfants pour qu''il les touchât. Mais les disciples réprimandaient ceux qui les présentaient.'),
('mc',10,14,'crampon1923','Jésus, à cette vue, fut indigné et leur dit: " Laissez les petits enfants venir à moi, et ne les en empêchez pas; car le royaume des cieux est à ceux qui leur ressemblent.'),
('mc',10,15,'crampon1923','Je vous le dis, en vérité, quiconque ne recevra pas comme un petit enfant le royaume de Dieu, n''y entrera point. "'),
('mc',10,16,'crampon1923','Puis il les embrassa, et les bénit en leur imposant les mains.'),
('mc',10,17,'crampon1923','Comme il sortait pour se mettre en chemin, quelqu''un accourut, et se jetant à genoux devant lui, lui demanda: " Bon Maître, que dois-je faire pour avoir en héritage la vie éternelle? "'),
('mc',10,18,'crampon1923','Jésus lui dit: " Pourquoi m''appelles-tu bon? Il n''y a de bon que Dieu seul.'),
('mc',10,19,'crampon1923','Tu connais les commandements: Ne commets point d''adultère, ne tue point, ne dérobe point, ne porte point de faux témoignage, abstiens-toi de toute fraude, honore ton père et ta mère. "'),
('mc',10,20,'crampon1923','Il lui répondit: " Maître, j''ai observé toutes ces choses dès ma jeunesse. "'),
('mc',10,21,'crampon1923','Jésus, l''ayant regardé, l''aima et lui dit: " Il te manque une chose; va, vends tout ce que tu as, donne-le aux pauvres, et tu auras un trésor dans le ciel; puis viens, et suis-moi. "'),
('mc',10,22,'crampon1923','Mais lui, affligé de cette parole, s''en alla tout triste; car il avait de grands biens.'),
('mc',10,23,'crampon1923','Et Jésus, jetant ses regards autour de lui, dit à ses disciples: " Qu''il est difficile à ceux qui ont les biens de ce monde d''entrer dans le royaume de Dieu! "'),
('mc',10,24,'crampon1923','Comme les disciples étaient étonnés de ses paroles, Jésus reprit: " Mes petits enfants, qu''il est difficile à ceux qui se confient dans les richesses, d''entrer dans le royaume de Dieu!'),
('mc',10,25,'crampon1923','Il est plus aisé à un chameau de passer par le trou d''une aiguille, qu''à un riche d''entrer dans le royaume de Dieu. "'),
('mc',10,26,'crampon1923','Et ils étaient encore plus étonnés, et ils se disaient les uns aux autres: " Qui peut donc être sauvé? "'),
('mc',10,27,'crampon1923','Jésus les regarda, et dit: " Aux hommes cela est impossible, mais non à Dieu: car tout est possible à Dieu. "'),
('mc',10,28,'crampon1923','Alors Pierre, prenant la parole: " Voici, lui dit-il, que nous avons tout quitté pour vous suivre. "'),
('mc',10,29,'crampon1923','Jésus répondit: " Je vous le dis en vérité, nul ne quittera sa maison, ou ses frères, ou ses sœurs, ou son père, ou sa mère, ou ses enfants, ou ses champs, à cause de moi et à cause de l''Evangile,'),
('mc',10,30,'crampon1923','qu''il ne reçoive maintenant, en ce temps présent, cent fois autant: maisons, frères, sœurs, mères, enfants et champs, au milieu même des persécutions, et dans le siècle à venir, la vie éternelle.'),
('mc',10,31,'crampon1923','Et plusieurs des derniers seront les premiers, et des premiers, les derniers. "'),
('mc',10,32,'crampon1923','Or, ils étaient en chemin pour monter à Jérusalem, et Jésus marchait devant eux; ils s''en étonnaient et ils le suivaient avec crainte. Jésus, de nouveau, prenant à part les Douze, se mit à leur dire ce qui devait lui arriver:'),
('mc',10,33,'crampon1923','" Voici que nous montons à Jérusalem, et le Fils de l''homme sera livré aux Princes des prêtres et aux Scribes; ils le condamneront à mort et le livreront aux Gentils;'),
('mc',10,34,'crampon1923','on l''insultera, on crachera sur lui, on le flagellera et on le fera mourir, et, trois jours après, il ressuscitera. "'),
('mc',10,35,'crampon1923','Jacques et Jean, fils de Zébédée, s''approchèrent de lui, disant: " Maître, nous désirons bien que vous fassiez pour nous ce que nous vous demanderons. —'),
('mc',10,36,'crampon1923','Que voulez-vous, leur dit-il, que je fasse pour vous? "'),
('mc',10,37,'crampon1923','Ils dirent: " Accordez-nous d''être assis, l''un à votre droite, l''autre à votre gauche, dans votre gloire. "'),
('mc',10,38,'crampon1923','Jésus leur dit: " Vous ne savez ce que vous demandez. Pouvez-vous boire le calice que je vais boire, ou être baptisés du baptême dont je vais être baptisé? "'),
('mc',10,39,'crampon1923','Ils répondirent: " Nous le pouvons. " Et Jésus leur dit: " Le calice que je vais boire, vous le boirez en effet, et vous serez baptisés du baptême dont je vais être baptisé;'),
('mc',10,40,'crampon1923','mais d''être assis à ma droite ou à ma gauche, ce n''est pas à moi de l''accorder, si ce n''est à ceux à qui cela a été préparé. "'),
('mc',10,41,'crampon1923','Ayant entendu cela, les dix autres s''indignèrent contre Jacques et Jean.'),
('mc',10,42,'crampon1923','Jésus les appela et leur dit: " Vous savez que ceux qui sont reconnus comme les chefs des nations leur commandent en maîtres, et que les grands exercent sur elles l''empire.'),
('mc',10,43,'crampon1923','Il n''en doit pas être ainsi parmi vous; mais quiconque veut être grand parmi vous se fera votre serviteur;'),
('mc',10,44,'crampon1923','et quiconque veut être le premier parmi vous, se fera l''esclave de tous.'),
('mc',10,45,'crampon1923','Car le Fils de l''homme est venu, non pour être servi, mais pour servir et donner sa vie pour la rançon de la multitude. "'),
('mc',10,46,'crampon1923','Ils arrivèrent à Jéricho. Comme Jésus sortait de cette ville avec ses disciples et une assez grande foule, le fils de Timée, Bartimée l''aveugle, était assis sur le bord du chemin, demandant l''aumône.'),
('mc',10,47,'crampon1923','Ayant entendu dire que c''était Jésus de Nazareth, il se mit à crier: " Jésus, fils de David, ayez pitié de moi. "'),
('mc',10,48,'crampon1923','Et plusieurs le gourmandaient pour le faire taire; mais lui criait beaucoup plus fort: " Fils de David, ayez pitié de moi. "'),
('mc',10,49,'crampon1923','Alors Jésus s''arrêta, et dit: " Appelez-le. " Et ils l''appelèrent en lui disant: " Aie confiance, lève-toi, il t''appelle. "'),
('mc',10,50,'crampon1923','Celui-ci jetant son manteau, se leva d''un bond et vint vers Jésus.'),
('mc',10,51,'crampon1923','Jésus lui dit: " Que veux-tu que je te fasse? — L''aveugle répondit: Rabboni, que je voie. "'),
('mc',10,52,'crampon1923','Jésus lui dit: " Va, ta foi t''a sauvé. " Et aussitôt il vit, et il le suivait dans le chemin.'),
('mc',11,1,'crampon1923','Comme ils approchaient de Jérusalem, aux environs de Betphagé et Béthanie, vers la montagne des Oliviers, Jésus envoya deux de ses disciples,'),
('mc',11,2,'crampon1923','en leur disant: " Allez au village qui est devant vous; dès que vous y serez entrés, vous trouverez un ânon attaché, sur lequel nul homme ne s''est encore assis: détachez-le et amenez-le-moi.'),
('mc',11,3,'crampon1923','Et si quelqu''un vous dit: Que faites-vous? répondez: Le Seigneur en a besoin; et aussitôt il va le renvoyer ici. "'),
('mc',11,4,'crampon1923','S''en étant allés, les disciples trouvèrent un ânon attaché à une porte, en dehors, au tournant du chemin, et ils le détachèrent.'),
('mc',11,5,'crampon1923','Quelques-uns de ceux qui étaient là leur dirent: " Que faites-vous de détacher cet ânon? "'),
('mc',11,6,'crampon1923','Ils répondirent comme Jésus le leur avait commandé, et on les laissa faire.'),
('mc',11,7,'crampon1923','Et ils amenèrent l''ânon à Jésus, et ils mirent dessus leurs manteaux, et Jésus s''y assit.'),
('mc',11,8,'crampon1923','Un grand nombre étendirent leurs manteaux le long de la route; d''autres, ayant coupé des branches d''arbres, en jonchèrent le chemin.'),
('mc',11,9,'crampon1923','Et ceux qui marchaient devant, et ceux qui suivaient, criaient: " Hosanna! Béni soit celui qui vient au nom du Seigneur!'),
('mc',11,10,'crampon1923','Béni soit le règne de David notre père, qui va commencer! Hosanna au plus haut des cieux! "'),
('mc',11,11,'crampon1923','Et il entra à Jérusalem, dans le temple; et ayant observé toutes choses, comme déjà l''heure était avancée, il s''en alla à Béthanie avec les Douze.'),
('mc',11,12,'crampon1923','Le lendemain, après qu''ils furent sortis de Béthanie, il eut faim.'),
('mc',11,13,'crampon1923','Apercevant de loin un figuier couvert de feuilles, il s''avança pour voir s''il n''y trouverait pas quelque fruit; et s''en étant approché, il n''y trouva que des feuilles; car ce n''était pas la saison des figues.'),
('mc',11,14,'crampon1923','Alors il dit au figuier: " Qu''à jamais personne ne mange plus de ton fruit! " Ce que ses disciples entendirent.'),
('mc',11,15,'crampon1923','Ils arrivèrent à Jérusalem. Jésus étant entré dans le temple, se mit à chasser ceux qui vendaient et achetaient dans le temple, et il renversa les tables des changeurs, et les sièges de ceux qui vendaient des colombes,'),
('mc',11,16,'crampon1923','et il ne souffrait pas que personne transportât aucun objet à travers le temple.'),
('mc',11,17,'crampon1923','Et il enseignait, en disant: " N''est-il pas écrit: Ma maison sera appelée une maison de prière pour toutes les nations? Mais vous, vous en avez fait une caverne de voleurs. "'),
('mc',11,18,'crampon1923','Ce qu''ayant entendu, les Princes des prêtres et les Scribes cherchaient les moyens de le faire périr; car ils le craignaient, parce que tout le peuple admirait sa doctrine.'),
('mc',11,19,'crampon1923','Le soir étant venu, Jésus sortit de la ville.'),
('mc',11,20,'crampon1923','Or, en repassant de grand matin, les disciples virent le figuier desséché jusqu''à la racine.'),
('mc',11,21,'crampon1923','Et Pierre, se ressouvenant, dit à Jésus: " Maître, voilà que le figuier que vous avez maudit a séché. "'),
('mc',11,22,'crampon1923','Jésus leur répondit: " Ayez foi en Dieu.'),
('mc',11,23,'crampon1923','Je vous le dis, en vérité, si quelqu''un dit à cette montagne: Ote-toi de là, et te jette dans la mer, et s''il ne doute pas dans son cœur, mais qu''il croie que ce qu''il dit arrivera, il le verra s''accomplir.'),
('mc',11,24,'crampon1923','C''est pourquoi, je vous le dis, tout ce que vous demanderez dans la prière, croyez que vous l''obtiendrez, et vous le verrez s''accomplir.'),
('mc',11,25,'crampon1923','Lorsque vous êtes debout pour faire votre prière, si vous avez quelque chose contre quelqu''un, pardonnez, afin que votre Père qui est dans les cieux vous pardonne aussi vos offenses.'),
('mc',11,26,'crampon1923','Si vous ne pardonnez pas, votre Père qui est dans les cieux ne vous pardonnera pas non plus vos offenses. "'),
('mc',11,27,'crampon1923','Ils arrivèrent de nouveau à Jérusalem. Pendant que Jésus se promenait dans le temple, les Princes des prêtres, les Scribes et les Anciens s''approchèrent de lui,'),
('mc',11,28,'crampon1923','et lui dirent: " Par quel pouvoir faites-vous ces choses? Qui vous a donné pouvoir de les faire? "'),
('mc',11,29,'crampon1923','Jésus leur dit: " Je vous ferai, moi aussi, une question; répondez-moi et je vous dirai par quel pouvoir je fais ces choses.'),
('mc',11,30,'crampon1923','Le baptême de Jean, était-il du ciel ou des hommes? Répondez-moi. "'),
('mc',11,31,'crampon1923','Mais ils faisaient en eux-mêmes cette réflexion: " Si nous répondons: Du ciel, il dira: Pourquoi donc n''avez-vous pas cru en lui.'),
('mc',11,32,'crampon1923','Si nous répondons: des hommes... " Ils craignaient le peuple; car tous tenaient Jean pour un véritable prophète.'),
('mc',11,33,'crampon1923','Ils répondirent donc à Jésus: " Nous ne savons — Et moi, dit Jésus, je ne vous dirai pas non plus par quelle autorité je fais ces choses. "'),
('mc',12,1,'crampon1923','Jésus se mit donc à leur parler en paraboles. " Un homme planta une vigne; il l''entoura d''une haie, y creusa un pressoir et y bâtit une tour; puis il la loua à des vignerons et partit pour un autre pays.'),
('mc',12,2,'crampon1923','En temps convenable, il envoya un serviteur aux vignerons pour recevoir d''eux une part de la récolte.'),
('mc',12,3,'crampon1923','Mais s''étant saisis de lui, ils le battirent et le renvoyèrent les mains vides.'),
('mc',12,4,'crampon1923','Il leur envoya encore un autre serviteur, et ils le blessèrent à la tête, et le chargèrent d''outrages.'),
('mc',12,5,'crampon1923','Il en envoya un troisième, qu''ils tuèrent; beaucoup d''autres furent encore, les uns battus, les autres tués par eux.'),
('mc',12,6,'crampon1923','Il restait au maître un fils unique qui lui était très cher; il l''envoya aussi vers eux le dernier, se disant: Ils respecteront mon fils.'),
('mc',12,7,'crampon1923','Mais ces vignerons dirent entre eux: Celui-ci est l''héritier; venez, tuons-le, et l''héritage sera à nous.'),
('mc',12,8,'crampon1923','Et ils se saisirent de lui, le tuèrent et le jetèrent hors de la vigne.'),
('mc',12,9,'crampon1923','Maintenant que fera le maître de la vigne? Il viendra, il exterminera les vignerons et donnera sa vigne à d''autres.'),
('mc',12,10,'crampon1923','N''avez-vous pas lu cette parole de l''Ecriture: La pierre qu''ont rejetée ceux qui bâtissaient, est devenue le sommet de l''angle:'),
('mc',12,11,'crampon1923','c''est le Seigneur qui a fait cela, et c''est une merveille à nos yeux? "'),
('mc',12,12,'crampon1923','Et ils cherchaient à se saisir de lui, sachant qu''ils les avait en vue dans cette parabole; mais ils craignaient le peuple, et le laissant, ils s''en allèrent.'),
('mc',12,13,'crampon1923','Alors ils lui envoyèrent quelques-uns des Pharisiens et des Hérodiens pour le surprendre dans ses paroles.'),
('mc',12,14,'crampon1923','Ceux-ci étant venus, lui dirent: " Maître, nous savons que vous êtes véridique, et n''avez souci de personne; car vous ne considérez point l''extérieur des hommes, mais vous enseignez la voie de Dieu dans la vérité. Est-il permis, ou non, de payer le tribut à César? Devons-nous payer, ou non? "'),
('mc',12,15,'crampon1923','Connaissant leur perfidie, il leur dit: " Pourquoi me tentez-vous? Apportez-moi un denier, que je le voie. "'),
('mc',12,16,'crampon1923','Ils le lui apportèrent; et il leur dit: " De qui sont cette image et cette inscription? — De César ", lui dirent-ils.'),
('mc',12,17,'crampon1923','Alors Jésus leur répondit: " Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu. " Et ils les frappa d''étonnement.'),
('mc',12,18,'crampon1923','Des Sadducéens, qui nient la résurrection, l''abordèrent ensuite et lui firent cette question:'),
('mc',12,19,'crampon1923','" Maître, Moïse nous a prescrit que, si un frère meurt, laissant une femme sans enfants, son frère doit prendre sa femme, et susciter des enfants à son frère.'),
('mc',12,20,'crampon1923','Or, il y avait sept frères; le premier prit une femme, et mourut sans laisser d''enfants.'),
('mc',12,21,'crampon1923','Le second la prit ensuite, et mourut aussi sans laisser d''enfants. Il en arriva de même au troisième,'),
('mc',12,22,'crampon1923','et chacun des sept la prit, et ne laissa pas d''enfants. Après eux tous, mourut aussi la femme.'),
('mc',12,23,'crampon1923','Eh bien, dans la résurrection, lorsqu''ils seront ressuscités, duquel d''entre eux sera-t-elle la femme? car les sept l''ont eue pour femme. "'),
('mc',12,24,'crampon1923','Jésus leur répondit: " N''êtes-vous pas dans l''erreur, parce que vous ne comprenez ni les Ecritures, ni la puissance de Dieu?'),
('mc',12,25,'crampon1923','Car, une fois ressuscités des morts, les hommes ne prennent point de femmes, ni les femmes de maris; mais ils sont comme les anges dans le ciel.'),
('mc',12,26,'crampon1923','Et touchant la résurrection des morts, n''avez-vous pas lu dans le livre de Moïse, au passage du Buisson, ce que Dieu lui dit: Je suis le Dieu d''Abraham, le Dieu d''Isaac, et le Dieu de Jacob?'),
('mc',12,27,'crampon1923','Il n''est pas le Dieu des morts, mais des vivants. Vous êtes donc grandement dans l''erreur. "'),
('mc',12,28,'crampon1923','Un des Scribes, qui avait entendu cette discussion, voyant que Jésus leur avait bien répondu, s''approcha et lui demanda: " Quel est le premier de tous les commandements? "'),
('mc',12,29,'crampon1923','Jésus lui répondit: " Le premier de tous est celui-ci: Ecoute Israël: le Seigneur notre Dieu, est seul le Seigneur.'),
('mc',12,30,'crampon1923','Tu aimeras donc le Seigneur ton Dieu, de tout ton cœur, de toute ton âme, de tout ton esprit, et de toute ta force. C''est là le premier commandement.'),
('mc',12,31,'crampon1923','Le second lui est semblable: Tu aimeras ton prochain comme toi-même. Il n''y a pas d''autre commandement plus grand que ceux-là. "'),
('mc',12,32,'crampon1923','Le Scribe lui dit: " Bien, Maître, vous avez dit selon la vérité que Dieu est unique, et qu''il n''y en a point d''autre que lui;'),
('mc',12,33,'crampon1923','et que l''aimer de tout son cœur, de tout son esprit, de toute son âme et de toute sa force, et aimer son prochain comme soi-même, c''est plus que tous les holocaustes et tous les sacrifices. "'),
('mc',12,34,'crampon1923','Jésus, voyant qu''il avait répondu avec sagesse, lui dit: " Tu n''es pas loin du royaume de Dieu. " Et personne n''osait plus lui poser de questions.'),
('mc',12,35,'crampon1923','Jésus, continuant à enseigner dans le temple, dit: " Comment les Scribes disent-ils que le Christ est fils de David?'),
('mc',12,36,'crampon1923','Car David lui-même parle ainsi par l''Esprit-Saint: Le Seigneur a dit à mon Seigneur: Asseyez-vous à ma droite jusqu''à ce que je fasse de vos ennemis l''escabeau de vos pieds. —'),
('mc',12,37,'crampon1923','David lui-même l''appelle Seigneur, comment donc est-il son fils? " Et la foule nombreuse prenait plaisir à l''entendre.'),
('mc',12,38,'crampon1923','Il leur disait encore dans son enseignement: " Gardez-vous des Scribes qui aiment à se promener en longues robes, à recevoir les salutations dans les places publiques,'),
('mc',12,39,'crampon1923','les premiers sièges dans les synagogues et les premières places dans les festins:'),
('mc',12,40,'crampon1923','ces gens qui dévorent les maisons des veuves et font par ostentation de longues prières, subiront une plus forte condamnation. "'),
('mc',12,41,'crampon1923','S''étant assis vis-à-vis du Tronc, Jésus considérait comment le peuple y jetait de la monnaie; plusieurs riches y mettaient beaucoup.'),
('mc',12,42,'crampon1923','Une pauvre veuve étant venue, elle y mit deux petites pièces, valant ensemble le quart d''un as.'),
('mc',12,43,'crampon1923','Alors Jésus, appelant ses disciples, leur dit: " Je vous le dis, en vérité, cette pauvre veuve a donné plus que tous ceux qui ont mis dans le Tronc.'),
('mc',12,44,'crampon1923','Car tous ont mis de leur superflu, mais cette femme a donné de son nécessaire, tout ce qu''elle possédait, tout ce qu''elle avait pour vivre. "'),
('mc',13,1,'crampon1923','Comme Jésus sortait du temple, un de ses disciples lui dit: " Maître, voyez quelles pierres et quelles constructions! "'),
('mc',13,2,'crampon1923','Jésus lui répondit: " Tu vois ces grandes constructions? Il n''y sera pas laissé pierre sur pierre qui ne soit renversée. "'),
('mc',13,3,'crampon1923','Lorsqu''il se fut assis sur la montagne des Oliviers, en face du temple, Pierre, Jacques, Jean et André l''interrogèrent en particulier:'),
('mc',13,4,'crampon1923','" Dites-nous quand cela arrivera, et à quel signe on connaîtra que toutes ces choses seront près de s''accomplir? "'),
('mc',13,5,'crampon1923','Jésus leur répondant, commença ce discours: " Prenez garde que nul ne vous séduise.'),
('mc',13,6,'crampon1923','Car plusieurs viendront sous mon nom, disant: C''est moi le Christ; et ils en séduiront un grand nombre.'),
('mc',13,7,'crampon1923','Quand vous entendrez parler de guerres et de bruits de guerres, ne vous troublez point; car il faut que ces choses arrivent: mais ce ne sera pas encore la fin.'),
('mc',13,8,'crampon1923','On verra se soulever peuple contre peuple, royaume contre royaume; il y aura des tremblements de terre en divers lieux; il y aura des famines. Ce sera le commencement des douleurs.'),
('mc',13,9,'crampon1923','Prenez garde à vous-mêmes. On vous traduira devant les tribunaux et les synagogues; vous y serez battus; vous comparaîtrez devant les gouverneurs et les rois, à cause de moi, pour me rendre témoignage devant eux.'),
('mc',13,10,'crampon1923','Il faut qu''auparavant l''Evangile soit prêché à toutes les nations.'),
('mc',13,11,'crampon1923','Lors donc qu''on vous emmènera pour vous faire comparaître, ne pensez point d''avance à ce que vous direz; mais dites ce qui vous sera donné à l''heure même; car ce n''est pas vous qui parlerez, mais l''Esprit-Saint.'),
('mc',13,12,'crampon1923','Le frère livrera son frère à la mort, et le père son fils; les enfants s''élèveront contre leurs parents, et les mettront à mort.'),
('mc',13,13,'crampon1923','Et vous serez en haine à tous à cause de mon nom. Mais celui qui persévérera jusqu''à la fin sera sauvé.'),
('mc',13,14,'crampon1923','Lorsque vous verrez l''abomination de la désolation établie où elle ne doit pas être, — que celui qui lit, comprenne! — alors que ceux qui seront en Judée s''enfuient dans les montagnes.'),
('mc',13,15,'crampon1923','Que celui qui sera sur le toit ne descende pas dans sa maison, et n''y entre pas pour prendre quelque objet.'),
('mc',13,16,'crampon1923','Et que celui qui sera allé dans son champ ne revienne pas pour prendre son manteau.'),
('mc',13,17,'crampon1923','Mais malheur aux femmes qui seront enceintes, ou qui allaiteront en ces jours-là!'),
('mc',13,18,'crampon1923','Priez pour que ces choses n''arrivent pas en hiver.'),
('mc',13,19,'crampon1923','Car il y aura, en ces jours, des tribulations telles qu''il n''y en a point eu depuis le commencement du monde, que Dieu a créé, jusqu''à présent, et qu''il n''y en aura jamais.'),
('mc',13,20,'crampon1923','Et si le Seigneur n''avait abrégé ces jours, nul homme ne serait sauvé; mais il les a abrégés à cause des élus qu''il a choisis.'),
('mc',13,21,'crampon1923','Si quelqu''un vous dit alors: Le Christ est ici, il est là, ne le croyez point.'),
('mc',13,22,'crampon1923','Car il s''élèvera de faux christs et de faux prophètes, et ils feront des signes et des prodiges, jusqu''à séduire, s''il se pouvait, les élus mêmes.'),
('mc',13,23,'crampon1923','Pour vous, prenez garde! Voyez, je vous ai tout annoncé d''avance.'),
('mc',13,24,'crampon1923','Mais en ces jours-là, après cette tribulation, le soleil s''obscurcira, la lune ne donnera plus sa lumière,'),
('mc',13,25,'crampon1923','les étoiles du ciel tomberont, et les puissances qui sont dans les cieux seront ébranlées.'),
('mc',13,26,'crampon1923','Alors on verra le Fils de l''homme venir dans les nuées avec une grande puissance et une grande gloire.'),
('mc',13,27,'crampon1923','Et alors il enverra ses anges rassembler ses élus des quatre vents, de l''extrémité de la terre jusqu''à l''extrémité du ciel.'),
('mc',13,28,'crampon1923','Ecoutez cette comparaison du figuier: Dès que ses rameaux sont tendres et qu''il pousse ses feuilles, vous savez que l''été est proche.'),
('mc',13,29,'crampon1923','Ainsi, quand vous verrez ces choses arriver, sachez que le Fils de l''homme est proche, qu''il est à la porte.'),
('mc',13,30,'crampon1923','Je vous le dis en vérité, cette génération ne passera point que tout cela n''arrive.'),
('mc',13,31,'crampon1923','Le ciel et la terre passeront, mais mes paroles ne passeront point.'),
('mc',13,32,'crampon1923','Pour ce qui est de ce jour et de cette heure, nul ne les connaît, ni les anges dans le ciel, ni le Fils, mais le Père seul.'),
('mc',13,33,'crampon1923','Prenez garde, veillez et priez; car vous ne savez pas quand ce sera le moment.'),
('mc',13,34,'crampon1923','C''est ainsi qu''un homme, ayant laissé sa maison pour aller en voyage, après avoir remis l''autorité à ses serviteurs et assigné à chacun sa tâche, commande au portier de veiller.'),
('mc',13,35,'crampon1923','Veillez donc, car vous ne savez pas quand viendra le maître de la maison, le soir, ou au milieu de la nuit, ou au chant du coq, ou le matin;'),
('mc',13,36,'crampon1923','de peur que, survenant tout à coup, il ne vous trouve endormis.'),
('mc',13,37,'crampon1923','Ce que je vous dis, je le dis à tous: Veillez! "'),
('mc',14,1,'crampon1923','La Pâque et les Azymes devaient avoir lieu deux jours après; et les Princes des prêtres et les Scribes cherchaient les moyens de se saisir de Jésus par ruse, afin de le faire mourir.'),
('mc',14,2,'crampon1923','" Mais, disaient-ils, que ce ne soit pas pendant la fête, de peur qu''il n''y ait du tumulte parmi le peuple. "'),
('mc',14,3,'crampon1923','Comme Jésus était à Béthanie, dans la maison de Simon le lépreux, une femme entra pendant qu''il se trouvait à table. Elle tenait un vase d''albâtre plein d''un parfum de nard pur d''un grand prix; et ayant brisé le vase, elle répandit le parfum sur sa tête.'),
('mc',14,4,'crampon1923','Plusieurs de ceux qui étaient là en témoignaient entre eux leur mécontentement: " Pourquoi perdre ainsi ce parfum?'),
('mc',14,5,'crampon1923','On aurait pu le vendre plus de trois cents deniers, et les donner aux pauvres. " Et ils se fâchaient contre elle.'),
('mc',14,6,'crampon1923','Mais Jésus dit: " Laissez-la; pourquoi lui faites-vous de la peine? C''est une bonne action qu''elle a faite à mon égard.'),
('mc',14,7,'crampon1923','Car vous avez toujours les pauvres avec vous, et toutes les fois que vous voulez, vous pouvez leur faire du bien; mais moi, vous ne m''avez pas toujours. —'),
('mc',14,8,'crampon1923','Cette femme a fait ce qu''elle a pu; elle a d''avance embaumé mon corps pour la sépulture.'),
('mc',14,9,'crampon1923','Je vous le dis, en vérité, partout où sera prêché cet évangile, dans le monde entier, on racontera aussi ce qu''elle a fait, en mémoire d''elle. "'),
('mc',14,10,'crampon1923','Or, Judas l''Iscariote, l''un des Douze, alla vers les Princes des prêtres pour livrer Jésus.'),
('mc',14,11,'crampon1923','Après l''avoir entendu, ils furent dans la joie et promirent de lui donner de l''argent. Et Judas cherchait une occasion favorable pour le livrer.'),
('mc',14,12,'crampon1923','Le premier jour des Azymes, où l''on immolait la Pâque, ses disciples dirent à Jésus: " Où voulez-vous que nous allions vous préparer ce qu''il faut pour manger la Pâque? "'),
('mc',14,13,'crampon1923','Et il envoya deux de ses disciples, et leur dit: " Allez à la ville; vous rencontrerez un homme portant une cruche d''eau, suivez-le.'),
('mc',14,14,'crampon1923','Quelque part qu''il entre, dites au propriétaire de la maison: Le Maître te fait dire: Où est la salle où je pourrai manger la Pâque avec mes disciples?'),
('mc',14,15,'crampon1923','Et il vous montrera un grand cénacle meublé et tout prêt: faites-nous là les préparatifs. "'),
('mc',14,16,'crampon1923','Ses disciples partirent et allèrent à la ville; et ils trouvèrent les choses comme il le leur avait dit, et ils préparèrent la Pâque.'),
('mc',14,17,'crampon1923','Sur le soir, Jésus vint avec les Douze.'),
('mc',14,18,'crampon1923','Pendant qu''ils étaient à table et mangeaient, Jésus dit: " Je vous le dis en vérité, un de vous me trahira; celui qui mange avec moi! "'),
('mc',14,19,'crampon1923','Et ils se mirent à s''attrister et à lui dire l''un après l''autre: " Est-ce moi? "'),
('mc',14,20,'crampon1923','Il leur répondit: " C''est un des Douze, qui met avec moi la main dans le plat.'),
('mc',14,21,'crampon1923','Pour le Fils de l''homme, il s''en va, ainsi qu''il est écrit de lui; mais malheur à l''homme par qui le Fils de l''homme est trahi! Mieux vaudrait pour cet homme qu''il ne fût pas né. "'),
('mc',14,22,'crampon1923','Pendant le repas, Jésus prit du pain, et après avoir prononcé une bénédiction, il le rompit, et le leur donna, en disant: " Prenez, ceci est mon corps. "'),
('mc',14,23,'crampon1923','Il prit ensuite la coupe, et, ayant rendu grâces, il la leur donna, et ils en burent tous.'),
('mc',14,24,'crampon1923','Et il leur dit: " Ceci est mon sang, le sang de la nouvelle alliance, répandu pour la multitude.'),
('mc',14,25,'crampon1923','Je vous le dis, en vérité, je ne boirai plus jamais du fruit de la vigne, jusqu''au jour où je le boirai nouveau dans le royaume de Dieu. "'),
('mc',14,26,'crampon1923','Après le chant de l''hymne, ils s''en allèrent au mont des Oliviers.'),
('mc',14,27,'crampon1923','Alors Jésus leur dit: " Je serai pour vous tous, cette nuit, une occasion de chute, car il est écrit: Je frapperai le pasteur, et les brebis seront dispersées.'),
('mc',14,28,'crampon1923','Mais, après que je serai ressuscité, je serai à votre tête, en Galilée. "'),
('mc',14,29,'crampon1923','Pierre lui dit: " Quand vous seriez pour tous une occasion de chute, vous ne le seriez jamais pour moi. "'),
('mc',14,30,'crampon1923','Jésus lui dit: " Je te le dis, en vérité, aujourd''hui, cette nuit même, avant que le coq ait chanté deux fois, trois fois tu me renieras. "'),
('mc',14,31,'crampon1923','Mais Pierre insistait encore plus: " Quand il me faudrait mourir avec vous, je ne vous renierai point. " Et tous dirent de même.'),
('mc',14,32,'crampon1923','Ils arrivèrent à un domaine appelé Gethsémani, et il dit à ses disciples: " Asseyez-vous ici pendant que je prierai. "'),
('mc',14,33,'crampon1923','Et ayant pris avec lui Pierre, Jacques et Jean, il commença à sentir de la frayeur et de l''abattement.'),
('mc',14,34,'crampon1923','Et il leur dit: " Mon âme est triste jusqu''à la mort; restez ici et veillez. "'),
('mc',14,35,'crampon1923','S''étant un peu avancé, il se jeta contre terre; et il priait que cette heure, s''il se pouvait, s''éloignât de lui.'),
('mc',14,36,'crampon1923','Et il disait: " Abba (Père), tout vous est possible, éloignez de moi ce calice; cependant, non pas ma volonté, mais la vôtre! "'),
('mc',14,37,'crampon1923','Il vint ensuite et trouva ses disciples endormis; et il dit à Pierre: " Simon, tu dors! Tu n''as pu veiller une heure!'),
('mc',14,38,'crampon1923','Veillez et priez afin que vous n''entriez point en tentation. L''esprit est prompt, mais la chair est faible. "'),
('mc',14,39,'crampon1923','Et, s''éloignant de nouveau, il pria, disant les mêmes paroles.'),
('mc',14,40,'crampon1923','Puis, étant revenu, il les trouva encore endormis; car leurs yeux étaient appesantis, et ils ne savaient que lui répondre.'),
('mc',14,41,'crampon1923','Il revint une troisième fois et leur dit: " Dormez, maintenant, et reposez-vous. — C''est assez! L''heure est venue; voici que le Fils de l''homme est livré aux mains des pécheurs.'),
('mc',14,42,'crampon1923','Levez-vous, allons; celui qui me trahit est près d''ici. "'),
('mc',14,43,'crampon1923','Au même moment, comme il parlait encore, arrive Judas, l''un des Douze, et avec lui une grande troupe armée d''épées et de bâtons, envoyée par les Princes des prêtres, par les Scribes et par les Anciens.'),
('mc',14,44,'crampon1923','Le traître leur avait donné ce signe: " Celui que je baiserai, c''est lui, saisissez-le, et emmenez-le sûrement. "'),
('mc',14,45,'crampon1923','Dès qu''il fut arrivé, s''approchant de Jésus, il dit: " Maître! " et il le baisa.'),
('mc',14,46,'crampon1923','Les autres jetèrent les mains sur lui et l''arrêtèrent.'),
('mc',14,47,'crampon1923','Un de ceux qui étaient là, tirant l''épée, en frappa le serviteur du grand prêtre, et lui enleva l''oreille.'),
('mc',14,48,'crampon1923','Jésus, prenant la parole, leur dit: " Vous êtes venus comme à un brigand, avec des épées et des bâtons pour me prendre.'),
('mc',14,49,'crampon1923','Tous les jours j''étais parmi vous, enseignant dans le temple, et vous ne m''avez pas arrêté; mais c''est afin que les Écritures s''accomplissent. "'),
('mc',14,50,'crampon1923','Alors tous ses disciples l''abandonnèrent et prirent la fuite.'),
('mc',14,51,'crampon1923','Un jeune homme le suivait, couvert seulement d''un drap; on se saisit de lui;'),
('mc',14,52,'crampon1923','mais il lâcha le drap, et s''enfuit nu de leurs mains.'),
('mc',14,53,'crampon1923','Ils emmenèrent Jésus chez le grand prêtre, où s''assemblèrent tous les Princes des prêtres, les Scribes et les Anciens.'),
('mc',14,54,'crampon1923','Pierre le suivit de loin, jusque dans l''intérieur de la cour du grand prêtre, et s''étant assis près du feu avec les serviteurs, il se chauffait.'),
('mc',14,55,'crampon1923','Cependant les Princes des prêtres et tout le conseil cherchaient un témoignage contre Jésus pour le faire mourir, et ils n''en trouvaient point.'),
('mc',14,56,'crampon1923','Car plusieurs déposèrent faussement contre lui, mais les dépositions ne s''accordaient pas.'),
('mc',14,57,'crampon1923','Enfin quelques-uns se levant, portèrent contre lui ce faux témoignage:'),
('mc',14,58,'crampon1923','" Nous l''avons entendu dire: Je détruirai ce temple fait de main d''homme, et en trois jours j''en rebâtirai un autre qui ne sera pas fait de main d''homme. "'),
('mc',14,59,'crampon1923','Mais sur cela même leurs témoignages ne s''accordaient pas.'),
('mc',14,60,'crampon1923','Alors le grand prêtre se leva, et venant au milieu, il interrogea Jésus, disant: " Ne réponds-tu rien à ce que ces hommes déposent contre toi? "'),
('mc',14,61,'crampon1923','Mais Jésus garda le silence et ne répondit rien. Le grand prêtre l''interrogea de nouveau et lui dit: " Es-tu le Christ, le Fils de celui qui est Béni? "'),
('mc',14,62,'crampon1923','Jésus lui dit: " Je le suis, et vous verrez le Fils de l''homme siéger à la droite du Tout-Puissant, et venir environné des nuées du ciel. "'),
('mc',14,63,'crampon1923','Alors le grand prêtre déchira ses vêtements et dit: " Qu''avons-nous donc besoin de témoins?'),
('mc',14,64,'crampon1923','Vous avez entendu le blasphème; que vous en semble? " Tous prononcèrent qu''il méritait la mort.'),
('mc',14,65,'crampon1923','Et quelques-uns se mirent à cracher sur lui, et, lui voilant le visage, ils le frappaient du poing, en lui disant: " Devine "; et les valets le souffletaient.'),
('mc',14,66,'crampon1923','Pendant que Pierre était en bas, dans la cour, il vint une des servantes du grand prêtre;'),
('mc',14,67,'crampon1923','et voyant Pierre qui se chauffait, elle le regarda et lui dit: " Toi aussi, tu étais avec Jésus de Nazareth. "'),
('mc',14,68,'crampon1923','Mais il le nia, en disant: " Je ne sais, ni ne comprends ce que tu veux dire. " Puis il s''en alla, gagnant le vestibule; et le coq chanta.'),
('mc',14,69,'crampon1923','La servante l''ayant aperçu de nouveau, se mit à dire aux assistants: " Voilà un de ces gens-là. "'),
('mc',14,70,'crampon1923','Et il le nia de nouveau. Un peu après, ceux qui étaient là dirent à Pierre: " Tu es certainement des leurs, car tu es Galiléen. "'),
('mc',14,71,'crampon1923','Alors il se mit à faire des imprécations et à dire avec serment: " Je ne connais pas l''homme dont vous parlez. "'),
('mc',14,72,'crampon1923','Et aussitôt, pour la seconde fois, le coq chanta. Et Pierre se souvint de la parole que Jésus lui avait dite: " Avant que le coq ait chanté deux fois, trois fois tu me renieras "; et il se mit à pleurer.'),
('mc',15,1,'crampon1923','Dès le matin, sans retard, les Princes des prêtres tinrent conseil avec les Anciens et les Scribes, et tout le Sanhédrin. Et après avoir lié Jésus, ils l''emmenèrent et le livrèrent à Pilate.'),
('mc',15,2,'crampon1923','Pilate l''interrogea: " Es-tu le roi des Juifs? " Jésus lui répondit: " Tu le dis. "'),
('mc',15,3,'crampon1923','Comme les Princes des prêtres portaient contre lui diverses accusations,'),
('mc',15,4,'crampon1923','Pilate l''interrogea de nouveau, disant: " Tu ne réponds rien? Vois de combien de choses ils t''accusent."'),
('mc',15,5,'crampon1923','Mais Jésus ne fit plus aucune réponse, de sorte que Pilate était dans l''étonnement.'),
('mc',15,6,'crampon1923','Cependant, à chaque fête de Pâque, il leur relâchait un prisonnier, celui qu''ils demandaient.'),
('mc',15,7,'crampon1923','Or, il y avait dans la prison le nommé Barabbas, avec les séditieux ses complices, pour un meurtre qu''ils avaient commis dans la sédition.'),
('mc',15,8,'crampon1923','La foule étant montée se mit à réclamer ce qu''il leur accordait toujours.'),
('mc',15,9,'crampon1923','Pilate leur répondit: " Voulez-vous que je vous délivre le roi des Juifs? "'),
('mc',15,10,'crampon1923','Car il savait que c''était par envie que les Princes des prêtres l''avaient livré.'),
('mc',15,11,'crampon1923','Mais les Pontifes excitèrent le peuple, afin d''obtenir qu''il leur relachât plutôt Barabbas.'),
('mc',15,12,'crampon1923','Pilate, reprenant la parole, leur dit: " Que voulez-vous donc que je fasse de celui que vous appelez le roi des Juifs? "'),
('mc',15,13,'crampon1923','Ils crièrent de nouveau: " Crucifiez-le! "'),
('mc',15,14,'crampon1923','Pilate leur dit: " Mais quel mal a-t-il fait? " Et ils crièrent encore plus fort: " Crucifiez-le! "'),
('mc',15,15,'crampon1923','Pilate, voulant satisfaire le peuple, leur délivra Barabbas; et après avoir fait flageller Jésus, il le livra pour être crucifié.'),
('mc',15,16,'crampon1923','Les soldats conduisirent Jésus dans l''intérieur de la cour, c''est-à-dire dans le prétoire, et ils convoquèrent toute la cohorte.'),
('mc',15,17,'crampon1923','Et l''ayant revêtu de pourpre, ils ceignirent sa tête d''une couronne d''épines qu''ils avaient tressée.'),
('mc',15,18,'crampon1923','Puis ils se mirent à le saluer: " Salut, roi des Juifs! "'),
('mc',15,19,'crampon1923','Et ils lui frappaient la tête avec un roseau, et ils crachaient sur lui, et, fléchissant les genoux, ils lui rendaient hommage.'),
('mc',15,20,'crampon1923','Après s''être ainsi joués de lui, ils lui ôtèrent la pourpre, lui remirent ses vêtements, et l''emmenèrent pour le crucifier.'),
('mc',15,21,'crampon1923','Un certain Simon, de Cyrène, le père d''Alexandre et de Rufus, passant par là en revenant des champs, ils le réquisitionnent pour porter la croix de Jésus,'),
('mc',15,22,'crampon1923','qu''ils entraînent au lieu dit Golgotha, ce que l''on interprète: lieu du Crâne.'),
('mc',15,23,'crampon1923','Et ils lui donnaient à boire du vin mêlé de myrrhe; mais il n''en prit pas.'),
('mc',15,24,'crampon1923','L''ayant crucifié, ils se partagent ses vêtements, tirant au sort ce que chacun en prendrait.'),
('mc',15,25,'crampon1923','Il était la troisième heure lorsqu''on le crucifia.'),
('mc',15,26,'crampon1923','L''inscription indiquant la cause de sa condamnation portait: " Le roi des Juifs. "'),
('mc',15,27,'crampon1923','Ils crucifièrent avec lui deux brigands, l''un à sa droite, l''autre à sa gauche.'),
('mc',15,28,'crampon1923','Ainsi fut accomplie cette parole de l''Ecriture: " Et il a été mis au rang des malfaiteurs. "'),
('mc',15,29,'crampon1923','Les passants l''insultaient, en branlant la tête et disant: " Ah! Toi qui détruis le temple et le rebâtis en trois jours,'),
('mc',15,30,'crampon1923','sauve-toi toi-même, et descends de la croix. "'),
('mc',15,31,'crampon1923','Les Princes des prêtres aussi, avec les Scribes, le raillaient entre eux, et disaient: " Il en a sauvé d''autres, et il ne peut se sauver lui-même.'),
('mc',15,32,'crampon1923','Que le Christ, le roi d''Israël, descende maintenant de la croix, afin que nous voyions et que nous croyions. " Ceux même qui étaient crucifiés avec lui l''insultaient.'),
('mc',15,33,'crampon1923','La sixième heure étant arrivée, les ténèbres se répandirent sur toute la terre jusqu''à la neuvième heure.'),
('mc',15,34,'crampon1923','Et à la neuvième heure, Jésus s''écria d''une voix forte: " Eloï, Eloï, lama sabacthani. " Ce qui s''interprète: " Mon Dieu, mon Dieu, pourquoi m''avez-vous abandonné? "'),
('mc',15,35,'crampon1923','Quelques-uns de ceux qui étaient là, l''ayant entendu, disaient: " Voyez! Il appelle Elie. "'),
('mc',15,36,'crampon1923','Et l''un d''eux courut emplir une éponge de vinaigre, et l''ayant mise au bout d''un roseau, il lui donna à boire, en disant: " Laissez, voyons si Elie viendra le faire descendre. "'),
('mc',15,37,'crampon1923','Mais Jésus, ayant jeté un grand cri, expira.'),
('mc',15,38,'crampon1923','Et le voile du sanctuaire se déchira en deux, depuis le haut jusqu''en bas.'),
('mc',15,39,'crampon1923','Le centurion qui se tenait en face de Jésus, voyant qu''il avait expiré en jetant un tel cri, dit: " Vraiment cet homme était Fils de Dieu. "'),
('mc',15,40,'crampon1923','Il y avait aussi des femmes qui regardaient de loin, entre autres Marie-Madeleine, Marie, mère de Jacques le Mineur et de Joseph, et Salomé,'),
('mc',15,41,'crampon1923','qui le suivaient déjà et le servaient lorsqu''il était en Galilée, et plusieurs autres qui étaient montées à Jérusalem avec lui.'),
('mc',15,42,'crampon1923','Le soir étant déjà venu, comme c''était la Préparation, c''est-à-dire la veille du sabbat,'),
('mc',15,43,'crampon1923','arriva Joseph d''Arimathie: c''était un membre du grand conseil fort considéré, qui attendait, lui aussi, le royaume de Dieu. Il était allé hardiment auprès de Pilate, demander le corps de Jésus.'),
('mc',15,44,'crampon1923','Mais Pilate, surpris qu''il fût mort si tôt, fit venir le centurion, et lui demanda s''il y avait longtemps que Jésus était mort.'),
('mc',15,45,'crampon1923','Sur le rapport du centurion, il accorda le corps à Joseph.'),
('mc',15,46,'crampon1923','Alors Joseph, ayant acheté un linceul, descendit Jésus, l''enveloppa du linceul, et le déposa dans un sépulcre, taillé dans le roc; puis il roula une pierre à l''entrée du sépulcre.'),
('mc',15,47,'crampon1923','Or Marie-Madeleine, et Marie, mère de Joseph, observaient où on le déposait.'),
('mc',16,1,'crampon1923','Lorsque le sabbat fut passé, Marie-Madeleine, Marie, mère de Jacques, et Salomé, achetèrent des aromates, afin d''aller embaumer Jésus.'),
('mc',16,2,'crampon1923','Et, le premier jour de la semaine, de grand matin, elles arrivèrent au sépulcre, le soleil étant déjà levé.'),
('mc',16,3,'crampon1923','Elles se disaient entre elles: " Qui nous ôtera la pierre qui ferme l''entrée du sépulcre? "'),
('mc',16,4,'crampon1923','Et, levant les yeux, elles aperçurent que la pierre avait été roulée de côté; elle était en effet fort grande.'),
('mc',16,5,'crampon1923','Entrant alors dans le sépulcre, elles virent un jeune homme assis à droite, vêtu d''une robe blanche, et elles furent saisies de frayeur.'),
('mc',16,6,'crampon1923','Mais il leur dit: " Ne vous effrayez pas; vous cherchez Jésus de Nazareth, qui a été crucifié: il est ressuscité, il n''est point ici; voici le lieu où on l''avait mis.'),
('mc',16,7,'crampon1923','Mais allez dire à ses disciples et à Pierre qu''il va se mettre à votre tête en Galilée; c''est là que vous le verrez, comme il vous l''a dit. "'),
('mc',16,8,'crampon1923','Sortant aussitôt du sépulcre, elles s''enfuirent, car le tremblement et la stupeur les avaient saisies; et elles ne dirent rien à personne, à cause de leur effroi.'),
('mc',16,9,'crampon1923','Jésus étant donc ressuscité le matin du premier jour de la semaine, il apparut d''abord à Marie-Madeleine, de laquelle il avait chassé sept démons;'),
('mc',16,10,'crampon1923','et elle alla l''annoncer à ceux qui avaient été avec lui, et qui s''affligeaient et pleuraient.'),
('mc',16,11,'crampon1923','Quand ils entendirent qu''il vivait et qu''elle l''avait vu, ils ne la crurent point.'),
('mc',16,12,'crampon1923','Ensuite Jésus se montra en chemin sous une autre forme à deux d''entre eux qui allaient à la campagne.'),
('mc',16,13,'crampon1923','Ceux-ci revinrent l''annoncer aux autres, qui ne les crurent pas non plus.'),
('mc',16,14,'crampon1923','Plus tard, il se montra aux Onze eux-mêmes, pendant qu''ils étaient à table; et il leur reprocha leur incrédulité et la dureté de leur cœur, de n''avoir pas cru ceux qui l''avaient vu ressuscité.'),
('mc',16,15,'crampon1923','Puis il leur dit: " Allez par tout le monde, et prêchez l''Evangile à toute créature.'),
('mc',16,16,'crampon1923','Celui qui croira et sera baptisé, sera sauvé; celui qui ne croira pas, sera condamné.'),
('mc',16,17,'crampon1923','Et voici les miracles qui accompagneront ceux qui auront cru: en mon nom, ils chasseront les démons; ils parleront de nouvelles langues;'),
('mc',16,18,'crampon1923','ils prendront les serpents, et s''ils boivent quelque breuvage mortel, il ne leur fera point de mal; ils imposeront les mains aux malades, et les malades seront guéris. "'),
('mc',16,19,'crampon1923','Après leur avoir ainsi parlé, le Seigneur Jésus fut enlevé au ciel, et s''assit à la droite de Dieu.'),
('mc',16,20,'crampon1923','Pour eux, étant partis, ils prêchèrent en tous lieux, le Seigneur travaillant avec eux, et confirmant leur parole par les miracles qui l''accompagnaient.'),
('lc',1,1,'crampon1923','Après que plusieurs ont entrepris de composer une relation des choses dont on a parmi nous pleine conviction,'),
('lc',1,2,'crampon1923','conformément à ce que nous ont transmis ceux qui ont été dès le commencement, témoins oculaires et ministres de la parole;'),
('lc',1,3,'crampon1923','j''ai résolu moi aussi, après m''être appliqué à connaître exactement toutes choses depuis l''origine, de t''en écrire le récit suivi, excellent Théophile,'),
('lc',1,4,'crampon1923','afin que tu reconnaisses la certitude des enseignements que tu as reçus.'),
('lc',1,5,'crampon1923','Aux jours d''Hérode, roi de Judée, il y avait un prêtre, nommé Zacharie, de la classe d''Abia; et sa femme, qui était une des filles d''Aaron, s''appelait Elisabeth.'),
('lc',1,6,'crampon1923','Tous deux étaient justes devant Dieu, marchant dans tous les commandements et ordonnances du Seigneur, d''une manière irréprochable.'),
('lc',1,7,'crampon1923','Ils n''avaient point d''enfants, parce qu''Elisabeth était stérile, et ils étaient l''un et l''autre avancés en âge.'),
('lc',1,8,'crampon1923','Or, pendant que Zacharie s''acquittait devant Dieu des fonctions sacerdotales, dans l''ordre de sa classe,'),
('lc',1,9,'crampon1923','il fut désigné par le sort, selon la coutume observée par les prêtres, pour entrer dans le sanctuaire du Seigneur et y offrir l''encens.'),
('lc',1,10,'crampon1923','Et toute la multitude du peuple était dehors en prière à l''heure de l''encens.'),
('lc',1,11,'crampon1923','Mais un ange du Seigneur lui apparut, debout à droite de l''autel de l''encens.'),
('lc',1,12,'crampon1923','Zacharie, en le voyant, fut troublé, et la crainte le saisit.'),
('lc',1,13,'crampon1923','Mais l''ange lui dit: " Ne crains point, Zacharie, car ta prière a été exaucée; ta femme Elisabeth te donnera un fils que tu appelleras Jean.'),
('lc',1,14,'crampon1923','Il sera pour toi un sujet de joie et d''allégresse, et beaucoup se réjouiront de sa naissance;'),
('lc',1,15,'crampon1923','car il sera grand devant le Seigneur. Il ne boira ni vin, ni rien qui enivre, car il sera rempli de l''Esprit-Saint dès le sein de sa mère.'),
('lc',1,16,'crampon1923','Il convertira beaucoup d''enfants d''Israël au Seigneur leur Dieu;'),
('lc',1,17,'crampon1923','et lui-même marchera devant lui, dans l''esprit et la puissance d''Elie, pour ramener les cœurs des pères vers les enfants, et les indociles à la sagesse des justes, afin de préparer au Seigneur un peuple parfait. "'),
('lc',1,18,'crampon1923','Zacharie dit à l''ange: " A quoi reconnaîtrai-je que cela sera? Car je suis vieux, et ma femme est avancée en âge. "'),
('lc',1,19,'crampon1923','L''ange lui répondit: " Je suis Gabriel, qui me tiens devant Dieu; j''ai été envoyé pour te parler et t''annoncer cette heureuse nouvelle.'),
('lc',1,20,'crampon1923','Et voici que tu seras muet et ne pourras parler jusqu''au jour où ces choses arriveront, parce que tu n''as pas cru à mes paroles, qui s''accompliront en leur temps. "'),
('lc',1,21,'crampon1923','Cependant le peuple attendait Zacharie, et il s''étonnait qu''il demeurât si longtemps dans le sanctuaire.'),
('lc',1,22,'crampon1923','Mais étant sorti, il ne pouvait leur parler, et ils comprirent qu''il avait eu une vision dans le sanctuaire, ce qu''il leur faisait entendre par signes; et il resta muet.'),
('lc',1,23,'crampon1923','Quand les jours de son ministère furent accomplis, il s''en alla en sa maison.'),
('lc',1,24,'crampon1923','Quelque temps après, Elisabeth, sa femme, conçut, et elle se tint cachée pendant cinq mois, disant:'),
('lc',1,25,'crampon1923','" C''est une grâce que le Seigneur m''a faite, au jour où il m''a regardée pour ôter mon opprobre parmi les hommes. "'),
('lc',1,26,'crampon1923','Au sixième mois, l''ange Gabriel fut envoyé de Dieu dans une ville de Galilée appelée Nazareth,'),
('lc',1,27,'crampon1923','auprès d''une vierge qui était fiancée à un homme de la maison de David, nommé Joseph, et le nom de la vierge était Marie.'),
('lc',1,28,'crampon1923','L''ange étant entré où elle était, lui dit: " Je vous salue, pleine de grâce; le Seigneur est avec vous, vous êtes bénie entre les femmes. "'),
('lc',1,29,'crampon1923','Marie l''ayant aperçu, fut troublée de ses paroles, et elle se demandait ce que pouvait signifier cette salutation.'),
('lc',1,30,'crampon1923','L''ange lui dit: " Ne craignez point, Marie, car vous avez trouvé grâce devant Dieu.'),
('lc',1,31,'crampon1923','Voici que vous concevrez en votre sein, et vous enfanterez un fils, et vous lui donnerez le nom de Jésus.'),
('lc',1,32,'crampon1923','Il sera grand, on l''appellera le Fils du Très-Haut; le Seigneur Dieu lui donnera le trône de David son père; il règnera éternellement sur la maison de Jacob,'),
('lc',1,33,'crampon1923','et son règne n''aura point de fin. "'),
('lc',1,34,'crampon1923','Marie dit à l''ange: " Comment cela se fera-t-il, puisque je ne connais point d''homme? "'),
('lc',1,35,'crampon1923','L''ange lui répondit: " L''Esprit-Saint viendra sur vous, et la vertu du Très-Haut vous couvrira de son ombre. C''est pourquoi l''être saint qui naîtra (de vous) sera appelé Fils de Dieu.'),
('lc',1,36,'crampon1923','Déjà Elisabeth, votre parente, a conçu elle aussi, un fils dans sa vieillesse, et c''est actuellement son sixième mois, à elle que l''on appelle stérile:'),
('lc',1,37,'crampon1923','car rien ne sera impossible à Dieu. "'),
('lc',1,38,'crampon1923','Marie dit alors: " Voici la servante du Seigneur, qu''il me soit fait selon votre parole. " Et l''ange la quitta.'),
('lc',1,39,'crampon1923','En ces jours-là, Marie se levant, s''en alla en hâte au pays des montagnes, en une ville de Juda.'),
('lc',1,40,'crampon1923','Et elle entra dans la maison de Zacharie, et salua Elisabeth.'),
('lc',1,41,'crampon1923','Or, dès qu''Elisabeth eut entendu la salutation de Marie, l''enfant tressaillit dans son sein, et elle fut remplie du Saint-Esprit.'),
('lc',1,42,'crampon1923','Et élevant la voix, elle s''écria: " Vous êtes bénie entre les femmes, et le fruit de vos entrailles est béni.'),
('lc',1,43,'crampon1923','Et d''où m''est-il donné que la mère de mon Seigneur vienne à moi?'),
('lc',1,44,'crampon1923','Car votre voix, lorsque vous m''avez saluée, n''a pas plus tôt frappé mes oreilles, que mon enfant a tressailli de joie dans mon sein.'),
('lc',1,45,'crampon1923','Heureuse celle qui a cru! car elles seront accomplies les choses qui lui ont été dites de la part du Seigneur! "'),
('lc',1,46,'crampon1923','Et Marie dit: " Mon âme glorifie le Seigneur.'),
('lc',1,47,'crampon1923','Et mon esprit tressaille de joie en Dieu, mon Sauveur,'),
('lc',1,48,'crampon1923','Parce qu''il a jeté les yeux sur la bassesse de sa servante. Voici, en effet, que désormais toutes les générations m''appelleront bienheureuse,'),
('lc',1,49,'crampon1923','Parce qu''il a fait en moi de grandes choses, Celui qui est puissant, Et dont le nom est saint,'),
('lc',1,50,'crampon1923','Et dont la miséricorde s''étend d''âge en âge, Sur ceux qui le craignent.'),
('lc',1,51,'crampon1923','Il a déployé la force de son bras; Il a dissipé ceux qui s''enorgueillissaient dans les pensées de leur cœur;'),
('lc',1,52,'crampon1923','Il a renversé de leur trône les potentats, Et il a élevé les petits;'),
('lc',1,53,'crampon1923','Il a comblé de biens les affamés, Et les riches, il les a renvoyés les mains vides.'),
('lc',1,54,'crampon1923','Il a pris soin d''Israël son serviteur, Se ressouvenant de sa miséricorde,'),
('lc',1,55,'crampon1923','(Ainsi qu''il l''avait promis à nos pères) Envers Abraham et sa race, pour toujours. "'),
('lc',1,56,'crampon1923','Marie demeura avec Elisabeth environ trois mois, et s''en retourna chez elle.'),
('lc',1,57,'crampon1923','Cependant, le temps s''accomplit où Elisabeth devait enfanter, et elle mit au monde un fils.'),
('lc',1,58,'crampon1923','Ses voisins et ses parents, ayant appris que le Seigneur avait signalé en elle sa miséricorde, se réjouissaient avec elle.'),
('lc',1,59,'crampon1923','Le huitième jour, ils vinrent pour circoncire l''enfant, et ils le nommaient Zacharie d''après le nom de son père.'),
('lc',1,60,'crampon1923','Mais sa mère, prenant la parole: " Non, dit-elle, mais il s''appellera Jean. "'),
('lc',1,61,'crampon1923','Ils lui dirent: " Il n''y a personne dans votre famille qui soit appelé de ce nom. "'),
('lc',1,62,'crampon1923','Et ils demandaient par signe à son père comment il voulait qu''on le nommât.'),
('lc',1,63,'crampon1923','S''étant fait apporter une tablette, il écrivit: " Jean est son nom "; et tous furent dans l''étonnement.'),
('lc',1,64,'crampon1923','Au même instant sa bouche s''ouvrit, sa langue se délia; et il parlait, bénissant Dieu.'),
('lc',1,65,'crampon1923','La crainte s''empara de tous les habitants d''alentour, et partout dans les montagnes de la Judée, on racontait toutes ces merveilles.'),
('lc',1,66,'crampon1923','Tous ceux qui en entendirent parler les recueillirent dans leur cœur, et ils disaient: " Que sera donc cet enfant? Car la main du Seigneur était avec lui. "'),
('lc',1,67,'crampon1923','Et Zacharie, son père, fut rempli de l''Esprit-Saint, et il prophétisa, en disant:'),
('lc',1,68,'crampon1923','" Béni soit le Seigneur, le Dieu d''Israël, Parce qu''il a visité et racheté son peuple.'),
('lc',1,69,'crampon1923','Et qu''il a suscité une Force pour nous sauver, Dans la maison de David, son serviteur,'),
('lc',1,70,'crampon1923','(Ainsi qu''il l''a promis par la bouche de ses saints, De ses prophètes, dès les temps anciens).'),
('lc',1,71,'crampon1923','Pour nous sauver de nos ennemis Et du pouvoir de tous ceux qui nous haïssent.'),
('lc',1,72,'crampon1923','Afin d''exercer sa miséricorde envers nos pères. Et de se souvenir de son pacte saint;'),
('lc',1,73,'crampon1923','Selon le serment qu''il fit à Abraham, notre père, [74] De nous accorder que,'),
('lc',1,74,'crampon1923','sans crainte, Affranchis du pouvoir de nos ennemis, [75] Nous le servions,'),
('lc',1,75,'crampon1923','avec une sainteté et une justice Dignes de ses regards, tous les jours de notre vie.'),
('lc',1,76,'crampon1923','Quant à toi, petit enfant, tu seras appelé prophète du Très-Haut, Car tu marcheras devant la face du Seigneur, Pour lui préparer les voies;'),
('lc',1,77,'crampon1923','Pour apprendre à son peuple à reconnaître le salut Dans la rémission de leurs péchés:'),
('lc',1,78,'crampon1923','Par l''effet de la tendre miséricorde de notre Dieu, Grâce à laquelle nous a visités, d''en haut, le Soleil levant,'),
('lc',1,79,'crampon1923','Pour éclairer ceux qui sont assis dans les ténèbres et l''ombre de la mort, Pour diriger nos pas dans la voie de la paix. "'),
('lc',1,80,'crampon1923','Or l''enfant croissait et se fortifiait en esprit, et il demeura dans le désert jusqu''au jour de sa manifestation devant Israël.'),
('lc',2,1,'crampon1923','En ces jours-là fut publié un édit de César Auguste, pour le recensement de toute la terre.'),
('lc',2,2,'crampon1923','Ce premier recensement eut lieu pendant que Quirinius commandait la Syrie.'),
('lc',2,3,'crampon1923','Et tous allaient se faire recenser, chacun dans sa ville.'),
('lc',2,4,'crampon1923','Joseph monta de Galilée, de la ville de Nazareth, en Judée, à la ville de David, appelée Bethléem, parce qu''il était de la maison et de la famille de David,'),
('lc',2,5,'crampon1923','pour être recensé avec Marie son épouse, qui était enceinte.'),
('lc',2,6,'crampon1923','Or, pendant qu''ils étaient en ce lieu, le temps où elle devait enfanter s''accomplit.'),
('lc',2,7,'crampon1923','Et elle mit au monde son fils premier-né, l''enveloppa de langes et le coucha dans une crèche, parce qu''il n''y avait pas de place pour eux dans l''hôtellerie.'),
('lc',2,8,'crampon1923','Il y avait aux environs des bergers qui passaient la nuit aux champs, veillant à la garde de leur troupeau.'),
('lc',2,9,'crampon1923','Tout à coup un ange du Seigneur parut auprès d''eux et le rayonnement de la gloire du Seigneur les environna, et ils furent saisis d''une grande crainte.'),
('lc',2,10,'crampon1923','Mais l''ange leur dit: " Ne craignez point, car je vous annonce une nouvelle qui sera pour tout le peuple une grande joie.'),
('lc',2,11,'crampon1923','Il vous est né aujourd''hui, dans la ville de David, un Sauveur, qui est le Christ Seigneur.'),
('lc',2,12,'crampon1923','Et voici ce qui vous servira de signe: vous trouverez un nouveau-né enveloppé de langes et couché dans une crèche. "'),
('lc',2,13,'crampon1923','Au même instant, se joignit à l''ange une troupe de la milice céleste, louant Dieu et disant:'),
('lc',2,14,'crampon1923','" Gloire, dans les hauteurs, à Dieu! Et, sur la terre, paix aux hommes, Objet de la bienveillance divine! "'),
('lc',2,15,'crampon1923','Lorsque les anges, remontant au ciel, les eurent quittés, les bergers se dirent les uns aux autres: " Passons jusqu''à Bethléem, et voyons cet événement qui est arrivé, et que le Seigneur nous a fait savoir. "'),
('lc',2,16,'crampon1923','Ils s''y rendirent en toute hâte, et trouvèrent Marie, Joseph, et le nouveau-né couché dans la crèche.'),
('lc',2,17,'crampon1923','Après l''avoir vu, ils publièrent la révélation qui leur avait été faite au sujet de cet Enfant.'),
('lc',2,18,'crampon1923','Et tous ceux qui les entendirent furent dans l''admiration de ce que leur disaient les bergers.'),
('lc',2,19,'crampon1923','Or Marie conservait avec soin toutes ces choses, les méditant dans son cœur.'),
('lc',2,20,'crampon1923','Et les bergers s''en retournèrent, glorifiant et louant Dieu de tout ce qu''ils avaient vu et entendu, selon ce qui leur avait été annoncé.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('lc',2,21,'crampon1923','Les huit jours étant accomplis, pour la circoncision de l''Enfant, il fut appelé Jésus, nom que l''ange lui avait donné avant qu''il eût été conçu dans le sein maternel.'),
('lc',2,22,'crampon1923','Puis, lorsque les jours de leur purification furent accomplis, selon la loi de Moïse, Marie et Joseph portèrent l''Enfant à Jérusalem pour le présenter au Seigneur,'),
('lc',2,23,'crampon1923','suivant ce qui est écrit dans la loi du Seigneur: " Tout mâle premier-né sera consacré au Seigneur ";'),
('lc',2,24,'crampon1923','et pour offrir en sacrifice, ainsi que le prescrit la loi du Seigneur, une paire de tourterelles, ou deux petites colombes.'),
('lc',2,25,'crampon1923','Or, il y avait à Jérusalem un homme nommé Siméon; c''était un homme juste et craignant Dieu, qui attendait la consolation d''Israël, et l''Esprit-Saint était sur lui.'),
('lc',2,26,'crampon1923','L''Esprit-Saint lui avait révélé qu''il ne mourrait point avant d''avoir vu le Christ du Seigneur.'),
('lc',2,27,'crampon1923','Il vint donc dans le temple, poussé par l''Esprit. Et comme les parents apportaient le petit Enfant Jésus, pour observer les coutumes légales à son égard,'),
('lc',2,28,'crampon1923','lui aussi, il le reçut entre ses bras, et bénit Dieu en disant:'),
('lc',2,29,'crampon1923','" Maintenant, ô Maître, vous laissez partir votre serviteur En paix, selon votre parole;'),
('lc',2,30,'crampon1923','Puisque mes yeux ont vu votre salut,'),
('lc',2,31,'crampon1923','Que vous avez préparé à la face de tous les peuples:'),
('lc',2,32,'crampon1923','Lumière qui doit dissiper les ténèbres des Nations Et gloire d''Israël, votre peuple. "'),
('lc',2,33,'crampon1923','Le père et la mère de l''Enfant étaient dans l''admiration des choses que l''on disait de lui.'),
('lc',2,34,'crampon1923','Et Siméon les bénit et dit à Marie, sa mère: " Cet Enfant est au monde pour la chute et la résurrection d''un grand nombre en Israël, et pour être un signe en butte à la contradiction; —'),
('lc',2,35,'crampon1923','vous-même, un glaive transpercera votre âme; — et ainsi seront révélées les pensées cachées dans le cœur d''un grand nombre. "'),
('lc',2,36,'crampon1923','Il y avait aussi une prophétesse, Anne, fille de Phanuel, de la tribu d''Aser; elle était fort avancée en âge, ayant vécu, depuis sa virginité, sept ans avec son mari.'),
('lc',2,37,'crampon1923','Restée veuve, et parvenue à quatre-vingt-quatre ans, elle ne quittait point le temple, servant Dieu nuit et jour dans le jeûne et dans la prière.'),
('lc',2,38,'crampon1923','Elle aussi, survenant à cette heure, se mit à louer le Seigneur et à parler de l''Enfant à tous ceux qui, à Jérusalem, attendaient la rédemption.'),
('lc',2,39,'crampon1923','Lorsqu''ils eurent tout accompli selon la loi du Seigneur, ils retournèrent en Galilée, à Nazareth, leur ville.'),
('lc',2,40,'crampon1923','Cependant l''Enfant croissait et se fortifiait, étant rempli de sagesse, et la grâce de Dieu était sur lui.'),
('lc',2,41,'crampon1923','Or ses parents allaient tous les ans à Jérusalem, à la fête de Pâque.'),
('lc',2,42,'crampon1923','Quand il eut atteint sa douzième année, ils y montèrent, selon la coutume de cette fête;'),
('lc',2,43,'crampon1923','et lorsqu''ils s''en retournèrent, les jours de la fête étant passés, l''Enfant Jésus resta dans la ville, sans que ses parents s''en fussent aperçus.'),
('lc',2,44,'crampon1923','Pensant qu''il était avec leurs compagnons de voyage, ils marchèrent tout un jour, puis ils le cherchèrent parmi leurs parents et leurs connaissances.'),
('lc',2,45,'crampon1923','Ne l''ayant point trouvé, ils retournèrent à Jérusalem pour le chercher.'),
('lc',2,46,'crampon1923','Au bout de trois jours, ils le trouvèrent dans le temple, assis au milieu des docteurs, les écoutant et les interrogeant.'),
('lc',2,47,'crampon1923','Et tous ceux qui l''entendaient étaient ravis de son intelligence et de ses réponses.'),
('lc',2,48,'crampon1923','En le voyant, ils furent étonnés; et sa mère lui dit: " Mon enfant, pourquoi avez-vous agi ainsi avec nous? Votre père et moi, nous vous cherchions tout affligés. "'),
('lc',2,49,'crampon1923','Et il leur répondit: " Pourquoi me cherchiez-vous? Ne saviez-vous pas qu''il faut que je sois aux choses de mon Père? "'),
('lc',2,50,'crampon1923','Mais ils ne comprirent pas ce qu''il leur disait.'),
('lc',2,51,'crampon1923','Alors il descendit avec eux, et vint à Nazareth, et il leur était soumis. Et sa mère conservait toutes ces choses dans son cœur.'),
('lc',2,52,'crampon1923','Et Jésus progressait en sagesse, en taille et en grâce devant Dieu et devant les hommes.'),
('lc',3,1,'crampon1923','La quinzième année du règne de Tibère César, Ponce Pilate étant gouverneur de la Judée; Hérode, tétrarque de la Galilée; Philippe, son frère, tétrarque de l''Iturée et du pays de la Trachonite, et Lysanias, tétrarque de l''Abilène;'),
('lc',3,2,'crampon1923','au temps des grands prêtres Anne et Caïphe, la parole du Seigneur se fit entendre à Jean, fils de Zacharie, dans le désert.'),
('lc',3,3,'crampon1923','Et il vint dans toute la contrée du Jourdain, prêchant le baptême de pénitence pour la rémission des péchés,'),
('lc',3,4,'crampon1923','ainsi qu''il est écrit au livre des oracles du prophète Isaïe: " Une voix a retenti au désert: Préparez le chemin du Seigneur, aplanissez ses sentiers.'),
('lc',3,5,'crampon1923','Toute vallée sera comblée, toute montagne et toute colline seront abaissées; les chemins tortueux deviendront droits, et les raboteux unis.'),
('lc',3,6,'crampon1923','Et toute chair verra le salut de Dieu. "'),
('lc',3,7,'crampon1923','Il disait à ceux qui accouraient en foule, pour être baptisés par lui: " Race de vipères, qui vous a appris à fuir la colère qui vient?'),
('lc',3,8,'crampon1923','Faites donc de dignes fruits de repentir, et n''essayez pas de dire en vous-mêmes: Abraham est notre père; car je vous dis que de ces pierres mêmes Dieu peut susciter des enfants à Abraham.'),
('lc',3,9,'crampon1923','Déjà la cognée est à la racine des arbres. Tout arbre donc qui ne porte pas de bon fruit sera coupé et jeté au feu. "'),
('lc',3,10,'crampon1923','Et le peuple lui demanda: " Que faut-il donc faire? "'),
('lc',3,11,'crampon1923','Il leur répondit: " Que celui qui a deux tuniques en donne une à qui n''en a point, et que celui qui a de quoi manger fasse de même. "'),
('lc',3,12,'crampon1923','Il vint aussi des publicains pour être baptisés, et ils lui dirent: " Maître, que devons-nous faire? "'),
('lc',3,13,'crampon1923','Il leur dit: " N''exigez rien au delà de ce qui vous est ordonné. "'),
('lc',3,14,'crampon1923','Des gens de guerre l''interrogèrent aussi, disant: " Et nous, que devons-nous faire? " Il leur répondit: " Abstenez-vous de toute violence et de toute fraude, et contentez-vous de votre solde. "'),
('lc',3,15,'crampon1923','Comme le peuple était dans l''attente, et que tous se demandaient dans leurs cœurs, à l''égard de Jean, s''il ne serait pas le Christ,'),
('lc',3,16,'crampon1923','Jean leur dit à tous: " Moi, je vous baptise dans l''eau; mais il vient, celui qui est plus puissant que moi, et dont je ne suis pas digne de délier la courroie de la chaussure; lui, il vous baptisera dans l''Esprit-Saint et le feu.'),
('lc',3,17,'crampon1923','Sa main tient le van, et il nettoiera son aire, et il amassera le froment dans son grenier, et il brûlera la paille dans un feu qui ne s''éteint point. "'),
('lc',3,18,'crampon1923','Par ces exhortations, et beaucoup d''autres semblables, il annonçait donc au peuple la bonne nouvelle.'),
('lc',3,19,'crampon1923','Mais Hérode le tétrarque, étant repris par lui au sujet d''Hérodiade, femme de son frère, et de tout le mal qu''il avait fait,'),
('lc',3,20,'crampon1923','il ajouta ce crime à tous les autres, et enferma Jean en prison.'),
('lc',3,21,'crampon1923','Or, dans le temps que tout le peuple venait de recevoir le baptême, Jésus fut aussi baptisé, et pendant qu''il priait, le ciel s''ouvrit,'),
('lc',3,22,'crampon1923','et l''Esprit-Saint descendit sur lui sous une forme corporelle, comme une colombe, et du ciel une voix se fit entendre, disant: " Tu es mon Fils bien-aimé; en toi j''ai mes complaisances. "'),
('lc',3,23,'crampon1923','Jésus avait environ trente ans lorsqu''il commença son ministère; il était, comme on le croyait, fils de Joseph, fils d''Héli,'),
('lc',3,24,'crampon1923','fils de Matthat, fils de Lévi, fils de Melchi, fils de Janné, fils de Joseph,'),
('lc',3,25,'crampon1923','fils de Mattathias, fils d''Amos, fils de Nahum, fils d''Hesli, fils de Naggé,'),
('lc',3,26,'crampon1923','fils de Maath, fils de Mattathias, fils de Séméï, fils de Josech, fils de Juda,'),
('lc',3,27,'crampon1923','fils de Joanan, fils de Résa, fils de Zorobabel, fils de Salathiel, fils de Néri,'),
('lc',3,28,'crampon1923','fils de Melchi, fils d''Addi, fils de Cosam, fils d''Elmadam, fils de Her,'),
('lc',3,29,'crampon1923','fils de Jésus, fils d''Eliézer, fils de Jorim, fils de Matthat, fils de Lévi,'),
('lc',3,30,'crampon1923','fils de Siméon, fils de Juda, fils de Joseph, fils de Jonan, fils d''Eliakim,'),
('lc',3,31,'crampon1923','fils de Méléa, fils de Menna, fils de Mattatha, fils de Nathan, fils de David,'),
('lc',3,32,'crampon1923','fils de Jessé, fils d''Obed, fils de Booz, fils de Salmon, fils de Naasson,'),
('lc',3,33,'crampon1923','fils d''Aminadab, fils d''Aram, fils d''Esron, fils de Pharès, fils de Judas,'),
('lc',3,34,'crampon1923','fils de Jacob, fils d''Isaac, fils d''Abraham, fils de Tharé, fils de Nachor,'),
('lc',3,35,'crampon1923','fils de Sarug, fils de Réü, fils de Phaleg, fils d''Héber, fils de Salé,'),
('lc',3,36,'crampon1923','fils de Caïnan, fils d''Arphaxad, fils de Sem, fils de Noé, fils de Lamech,'),
('lc',3,37,'crampon1923','fils de Mathusalé, fils d''Enoch, fils de Jared, fils de Malaléel, fils de Caïnan,'),
('lc',3,38,'crampon1923','fils d''Enos, fils de Seth, fils d''Adam, fils de Dieu.'),
('lc',4,1,'crampon1923','Jésus, rempli de l''Esprit-Saint, revint du Jourdain, et il fut poussé par l''Esprit dans le désert,'),
('lc',4,2,'crampon1923','pendant quarante jours, en butte aux tentations du diable. Il ne mangea rien durant ces jours-là, et quand ils furent passés, il eut faim.'),
('lc',4,3,'crampon1923','Alors le diable lui dit: " Si vous êtes Fils de Dieu, commandez à cette pierre de se changer en pain. "'),
('lc',4,4,'crampon1923','Jésus lui répondit: " Il est écrit: L''homme ne vit pas seulement de pain, mais de toute parole de Dieu. "'),
('lc',4,5,'crampon1923','Et le diable l''ayant emmené sur une haute montagne, lui montra en un instant tous les royaumes de la terre,'),
('lc',4,6,'crampon1923','et lui dit: " Je vous donnerai toute cette puissance et toute la gloire de ces royaumes; car elle m''a été livrée, et je la donne à qui je veux.'),
('lc',4,7,'crampon1923','Si donc vous vous prosternez devant moi, elle sera toute à vous. "'),
('lc',4,8,'crampon1923','Jésus lui répondit: " Il est écrit: Tu adoreras le Seigneur ton Dieu, et tu le serviras lui seul. "'),
('lc',4,9,'crampon1923','Le démon le conduisit encore à Jérusalem, et l''ayant placé sur le pinacle du temple, il lui dit: " Si vous êtes Fils de Dieu, jetez-vous d''ici en bas.'),
('lc',4,10,'crampon1923','Car il est écrit: Il a été donné pour vous l''ordre à ses anges de vous garder,'),
('lc',4,11,'crampon1923','et ils vous prendront entre leurs mains, de peur que votre pied ne heurte contre la pierre. "'),
('lc',4,12,'crampon1923','Jésus lui répondit: " Il a été écrit: Tu ne tenteras point le Seigneur ton Dieu. "'),
('lc',4,13,'crampon1923','Après l''avoir ainsi tenté de toutes manières, le diable se retira de lui pour un temps.'),
('lc',4,14,'crampon1923','Alors Jésus retourna en Galilée, dans la puissance de l''Esprit, et sa renommée se répandit dans tout le pays d''alentour.'),
('lc',4,15,'crampon1923','Il enseignait dans leurs synagogues, et tous publiaient ses louanges.'),
('lc',4,16,'crampon1923','Etant venu à Nazareth, où il avait été élevé, il entra, selon sa coutume, le jour du sabbat dans la synagogue, et se leva pour faire la lecture.'),
('lc',4,17,'crampon1923','On lui remit le livre du prophète Isaïe; et l''ayant déroulé, il trouva l''endroit où il était écrit:'),
('lc',4,18,'crampon1923','" L''Esprit du Seigneur est sur moi, parce qu''il m''a consacré par son onction, pour porter la bonne nouvelle aux pauvres, et il m''a envoyé guérir ceux qui ont le cœur brisé,'),
('lc',4,19,'crampon1923','annoncer aux captifs la délivrance, aux aveugles le retour à la vue, pour rendre libres les opprimés, publier l''année favorable du Seigneur. "'),
('lc',4,20,'crampon1923','Ayant roulé le livre, il le rendit au ministre et s''assit; et tous, dans la synagogue, avaient les yeux attachés sur lui.'),
('lc',4,21,'crampon1923','Alors, il commença à leur dire: " Aujourd''hui vos oreilles ont entendu l''accomplissement de cet oracle. "'),
('lc',4,22,'crampon1923','Et tous lui rendaient témoignage, et admirant les paroles de grâce qui sortaient de sa bouche, ils disaient: " N''est-ce pas là le fils de Joseph? "'),
('lc',4,23,'crampon1923','Et il leur dit: " Sans doute, vous m''alléguerez cet adage: Médecin, guéris-toi toi-même; et vous me direz: Les grandes choses que nous avons ouï dire que vous avez faites à Capharnaüm, faites-les ici dans votre patrie. "'),
('lc',4,24,'crampon1923','Et il ajouta: " En vérité, je vous le dis, aucun prophète n''est bien reçu dans sa patrie.'),
('lc',4,25,'crampon1923','Je vous le dis, en vérité, il y avait beaucoup de veuves en Israël aux jours d''Elie, lorsque le ciel fut fermé pendant trois ans et six mois, et qu''il y eut une grande famine dans toute la terre;'),
('lc',4,26,'crampon1923','et pourtant Elie ne fut envoyé à aucune d''elles, mais à une veuve de Sarepta, dans le pays de Sidon.'),
('lc',4,27,'crampon1923','Il y avait de même beaucoup de lépreux en Israël au jours du prophète Elisée; et pourtant aucun d''eux ne fut guéri, mais bien Naaman le Syrien. "'),
('lc',4,28,'crampon1923','En entendant cela, ils furent tous remplis de colère dans la synagogue.'),
('lc',4,29,'crampon1923','Et s''étant levés, ils le poussèrent hors de la ville, et le menèrent jusqu''à un escarpement de la montagne sur laquelle leur ville était bâtie pour le précipiter en bas.'),
('lc',4,30,'crampon1923','Mais lui, passant au milieu d''eux, s''en alla.'),
('lc',4,31,'crampon1923','Il descendit à Capharnaüm, ville de Galilée, et là il enseignait les jours de sabbat.'),
('lc',4,32,'crampon1923','Et sa doctrine les frappait d''étonnement, parce qu''il parlait avec autorité.'),
('lc',4,33,'crampon1923','Il y avait dans la synagogue un homme possédé d''un démon impur, lequel jeta un grand cri,'),
('lc',4,34,'crampon1923','disant: " Laissez-moi, qu''avons-nous à faire avec vous, Jésus de Nazareth? Etes-vous venu pour nous perdre? Je sais qui vous êtes: le Saint de Dieu. "'),
('lc',4,35,'crampon1923','Mais Jésus lui dit d''un ton sévère: " Tais-toi, et sors de cet homme. " Et le démon l''ayant jeté par terre au milieu de l''assemblée, sortit de lui sans lui avoir fait aucun mal.'),
('lc',4,36,'crampon1923','Et tous, saisis de stupeur, se disaient entre eux: " Quelle est cette parole? Il commande avec autorité et puissance aux esprits impurs, et ils sortent! "'),
('lc',4,37,'crampon1923','Et sa renommée se répandait de tous côtés dans le pays.'),
('lc',4,38,'crampon1923','S''étant alors levé, Jésus quitta la synagogue, et entra dans la maison de Simon. Or, la belle-mère de Simon était atteinte d''une grosse fièvre, et ils le prièrent pour elle.'),
('lc',4,39,'crampon1923','Se penchant sur la malade, il commanda à la fièvre, et la fièvre la quitta; et s''étant levée aussitôt, elle se mit à les servir.'),
('lc',4,40,'crampon1923','Lorsque le soleil fut couché, tous ceux qui avaient chez eux des malades, quel que fût leur mal, les lui amenèrent; et Jésus, imposant la main à chacun d''eux, les guérit.'),
('lc',4,41,'crampon1923','Des démons aussi sortaient de plusieurs, criant et disant: " Tu es le Fils de Dieu "; et il les réprimandait pour leur imposer silence, parce qu''ils savaient qu''il était le Christ.'),
('lc',4,42,'crampon1923','Dès que le jour parut, il sortit et s''en alla en un lieu désert. Une foule de gens se mirent à sa recherche, et étant arrivés jusqu''à lui, ils voulaient le retenir, pour qu''il ne les quittât point.'),
('lc',4,43,'crampon1923','Mais il leur dit: " Il faut que j''annonce aussi aux autres villes le royaume de Dieu, car je suis envoyé pour cela. "'),
('lc',4,44,'crampon1923','Et Jésus prêchait dans les synagogues de la Galilée.'),
('lc',5,1,'crampon1923','Or, un jour que pressé par la foule qui voulait entendre la parole de Dieu, il se tenait sur le bord du lac de Génésareth,'),
('lc',5,2,'crampon1923','il vit deux barques qui stationnaient près du rivage; les pêcheurs étaient descendus pour laver leurs filets.'),
('lc',5,3,'crampon1923','Il monta donc dans une de ces barques, qui était à Simon, et le pria de s''éloigner un peu de terre; puis, s''étant assis, il enseigna le peuple de dessus la barque.'),
('lc',5,4,'crampon1923','Lorsqu''il eut cessé de parler, il dit à Simon: " Avance en pleine mer, et vous jetterez vos filets pour pêcher. "'),
('lc',5,5,'crampon1923','Simon lui répondit: " Maître, toute la nuit nous avons travaillé sans rien prendre; mais, sur votre parole, je jetterai le filet. "'),
('lc',5,6,'crampon1923','L''ayant jeté, ils prirent une si grande quantité de poissons, que leur filet se rompait.'),
('lc',5,7,'crampon1923','Et ils firent signe à leurs compagnons, qui étaient dans l''autre barque, de venir à leur aide. Ils y vinrent, et ils remplirent les deux barques, au point qu''elles enfonçaient.'),
('lc',5,8,'crampon1923','Ce que voyant Simon Pierre, il tomba aux pieds de Jésus en disant: " Eloignez-vous de moi, Seigneur, parce que je suis un pécheur. "'),
('lc',5,9,'crampon1923','Car l''effroi l''avait saisi, lui et tous ceux qui l''accompagnaient, à cause de la capture de poissons qu''ils avaient faite;'),
('lc',5,10,'crampon1923','il en était de même de Jacques et de Jean, fils de Zébédée, les associés de Simon. Et Jésus dit à Simon: " Ne crains point, car désormais ce sont des hommes que tu prendras. "'),
('lc',5,11,'crampon1923','Aussitôt, ramenant leurs barques à terre, ils quittèrent tout et le suivirent.'),
('lc',5,12,'crampon1923','Comme il était dans une ville, voici qu''un homme tout couvert de lèpre, apercevant Jésus, se prosterna la face contre terre, et le pria en disant: " Seigneur, si vous le voulez, vous pouvez me guérir. "'),
('lc',5,13,'crampon1923','Jésus, étendant la main, le toucha et lui dit: " Je le veux, sois guéri "; et à l''instant sa lèpre disparut.'),
('lc',5,14,'crampon1923','Et il lui défendit d''en parler à personne; mais: " Va, dit-il, te montrer au prêtre, et offre pour ta guérison ce qu''a prescrit Moïse, pour l''attester au peuple. "'),
('lc',5,15,'crampon1923','Sa renommée se répandait de plus en plus, et l''on venait par troupes nombreuses pour l''entendre et pour être guéri de ses maladies.'),
('lc',5,16,'crampon1923','Pour lui, il se retirait dans les déserts et priait.'),
('lc',5,17,'crampon1923','Un jour qu''il enseignait, il y avait là, assis autour de lui, des Pharisiens et des docteurs de la Loi, venus de tous les villages de la Galilée, ainsi que de la Judée et de Jérusalem, et la puissance du Seigneur se manifestait par des guérisons.'),
('lc',5,18,'crampon1923','Et voilà que des gens, portant sur un lit un homme paralysé, cherchaient à le faire entrer et à le mettre devant lui.'),
('lc',5,19,'crampon1923','Et n''en trouvant pas le moyen à cause de la foule, ils montèrent sur le toit et, à travers les tuiles, descendirent le malade avec sa couchette au milieu de tous, devant Jésus.'),
('lc',5,20,'crampon1923','Voyant leur foi, il dit: " Homme, tes péchés te sont remis. "'),
('lc',5,21,'crampon1923','Alors les Scribes et les Pharisiens se mirent à raisonner et à dire: " Qui est celui-ci qui profère des blasphèmes? Qui peut remettre les péchés, si ce n''est Dieu seul? "'),
('lc',5,22,'crampon1923','Jésus, connaissant leurs pensées, prit la parole et leur dit: " Quelles pensées avez-vous en vos cœurs?'),
('lc',5,23,'crampon1923','Lequel est le plus facile de dire: Tes péchés te sont remis, ou de dire: Lève-toi et marche?'),
('lc',5,24,'crampon1923','Or, afin que vous sachiez que le Fils de l''homme a sur la terre le pouvoir de remettre les péchés: Je te le commande, dit-il au paralytique, lève-toi, prends ta couchette et va dans ta maison. "'),
('lc',5,25,'crampon1923','A l''instant, celui-ci se leva devant eux, prit le lit sur lequel il était couché, et s''en alla dans sa maison en glorifiant Dieu.'),
('lc',5,26,'crampon1923','Et tous étaient frappés de stupeur; ils glorifiaient Dieu, et, remplis de crainte, ils disaient: " Nous avons vu aujourd''hui des choses merveilleuses. "'),
('lc',5,27,'crampon1923','Après cela, Jésus sortit, et ayant vu un publicain nommé Lévi, assis au bureau du péage, il lui dit: " Suis-moi. "'),
('lc',5,28,'crampon1923','Et lui, quittant tout, se leva et le suivit.'),
('lc',5,29,'crampon1923','Lévi lui donna un grand festin dans sa maison; et une foule nombreuse de publicains et d''autres personnes étaient à table avec eux.'),
('lc',5,30,'crampon1923','Les Pharisiens et leurs Scribes murmuraient et disaient à ses disciples: " Pourquoi mangez-vous et buvez-vous avec les publicains et les pécheurs? "'),
('lc',5,31,'crampon1923','Jésus leur répondit: " Ce ne sont pas les bien portants qui ont besoin de médecin, mais les malades.'),
('lc',5,32,'crampon1923','Je ne suis pas venu appeler les justes à la pénitence, mais les pécheurs. "'),
('lc',5,33,'crampon1923','Alors ils lui dirent: " Pourquoi, tandis que les disciples de Jean et ceux des Pharisiens jeûnent et prient souvent, les vôtres mangent-ils et boivent-ils? "'),
('lc',5,34,'crampon1923','Il leur répondit: " Pouvez-vous faire jeûner les amis de l''Epoux, pendant que l''Epoux est avec eux?'),
('lc',5,35,'crampon1923','Viendront des jours où l''Epoux leur sera enlevé: ils jeûneront ces jours-là. "'),
('lc',5,36,'crampon1923','Il leur proposa encore cette comparaison: " Personne ne met à un vieux vêtement un morceau pris à un vêtement neuf: autrement on déchire le neuf, et le morceau du neuf convient mal au vêtement vieux.'),
('lc',5,37,'crampon1923','Personne non plus ne met du vin nouveau dans de vieilles outres: autrement, le vin nouveau rompant les outres, il se répandra, et les outres seront perdues.'),
('lc',5,38,'crampon1923','Mais il faut mettre le vin nouveau dans des outres neuves, et tous les deux se conservent.'),
('lc',5,39,'crampon1923','Et personne après avoir bu du vieux vin, ne veut aussitôt du nouveau; car on dit: Le vieux vin est meilleur. "'),
('lc',6,1,'crampon1923','Un jour de sabbat, dit le second-premier, comme Jésus traversait des champs de blé, ses disciples cueillaient des épis, et, les froissant dans leurs mains, les mangeaient.'),
('lc',6,2,'crampon1923','Quelques Pharisiens leur dirent: " Pourquoi faites-vous ce qui n''est pas permis le jour du sabbat? "'),
('lc',6,3,'crampon1923','Jésus leur répondit: " Vous n''avez donc pas lu ce que fit David, lorsqu''il eut faim, lui et ceux qui l''accompagnaient:'),
('lc',6,4,'crampon1923','comment il entra dans la maison de Dieu, et prit les pains de proposition, en mangea et en donna à ceux qui étaient avec lui, bien qu''il ne soit permis d''en manger qu''aux prêtres seuls? "'),
('lc',6,5,'crampon1923','Et il ajouta: " Le Fils de l''homme est maître même du sabbat. "'),
('lc',6,6,'crampon1923','Un autre jour de sabbat, Jésus entra dans la synagogue et il enseignait. Et il y avait là un homme dont la main droite était desséchée.'),
('lc',6,7,'crampon1923','Or, les Scribes et les Pharisiens l''observaient, pour voir s''il faisait des guérisons le jour du sabbat, afin d''avoir un prétexte pour l''accuser.'),
('lc',6,8,'crampon1923','Mais lui, pénétrant leurs pensées, dit à l''homme qui avait la main desséchée: " Lève-toi, et tiens-toi au milieu "; et lui, s''étant levé, se tint debout.'),
('lc',6,9,'crampon1923','Alors Jésus leur dit: " Je vous le demande, est–il permis, le jour du sabbat, de faire du bien ou de faire du mal, de sauver la vie ou de l''ôter? "'),
('lc',6,10,'crampon1923','Puis, promenant son regard sur eux tous, il dit à cet homme: " Etends ta main. " Il l''étendit et sa main redevint saine.'),
('lc',6,11,'crampon1923','Mais eux, remplis de démence, se consultaient sur ce qu''ils feraient à Jésus.'),
('lc',6,12,'crampon1923','En ces jours-là, il se retira sur la montagne pour prier, et il passa toute la nuit à prier Dieu.'),
('lc',6,13,'crampon1923','Quand il fut jour, il appela ses disciples, et choisit douze d''entre eux, qu''il nomma apôtres:'),
('lc',6,14,'crampon1923','Simon, auquel il donna le nom de Pierre, et André son frère, Jacques et Jean, Philippe et Barthélemy,'),
('lc',6,15,'crampon1923','Matthieu et Thomas, Jacques, fils d''Alphée, et Simon, appelé le Zélé,'),
('lc',6,16,'crampon1923','Jude, frère de Jacques, et Judas Iscariote, qui devint traître.'),
('lc',6,17,'crampon1923','Etant descendu avec eux, il s''arrêta sur un plateau, où se trouvaient une foule de ses disciples et une grande multitude de peuple de toute la Judée, de Jérusalem et de toute la région maritime de Tyr et de Sidon.'),
('lc',6,18,'crampon1923','Ils étaient venus pour l''entendre et pour être guéris de leurs maladies. Ceux qui étaient tourmentés par des esprits impurs étaient guéris.'),
('lc',6,19,'crampon1923','Et toute cette foule cherchait à le toucher, parce qu''il sortait de lui une vertu qui les guérissait tous.'),
('lc',6,20,'crampon1923','Alors, levant les yeux vers ses disciples, il leur dit: " Heureux, vous qui êtes pauvres, car le royaume des cieux est à vous!'),
('lc',6,21,'crampon1923','Heureux, vous qui avez faim maintenant, car vous serez rassasiés! Heureux, vous qui pleurez maintenant, car vous serez dans la joie!'),
('lc',6,22,'crampon1923','Heureux serez-vous, lorsque les hommes vous haïront, vous repousseront de leur société, vous chargeront d''opprobre, et rejetteront votre nom comme infâme, à cause du Fils de l''homme.'),
('lc',6,23,'crampon1923','Réjouissez-vous en ce jour-là, et tressaillez de joie, car voici que votre récompense est grande dans le ciel: c''est ainsi que leurs pères traitaient les prophètes.'),
('lc',6,24,'crampon1923','Mais malheur à vous, riches, car vous avez votre consolation!'),
('lc',6,25,'crampon1923','Malheur à vous, qui êtes rassasiés, car vous aurez faim! Malheur à vous, qui riez maintenant, car vous serez dans le deuil et dans les larmes!'),
('lc',6,26,'crampon1923','Malheur à vous, quand tous les hommes diront du bien de vous, car c''est ce que leurs pères faisaient à l''égard des faux prophètes!'),
('lc',6,27,'crampon1923','Mais je vous le dis, à vous qui m''écoutez: Aimez vos ennemis; faites du bien à ceux qui vous haïssent.'),
('lc',6,28,'crampon1923','Bénissez ceux qui vous maudissent, et priez pour ceux qui vous maltraitent.'),
('lc',6,29,'crampon1923','Si quelqu''un te frappe sur une joue, présente-lui encore l''autre; et si quelqu''un t''enlève ton manteau, ne l''empêche pas de prendre aussi ta tunique.'),
('lc',6,30,'crampon1923','Donne à quiconque te demande, et si l''on te ravit ton bien, ne le réclame point.'),
('lc',6,31,'crampon1923','Ce que vous voulez que les hommes fassent pour vous, faites-le pareillement pour eux.'),
('lc',6,32,'crampon1923','Si vous aimez ceux qui vous aiment, quel gré vous en saura-t-on? Les pécheurs aussi aiment ceux qui les aiment.'),
('lc',6,33,'crampon1923','Et si vous faites du bien à ceux qui vous font du bien, quel gré vous en saura-t-on? Les pécheurs aussi en font autant.'),
('lc',6,34,'crampon1923','Et si vous prêtez à ceux de qui vous espérez recevoir, quel gré vous en saura-t-on? Des pécheurs aussi prêtent à des pécheurs, afin qu''on leur rende l''équivalent.'),
('lc',6,35,'crampon1923','Pour vous, aimez vos ennemis, faites du bien et prêtez sans rien espérer en retour; et votre récompense sera grande, et vous serez les fils du Très-Haut, qui est bon aux ingrats et aux méchants.'),
('lc',6,36,'crampon1923','Soyez donc miséricordieux, comme votre Père est miséricordieux.'),
('lc',6,37,'crampon1923','Ne jugez point, et vous ne serez point jugés; ne condamnez point, et vous ne serez point condamnés; remettez et il vous sera remis.'),
('lc',6,38,'crampon1923','Donnez, et il vous sera donné: on versera dans votre sein une bonne mesure, pressée, secouée et débordante, car on se servira, pour vous rendre, de la même mesure avec laquelle vous aurez mesuré. "'),
('lc',6,39,'crampon1923','Il leur fit encore cette comparaison: " Un aveugle peut-il conduire un aveugle? Ne tomberont-ils pas tous les deux dans la fosse?'),
('lc',6,40,'crampon1923','Le disciple n''est pas au-dessus du maître; mais tout disciple, son instruction achevée, sera comme son maître.'),
('lc',6,41,'crampon1923','Pourquoi regardes-tu la paille qui est dans l''œil de ton frère, et ne remarques-tu pas la poutre qui est dans ton œil?'),
('lc',6,42,'crampon1923','Ou comment peux-tu dire à ton frère: Mon frère, laisse-moi ôter cette paille de ton œil, toi qui ne vois pas la poutre qui est dans le tien? Hypocrite, ôte d''abord la poutre de ton œil, et tu verras ensuite à ôter la paille qui est dans l''œil de ton frère.'),
('lc',6,43,'crampon1923','En effet, il n''y a pas de bon arbre qui porte de mauvais fruits, ni de mauvais arbre qui porte de bons fruits;'),
('lc',6,44,'crampon1923','chaque arbre se reconnaît à son fruit. On ne cueille pas de figues sur les épines; on ne coupe pas de raisin sur les ronces.'),
('lc',6,45,'crampon1923','L''homme bon tire le bien du bon trésor de son cœur; et, de son mauvais trésor, l''homme méchant tire le mal; car la bouche parle de l''abondance du cœur.'),
('lc',6,46,'crampon1923','Pourquoi m''appelez-vous Seigneur, Seigneur, et ne faites-vous pas ce que je dis?'),
('lc',6,47,'crampon1923','Tout homme qui vient à moi, qui écoute mes paroles, et les met en pratique, je vous montrerai à qui il est semblable.'),
('lc',6,48,'crampon1923','Il est semblable à un homme qui, bâtissant une maison, a creusé bien avant, et en a posé les fondements sur le roc. Une inondation étant survenue, le torrent s''est jeté contre cette maison, et il n''a pu l''ébranler, parce qu''elle était fondée sur le roc.'),
('lc',6,49,'crampon1923','Mais celui qui écoute et ne met pas en pratique, est semblable à un homme qui a bâti sa maison sur la terre, sans fondements; le torrent est venu se heurter contre elle, et elle est tombée aussitôt, et grande a été la ruine de cette maison. "'),
('lc',7,1,'crampon1923','Après qu''il eut achevé de faire entendre au peuple tous ses discours, Jésus entra dans Capharnaüm.'),
('lc',7,2,'crampon1923','Or, un centurion avait un serviteur malade, qui allait mourir et il l''aimait beaucoup.'),
('lc',7,3,'crampon1923','Ayant entendu parler de Jésus, il lui députa quelques anciens d''entre les Juifs, pour le prier de venir guérir son serviteur.'),
('lc',7,4,'crampon1923','Ceux-ci étant arrivés vers Jésus, le prièrent avec grande instance, en disant: " Il mérite que vous fassiez cela pour lui;'),
('lc',7,5,'crampon1923','car il aime notre nation, et il a même bâti notre synagogue. "'),
('lc',7,6,'crampon1923','Jésus s''en alla donc avec eux. Il n''était plus loin de la maison, lorsque le centurion envoya quelques-uns de ses amis lui dire: " Seigneur, ne prenez pas tant de peine, car je ne suis pas digne que vous entriez sous mon toit;'),
('lc',7,7,'crampon1923','aussi ne me suis-je pas même jugé digne de venir auprès de vous; mais dites un mot, et mon serviteur sera guéri.'),
('lc',7,8,'crampon1923','Car moi, qui suis soumis à des supérieurs, j''ai des soldats sous mes ordres, et je dis à l''un: Va, et il va; à un autre: Viens, et il vient; et à mon serviteur: Fais cela, et il le fait. "'),
('lc',7,9,'crampon1923','Ce qu''ayant entendu, Jésus admira cet homme, et, se tournant vers la foule qui le suivait, il dit: " Je vous le dis, en vérité, en Israël même je n''ai pas trouvé une si grande foi. "'),
('lc',7,10,'crampon1923','A leur retour dans la maison du centurion, les envoyés trouvèrent guéri le serviteur qui était malade.'),
('lc',7,11,'crampon1923','Quelques temps après, Jésus se rendait à une ville appelée Naïm; de nombreux disciples et une grande foule faisaient route avec lui.'),
('lc',7,12,'crampon1923','Comme il arrivait près de la porte de la ville, il se trouva qu''on emportait un mort, fils unique de sa mère, et celle-ci était veuve, et beaucoup de gens de la ville l''accompagnaient.'),
('lc',7,13,'crampon1923','Le Seigneur l''ayant vue, fut touché de compassion pour elle, et lui dit: " Ne pleurez pas. "'),
('lc',7,14,'crampon1923','Et s''approchant, il toucha le cercueil, les porteurs s''étant arrêtés; puis il dit: " Jeune homme, je te le commande, lève-toi. "'),
('lc',7,15,'crampon1923','Aussitôt le mort se leva sur son séant, et se mit à parler, et Jésus le rendit à sa mère.'),
('lc',7,16,'crampon1923','Tous furent saisis de crainte, et ils glorifiaient Dieu en disant: " Un grand prophète a paru parmi nous, et Dieu a visité son peuple. "'),
('lc',7,17,'crampon1923','Et cette parole prononcée à son sujet se répandit dans toute la Judée et dans tout le pays d''alentour.'),
('lc',7,18,'crampon1923','Les disciples de Jean lui ayant rapporté toutes ces choses,'),
('lc',7,19,'crampon1923','il en appela deux, et les envoya vers Jésus pour lui dire: " Etes-vous celui qui doit venir, ou devons-nous en attendre un autre? "'),
('lc',7,20,'crampon1923','Etant donc venus à lui: " Jean-Baptiste, lui dirent-ils, nous a envoyés vers vous pour vous demander: Etes-vous celui qui doit venir, ou devons-nous en attendre un autre? "'),
('lc',7,21,'crampon1923','— A ce moment même, Jésus guérit un grand nombre de personnes affligées par la maladie, les infirmités, ou les esprits malins, et accorda la vue à plusieurs aveugles. —'),
('lc',7,22,'crampon1923','Puis il répondit aux envoyés: " Allez rapporter à Jean ce que vous avez vu et entendu: les aveugles voient, les boiteux marchent, les lépreux sont purifiés, les sourds entendent, les morts ressuscitent, les pauvres sont évangélisés.'),
('lc',7,23,'crampon1923','Heureux celui qui ne se scandalise pas en moi! "'),
('lc',7,24,'crampon1923','Lorsque les envoyés de Jean furent partis, Jésus se mit à dire au peuple, au sujet de Jean: " Qu''êtes-vous allés voir au désert? Un roseau agité par le vent?'),
('lc',7,25,'crampon1923','Qu''êtes-vous allés voir au désert? Un homme vêtu d''habits moelleux? Mais ceux qui portent des vêtements précieux et vivent dans les délices sont dans les palais royaux.'),
('lc',7,26,'crampon1923','Enfin qu''êtes-vous allés voir? Un prophète? Oui, je vous le dis, et plus qu''un prophète.'),
('lc',7,27,'crampon1923','C''est de lui qu''il est écrit: J''envoie mon messager devant votre face, pour vous précéder et vous préparer la voie.'),
('lc',7,28,'crampon1923','Je vous le dis en effet, parmi les enfants des femmes, il n''y a pas de prophète plus grand que Jean-Baptiste; mais le plus petit dans le royaume de Dieu est plus grand que lui.'),
('lc',7,29,'crampon1923','Tout le peuple qui l''a entendu, et les publicains eux-mêmes, ont justifié Dieu, en se faisant baptiser du baptême de Jean,'),
('lc',7,30,'crampon1923','tandis que les Pharisiens et les Docteurs de la Loi ont annulé le dessein de Dieu à leur égard, en ne se faisant pas baptiser par lui. "'),
('lc',7,31,'crampon1923','" A qui donc, dit encore le Seigneur, comparerai-je les hommes de cette génération? A qui sont-ils semblables?'),
('lc',7,32,'crampon1923','Ils sont semblables à des enfants assis dans la place publique, qui s''interpellent entre eux et se disent les uns aux autres: Nous vous avons joué de la flûte, et vous n''avez pas dansé; nous vous avons chanté des complaintes, et vous n''avez point pleuré.'),
('lc',7,33,'crampon1923','Car Jean-Baptiste est venu, ne mangeant point de pain et ne buvant point de vin, et vous dites: Il est possédé du démon.'),
('lc',7,34,'crampon1923','Le Fils de l''homme est venu mangeant et buvant, et vous dites: C''est un homme de bonne chère et un buveur, un ami des publicains et des gens de mauvaise vie.'),
('lc',7,35,'crampon1923','Mais la Sagesse a été justifiée par tous ses enfants. "'),
('lc',7,36,'crampon1923','Un Pharisien ayant prié Jésus de manger avec lui, il entra dans sa maison et se mit à table.'),
('lc',7,37,'crampon1923','Et voici qu''une femme qui menait dans la ville une vie déréglée, ayant su qu''il était à table dans la maison du Pharisien, apporta un vase d''albâtre plein de parfum;'),
('lc',7,38,'crampon1923','et se tenant derrière lui, à ses pieds, tout en pleurs, elle se mit à les arroser de ses larmes et à les essuyer avec les cheveux de sa tête, et elle les baisait et les oignait de parfum.'),
('lc',7,39,'crampon1923','A cette vue, le Pharisien qui l''avait invité, dit en lui-même: " Si cet homme était prophète, il saurait qui et de quelle espèce est la femme qui le touche, et que c''est une pécheresse. "'),
('lc',7,40,'crampon1923','Alors prenant la parole, Jésus lui dit: " Simon, j''ai quelque chose à te dire. " — " Maître, parlez ", dit-il. —'),
('lc',7,41,'crampon1923','" Un créancier avait deux débiteurs; l''un devait cinq cents deniers et l''autre cinquante.'),
('lc',7,42,'crampon1923','Comme ils n''avaient pas de quoi payer leur dette, il en fit grâce à tous deux. Lequel donc l''aimera davantage? "'),
('lc',7,43,'crampon1923','Simon répondit: " Celui, je pense, auquel il a fait grâce de la plus forte somme. " Jésus lui dit: " Tu as bien jugé. "'),
('lc',7,44,'crampon1923','Et, se tournant vers la femme, il dit à Simon: " Vois-tu cette femme? Je suis entré dans ta maison, et tu n''as pas versé d''eau sur mes pieds; mais elle, elle les a mouillés de ses larmes, et les a essuyés avec ses cheveux.'),
('lc',7,45,'crampon1923','Tu ne m''as point donné de baiser; mais elle, depuis que je suis entré, elle n''a cessé de me baiser les pieds.'),
('lc',7,46,'crampon1923','Tu n''as pas oint ma tête d''huile, mais elle a oint mes pieds de parfum.'),
('lc',7,47,'crampon1923','C''est pourquoi, je te le déclare, ses nombreux péchés lui sont pardonnés, parce qu''elle a beaucoup aimé; mais celui à qui l''on pardonne peu, aime peu. "'),
('lc',7,48,'crampon1923','Puis il dit à la femme: " Tes péchés te sont pardonnés. "'),
('lc',7,49,'crampon1923','Et ceux qui étaient à table avec lui se mirent à dire en eux-mêmes: " Qui est celui-ci qui remet même les péchés? "'),
('lc',7,50,'crampon1923','Mais Jésus dit à la femme: " Ta foi t''a sauvée, va en paix. "'),
('lc',8,1,'crampon1923','Ensuite Jésus cheminait par les villes et par les villages, prêchant et annonçant la bonne nouvelle du royaume de Dieu. Les Douze étaient avec lui,'),
('lc',8,2,'crampon1923','ainsi que quelques femmes qui avaient été guéries d''esprits malins et de maladies: Marie, dite de Magdala, de laquelle étaient sortis sept démons;'),
('lc',8,3,'crampon1923','Jeanne, femme de Chusa, intendant d''Hérode, Suzanne et plusieurs autres, qui l''assistaient de leurs biens.'),
('lc',8,4,'crampon1923','Une grande foule s''étant amassée, et des gens étant venus à lui de diverses villes, Jésus dit en parabole:'),
('lc',8,5,'crampon1923','" Le semeur sortit pour répandre sa semence; et pendant qu''il semait, une partie tomba le long du chemin, et elle fut foulée aux pieds, et les oiseaux du ciel la mangèrent.'),
('lc',8,6,'crampon1923','Une autre partie tomba sur la pierre, et, aussitôt levée, elle sécha, parce qu''elle n''avait pas d''humidité.'),
('lc',8,7,'crampon1923','Une autre partie tomba parmi les épines, et les épines croissant avec elle l''étouffèrent.'),
('lc',8,8,'crampon1923','Une autre partie tomba dans la bonne terre, et ayant levé, elle donna du fruit au centuple. " Parlant ainsi, il disait à haute voix: " Que celui qui a des oreilles entende bien. "'),
('lc',8,9,'crampon1923','Ses disciples lui demandèrent ce que signifiait cette parabole:'),
('lc',8,10,'crampon1923','" A vous, leur dit-il, il a été donné de connaître le mystère du royaume de Dieu, tandis qu''aux autres, il est annoncé en paraboles, de sorte qu''en voyant ils ne voient point, et qu''en entendant ils ne comprennent point.'),
('lc',8,11,'crampon1923','Voici ce que signifie cette parabole: La semence, c''est la parole de Dieu.'),
('lc',8,12,'crampon1923','Ceux qui sont le long du chemin, ce sont ceux qui entendent la parole; mais ensuite le démon vient, et l''enlève de leur cœur, de peur qu''ils ne croient et ne soient sauvés.'),
('lc',8,13,'crampon1923','Ceux en qui on sème sur la pierre, ce sont ceux qui, entendant la parole, la reçoivent avec joie; mais ils n''ont point de racine: ils croient pour un temps, et ils succombent à l''heure de la tentation.'),
('lc',8,14,'crampon1923','Ce qui est tombé sur les épines, représente ceux qui, ayant entendu la parole, se laissent peu à peu étouffer par les soucis, les richesses et les plaisirs de la vie, et ils n''arrivent point à maturité.'),
('lc',8,15,'crampon1923','Enfin, ce qui est tombé dans la bonne terre, représente ceux qui, ayant entendu la parole avec un cœur bon et excellent, la gardent, et portent du fruit par la constance.'),
('lc',8,16,'crampon1923','Il n''est personne qui, après avoir allumé une lampe, la couvre d''un vase, ou la mette sous un lit; mais on la met sur un chandelier, afin que ceux qui entrent voient la lumière.'),
('lc',8,17,'crampon1923','Car il n''y a rien de caché qui ne se découvre, rien de secret qui ne finisse par être connu et ne vienne au grand jour.'),
('lc',8,18,'crampon1923','Prenez donc garde à la manière dont vous écoutez; car on donnera à celui qui a; et à celui qui n''a pas, on ôtera même ce qu''il croit avoir. "'),
('lc',8,19,'crampon1923','La mère et les frères de Jésus vinrent le trouver, mais ils ne purent pénétrer jusqu''à lui à cause de la foule.'),
('lc',8,20,'crampon1923','On vint lui dire: " Votre mère et vos frères sont là dehors, et ils désirent vous voir. "'),
('lc',8,21,'crampon1923','Il leur répondit: " Ma mère et mes frères sont ceux qui écoutent la parole de Dieu et qui la mettent en pratique. "'),
('lc',8,22,'crampon1923','Un jour, il arriva que Jésus monta dans une barque avec ses disciples, et leur dit: " Passons de l''autre côté du lac. " Et ils se mirent en mer.'),
('lc',8,23,'crampon1923','Pendant qu''ils naviguaient, il s''endormit; et un tourbillon de vent s''étant abattu sur le lac, leur barque s''emplissait d''eau, et ils étaient en péril.'),
('lc',8,24,'crampon1923','S''approchant donc, ils le réveillèrent en disant: " Maître! Maître! nous périssons! " S''étant levé, il réprimanda le vent et les flots agités, et ils s''apaisèrent, et le calme se fit.'),
('lc',8,25,'crampon1923','Puis il leur dit: " Où est votre foi? " Saisis de crainte et d''étonnement, ils se disaient les uns aux autres: " Quel est donc celui-ci, qui commande au vent et à la mer, et ils lui obéissent? "'),
('lc',8,26,'crampon1923','Ils abordèrent ensuite au pays des Géraséniens, qui est vis-à-vis de la Galilée.'),
('lc',8,27,'crampon1923','Lorsque Jésus fut descendu à terre, il vint au-devant de lui un homme de la ville, qui était depuis longtemps possédé des démons, il ne portait aucun vêtement et n''avait point d''autre habitation que les sépulcres.'),
('lc',8,28,'crampon1923','Aussitôt qu''il eut aperçu Jésus, il poussa des cris et vint se prosterner à ses pieds, disant à haute voix: " Qu''avez-vous à faire avec moi, Jésus, Fils de Dieu, Très-Haut? De grâce, ne me tourmentez point. "'),
('lc',8,29,'crampon1923','En effet, Jésus commandait à l''esprit impur de sortir de cet homme. Bien des fois en effet l''esprit s''en était emparé, et quoiqu''on le gardât lié de chaînes et de fers aux pieds, il rompait ses liens, et le démon le chassait dans les lieux déserts.'),
('lc',8,30,'crampon1923','Jésus lui demanda: " Quel est ton nom? " Il lui dit: " Je m''appelle Légion "; car beaucoup de démons étaient entrés en lui.'),
('lc',8,31,'crampon1923','Et ces démons priaient Jésus de ne pas leur commander d''aller dans l''abîme.'),
('lc',8,32,'crampon1923','Or, il y avait là un nombreux troupeau de porcs qui paissaient sur la montagne; ils le prièrent de leur permettre d''y entrer, et il le leur permit.'),
('lc',8,33,'crampon1923','Sortant donc de cet homme ils entrèrent dans les pourceaux; et le troupeau, prenant sa course, se précipita par les pentes escarpées dans le lac, et s''y noya.'),
('lc',8,34,'crampon1923','A cette vue, les gardiens s''enfuirent, et en portèrent la nouvelle dans la ville et dans la campagne.'),
('lc',8,35,'crampon1923','Les habitants sortirent pour voir ce qui était arrivé: ils vinrent à Jésus, et trouvèrent l''homme de qui les démons étaient sortis, assis à ses pieds, vêtu et sain d''esprit; et ils furent remplis de frayeur.'),
('lc',8,36,'crampon1923','Ceux qui en avaient été témoins leur racontèrent aussi comment le démoniaque avait été délivré.'),
('lc',8,37,'crampon1923','Alors tous les habitants du pays des Géraséniens le prièrent de s''éloigner d''eux, parce qu''ils étaient saisis d''une grande crainte. Jésus monta donc dans la barque pour s''en retourner.'),
('lc',8,38,'crampon1923','Or, l''homme de qui les démons étaient sortis le priait de l''admettre à sa suite; mais Jésus le renvoya en disant:'),
('lc',8,39,'crampon1923','" Retourne dans ta maison, et raconte tout ce que Dieu a fait pour toi. " Et il s''en alla et publia par toute la ville, ce que Jésus avait fait pour lui.'),
('lc',8,40,'crampon1923','Jésus, à son retour, fut accueilli par le peuple, car tous l''attendaient.'),
('lc',8,41,'crampon1923','Et voilà qu''un homme appelé Jaïre, lequel était chef de la synagogue, vint se jeter aux pieds de Jésus, le priant d''entrer dans sa maison,'),
('lc',8,42,'crampon1923','parce qu''il avait une fille unique, d''environ douze ans, qui se mourait. Comme Jésus y allait, et qu''il était pressé par la foule,'),
('lc',8,43,'crampon1923','une femme affligée d''un flux de sang depuis douze ans, et qui avait dépensé tout son bien en médecins, sans qu''aucun eût pu la guérir,'),
('lc',8,44,'crampon1923','s''approcha de lui par derrière et toucha la houppe de son manteau. A l''instant son flux de sang s''arrêta.'),
('lc',8,45,'crampon1923','Et Jésus dit: " Qui m''a touché? " Tous s''en défendant, Pierre et ceux qui étaient avec lui dirent: " Maître, la foule vous entoure et vous presse, et vous demandez: Qui m''a touché? "'),
('lc',8,46,'crampon1923','Mais Jésus dit: " Quelqu''un m''a touché, car j''ai senti qu''une force était sortie de moi. "'),
('lc',8,47,'crampon1923','Se voyant découverte, la femme vint toute tremblante se jeter à ses pieds, et raconta devant tout le peuple pourquoi elle l''avait touché, et comment elle avait été guérie à l''instant.'),
('lc',8,48,'crampon1923','Et Jésus lui dit: " Ma fille, ta foi t''a sauvée; va en paix. "'),
('lc',8,49,'crampon1923','Comme il parlait encore, quelqu''un de chez le chef de la synagogue vint lui dire: " Ta fille est morte, ne fatigue pas le Maître. "'),
('lc',8,50,'crampon1923','Jésus ayant entendu cette parole, répondit au père: " Ne crains pas; crois seulement, et elle sera sauvée. "'),
('lc',8,51,'crampon1923','Arrivé à la maison, il ne laissa personne entrer avec lui, si ce n''est Pierre, Jacques et Jean, avec le père et la mère de l''enfant.'),
('lc',8,52,'crampon1923','Or tous pleuraient et se lamentaient sur elle, et Jésus dit: " Ne pleurez point; elle n''est pas morte, mais elle dort. "'),
('lc',8,53,'crampon1923','Et ils se moquaient de lui, sachant bien qu''elle était morte.'),
('lc',8,54,'crampon1923','Mais lui, la prenant par la main, dit à haute voix: " Enfant, lève-toi "'),
('lc',8,55,'crampon1923','Et son esprit revint en elle, et elle se leva à l''instant; et Jésus ordonna de lui donner à manger.'),
('lc',8,56,'crampon1923','Ses parents furent dans le ravissement, mais il leur recommanda de ne dire à personne ce qui était arrivé.'),
('lc',9,1,'crampon1923','Ayant assemblé les Douze, Jésus leur donna puissance et autorité sur tous les démons, et le pouvoir de guérir les maladies.'),
('lc',9,2,'crampon1923','Et il les envoya prêcher le royaume de Dieu et guérir les malades,'),
('lc',9,3,'crampon1923','et il leur dit: " Ne prenez rien pour le voyage, ni bâton, ni sac, ni pain, ni argent, et n''ayez point deux tuniques.'),
('lc',9,4,'crampon1923','Dans quelque maison que vous entriez, demeurez-y jusqu''à ce que vous partiez de ce lieu.'),
('lc',9,5,'crampon1923','Si l''on refuse de vous recevoir, sortez de cette ville et secouez même la poussière de vos pieds en témoignage contre eux. "'),
('lc',9,6,'crampon1923','Les disciples étant partis allèrent de village en village, prêchant l''Evangile et opérant partout des guérisons.'),
('lc',9,7,'crampon1923','Cependant Hérode le tétrarque entendit parler de tout ce que faisait Jésus, et il ne savait que penser;'),
('lc',9,8,'crampon1923','car les uns disaient: " Jean est ressuscité des morts "; d''autres: " Elie a paru "; d''autres: " Un des anciens prophètes est ressuscité. "'),
('lc',9,9,'crampon1923','Hérode dit: " Quant à Jean, je l''ai fait décapiter. Quel est donc cet homme, de qui j''entends dire de telles choses? " Et il cherchait à le voir.'),
('lc',9,10,'crampon1923','Les apôtres, étant de retour, racontèrent à Jésus tout ce qu''ils avaient fait. Il les prit avec lui et se retira à l''écart dans un lieu désert, près d''une ville nommée Bethsaïde.'),
('lc',9,11,'crampon1923','Lorsque le peuple l''eut appris, il le suivit; Jésus les accueillit, et il leur parla du royaume de Dieu, et il rendit la santé à ceux qui en avaient besoin.'),
('lc',9,12,'crampon1923','Comme le jour commençait à baisser, les Douze vinrent lui dirent: " Renvoyez le peuple, afin que, se répandant dans les villages et les hameaux d''alentour, ils y trouvent un abri et de la nourriture; car nous sommes ici dans un lieu désert. "'),
('lc',9,13,'crampon1923','Il leur répondit: " Donnez-leur vous-mêmes à manger. " Ils lui dirent: " Nous n''avons que cinq pains et deux poissons, à moins peut-être que nous n''allions nous-mêmes acheter de quoi nourrir tout ce peuple! "'),
('lc',9,14,'crampon1923','Car il y avait environ cinq mille hommes. Jésus dit à ses disciples: " Faites-les asseoir par groupes de cinquante. "'),
('lc',9,15,'crampon1923','Ils lui obéirent et les firent asseoir.'),
('lc',9,16,'crampon1923','Alors Jésus prit les cinq pains et les deux poissons, et levant les yeux au ciel, il prononça une bénédiction, les rompit et les donna à ses disciples pour les servir au peuple.'),
('lc',9,17,'crampon1923','Tous mangèrent et furent rassasiés, et des morceaux qui étaient de reste, on emporta douze corbeilles.'),
('lc',9,18,'crampon1923','Un jour qu''il priait dans un lieu solitaire, ayant ses disciples avec lui, il leur fit cette question: " Qui suis-je, au dire des foules? "'),
('lc',9,19,'crampon1923','Ils répondirent: " Les uns disent Jean Baptiste; d''autres Elie; d''autres, qu''un des anciens prophètes est ressuscité. —'),
('lc',9,20,'crampon1923','Et vous, leur demanda-t-il, qui dites-vous que je suis? " Pierre répondit: " Le Christ de Dieu. "'),
('lc',9,21,'crampon1923','Mais il leur enjoignit d''un ton sévère de ne le dire à personne.'),
('lc',9,22,'crampon1923','" Il faut, ajouta-t-il, que le Fils de l''homme souffre beaucoup, qu''il soit rejeté par les Anciens, par les Princes des prêtres et par les Scribes, qu''il soit mis à mort et qu''il ressuscite le troisième jour. "'),
('lc',9,23,'crampon1923','Puis, s''adressant à tous, il dit: " Si quelqu''un veut venir après moi, qu''il se renonce lui-même, qu''il porte sa croix chaque jour, et me suive.'),
('lc',9,24,'crampon1923','Car celui qui voudra sauver sa vie la perdra, et celui qui perdra sa vie à cause de moi, la sauvera.'),
('lc',9,25,'crampon1923','Que sert-il à un homme de gagner le monde entier, s''il se ruine ou se perd lui-même?'),
('lc',9,26,'crampon1923','Et si quelqu''un rougit de moi et de mes paroles, le Fils de l''homme rougira de lui, lorsqu''il viendra dans sa gloire et dans celle du Père et des saints anges.'),
('lc',9,27,'crampon1923','Je vous le dis en vérité, quelques-uns de ceux qui sont ici présents ne goûteront point la mort, qu''ils n''aient vu le royaume de Dieu. "'),
('lc',9,28,'crampon1923','Environ huit jours après qu''il eut dit ces paroles, Jésus prit avec lui Pierre, Jacques et Jean, et monta sur la montagne pour prier.'),
('lc',9,29,'crampon1923','Pendant qu''il priait, l''aspect de son visage changea, et ses vêtements devinrent éblouissants de blancheur.'),
('lc',9,30,'crampon1923','Et voilà que deux hommes conversaient avec lui: c''étaient Moïse et Elie,'),
('lc',9,31,'crampon1923','apparaissant dans la gloire; ils s''entretenaient de sa mort qui devait s''accomplir dans Jérusalem.'),
('lc',9,32,'crampon1923','Pierre et ses compagnons étaient accablés de sommeil; mais s''étant tenus éveillés, ils virent la gloire de Jésus, et les deux hommes qui étaient avec lui.'),
('lc',9,33,'crampon1923','Au moment où ceux-ci s''éloignaient de lui, Pierre dit à Jésus: " Maître, il nous est bon d''être ici; dressons trois tentes, une pour vous, une pour Moïse et une pour Elie ", il ne savait ce qu''il disait.'),
('lc',9,34,'crampon1923','Comme il parlait ainsi, une nuée vint les couvrir de son ombre et les disciples furent saisis de frayeur tandis qu''ils entraient dans la nuée.'),
('lc',9,35,'crampon1923','Et de la nuée sortit une voix qui disait: " Celui-ci est mon Fils bien-aimé, écoutez-le. "'),
('lc',9,36,'crampon1923','Pendant que la voix parlait, Jésus se trouva seul. Les disciples gardèrent le silence, et ils ne racontèrent à personne, en ce temps-là, rien de ce qu''ils avaient vu.'),
('lc',9,37,'crampon1923','Le jour suivant, lorsqu''ils furent descendus de la montagne, une foule nombreuse vint au-devant de Jésus.'),
('lc',9,38,'crampon1923','Et un homme s''écria du milieu de la foule: " Maître, je vous en supplie, jetez un regard sur mon fils, car c''est mon seul enfant.'),
('lc',9,39,'crampon1923','Un esprit s''empare de lui, et aussitôt il pousse des cris; l''esprit l''agite avec violence en le faisant écumer, et à peine le quitte-t-il après l''avoir tout meurtri.'),
('lc',9,40,'crampon1923','J''ai prié vos disciples de le chasser, et ils ne l''ont pu. —'),
('lc',9,41,'crampon1923','O race incrédule et perverse, répondit Jésus, jusques à quand serai-je avec vous et vous supporterai-je? Amène ici ton fils. "'),
('lc',9,42,'crampon1923','Et comme l''enfant s''approchait, le démon le jeta par terre et l''agita violemment.'),
('lc',9,43,'crampon1923','Mais Jésus menaça l''esprit impur, guérit l''enfant et le rendit à son père.'),
('lc',9,44,'crampon1923','Et tous furent frappés de la grandeur de Dieu. Tandis que chacun était dans l''admiration de ce que faisait Jésus, il dit à ses disciples: " Vous, écoutez bien ceci. Le Fils de l''homme doit être livré entre les mains des hommes. "'),
('lc',9,45,'crampon1923','Mais ils ne comprenaient point cette parole; elle était voilée pour eux, de sorte qu''ils n''en avaient pas l''intelligence, et ils craignaient de l''interroger à ce sujet.'),
('lc',9,46,'crampon1923','Or, une pensée se glissa dans leur esprit, savoir lequel d''entre eux était le plus grand.'),
('lc',9,47,'crampon1923','Jésus, voyant les pensées de leur cœur, prit un petit enfant, le mit près de lui,'),
('lc',9,48,'crampon1923','et leur dit: " Quiconque reçoit en mon nom ce petit enfant, me reçoit; et quiconque me reçoit, reçoit Celui qui m''a envoyé. Car celui d''entre vous tous qui est le plus petit, c''est celui-là qui est grand. "'),
('lc',9,49,'crampon1923','Jean, prenant la parole, dit: " Maître, nous avons vu un homme qui chasse les démons en votre nom, et nous l''en avons empêché, parce qu''il ne va pas avec nous. —'),
('lc',9,50,'crampon1923','Ne l''en empêchez pas, lui répondit Jésus, car celui qui n''est pas contre vous est pour vous. "'),
('lc',9,51,'crampon1923','Quand les jours où il devait être enlevé du monde furent près de s''accomplir, il prit la résolution d''aller à Jérusalem,'),
('lc',9,52,'crampon1923','Il envoya devant lui des messagers, qui se mirent en route, et entrèrent dans un bourg des Samaritains pour préparer sa réception;'),
('lc',9,53,'crampon1923','mais les habitants refusèrent de le recevoir, parce qu''il se dirigeait vers Jérusalem.'),
('lc',9,54,'crampon1923','Ce que voyant, ses disciples Jacques et Jean dirent: " Seigneur, voulez-vous que nous commandions que le feu descende du ciel et les consume? "'),
('lc',9,55,'crampon1923','Jésus, s''étant retourné, les reprit en disant: " Vous ne savez pas de quel esprit vous êtes!'),
('lc',9,56,'crampon1923','Le Fils de l''homme est venu, non pour perdre les vies d''hommes, mais pour les sauver. " Et ils allèrent dans une autre bourgade.'),
('lc',9,57,'crampon1923','Pendant qu''ils étaient en chemin, un homme lui dit: " Je vous suivrai partout où vous irez. "'),
('lc',9,58,'crampon1923','Jésus lui répondit: " Les renards ont des tanières, et les oiseaux du ciel des nids; mais le Fils de l''homme n''a pas où reposer sa tête. "'),
('lc',9,59,'crampon1923','Il dit à un autre: " Suis-moi. " Celui-ci répondit: " Seigneur, permettez-moi d''aller auparavant ensevelir mon père. "'),
('lc',9,60,'crampon1923','Mais Jésus lui dit: " Laisse les morts ensevelir leurs morts; pour toi, va annoncer le royaume de Dieu. "'),
('lc',9,61,'crampon1923','Un autre lui dit: " Je vous suivrai, Seigneur, mais permettez-moi d''aller auparavant faire mes adieux à ceux de ma maison. "'),
('lc',9,62,'crampon1923','Jésus lui répondit: " Quiconque met la main à la charrue et regarde en arrière, n''est pas propre au royaume de Dieu. "'),
('lc',10,1,'crampon1923','Après cela, le Seigneur en désigna encore soixante-douze autres, et les envoya devant lui, deux à deux, dans toutes les villes et tous les lieux où lui-même devait aller.'),
('lc',10,2,'crampon1923','Il leur dit: " La moisson est grande, mais les ouvriers sont en petit nombre. Priez donc le maître de la moisson d''envoyer des ouvriers à sa moisson.'),
('lc',10,3,'crampon1923','Partez: voici que je vous envoie comme des agneaux au milieu des loups.'),
('lc',10,4,'crampon1923','Ne portez ni bourse, ni sac, ni souliers, et ne saluez personne en chemin.'),
('lc',10,5,'crampon1923','Dans quelque maison que vous entriez, dites d''abord: Paix à cette maison!'),
('lc',10,6,'crampon1923','Et s''il s''y trouve un enfant de paix, votre paix reposera sur lui; sinon, elle reviendra à vous.'),
('lc',10,7,'crampon1923','Demeurez dans la même maison, mangeant et buvant de ce qu''il y aura chez eux; car l''ouvrier mérite son salaire. Ne passez pas d''une maison dans une autre.'),
('lc',10,8,'crampon1923','Dans quelque ville que vous entriez, si l''on vous reçoit, mangez ce qu''on vous présentera;'),
('lc',10,9,'crampon1923','guérissez les malades qui s''y trouveront, et dites-leur: Le royaume de Dieu est proche de vous.'),
('lc',10,10,'crampon1923','Mais dans quelque ville que vous entriez, si l''on ne vous reçoit pas, allez sur les places publiques et dites:'),
('lc',10,11,'crampon1923','La poussière même de votre ville, qui s''est attachée à nous, nous l''essuyons contre vous; sachez cependant ceci, c''est que le royaume de Dieu est proche.'),
('lc',10,12,'crampon1923','Je vous le dis, il y aura, en ce jour-là, moins de rigueur pour Sodome que pour cette ville.'),
('lc',10,13,'crampon1923','Malheur à toi, Corozaïn! Malheur à toi, Bethsaïde! Car si les miracles qui ont été faits au milieu de vous, l''avaient été dans Tyr et dans Sidon, elles auraient depuis longtemps fait pénitence, assises sous le cilice et la cendre.'),
('lc',10,14,'crampon1923','C''est pourquoi, il y aura, au jugement, moins de rigueur pour Tyr et pour Sidon que pour vous.'),
('lc',10,15,'crampon1923','Et toi, Capharnaüm, qui t''élèves au ciel, tu seras abaissée jusqu''aux enfers.'),
('lc',10,16,'crampon1923','Celui qui vous écoute, m''écoute, et celui qui vous méprise, me méprise; or celui qui me méprise, méprise Celui qui m''a envoyé. "'),
('lc',10,17,'crampon1923','Les soixante-douze revinrent avec joie, disant: " Seigneur, les démons mêmes nous sont soumis en votre nom. "'),
('lc',10,18,'crampon1923','Il leur répondit: " Je contemplais Satan tombant du ciel comme la foudre.'),
('lc',10,19,'crampon1923','Voilà que je vous ai donné le pouvoir de fouler aux pieds les serpents et les scorpions, et toute la puissance de l''ennemi, et elle ne pourra vous nuire en rien.'),
('lc',10,20,'crampon1923','Seulement ne vous réjouissez pas de ce que les esprits vous sont soumis; mais réjouissez-vous de ce que vos noms sont écrits dans les cieux. "'),
('lc',10,21,'crampon1923','Au même moment, il tressaillit de joie sous l''action de l''Esprit-Saint, et il dit: " Je vous bénis, ô Père, Seigneur du ciel et de la terre, de ce que vous avez caché ces choses aux sages et aux prudents, et les avez révélées aux petits enfants. Oui, je vous bénis, ô Père, de ce qu''il vous a plu ainsi.'),
('lc',10,22,'crampon1923','Toutes choses m''ont été données par mon Père; et personne ne sait ce qu''est le Fils, si ce n''est le Père, et ce qu''est le Père, si ce n''est le Fils, et celui à qui le Fils veut bien le révéler. "'),
('lc',10,23,'crampon1923','Et se tournant vers ses disciples, il leur dit en particulier: " Heureux les yeux qui voient ce que vous voyez!'),
('lc',10,24,'crampon1923','Car, je vous le dis, beaucoup de prophètes et de rois ont désiré voir ce que vous voyez, et ne l''ont pas vu, entendre ce que vous entendez, et ne l''ont pas entendu. "'),
('lc',10,25,'crampon1923','Et voici qu''un docteur de la Loi, s''étant levé, lui dit pour l''éprouver: " Maître, que ferai-je pour posséder la vie éternelle? "'),
('lc',10,26,'crampon1923','Jésus lui dit: " Qu''y a-t-il d''écrit dans la Loi? Qu''y lis-tu? "'),
('lc',10,27,'crampon1923','Il répondit: " Tu aimeras le Seigneur ton Dieu de tout cœur, de toute ton âme, de toute tes forces et de tout ton esprit, et ton prochain comme toi-même. "'),
('lc',10,28,'crampon1923','Jésus lui dit: " Tu as bien répondu, fais cela et tu vivras. "'),
('lc',10,29,'crampon1923','Mais cet homme, voulant se justifier, dit à Jésus: " Et qui est mon prochain? "'),
('lc',10,30,'crampon1923','Jésus reprit: " Un homme descendait de Jérusalem à Jéricho; il tomba entre les mains des brigands, qui le dépouillèrent, et l''ayant chargé de coups, se retirèrent, le laissant à demi-mort.'),
('lc',10,31,'crampon1923','Or, il arriva qu''un prêtre descendait par le même chemin; il vit cet homme et passa outre.'),
('lc',10,32,'crampon1923','De même un lévite, étant venu dans ce lieu, s''approcha, le vit et passa outre.'),
('lc',10,33,'crampon1923','Mais un Samaritain, qui était en voyage, arriva près de lui, et, le voyant, fut touché de compassion.'),
('lc',10,34,'crampon1923','Il s''approcha, banda ses plaies, après y avoir versé de l''huile et du vin; puis il le mit sur sa propre monture, le mena dans une hôtellerie, et prit soin de lui.'),
('lc',10,35,'crampon1923','Le lendemain, tirant deux deniers, il les donna à l''hôte et lui dit: Aie soin de cet homme, et tout ce que tu dépenseras de plus, je te le rendrai à mon retour.'),
('lc',10,36,'crampon1923','Lequel de ces trois te semble avoir été le prochain de l''homme qui tomba entre les mains des brigands? "'),
('lc',10,37,'crampon1923','Le docteur répondit: " Celui qui a pratiqué la miséricorde envers lui. " Et Jésus lui dit: " Toi aussi, va et fais de même. "'),
('lc',10,38,'crampon1923','Pendant qu''ils étaient en chemin, Jésus entra dans un village, et une femme, nommée Marthe, le reçut dans sa maison.'),
('lc',10,39,'crampon1923','Elle avait une sœur, nommée Marie, qui, s''étant assise aux pieds du Seigneur, écoutait sa parole,'),
('lc',10,40,'crampon1923','tandis que Marthe s''empressait aux divers soins du service. S''étant donc arrêtée: " Seigneur, dit-elle, ne vous mettez-vous pas en peine que ma sœur m''ait laissée servir seule? Dites-lui donc de m''aider. "'),
('lc',10,41,'crampon1923','Le Seigneur lui répondit: " Marthe, Marthe, vous vous inquiétez et vous agitez pour beaucoup de choses.'),
('lc',10,42,'crampon1923','Une seule est nécessaire. Marie a choisi la bonne part, qui ne lui sera point ôtée. "'),
('lc',11,1,'crampon1923','Un jour que Jésus était en prière en un certain lieu, lorsqu''il eut achevé, un de ses disciples lui dit: " Seigneur, apprenez-nous à prier, comme Jean l''a appris à ses disciples. "'),
('lc',11,2,'crampon1923','Il leur dit: " Lorsque vous priez, dites: Père, que votre nom soit sanctifié, que votre règne arrive.'),
('lc',11,3,'crampon1923','Donnez-nous aujourd''hui le pain nécessaire à notre subsistance,'),
('lc',11,4,'crampon1923','et remettez-nous nos offenses, car nous remettons nous-mêmes à tous ceux qui nous doivent; et ne nous induisez pas en tentation. "'),
('lc',11,5,'crampon1923','Il leur dit encore: " Si quelqu''un de vous, ayant un ami, va le trouver au milieu de la nuit, disant: Mon ami, prête-moi trois pains,'),
('lc',11,6,'crampon1923','car un de mes ami qui voyage est arrivé chez moi, et je n''ai rien à lui offrir;'),
('lc',11,7,'crampon1923','et que de l''intérieur de la maison, l''autre réponde: Ne m''importune point; la porte est déjà fermée, mes enfants et moi nous sommes au lit; je ne puis me lever pour te rien donner:'),
('lc',11,8,'crampon1923','je vous le dis, quand même il ne se lèverait pas pour lui donner, parce qu''il est son ami, il se lèvera à cause de son importunité, et lui donnera autant de pains qu''il en a besoin.'),
('lc',11,9,'crampon1923','Et moi je vous dis: Demandez, et l''on vous donnera; cherchez, et vous trouverez; frappez, et l''on vous ouvrira.'),
('lc',11,10,'crampon1923','Car quiconque demande, reçoit; et qui cherche, trouve, et l''on ouvrira à celui qui frappe.'),
('lc',11,11,'crampon1923','Quel est parmi vous le père qui, si son fils lui demande du pain, lui donne une pierre? ou, si c''est un poisson, lui donnera-t-il, au lieu de poisson, un serpent?'),
('lc',11,12,'crampon1923','ou, s''il lui demande un œuf, lui donnera-t-il un scorpion?'),
('lc',11,13,'crampon1923','Si donc vous, tout méchants que vous êtes, vous savez donner à vos enfants de bonnes choses, combien plus votre Père céleste donnera-t-il l''Esprit-Saint à ceux qui le lui demandent? "'),
('lc',11,14,'crampon1923','Jésus chassait un démon, et ce démon était muet. Lorsque le démon fut sorti, le muet parla, et le peuple était dans l''admiration.'),
('lc',11,15,'crampon1923','Mais quelques-uns d''entre eux dirent: " C''est par Béelzébub, prince des démons, qu''il chasse les démons. "'),
('lc',11,16,'crampon1923','D''autres, pour l''éprouver, lui demandèrent un signe dans le ciel.'),
('lc',11,17,'crampon1923','Connaissant leurs pensées, Jésus leur dit: " Tout royaume divisé contre lui-même, se détruit, les maisons tombent l''une sur l''autre.'),
('lc',11,18,'crampon1923','Si donc Satan est divisé contre lui-même, comment son royaume subsistera-t-il? Car vous dites que c''est par Béelzébub que je chasse les démons.'),
('lc',11,19,'crampon1923','Et si, moi, je chasse les démons par Béelzébub, vos fils, par qui les chassent-ils? C''est pourquoi ils seront eux-mêmes vos juges.'),
('lc',11,20,'crampon1923','Mais si c''est par le doigt de Dieu que je chasse les démons, le royaume de Dieu est donc venu à vous.'),
('lc',11,21,'crampon1923','Lorsqu''un homme fort et bien armé garde l''entrée de sa maison, ce qu''il possède est en sûreté.'),
('lc',11,22,'crampon1923','Mais qu''il en survienne un plus fort qui le vainque, il lui enlève toutes les armes dans lesquelles il se confiait, et il partage ses dépouilles.'),
('lc',11,23,'crampon1923','Qui n''est pas avec moi est contre moi, et qui n''amasse pas avec moi, dissipe.'),
('lc',11,24,'crampon1923','Lorsque l''esprit impur est sorti d''un homme, il va par des lieux arides, cherchant du repos. N''en trouvant point, il dit: Je retournerai dans ma maison, d''où je suis sorti.'),
('lc',11,25,'crampon1923','Et quand il arrive, il la trouve nettoyée et ornée.'),
('lc',11,26,'crampon1923','Alors il s''en va, prend avec lui sept autres esprits plus méchants que lui; puis ils entrent et s''y établissent: et le dernier état de cet homme devient pire que le premier. "'),
('lc',11,27,'crampon1923','Comme il parlait ainsi, une femme élevant la voix du milieu de la foule, lui dit: " Heureux le sein qui vous a porté, et les mamelles que vous avez sucées! "'),
('lc',11,28,'crampon1923','Jésus répondit: " Heureux plutôt ceux qui écoutent la parole de Dieu et qui la gardent! "'),
('lc',11,29,'crampon1923','Le peuple s''amassant en foules, il se mit à dire: " Cette génération est une génération méchante; elle demande un signe, et il ne lui en sera point donné d''autre que celui du prophète Jonas.'),
('lc',11,30,'crampon1923','Car, de même que Jonas fut un signe pour les Ninivites, ainsi le Fils de l''homme sera un signe pour cette génération.'),
('lc',11,31,'crampon1923','La reine du Midi se lèvera, au jour du jugement, avec les hommes de cette génération, et les condamnera, parce qu''elle est venue des extrémités de la terre entendre la sagesse de Salomon: et il y a ici plus que Salomon.'),
('lc',11,32,'crampon1923','Les hommes de Ninive se lèveront, au jour du jugement, avec cette génération et la condamneront, parce qu''ils ont fait pénitence à la prédication de Jonas; et il y a ici plus que Jonas.'),
('lc',11,33,'crampon1923','Personne n''allume une lampe pour la mettre dans un lieu caché ou sous le boisseau: on la met sur le chandelier, afin que ceux qui entrent voient la lumière.'),
('lc',11,34,'crampon1923','La lampe de ton corps, c''est ton œil. Si ton œil est sain, tout ton corps sera dans la lumière; s''il est mauvais, ton corps aussi sera dans les ténèbres.'),
('lc',11,35,'crampon1923','Prends donc garde que la lumière qui est en toi ne soit ténèbres.'),
('lc',11,36,'crampon1923','Si donc tout ton corps est dans la lumière, sans mélange de ténèbres, il sera éclairé tout entier, comme lorsque brille sur toi la clarté d''une lampe. "'),
('lc',11,37,'crampon1923','Pendant qu''il parlait, un Pharisien le pria de dîner chez lui; Jésus entra et se mit à table.'),
('lc',11,38,'crampon1923','Or le Pharisien vit avec étonnement qu''il n''avait point fait l''ablution avant le dîner.'),
('lc',11,39,'crampon1923','Le Seigneur lui dit: " Vous, Pharisiens, vous nettoyez le dehors de la coupe et du plat; mais au dedans de vous tout est plein de rapine et d''iniquité.'),
('lc',11,40,'crampon1923','Insensés! celui qui a fait le dehors n''a-t-il pas fait aussi le dedans?'),
('lc',11,41,'crampon1923','Toutefois, donnez l''aumône selon vos moyens, et tout sera pur pour vous.'),
('lc',11,42,'crampon1923','Mais malheur à vous, Pharisiens, qui payez la dîme de la menthe, de la rue et de toute plante potagère et qui n''avez nul soucis de la justice et de l''amour de Dieu! C''est là ce qu''il fallait pratiquer, sans omettre le reste.'),
('lc',11,43,'crampon1923','Malheur à vous, Pharisiens, qui aimez les premiers sièges dans les synagogues, et les salutations dans les places publiques!'),
('lc',11,44,'crampon1923','Malheur à vous, parce que vous ressemblez à des sépulcres qu''on ne voit pas et sur lesquels on marche sans le savoir! "'),
('lc',11,45,'crampon1923','Alors un docteurs de la Loi, prenant la parole, lui dit: " Maître, en parlant de la sorte, vous nous outragez aussi. "'),
('lc',11,46,'crampon1923','Jésus répondit: " Et à vous aussi, docteurs de la Loi, malheur! parce que vous chargez les hommes de fardeaux difficiles à porter, et vous-mêmes, vous n''y touchez pas d''un seul de vos doigts!'),
('lc',11,47,'crampon1923','Malheur à vous, qui bâtissez des tombeaux aux prophètes, et ce sont vos pères qui les ont tués!'),
('lc',11,48,'crampon1923','Vous servez donc de témoins et vous applaudissez aux œuvres de vos pères; car eux les ont tués, et vous, vous leur bâtissez des tombeaux.'),
('lc',11,49,'crampon1923','C''est pourquoi la Sagesse de Dieu a dit: Je leur enverrai des prophètes et des apôtres; ils tueront plusieurs d''entre eux et en persécuteront d''autres:'),
('lc',11,50,'crampon1923','afin qu''il soit redemandé compte à cette génération du sang de tous les prophètes qui a été répandu depuis la création du monde,'),
('lc',11,51,'crampon1923','depuis le sang d''Abel jusqu''au sang de Zacharie, tué entre l''autel et le sanctuaire. Oui, je vous le dis, il en sera redemandé compte à cette génération.'),
('lc',11,52,'crampon1923','Malheur à vous, docteurs de la Loi, parce que vous avez enlevé la clef de la science; vous-mêmes n''êtes point entrés, et vous avez empêché ceux qui entraient! "'),
('lc',11,53,'crampon1923','Comme Jésus leur disait ces choses, les Pharisiens et les Scribes se mirent à le presser vivement et à l''accabler de questions,'),
('lc',11,54,'crampon1923','lui tendant des pièges, et cherchant à surprendre quelque parole de sa bouche pour l''accuser.'),
('lc',12,1,'crampon1923','Sur ces entrefaites, les gens s''étant rassemblés par milliers, au point de se fouler les uns les autres, Jésus se mit à dire à ses disciples: " Gardez-vous avant tout du levain des Pharisiens, qui est l''hypocrisie.'),
('lc',12,2,'crampon1923','Il n''y a rien de caché qui ne doive être révélé, rien de secret qui ne doive être connu.'),
('lc',12,3,'crampon1923','C''est pourquoi, tout ce que vous aurez dit dans les ténèbres, on l''entendra au grand jour; et ce que vous aurez dit à l''oreille dans l''intérieur de la maison, sera publié sur les toits.'),
('lc',12,4,'crampon1923','Mais je vous dis, à vous qui êtes mes amis: Ne craignez pas ceux qui tuent le corps, et qui après cela ne peuvent rien faire de plus.'),
('lc',12,5,'crampon1923','Je vais vous apprendre qui vous devez craindre: craignez celui qui, après avoir tué, a le pouvoir de jeter dans la géhenne; oui, je vous le dis, craignez celui-là.'),
('lc',12,6,'crampon1923','Cinq passereaux ne se vendent-ils pas deux as? Et pas un d''eux n''est en oubli devant Dieu.'),
('lc',12,7,'crampon1923','Mais les cheveux mêmes de votre tête sont tous comptés. Ne craignez donc point: vous êtes de plus de prix que beaucoup de passereaux.'),
('lc',12,8,'crampon1923','Je vous le dis encore, quiconque m''aura confessé devant les hommes, le Fils de l''homme aussi le confessera devant les anges de Dieu;'),
('lc',12,9,'crampon1923','mais celui qui m''aura renié devant les hommes, sera renié devant les anges de Dieu.'),
('lc',12,10,'crampon1923','Et quiconque parlera contre le Fils de l''homme, obtiendra le pardon; mais pour celui qui aura blasphémé contre l''Esprit-Saint, il n''y aura point de pardon.'),
('lc',12,11,'crampon1923','Quand on vous conduira devant les synagogues, les magistrats et les autorités, ne vous mettez point en peine de la manière dont vous vous défendrez, ni de ce que vous direz;'),
('lc',12,12,'crampon1923','car le Saint-Esprit vous enseignera à l''heure même ce qu''il faudra dire. "'),
('lc',12,13,'crampon1923','Alors du milieu de la foule quelqu''un dit à Jésus: " Maître, dites à mon frère de partager avec moi notre héritage. "'),
('lc',12,14,'crampon1923','Jésus lui répondit: " Homme, qui m''a établi pour être votre juge, ou pour faire vos partages? "'),
('lc',12,15,'crampon1923','Et il dit au peuple: " Gardez-vous avec soin de toute avarice; car, dans l''abondance même, la vie d''un homme ne dépend pas des biens qu''il possède. "'),
('lc',12,16,'crampon1923','Puis il leur dit cette parabole: " Il y avait un homme riche dont le domaine avait beaucoup rapporté.'),
('lc',12,17,'crampon1923','Et il s''entretenait en lui-même de ces pensées: Que ferai-je? car je n''ai pas de place pour serrer ma récolte.'),
('lc',12,18,'crampon1923','Voici, dit-il, ce que je ferai. J''abattrai mes greniers, et j''en construirai de plus grands, et j''y amasserai la totalité de mes récoltes et de mes biens.'),
('lc',12,19,'crampon1923','Et je dirai à mon âme: Mon âme, tu as de grands biens en réserve pour beaucoup d''années; repose-toi, mange, bois, fais bonne chère.'),
('lc',12,20,'crampon1923','Mais Dieu lui dit: Insensé! cette nuit même on te redemandera ton âme; et ce que tu as mis en réserve, pour qui sera-t-il?'),
('lc',12,21,'crampon1923','Il en est ainsi de l''homme qui amasse des trésors pour lui-même, et qui n''est pas riche devant Dieu. "'),
('lc',12,22,'crampon1923','Jésus dit ensuite à ses disciples: " C''est pourquoi je vous dis: Ne vous inquiétez pas pour votre vie, de ce que vous mangerez; ni pour votre corps, de quoi vous le vêtirez.'),
('lc',12,23,'crampon1923','La vie est plus que la nourriture, et le corps plus que le vêtement.'),
('lc',12,24,'crampon1923','Considérez les corbeaux: ils ne sèment ni ne moissonnent; ils n''ont ni cellier ni grenier, et Dieu les nourrit. Combien ne valez-vous pas plus que ces oiseaux?'),
('lc',12,25,'crampon1923','Qui de vous pourrait, à force de soucis, ajouter une coudée à la longueur de sa vie?'),
('lc',12,26,'crampon1923','Si donc les moindres choses sont au-dessus de votre pouvoir, pourquoi vous inquiétez-vous des autres?'),
('lc',12,27,'crampon1923','Considérez les lis, comment ils croissent, ils ne travaillent ni ne filent, et, je vous le dis, Salomon dans toute sa gloire n''était pas vêtu comme l''un d''eux.'),
('lc',12,28,'crampon1923','Si Dieu revêt de la sorte l''herbe, qui est aujourd''hui dans les champs et qui demain sera jetée au four, combien plus le fera-t-il pour vous, hommes de peu de foi!'),
('lc',12,29,'crampon1923','Vous non plus, ne cherchez pas ce que vous mangerez ou ce que vous boirez, et ne soyez pas en suspens dans l''inquiétude.'),
('lc',12,30,'crampon1923','Car ce sont les gens de ce monde qui se préoccupent de toutes ces choses; mais votre Père sait que vous en avez besoin.'),
('lc',12,31,'crampon1923','Au reste, cherchez le royaume de Dieu, et tout cela vous sera donné par surcroît.'),
('lc',12,32,'crampon1923','Ne craignez point, petit troupeau, car il a plus à votre Père de vous donner le royaume.'),
('lc',12,33,'crampon1923','Vendez ce que vous avez, et donnez l''aumône. Faites-vous des bourses que le temps n''use pas, un trésor inépuisable dans les cieux, où les voleurs n''ont point d''accès, et où les mites ne rongent point.'),
('lc',12,34,'crampon1923','Car là où est votre trésor, là aussi sera votre cœur.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('lc',12,35,'crampon1923','Ayez la ceinture aux reins et vos lampes allumées!'),
('lc',12,36,'crampon1923','Soyez semblables à des hommes qui attendent le moment où leur maître reviendra des noces, afin que, dès qu''il arrivera et frappera à la porte, ils lui ouvrent aussitôt.'),
('lc',12,37,'crampon1923','Heureux ces serviteurs que le maître, à son retour, trouvera veillant! Je vous le dis en vérité, il se ceindra, il les fera mettre à table, et s''approchera pour les servir.'),
('lc',12,38,'crampon1923','Qu''il arrive à la deuxième veille, qu''il arrive à la troisième, s''il les trouve ainsi, heureux ces serviteurs!'),
('lc',12,39,'crampon1923','Mais sachez bien que si le père de famille savait à quelle heure le voleur doit venir, il veillerait et ne laisserait point percer sa maison.'),
('lc',12,40,'crampon1923','Vous aussi, tenez-vous prêts, car le Fils de l''homme viendra à l''heure que vous ne pensez pas. "'),
('lc',12,41,'crampon1923','Alors Pierre lui dit: " Est-ce à nous que vous adressez cette parabole, ou bien est-ce aussi à tous? "'),
('lc',12,42,'crampon1923','Le Seigneur répondit: " Quel est l''économe fidèle et sage que le maître établira sur ses serviteurs, pour distribuer, au temps convenable, la mesure de froment?'),
('lc',12,43,'crampon1923','Heureux ce serviteur, que le maître, à son arrivée, trouvera agissant ainsi!'),
('lc',12,44,'crampon1923','Je vous le dis, en vérité, il l''établira sur tous ses biens.'),
('lc',12,45,'crampon1923','Mais si ce serviteur dit en lui-même: Mon maître tarde à venir; et qu''il se mette à battre les serviteurs et les servantes, à manger, à boire et à s''enivrer,'),
('lc',12,46,'crampon1923','le maître de ce serviteur viendra au jour où il ne s''attend pas et à l''heure qu''il ne sait pas, et il le fera déchirer de coups, et lui assignera sa part avec les infidèles.'),
('lc',12,47,'crampon1923','Ce serviteur-là qui aura connu la volonté de son maître, et qui n''aura rien tenu prêt, ni agi selon sa volonté, recevra un grand nombre de coups.'),
('lc',12,48,'crampon1923','Mais celui qui ne l''aura pas connue, et qui aura fait des choses dignes de châtiment, recevra peu de coups. On exigera beaucoup de celui à qui l''on a beaucoup donné; et plus on aura confié à quelqu''un, plus on lui demandera.'),
('lc',12,49,'crampon1923','Je suis venu jeter le feu sur la terre, et que désiré-je, si déjà il est allumé?'),
('lc',12,50,'crampon1923','Je dois encore être baptisé d''un baptême, et quelle angoisse en moi jusqu''à ce qu''il soit accompli!'),
('lc',12,51,'crampon1923','Pensez-vous que je sois venu établir la paix sur la terre? Non, vous dis-je, mais bien la division.'),
('lc',12,52,'crampon1923','Car désormais, s''il y a cinq personnes dans une maison, elles seront divisés, trois contre deux, et deux contre trois;'),
('lc',12,53,'crampon1923','le père sera divisé contre son fils, et le fils contre son père; la mère contre sa fille et la fille contre sa mère; la belle-mère contre sa belle-fille, et la belle-fille contre sa belle-mère. "'),
('lc',12,54,'crampon1923','Il disait encore au peuple: " Lorsque vous voyez la nuée se lever au couchant, vous dites aussitôt: La pluie vient; et cela arrive ainsi.'),
('lc',12,55,'crampon1923','Et quand vous voyez souffler le vent du midi, vous dites: Il fera chaud, et cela arrive.'),
('lc',12,56,'crampon1923','Hypocrites, vous savez reconnaître les aspects du ciel et de la terre; comment donc ne reconnaissez-vous pas le temps où nous sommes?'),
('lc',12,57,'crampon1923','Et comment ne discernez-vous pas de vous-mêmes ce qui est juste?'),
('lc',12,58,'crampon1923','En effet, lorsque tu te rends avec ton adversaire devant le magistrat, tâche en chemin de te dégager de sa poursuite, de peur qu''il ne te traîne devant le juge, et que le juge ne te livre à l''officier de justice, et que celui-ci ne te jette en prison.'),
('lc',12,59,'crampon1923','Je te le dis, tu ne sortiras point de là que tu n''aies payé jusqu''à la dernière obole. "'),
('lc',13,1,'crampon1923','En ce même temps, quelques-uns vinrent raconter à Jésus ce qui était arrivé aux Galiléens, dont Pilate avait mêlé le sang avec celui de leurs sacrifices.'),
('lc',13,2,'crampon1923','Il leur répondit: " Pensez-vous que ces Galiléens fussent de plus grands pécheurs que tous les autres Galiléens, pour avoir souffert de la sorte?'),
('lc',13,3,'crampon1923','Non, je vous le dis; mais si vous ne vous repentez, vous périrez tous comme eux.'),
('lc',13,4,'crampon1923','Ou bien ces dix-huit sur qui tomba la tour de Siloé, et qu''elle tua, pensez-vous que leur dette fût plus grande que celle de tous les autres habitants de Jérusalem?'),
('lc',13,5,'crampon1923','Non, je vous le dis; mais si vous ne vous repentez, vous périrez tous de même. "'),
('lc',13,6,'crampon1923','Il dit aussi cette parabole: " Un homme avait un figuier planté dans sa vigne; il vint pour y chercher des fruits, et n''en trouvant point,'),
('lc',13,7,'crampon1923','il dit au vigneron: Voilà trois ans que je viens chercher du fruit à ce figuier, et je n''en trouve point; coupe-le donc: pourquoi rend-il la terre improductive?'),
('lc',13,8,'crampon1923','Le vigneron lui répondit: Seigneur, laissez-le encore cette année, jusqu''à ce que j''aie creusé et mis du fumier tout autour.'),
('lc',13,9,'crampon1923','Peut-être portera-t-il du fruit ensuite; sinon, vous le couperez. "'),
('lc',13,10,'crampon1923','Jésus enseignait dans une synagogue un jour de sabbat.'),
('lc',13,11,'crampon1923','Or, il y avait là une femme possédée depuis dix-huit ans d''un esprit qui la rendait infirme: elle était courbée, et ne pouvait absolument pas se redresser.'),
('lc',13,12,'crampon1923','L''ayant vue, Jésus l''appela et lui dit: " Femme, tu es délivrée de ton infirmité. "'),
('lc',13,13,'crampon1923','Et il lui imposa les mains; aussitôt elle se redressa, et elle glorifiait Dieu.'),
('lc',13,14,'crampon1923','Mais le chef de synagogue, indigné de ce que Jésus avait fait cette guérison un jour de sabbat, prit la parole et dit au peuple: " Il y a six jours pour travailler, venez donc vous faire guérir ces jours-là et non pas le jour du sabbat. —'),
('lc',13,15,'crampon1923','Hypocrite, lui répondit le Seigneur, est-ce que chacun de vous, le jour du sabbat, ne détache pas de la crèche son bœuf ou son âne, pour le mener boire?'),
('lc',13,16,'crampon1923','Et cette fille d''Abraham, que Satan tenait liée depuis dix-huit ans, il ne fallait pas la délivrer de cette chaîne le jour du sabbat! "'),
('lc',13,17,'crampon1923','Pendant qu''il parlait ainsi, tous ses adversaires étaient couverts de confusion, et tout le peuple était ravi de toutes les choses merveilleuses qu''il accomplissait.'),
('lc',13,18,'crampon1923','Il disait encore: " A quoi le royaume de Dieu est-il semblable, et à quoi le comparerai-je?'),
('lc',13,19,'crampon1923','Il est semblable à un grain de sénevé qu''un homme prit et jeta dans son jardin; il poussa et il devint un arbre, et les oiseaux du ciel firent leur demeure dans ses rameaux. "'),
('lc',13,20,'crampon1923','Il dit encore: " A quoi comparerai-je le royaume de Dieu?'),
('lc',13,21,'crampon1923','Il est semblable au levain qu''une femme prend et mêle dans trois mesures de farine, de façon à faire lever toute la pâte. "'),
('lc',13,22,'crampon1923','Il allait donc par les villes et les villages, enseignant et s''avançant vers Jérusalem.'),
('lc',13,23,'crampon1923','Quelqu''un lui demanda: " Seigneur, n''y aura-t-il qu''un petit nombre de sauvés? " Il leur dit:'),
('lc',13,24,'crampon1923','" Efforcez-vous d''entrer par la porte étroite; car beaucoup, je vous le dis, chercheront à entrer, et ne le pourront pas.'),
('lc',13,25,'crampon1923','Une fois que le père de famille se sera levé et aura fermé la porte, si vous êtes dehors et que vous vous mettiez à frapper, en disant: Seigneur, ouvrez-nous! Il vous répondra: Je ne sais d''où vous êtes.'),
('lc',13,26,'crampon1923','Alors vous vous mettrez à dire: Nous avons mangé et bu devant vous, et vous avez enseigné dans nos places publiques.'),
('lc',13,27,'crampon1923','Et il vous répondra: Je vous le dis, je ne sais d''où vous êtes; retirez-vous de moi, vous tous, ouvriers d''iniquités.'),
('lc',13,28,'crampon1923','C''est alors qu''il y aura des pleurs et des grincements de dents, lorsque vous verrez Abraham, Isaac et Jacob, et tous les prophètes dans le royaume de Dieu, tandis que vous serez jetés dehors.'),
('lc',13,29,'crampon1923','Il en viendra de l''Orient et de l''Occident, de l''Aquilon et du Midi; et ils prendront place au banquet dans le royaume de Dieu.'),
('lc',13,30,'crampon1923','Et tels sont les derniers, qui seront les premiers; et tels sont les premiers, qui seront les derniers. "'),
('lc',13,31,'crampon1923','Le même jour, quelques Pharisiens vinrent lui dire: " Retirez-vous et partez d''ici; car Hérode veut vous faire mourir. "'),
('lc',13,32,'crampon1923','Il leur répondit: " Allez et dites à ce renard: Je chasse les démons et guéris les malades aujourd''hui et demain, et le troisième jour j''aurai fini.'),
('lc',13,33,'crampon1923','Seulement il faut que je poursuive ma route aujourd''hui, et demain, et le jour suivant; car il ne convient pas qu''un prophète meure hors de Jérusalem.'),
('lc',13,34,'crampon1923','Jérusalem, Jérusalem, qui tues les prophètes, et lapide ceux qui sont envoyés vers elle! Combien de fois j''ai voulu rassembler tes enfants comme la poule rassemble sa couvée sous ses ailes, et vous ne l''avez pas voulu!'),
('lc',13,35,'crampon1923','Voici que votre maison va vous être laissée. Je vous le dis, vous ne me verrez plus, jusqu''à ce que vienne le jour où vous direz: Béni soit celui qui vient au nom du Seigneur! "'),
('lc',14,1,'crampon1923','Un jour de sabbat, Jésus étant entré dans la maison d''un des principaux Pharisiens pour y prendre son repas, ceux-ci l''observaient.'),
('lc',14,2,'crampon1923','Et voici qu''un homme hydropique se trouvait devant lui.'),
('lc',14,3,'crampon1923','Jésus, prenant la parole, dit aux Docteurs de la Loi et aux Pharisiens: " Est-il permis de faire une guérison le jour du sabbat? "'),
('lc',14,4,'crampon1923','Et ils gardèrent le silence. Lui, prenant cet homme par la main, le guérit et le renvoya.'),
('lc',14,5,'crampon1923','Puis, s''adressant à eux, il dit: " Qui de vous, si son âne ou son bœuf tombe dans un puits, ne l''en retire aussitôt le jour du sabbat? "'),
('lc',14,6,'crampon1923','Et à cela ils ne surent que lui répondre.'),
('lc',14,7,'crampon1923','Ensuite, ayant remarqué l''empressement des conviés à choisir les premières places, Jésus leur dit cette parabole:'),
('lc',14,8,'crampon1923','" Quand tu seras invité par quelqu''un à des noces, ne prends pas la première place, de peur qu''il n''y ait un homme plus considéré que toi,'),
('lc',14,9,'crampon1923','et que celui qui vous aura invités l''un et l''autre ne vienne te dire: Cède-lui la place; et qu''alors tu ne commences avec confusion à occuper la dernière place.'),
('lc',14,10,'crampon1923','Mais lorsque tu seras invité, va te mettre à la dernière place; de cette façon, quand viendra celui qui t''a invité, il te dira: Mon ami, monte plus haut. Alors ce sera pour toi un honneur devant les autres convives.'),
('lc',14,11,'crampon1923','Car quiconque s''élève sera abaissé, et quiconque s''abaisse sera élevé. "'),
('lc',14,12,'crampon1923','Il dit aussi à celui qui l''avait invité: " Lorsque tu donnes à dîner ou à souper, n''invite ni tes amis, ni tes frères, ni tes parents, ni des voisins riches, de peur qu''ils ne t''invitent à leur tour, et ne te rendent ce qu''ils auront reçu de toi.'),
('lc',14,13,'crampon1923','Mais, quand tu donnes un festin, invite des pauvres, des estropiés, des boiteux et des aveugles;'),
('lc',14,14,'crampon1923','et tu seras heureux de ce qu''ils ne peuvent te rendre la pareille, car cela te sera rendu à la résurrection des justes. "'),
('lc',14,15,'crampon1923','Un de ceux qui étaient à table avec lui, ayant entendu ces paroles, dit à Jésus: " Heureux celui qui aura part au banquet dans le royaume de Dieu! "'),
('lc',14,16,'crampon1923','Jésus lui dit: " Un homme donna un grand repas et y convia beaucoup de gens.'),
('lc',14,17,'crampon1923','A l''heure du repas, il envoya son serviteur dire aux invités: Venez, car tout est déjà prêt.'),
('lc',14,18,'crampon1923','Et tous, unanimement, se mirent à s''excuser. Le premier lui dit: J''ai acheté une terre, et il faut que j''aille la voir; je te prie de m''excuser.'),
('lc',14,19,'crampon1923','Le second dit: J''ai acheté cinq paires de bœufs, et je vais les essayer; je te prie de m''excuser.'),
('lc',14,20,'crampon1923','Un autre dit: Je viens de me marier, et c''est pourquoi je ne puis aller.'),
('lc',14,21,'crampon1923','Le serviteur étant revenu, rapporta ces choses à son maître. Alors le père de famille irrité dit à son serviteur: Va vite dans les places et les rues de la ville, et amène ici les pauvres, les estropiés, les aveugles et les boiteux.'),
('lc',14,22,'crampon1923','Le serviteur dit: Seigneur, il a été fait comme vous l''avez commandé, et il y a encore de la place.'),
('lc',14,23,'crampon1923','Le maître dit au serviteur: Va dans les chemins et le long des haies, et ceux que tu trouveras, presse-les d''entrer, afin que ma maison soit remplie.'),
('lc',14,24,'crampon1923','Car, je vous le dis, aucun de ces hommes qui avaient été invités ne goûtera de mon festin. "'),
('lc',14,25,'crampon1923','Comme une grande foule cheminait avec lui, il se retourna et leur dit:'),
('lc',14,26,'crampon1923','" Si quelqu''un vient à moi et ne hait pas son père et sa mère, sa femme et ses enfants, ses frères et ses sœurs, et même sa propre vie, il ne peut être mon disciple.'),
('lc',14,27,'crampon1923','Et quiconque ne porte pas sa croix et ne me suis pas, ne peut être mon disciple.'),
('lc',14,28,'crampon1923','Qui de vous, en effet, s''il veut bâtir une tour, ne s''assied pas auparavant pour calculer la dépense, et s''il a de quoi l''achever?'),
('lc',14,29,'crampon1923','de peur qu''après avoir posé les fondements de l''édifice, il ne puisse le conduire à sa fin, et que tous ceux qui le verront ne se mettent à le railler,'),
('lc',14,30,'crampon1923','disant: Cet homme a commencé à bâtir, et il n''a pu achever.'),
('lc',14,31,'crampon1923','Ou quel roi, s''il va faire la guerre à un autre roi, ne s''assied d''abord pour délibérer s''il peut, avec dix mille hommes, faire face à un ennemi qui vient l''attaquer avec vingt mille?'),
('lc',14,32,'crampon1923','S''il ne le peut, tandis que celui-ci est encore loin, il lui envoie une ambassade pour négocier la paix.'),
('lc',14,33,'crampon1923','Ainsi donc, quiconque d''entre vous ne renonce pas à tout ce qu''il possède, ne peut être mon disciple.'),
('lc',14,34,'crampon1923','Le sel est bon; mais si le sel s''affadit, avec quoi lui donnera-t-on de la saveur?'),
('lc',14,35,'crampon1923','Inutile et pour la terre et pour le fumier, on le jette dehors. Que celui qui a des oreilles entende bien! "'),
('lc',15,1,'crampon1923','Tous les publicains et les pécheurs s''approchaient de Jésus pour l''entendre.'),
('lc',15,2,'crampon1923','Et les Pharisiens et les scribes murmuraient, disant: " Cet homme accueille des pécheurs et mange avec eux. "'),
('lc',15,3,'crampon1923','Sur quoi il leur dit cette parabole:'),
('lc',15,4,'crampon1923','" Qui d''entre vous, ayant cent brebis, s''il en perd une, ne laisse les quatre-vingt-dix-neuf autres dans le désert, pour aller après celle qui est perdue, jusqu''à ce qu''il l''ait retrouvée?'),
('lc',15,5,'crampon1923','Et quand il l''a retrouvée, il la met avec joie sur ses épaules;'),
('lc',15,6,'crampon1923','et, de retour à la maison, il assemble ses amis et ses voisins et leur dit: Réjouissez-vous avec moi, parce que j''ai trouvé ma brebis qui était perdue.'),
('lc',15,7,'crampon1923','Ainsi, je vous le dis, il y aura plus de joie dans le ciel pour un seul pécheur qui se repent, que pour quatre-vingt-dix-neuf justes qui n''ont pas besoin de repentir.'),
('lc',15,8,'crampon1923','Ou bien quelle est la femme qui, ayant dix drachmes, si elle en perd une, n''allume une lampe, ne balaie sa maison, et ne cherche avec soin jusqu''à ce qu''elle l''ait retrouvée?'),
('lc',15,9,'crampon1923','Et quand elle l''a retrouvée, elle assemble ses amies et ses voisines et leur dit: Réjouissez-vous avec moi, parce que j''ai retrouvé la drachme que j''avais perdue.'),
('lc',15,10,'crampon1923','Ainsi, je vous le dis, il y a de la joie devant les anges de Dieu pour un seul pécheur qui se repent. "'),
('lc',15,11,'crampon1923','Il dit encore: " Un homme avait deux fils.'),
('lc',15,12,'crampon1923','Le plus jeune dit à son père: Mon père, donne-moi la part du bien qui doit me revenir. Et le père leur partagea son bien.'),
('lc',15,13,'crampon1923','Peu de jours après, le plus jeune fils ayant rassemblé tout ce qu''il avait, partit pour un pays lointain, et il y dissipa son bien en vivant dans la débauche.'),
('lc',15,14,'crampon1923','Lorsqu''il eut tout dépensé, une grande famine survint dans ce pays, et il commença à sentir le besoin.'),
('lc',15,15,'crampon1923','S''en allant donc, il se mit au service d''un habitant du pays, qui l''envoya à sa maison des champs pour garder les pourceaux.'),
('lc',15,16,'crampon1923','Il eût bien voulu se rassasier des gousses que mangeaient les pourceaux, mais personne ne lui en donnait.'),
('lc',15,17,'crampon1923','Alors, rentrant en lui-même, il dit: Combien de mercenaires de mon père ont du pain en abondance, et moi, je meurs ici de faim!'),
('lc',15,18,'crampon1923','Je me lèverai et j''irai à mon père, et je lui dirai: Mon père, j''ai péché contre le ciel et envers toi;'),
('lc',15,19,'crampon1923','je ne mérite plus d''être appelé ton fils: traite-moi comme l''un de tes mercenaires.'),
('lc',15,20,'crampon1923','Et il se leva et il alla vers son père. Comme il était encore loin, son père le vit, et, tout ému, il accourut, se jeta à son cou, et le couvrit de baisers.'),
('lc',15,21,'crampon1923','Son fils lui dit: Mon père, j''ai péché contre le ciel et envers toi; je ne mérite plus d''être appelé ton fils.'),
('lc',15,22,'crampon1923','Mais le père dit à ses serviteurs: Apportez la plus belle robe et l''en revêtez; mettez-lui un anneau au doigt et des souliers aux pieds.'),
('lc',15,23,'crampon1923','Amenez aussi le veau gras et tuez-le; faisons un festin de réjouissance:'),
('lc',15,24,'crampon1923','car mon fils que voici était mort, et il est revenu à la vie; il était perdu, et il est retrouvé. Et ils se mirent à faire fête.'),
('lc',15,25,'crampon1923','Or, le fils aîné était dans les champs; comme il revenait et approchait de la maison, il entendit de la musique et des danses.'),
('lc',15,26,'crampon1923','Appelant un des serviteurs, il lui demanda ce que c''était.'),
('lc',15,27,'crampon1923','Le serviteur lui dit: Votre frère est arrivé, et votre père a tué le veau gras, parce qu''il l''a recouvré sain et sauf.'),
('lc',15,28,'crampon1923','Mais il se mit en colère, et ne voulut pas entrer. Le père sortit donc, et se mit à le prier.'),
('lc',15,29,'crampon1923','Il répondit à son père: Voilà tant d''années que je te sers, sans avoir jamais transgressé tes ordres, et jamais tu ne m''as donné, à moi, un chevreau pour festoyer avec mes amis.'),
('lc',15,30,'crampon1923','Et quand cet autre fils, qui a dévoré ton bien avec des courtisanes, arrive, tu tues pour lui le veau gras!'),
('lc',15,31,'crampon1923','Le père lui dit: Toi, mon fils, tu es toujours avec moi, et tout ce que j''ai est à toi.'),
('lc',15,32,'crampon1923','Mais il fallait bien faire un festin et se réjouir, parce que ton frère que voilà était mort, et qu''il est revenu à la vie; il était perdu, et il est retrouvé. "'),
('lc',16,1,'crampon1923','Jésus disait aussi à ses disciples: " Un homme riche avait un économe qu''on accusa devant lui de dissiper ses biens.'),
('lc',16,2,'crampon1923','Il l''appela et lui dit: Qu''est-ce que j''entends dire de toi? Rends compte de ton administration: car désormais tu ne pourras plus gérer mes biens.'),
('lc',16,3,'crampon1923','Alors l''économe dit en lui-même: Que ferai-je, puisque mon maître me retire la gestion de ses biens? Travailler la terre, je n''en ai pas la force, et j''ai honte de mendier.'),
('lc',16,4,'crampon1923','Je sais ce que je ferai, afin que, lorsqu''on m''aura ôté mon emploi, il y ait des gens qui me reçoivent dans leurs maisons.'),
('lc',16,5,'crampon1923','Faisant donc venir l''un après l''autre les débiteurs de son maître, il dit au premier: Combien dois-tu à mon maître?'),
('lc',16,6,'crampon1923','Il répondit: Cent barils d''huile. L''économe lui dit: Prends ton billet: assieds-toi vite, et écris cinquante.'),
('lc',16,7,'crampon1923','Ensuite il dit à un autre: Et toi, combien dois-tu? Il répondit: Cent mesures de froment. L''économe lui dit: Prends ton billet, et écris quatre-vingts.'),
('lc',16,8,'crampon1923','Et le maître loua l''économe infidèle d''avoir agi habilement; car les enfants de ce siècle sont plus habiles entre eux que les enfants de la lumière.'),
('lc',16,9,'crampon1923','Moi aussi je vous dis: Faites-vous des amis avec les richesses d''iniquité, afin que, lorsque vous quitterez la vie, ils vous reçoivent dans les tabernacles éternels.'),
('lc',16,10,'crampon1923','Celui qui est fidèle dans les petites choses, est fidèle aussi dans les grandes, et celui qui est injuste dans les petites choses, est injuste aussi dans les grandes.'),
('lc',16,11,'crampon1923','Si donc vous n''avez pas été fidèles dans les richesses d''iniquité, qui vous confiera les biens véritables?'),
('lc',16,12,'crampon1923','Et si vous n''avez pas été fidèles dans un bien étranger, qui vous donnera votre bien propre?'),
('lc',16,13,'crampon1923','Nul serviteur ne peut servir deux maîtres; car ou il haïra l''un et aimera l''autre, ou il s''attachera à l''un et méprisera l''autre. Vous ne pouvez servir Dieu et la Richesse. "'),
('lc',16,14,'crampon1923','Les Pharisiens qui aimaient l''argent, écoutaient aussi tout cela, et se moquaient de lui.'),
('lc',16,15,'crampon1923','Jésus leur dit: " Vous êtes ceux qui se font passer pour justes devant les hommes; mais Dieu connaît vos cœurs; et ce qui est élevé aux yeux des hommes est une abomination devant Dieu.'),
('lc',16,16,'crampon1923','La Loi et les prophètes vont jusqu''à Jean; depuis Jean, le royaume de Dieu est annoncé, et chacun fait effort pour y entrer.'),
('lc',16,17,'crampon1923','Plus facilement le ciel et la terre passeront, qu''un seul trait de la Loi périsse.'),
('lc',16,18,'crampon1923','Quiconque renvoie sa femme et en épouse une autre, commet un adultère; et quiconque épouse la femme renvoyée par son mari, commet un adultère.'),
('lc',16,19,'crampon1923','Il y avait un homme riche qui était vêtu de pourpre et de fin lin, et qui faisait chaque jour splendide chère.'),
('lc',16,20,'crampon1923','Un pauvre, nommé Lazare, était couché à sa porte, couvert d''ulcères,'),
('lc',16,21,'crampon1923','et souhaitant de se rassasier des miettes qui tombaient de la table du riche; mais les chiens mêmes venaient lécher ses ulcères.'),
('lc',16,22,'crampon1923','Or, il arriva que le pauvre mourut, et il fut porté par les anges dans le sein d''Abraham. Le riche mourut aussi, et on lui donna la sépulture.'),
('lc',16,23,'crampon1923','Dans l''enfer, il leva les yeux, et tandis qu''il était en proie aux tourments, il vit de loin Abraham, et Lazare dans son sein,'),
('lc',16,24,'crampon1923','et il s''écria: Abraham, notre père, aie pitié de moi, et envoie Lazare, pour qu''il trempe dans l''eau le bout de son doigt et me rafraîchisse la langue; car je souffre cruellement de ces flammes.'),
('lc',16,25,'crampon1923','Abraham répondit: Mon fils, souviens-toi que tu as reçu tes biens pendant ta vie, et que pareillement Lazare a eu ses maux: maintenant il est ici consolé, et toi, tu souffres.'),
('lc',16,26,'crampon1923','De plus, entre nous et vous il y a pour toujours un grand abîme, afin que ceux qui voudraient passer d''ici vers vous ne le puissent, et qu''il soit impossible de passer de là-bas jusqu''à nous.'),
('lc',16,27,'crampon1923','Et le riche dit: Je te prie donc, père, d''envoyer Lazare dans la maison de mon père,'),
('lc',16,28,'crampon1923','— car j''ai cinq frères, — pour leur attester ces choses de peur qu''ils ne viennent, eux aussi, dans ce lieu de tourments.'),
('lc',16,29,'crampon1923','Abraham répondit: Ils ont Moïse et les prophètes; qu''ils les écoutent. —'),
('lc',16,30,'crampon1923','Non, Abraham, notre père, reprit-il; mais si quelqu''un des morts va vers eux, ils se repentiront.'),
('lc',16,31,'crampon1923','Mais Abraham lui dit: S''ils n''écoutent pas Moïse et les prophètes, quelqu''un des morts ressusciterait, qu''ils ne le croiraient point. "'),
('lc',17,1,'crampon1923','Jésus dit encore à ses disciples: " Il est impossible qu''il n''arrive pas des scandales; mais malheur à celui par qui ils arrivent!'),
('lc',17,2,'crampon1923','Il vaudrait mieux pour lui qu''on lui mit au cou une meule de moulin, et qu''on le jetât dans la mer, que de scandaliser un seul de ces petits.'),
('lc',17,3,'crampon1923','Prenez garde à vous-mêmes. Si ton frère a péché contre toi reprends-le, et s''il se repent, pardonne-lui.'),
('lc',17,4,'crampon1923','Et quand il pécherait contre toi sept fois le jour, s''il revient sept fois [le jour] te dire: Je me repens, tu lui pardonneras. "'),
('lc',17,5,'crampon1923','Les apôtres dirent au Seigneur: " Augmentez notre foi. "'),
('lc',17,6,'crampon1923','Le Seigneur répondit: " Si vous aviez de la foi comme un grain de sénevé, vous diriez à ce mûrier: Déracine-toi, et te transplante dans la mer; et il vous obéirait.'),
('lc',17,7,'crampon1923','Qui de vous, ayant un serviteur au labourage ou à la garde des troupeaux, lui dira, à son retour des champs: Viens vite, et mets-toi à table?'),
('lc',17,8,'crampon1923','Ne lui dira-t-il pas, au contraire: Prépare-moi à souper, ceins-toi, et me sers, jusqu''à ce que j''aie mangé et bu; après cela, toi, tu mangeras et boiras?'),
('lc',17,9,'crampon1923','A-t-il de la reconnaissance à ce serviteur, parce qu''il a fait ce qui lui était ordonné?'),
('lc',17,10,'crampon1923','Je ne le pense pas. De même vous, quand vous aurez fait ce qui vous était commandé, dites: Nous sommes des serviteurs inutiles; nous avons fait ce que nous devions faire. "'),
('lc',17,11,'crampon1923','En se rendant à Jérusalem, Jésus côtoyait la frontière de la Samarie et de la Galilée.'),
('lc',17,12,'crampon1923','Comme il entrait dans un village, dix lépreux vinrent à sa rencontre, et se tenant à distance,'),
('lc',17,13,'crampon1923','ils élevèrent la voix en disant: " Jésus, Maître, ayez pitié de nous. "'),
('lc',17,14,'crampon1923','Dès qu''il les eut aperçus: " Allez, leur dit-il, montrez-vous aux prêtres. " Et en y allant, ils furent guéris.'),
('lc',17,15,'crampon1923','L''un d''eux, lorsqu''il se vit guéri, revint sur ses pas, glorifiant Dieu à haute voix,'),
('lc',17,16,'crampon1923','et tombant le visage contre terre aux pieds de Jésus, il lui rendit grâces. Or c''était un Samaritain.'),
('lc',17,17,'crampon1923','Prenant alors la parole, Jésus dit: " Est-ce que les dix n''ont pas été guéris? Et les neuf, où sont-ils?'),
('lc',17,18,'crampon1923','Il ne s''est trouvé parmi eux que cet étranger pour revenir et rendre gloire à Dieu?'),
('lc',17,19,'crampon1923','Et il lui dit: Lève-toi, va; ta foi t''a sauvé. "'),
('lc',17,20,'crampon1923','Les Pharisiens lui ayant demandé quand viendrait le royaume de Dieu, il leur répondit: " Le royaume de Dieu ne vient pas de manière à frapper les regards.'),
('lc',17,21,'crampon1923','On ne dira point: Il est ici, ou: Il est là; car voyez, le royaume de Dieu est au milieu de vous. "'),
('lc',17,22,'crampon1923','Il dit encore à ses disciples: " Viendra un temps où vous désirerez voir un seul des jours du Fils de l''homme, et vous ne le verrez point.'),
('lc',17,23,'crampon1923','On vous dira: Il est ici, et: Il est là; gardez-vous d''y aller et de courir après.'),
('lc',17,24,'crampon1923','Car, comme la lueur de l''éclair brille d''un bout du ciel à l''autre, ainsi en sera-t-il du Fils de l''homme en son jour.'),
('lc',17,25,'crampon1923','Mais il faut auparavant qu''il souffre beaucoup, et qu''il soit rejeté par cette génération.'),
('lc',17,26,'crampon1923','Et comme il arriva aux jours de Noé, ainsi arrivera-t-il aux jours du Fils de l''homme.'),
('lc',17,27,'crampon1923','Les hommes mangeaient et buvaient, ils se mariaient et mariaient leur filles, jusqu''au jour où Noé entra dans l''arche; et le déluge vint qui les fit périr tous.'),
('lc',17,28,'crampon1923','Et comme il arriva aux jours de Loth: les hommes mangeaient et buvaient, ils achetaient et vendaient, ils plantaient et bâtissaient;'),
('lc',17,29,'crampon1923','mais le jour où Loth sortit de Sodome, une pluie de feu et de soufre tomba du ciel, et les fit périr tous:'),
('lc',17,30,'crampon1923','ainsi en sera-t-il au jour où le Fils de l''homme paraîtra.'),
('lc',17,31,'crampon1923','En ce jour, que celui qui sera sur le toit, et dont les effets seront dans la maison, ne descende point pour les prendre; et que celui qui sera aux champs ne revienne pas non plus en arrière.'),
('lc',17,32,'crampon1923','Souvenez-vous de la femme de Loth.'),
('lc',17,33,'crampon1923','Quiconque cherchera à sauver sa vie, la perdra, et quiconque l''aura perdu, la régénérera.'),
('lc',17,34,'crampon1923','Je vous le dis: en cette nuit-là, de deux personnes qui seront dans le même lit, l''une sera prise et l''autre laissée;'),
('lc',17,35,'crampon1923','de deux femmes qui moudront ensemble, l''une sera prise et l''autre laissée; [de deux hommes qui seront dans un champ, l''un sera pris et l''autre laissé]. "'),
('lc',17,36,'crampon1923','Ils lui dirent: " Où sera-ce, Seigneur? "'),
('lc',17,37,'crampon1923','Il répondit: " Où sera le corps, là s''assembleront les aigles. "'),
('lc',18,1,'crampon1923','Il leur adressa encore une parabole, pour montrer qu''il faut prier toujours et sans se lasser.'),
('lc',18,2,'crampon1923','Il dit: " Il y avait dans une ville un juge qui ne craignait point Dieu, et ne se souciait pas des hommes.'),
('lc',18,3,'crampon1923','Il y avait aussi dans cette ville une veuve qui venait à lui, disant: Fais-moi justice de mon adversaire.'),
('lc',18,4,'crampon1923','Et pendant longtemps il ne le voulut point; mais ensuite il dit en lui-même: Encore que je ne craigne pas Dieu et ne me soucie pas des hommes,'),
('lc',18,5,'crampon1923','cependant, parce que cette veuve m''importune, je lui ferai justice, afin qu''elle ne vienne pas sans cesse me tourmenter. —'),
('lc',18,6,'crampon1923','Entendez, ajouta le Seigneur, ce que dit ce juge inique.'),
('lc',18,7,'crampon1923','Et Dieu ne ferait pas justice à ses élus qui crient à lui nuit et jour, et il tarderait à leur égard?'),
('lc',18,8,'crampon1923','Je vous le dis, il leur fera bientôt justice. Seulement, quand le Fils de l''homme viendra, trouvera-t-il la foi sur terre? "'),
('lc',18,9,'crampon1923','Il dit encore cette parabole en vue de quelques gens persuadés de leur propre perfection, et pleins de mépris pour les autres:'),
('lc',18,10,'crampon1923','" Deux hommes montèrent au temple pour prier; l''un était Pharisien, l''autre publicain.'),
('lc',18,11,'crampon1923','Le Pharisien, debout, priait ainsi en lui-même: O Dieu, je vous rends grâces de ce que je ne suis pas comme le reste des hommes, qui sont voleurs, injustes et adultères, ni encore comme ce publicain.'),
('lc',18,12,'crampon1923','Je jeûne deux fois la semaine; je paie la dîme de tous mes revenus.'),
('lc',18,13,'crampon1923','Le publicain, se tenant à distance, ne voulait pas même lever les yeux au ciel; mais il frappait sa poitrine en disant: O Dieu, ayez pitié de moi qui suis un pécheur!'),
('lc',18,14,'crampon1923','Je vous le dis, celui-ci descendit justifié dans sa maison, plutôt que celui-là; car quiconque s''élève sera abaissé, et quiconque s''abaisse sera élevé. "'),
('lc',18,15,'crampon1923','Des personnes lui apportaient aussi leurs petits enfants pour qu''il les touchât; ce que voyant, ses disciples les réprimandèrent.'),
('lc',18,16,'crampon1923','Mais Jésus appela ces enfants et dit: " Laissez les petits enfants venir à moi, et ne les empêchez pas; car le royaume de Dieu est à ceux qui leur ressemblent.'),
('lc',18,17,'crampon1923','En vérité, je vous le dis, quiconque ne recevra pas le royaume de Dieu comme un petit enfant, n''y entrera point. "'),
('lc',18,18,'crampon1923','Alors un chef lui demanda: " Bon Maître, que dois-je faire pour obtenir la vie éternelle? "'),
('lc',18,19,'crampon1923','Jésus lui dit: " Pourquoi m''appelles-tu bon? Il n''y a de bon que Dieu seul.'),
('lc',18,20,'crampon1923','Tu connais les commandements: Ne commets point l''adultère; ne tue point; ne dérobe point; ne porte point de faux témoignage; honore ton père et ta mère. "'),
('lc',18,21,'crampon1923','Il répondit: " J''ai observé tout cela depuis ma jeunesse. "'),
('lc',18,22,'crampon1923','Ayant entendu cette réponse, Jésus lui dit: " Une chose te manque encore: vends tout ce que tu as, distribue-le aux pauvres, et tu auras un trésor dans le ciel; puis viens, et suis-moi. "'),
('lc',18,23,'crampon1923','Mais lui, ayant entendu ces paroles, devint triste, parce qu''il était fort riche.'),
('lc',18,24,'crampon1923','Voyant qu''il était devenu triste, Jésus dit: " Qu''il est difficile à ceux qui possèdent la richesse d''entrer dans le royaume de Dieu!'),
('lc',18,25,'crampon1923','Il est, en effet, plus aisé qu''un chameau passe par le trou d''une aiguille, qu''il ne l''est à un riche d''entrer dans le royaume de Dieu. "'),
('lc',18,26,'crampon1923','Ceux qui l''écoutaient dirent: " Qui peut donc être sauvé? "'),
('lc',18,27,'crampon1923','Il répondit: " Ce qui est impossible aux hommes est possible à Dieu. "'),
('lc',18,28,'crampon1923','Pierre dit alors: " Voyez, nous avons tout quitté et vous avons suivi. "'),
('lc',18,29,'crampon1923','Il leur dit: " Je vous le dis, en vérité, nul n''aura quitté sa maison, ou ses parents, ou ses frères, ou son épouse, ou ses enfants, à cause du royaume de Dieu,'),
('lc',18,30,'crampon1923','sans qu''il ne reçoive beaucoup plus en ce temps même, et dans le siècle à venir la vie éternelle. "'),
('lc',18,31,'crampon1923','Ensuite Jésus prit à part les Douze, et leur dit: " Voici que nous montons à Jérusalem, et que va s''accomplir tout ce que les prophètes ont écrit du Fils de l''homme.'),
('lc',18,32,'crampon1923','Il sera livré aux Gentils, et moqué, et injurié, et couvert de crachats;'),
('lc',18,33,'crampon1923','et après l''avoir flagellé, on le mettra à mort et il ressuscitera le troisième jour. "'),
('lc',18,34,'crampon1923','Mais ils ne comprirent rien à cela; c''était pour eux un langage caché, dont ils ne saisissaient pas le sens.'),
('lc',18,35,'crampon1923','Comme Jésus approchait de Jéricho, il arriva qu''un aveugle était assis sur le bord du chemin, demandant l''aumône.'),
('lc',18,36,'crampon1923','Entendant passer beaucoup de gens, il demanda ce que c''était.'),
('lc',18,37,'crampon1923','On lui dit: " C''est Jésus de Nazareth qui passe. "'),
('lc',18,38,'crampon1923','Aussitôt il s''écria: " Jésus, fils de David, ayez pitié de moi! "'),
('lc',18,39,'crampon1923','Ceux qui marchaient devant le réprimandaient pour le faire taire; mais il criait beaucoup plus fort: " Fils de David, ayez pitié de moi! "'),
('lc',18,40,'crampon1923','Alors Jésus s''arrêtant, commanda qu''on le lui amenât, et quand l''aveugle se fut approché, il lui demanda:'),
('lc',18,41,'crampon1923','" Que veux-tu que je te fasse? " Il dit: " Que je voie. "'),
('lc',18,42,'crampon1923','Et Jésus lui dit: " Vois! ta foi t''a sauvé. "'),
('lc',18,43,'crampon1923','A l''instant il vit, et il le suivait en glorifiant Dieu. Et tout le peuple, voyant cela, donna louange à Dieu.'),
('lc',19,1,'crampon1923','Jésus étant entré dans Jéricho, traversait la ville.'),
('lc',19,2,'crampon1923','Et voilà qu''un homme appelé Zachée, — c''était un chef de publicains et il était riche, —'),
('lc',19,3,'crampon1923','cherchait à voir qui était Jésus; et il ne le pouvait à cause de la foule, car il était de petite taille.'),
('lc',19,4,'crampon1923','Courant donc en avant, il monta sur un sycomore pour le voir, parce qu''il devait passer par là.'),
('lc',19,5,'crampon1923','Arrivé à cet endroit, Jésus leva les yeux, et l''ayant vu, il lui dit: " Zachée, descends vite, car il faut que je loge aujourd''hui dans ta maison. "'),
('lc',19,6,'crampon1923','Zachée se hâta de descendre et le reçut avec joie.'),
('lc',19,7,'crampon1923','Voyant cela, ils murmuraient tous en disant: " Il est allé loger chez un pécheur. "'),
('lc',19,8,'crampon1923','Mais Zachée, se présentant devant le Seigneur, lui dit: " Voici, Seigneur, que je donne aux pauvres la moitié de mes biens; et si j''ai fait tort de quelque chose à quelqu''un, je lui rends le quadruple. "'),
('lc',19,9,'crampon1923','Jésus lui dit: " Le salut est venu aujourd''hui pour cette maison, parce que celui-ci est aussi un fils d''Abraham.'),
('lc',19,10,'crampon1923','Car le Fils de l''homme est venu chercher et sauver ce qui était perdu. "'),
('lc',19,11,'crampon1923','Comme ils écoutaient ce discours, il ajouta une parabole, parce qu''il était près de Jérusalem, et que le peuple pensait que le royaume de Dieu allait bientôt paraître.'),
('lc',19,12,'crampon1923','Il dit donc: " Un homme de grande naissance s''en alla dans un pays lointain pour être investi de la royauté et revenir ensuite.'),
('lc',19,13,'crampon1923','Ayant appelé dix de ses serviteurs, il leur donna dix mines, et leur dit: Faites-les valoir, jusqu''à ce que je revienne.'),
('lc',19,14,'crampon1923','Mais ses concitoyens le haïssaient, et ils envoyèrent après lui des députés chargés de dire: Nous ne voulons pas que cet homme règne sur nous.'),
('lc',19,15,'crampon1923','Quand il fut de retour, après avoir été investi de la royauté, il se fit appeler les serviteurs auxquels il avait donné l''argent, pour savoir quel profit chacun en avait tiré.'),
('lc',19,16,'crampon1923','Le premier vint et dit: Seigneur, votre mine a gagné dix autres mines.'),
('lc',19,17,'crampon1923','Il lui dit: C''est bien, bon serviteur; parce que tu as été fidèle en peu de chose, reçois le gouvernement de dix villes.'),
('lc',19,18,'crampon1923','Le second vint et dit: Seigneur, votre mine a produit cinq autres mines.'),
('lc',19,19,'crampon1923','Toi aussi lui dit-il, gouverne cinq villes.'),
('lc',19,20,'crampon1923','Puis un autre vint et dit: Seigneur, voici votre mine que j''ai gardée en dépôt dans un linge.'),
('lc',19,21,'crampon1923','Car j''avais peur de vous, parce que vous êtes un homme rigide: vous retirez ce que vous n''avez pas déposé, et vous moissonnez ce que vous n''avez pas semé.'),
('lc',19,22,'crampon1923','Le roi lui répondit: Je te juge sur tes paroles, méchant serviteur. Tu savais que je suis un homme rigide, retirant ce que je n''ai pas déposé, et moissonnant ce que je n''ai pas semé;'),
('lc',19,23,'crampon1923','pourquoi donc n''as-tu pas mis mon argent à la banque? Et à mon retour, je l''aurais retiré avec les intérêts.'),
('lc',19,24,'crampon1923','Et il dit à ceux qui étaient là: Otez-lui la mine, et donnez-la à celui qui en a dix.'),
('lc',19,25,'crampon1923','— Seigneur, lui dirent-ils, il en a dix. —'),
('lc',19,26,'crampon1923','Je vous le dis, à quiconque possède, on donnera; et à celui qui n''a pas, on ôtera même ce qu''il a.'),
('lc',19,27,'crampon1923','Quant à ces gens qui me haïssent et n''ont pas voulu m''avoir pour roi, amenez-les ici, et égorgez-les en ma présence. "'),
('lc',19,28,'crampon1923','Après ce discours, Jésus se mit à marcher en avant, pour monter à Jérusalem.'),
('lc',19,29,'crampon1923','Lorsqu''il approcha de Bethphagé et de Béthanie, vers la montagne appelée des Oliviers, Jésus envoya deux de ses disciples,'),
('lc',19,30,'crampon1923','en disant: " Allez au village qui est en face; en y entrant, vous trouverez un ânon attaché, sur lequel aucun homme ne s''est jamais assis; détachez-le et l''amenez.'),
('lc',19,31,'crampon1923','Et si quelqu''un vous demande pourquoi vous le détachez, vous répondrez: Parce que le Seigneur en a besoin. "'),
('lc',19,32,'crampon1923','Ceux qui étaient envoyés partirent et trouvèrent les choses comme Jésus le leur avait dit.'),
('lc',19,33,'crampon1923','Comme ils détachaient l''ânon, ses maîtres leur dirent: " Pourquoi détachez-vous cet ânon? "'),
('lc',19,34,'crampon1923','Ils répondirent: " Parce que le Seigneur en a besoin. "'),
('lc',19,35,'crampon1923','Et ils l''amenèrent à Jésus; puis, ayant jeté leurs manteaux sur l''ânon, ils y firent monter Jésus.'),
('lc',19,36,'crampon1923','A son passage les gens étendaient leurs manteaux sur la route.'),
('lc',19,37,'crampon1923','Lorsqu''il était déjà près de la descente du mont des Oliviers, toute la foule des disciples, transportés de joie, se mit à louer Dieu à haute voix pour tous les miracles qu''ils avaient vus.'),
('lc',19,38,'crampon1923','" Béni soit, disaient-ils, le roi qui vient au nom du Seigneur! Paix dans le ciel, et gloire au plus haut des cieux! "'),
('lc',19,39,'crampon1923','Alors quelques Pharisiens, au milieu de la foule, dirent à Jésus: " Maître, réprimandez vos disciples. "'),
('lc',19,40,'crampon1923','Il leur répondit: " Je vous le dis, si eux se taisent, les pierres crieront. "'),
('lc',19,41,'crampon1923','Et lorsque, s''étant approché, il aperçut Jérusalem, il pleura sur elle, en disant:'),
('lc',19,42,'crampon1923','" Si tu connaissais, toi aussi, du moins en ce jour qui t''est donné, ce qui ferait ta paix! Mais maintenant ces choses sont cachées à tes yeux.'),
('lc',19,43,'crampon1923','Viendront sur toi des jours où tes ennemis t''environneront de tranchées, t''investiront et te serreront de toutes parts;'),
('lc',19,44,'crampon1923','ils te renverseront par terre, toi et tes enfants qui sont dans ton sein, et ils ne laisseront pas dans ton enceinte pierre sur pierre, parce que tu n''as pas connu le temps où tu as été visitée. "'),
('lc',19,45,'crampon1923','Etant entré dans le temple, il se mit à chasser ceux qui y vendaient et y achetaient,'),
('lc',19,46,'crampon1923','leur disant: " Il est écrit: Ma maison est une maison de prière, et vous en avez fait une caverne de voleurs. "'),
('lc',19,47,'crampon1923','Jésus passait les journées à enseigner dans le temple. Et les Princes des prêtres, les Scribes et les principaux du peuple cherchaient à le perdre;'),
('lc',19,48,'crampon1923','mais ils ne savaient comment s''y prendre, car tout le peuple l''écoutait avec ravissement.'),
('lc',20,1,'crampon1923','Un de ces jours-là, comme Jésus enseignait le peuple dans le temple, et qu''il annonçait la bonne nouvelle, les Princes des prêtres et les Scribes survinrent avec les Anciens,'),
('lc',20,2,'crampon1923','et lui dirent: " Dites-nous par quelle autorité vous faites ces choses, ou qui vous a donné cette autorité? "'),
('lc',20,3,'crampon1923','Jésus leur répondit: " Moi aussi je vous ferai une question. Répondez-moi.'),
('lc',20,4,'crampon1923','Le baptême de Jean était-il du ciel, ou des hommes? "'),
('lc',20,5,'crampon1923','Mais ils faisaient entre eux cette réflexion: " Si nous répondons: Du ciel, il nous dira: Pourquoi n''avez-vous pas cru en lui?'),
('lc',20,6,'crampon1923','Et si nous répondons: Des hommes, tout le peuple nous lapidera, car il est persuadé que Jean était un prophète. "'),
('lc',20,7,'crampon1923','Ils lui répondirent donc qu''ils ne savaient d''où il était.'),
('lc',20,8,'crampon1923','" Et Moi, leur dit Jésus, je ne vous dis pas non plus par quelle autorité je fais ces choses. "'),
('lc',20,9,'crampon1923','Alors il se mit à dire au peuple cette parabole: " Un homme planta une vigne, et la loua à des vignerons; puis il s''en alla pour un temps assez long en pays étranger.'),
('lc',20,10,'crampon1923','La saison étant venue, il envoya un serviteur aux vignerons, afin qu''ils lui donnassent du produit de la vigne. Mais eux, l''ayant battu, le renvoyèrent les mains vides.'),
('lc',20,11,'crampon1923','Il envoya encore un autre serviteur; mais, l''ayant aussi battu et traité indignement, ils le renvoyèrent les mains vides.'),
('lc',20,12,'crampon1923','Il en envoya un troisième; mais, lui aussi, les vignerons le blessèrent et le jetèrent dehors.'),
('lc',20,13,'crampon1923','Alors le maître de la vigne se dit: Que ferai-je? J''enverrai mon fils bien-aimé; peut-être qu''en le voyant ils auront pour lui du respect.'),
('lc',20,14,'crampon1923','Mais lorsque les vignerons le virent, ils se dirent entre eux: Celui-ci est l''héritier, tuons-le, afin que l''héritage soit à nous.'),
('lc',20,15,'crampon1923','Et l''ayant jeté hors de la vigne, ils le tuèrent. Que leur fera donc le maître de la vigne?'),
('lc',20,16,'crampon1923','Il viendra et exterminera ces vignerons, et donnera sa vigne à d''autres. " Ce qu''ayant entendu, ils dirent: " A Dieu ne plaise! "'),
('lc',20,17,'crampon1923','Mais, fixant le regard sur eux, Jésus dit: " Qu''est-ce donc que cette parole de l''Ecriture: La pierre qu''ont rejetée ceux qui bâtissaient est devenue la pierre angulaire?'),
('lc',20,18,'crampon1923','Quiconque tombera sur cette pierre sera brisé; et celui sur qui elle tombera, sera écrasé. "'),
('lc',20,19,'crampon1923','Les Princes des prêtres et les Scribes cherchèrent à se saisir de lui à l''heure même; mais la crainte du peuple les retint, car ils comprenaient bien que c''était pour eux que Jésus avait dit cette parabole.'),
('lc',20,20,'crampon1923','Ils ne le perdirent donc pas de vue, et lui envoyèrent des gens apostés qui feignaient d''être justes, pour le surprendre dans ses paroles, afin de le livrer à l''autorité et au pouvoir du gouverneur.'),
('lc',20,21,'crampon1923','Ces gens l''interrogèrent en ces termes: " Maître, nous savons que vous parlez et enseignez avec droiture, et sans faire acception de personne, mais que vous enseignez la voie de Dieu dans la vérité.'),
('lc',20,22,'crampon1923','Nous est-il permis, ou non, de payer le tribut à César? "'),
('lc',20,23,'crampon1923','Jésus, connaissant leur fourberie, leur dit: " Pourquoi me tentez-vous?'),
('lc',20,24,'crampon1923','Montrez-moi un denier. De qui porte-t-il l''effigie et le nom? " Ils lui répondirent: " De César. "'),
('lc',20,25,'crampon1923','Et il leur dit: " Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu. "'),
('lc',20,26,'crampon1923','Ainsi ils ne purent le prendre en défaut sur aucune parole devant le peuple; et admirant sa réponse, ils gardèrent le silence.'),
('lc',20,27,'crampon1923','Quelques-uns des Sadducéens, qui nient la résurrection, s''approchèrent alors et l''interrogèrent:'),
('lc',20,28,'crampon1923','" Maître, lui dirent-ils, Moïse nous a donné cette loi: Si un homme, ayant une femme, meurt sans laisser d''enfants, que son frère prenne sa femme, et suscite des enfants à son frère.'),
('lc',20,29,'crampon1923','Or, il y avait sept frères; le premier prit une femme et mourut sans enfants.'),
('lc',20,30,'crampon1923','Le second prit sa femme, et mourut aussi sans enfants.'),
('lc',20,31,'crampon1923','Le troisième la prit ensuite, et de même tous les sept, et ils moururent sans laisser d''enfants.'),
('lc',20,32,'crampon1923','Après eux tous, la femme mourut aussi.'),
('lc',20,33,'crampon1923','Duquel donc, au temps de la résurrection, sera-t-elle la femme, car elle l''a été de tous les sept? "'),
('lc',20,34,'crampon1923','Jésus leur dit: " Les enfants de ce siècle se marient et sont donnés en mariage;'),
('lc',20,35,'crampon1923','mais ceux qui ont été trouvés dignes d''avoir part au siècle à venir et à la résurrection des morts, ne prennent point de femme et n''ont point de mari;'),
('lc',20,36,'crampon1923','aussi bien ne peuvent-ils plus mourir, puisqu''ils sont en comme les anges, et qu''ils sont fils de Dieu, étant fils de la résurrection.'),
('lc',20,37,'crampon1923','Mais que les morts ressuscitent, c''est ce que Moïse lui-même a fait connaître dans le passage du Buisson, lorsqu''il nomme le Seigneur: Le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob.'),
('lc',20,38,'crampon1923','Or il n''est pas Dieu des morts, mais des vivants; car tous sont vivants devant lui. "'),
('lc',20,39,'crampon1923','Quelques-uns des Scribes, prenant la parole, lui dirent: " Maître, vous avez bien parlé. "'),
('lc',20,40,'crampon1923','Et ils n''osaient plus lui poser aucune question.'),
('lc',20,41,'crampon1923','Jésus leur dit: " Comment dit-on que le Christ est fils de David?'),
('lc',20,42,'crampon1923','David lui-même dit dans le livre des Psaumes: Le Seigneur a dit à mon Seigneur: Asseyez-vous à ma droite,'),
('lc',20,43,'crampon1923','jusqu''à ce que je fasse de vos ennemis l''escabeau de vos pieds. —'),
('lc',20,44,'crampon1923','David l''appelle donc Seigneur; comment peut-il être son fils? "'),
('lc',20,45,'crampon1923','Tandis que tout le peuple l''écoutait, il dit à ses disciples:'),
('lc',20,46,'crampon1923','" Gardez-vous des Scribes, qui se plaisent à se promener en longues robes; qui aiment à être salués dans les places publiques, à occuper les premiers sièges dans les synagogues et les premières places dans les festins:'),
('lc',20,47,'crampon1923','ces gens qui dévorent les maisons des veuves, et font pour l''apparence de longues prières, subiront une condamnation plus sévère. "'),
('lc',21,1,'crampon1923','Jésus, levant les yeux, vit les riches qui mettaient leurs offrandes dans le tronc.'),
('lc',21,2,'crampon1923','Il vit aussi une veuve indigente qui y mettait deux petites pièces de monnaie,'),
('lc',21,3,'crampon1923','et il dit: " Je vous le dis, en vérité, cette pauvre veuve a mis plus que tous les autres.'),
('lc',21,4,'crampon1923','Car tous ceux-là ont donné de leur superflu en offrande à Dieu; mais cette femme a donné de son indigence tout ce qu''elle avait pour vivre. "'),
('lc',21,5,'crampon1923','Quelques-uns disant que le temple était orné de belles pierres et de riches offrandes, Jésus dit:'),
('lc',21,6,'crampon1923','" Des jours viendront où, de tout ce que vous regardez-là, il ne restera pas pierre sur pierre qui ne soit renversée. "'),
('lc',21,7,'crampon1923','Alors ils lui demandèrent: " Maître, quand ces choses arriveront-elles, et à quel signe connaîtra-t-on qu''elles sont près de s''accomplir? "'),
('lc',21,8,'crampon1923','Jésus répondit: " Prenez garde qu''on ne vous séduise; car plusieurs viendront sous mon nom, disant: Je suis le Christ, et le temps est proche. Ne les suivez donc point.'),
('lc',21,9,'crampon1923','Et quand vous entendrez parler de guerres et de séditions, ne soyez pas effrayés; il faut que ces choses arrivent d''abord; mais la fin ne viendra pas sitôt. "'),
('lc',21,10,'crampon1923','Il leur dit alors: " Une nation s''élèvera contre une nation, et un royaume contre un royaume.'),
('lc',21,11,'crampon1923','Il y aura de grands tremblements de terre, des pestes et des famines en divers lieux, et dans le ciel d''effrayantes apparitions et des signes extraordinaires.'),
('lc',21,12,'crampon1923','Mais, avant tout cela, on mettra les main sur vous, et l''on vous persécutera; on vous traînera dans les synagogues et dans les prisons, on vous traduira devant les rois et les gouverneurs, à cause de mon nom.'),
('lc',21,13,'crampon1923','Cela vous arrivera, afin que vous me rendiez témoignage.'),
('lc',21,14,'crampon1923','Mettez donc dans vos cœurs de ne point songer d''avance à votre défense;'),
('lc',21,15,'crampon1923','car je vous donnerai moi-même une bouche et une sagesse à laquelle tous vos ennemis ne pourront ni répondre, ni résister.'),
('lc',21,16,'crampon1923','Vous serez livrés même par vos parents, par vos frères, par vos proches et par vos amis, et ils feront mourir plusieurs d''entre vous.'),
('lc',21,17,'crampon1923','Vous serez en haine à tous à cause de mon nom.'),
('lc',21,18,'crampon1923','Cependant pas un cheveu de votre tête ne se perdra;'),
('lc',21,19,'crampon1923','par votre constance, vous sauverez vos âmes.'),
('lc',21,20,'crampon1923','Mais lorsque vous verrez des armées investir Jérusalem, sachez alors que sa désolation est proche.'),
('lc',21,21,'crampon1923','Alors que ceux qui seront dans la Judée s''enfuient dans les montagnes, que ceux qui seront dans la ville en sortent, et que ceux qui seront dans les campagnes n''entrent pas dans la ville.'),
('lc',21,22,'crampon1923','Car ce seront des jours de châtiment, pour l''accomplissement de tout ce qui est écrit.'),
('lc',21,23,'crampon1923','Malheur aux femmes qui seront enceintes ou qui allaiteront en ces jours-là, car la détresse sera grande sur la terre, grande la colère contre ce peuple.'),
('lc',21,24,'crampon1923','Ils tomberont sous le tranchant du glaive; ils seront emmenés captifs parmi toutes les nations, et Jérusalem sera foulée aux pieds par les Gentils, jusqu''à ce que les temps des Gentils soient accomplis.'),
('lc',21,25,'crampon1923','Et il y aura des signes dans le soleil, dans la lune et dans les étoiles, et, sur la terre, les nations seront dans l''angoisse et la consternation, au bruit de la mer et des flots;'),
('lc',21,26,'crampon1923','les hommes séchant de frayeur dans l''attente de ce qui doit arriver à la terre entière; car les puissances des cieux seront ébranlées.'),
('lc',21,27,'crampon1923','Alors on verra le Fils de l''homme venant dans une nuée avec une grande puissance et une grande gloire.'),
('lc',21,28,'crampon1923','Quand ces choses commenceront à arriver, redressez-vous et relevez la tête, parce que votre délivrance approche. "'),
('lc',21,29,'crampon1923','Et il leur dit cette comparaison: " Voyez le figuier et tous les arbres:'),
('lc',21,30,'crampon1923','dès qu''ils se sont mis à pousser, vous savez de vous-mêmes, en les voyant, que l''été est proche.'),
('lc',21,31,'crampon1923','De même, quand vous verrez ces choses arriver, sachez que le royaume de Dieu est proche.'),
('lc',21,32,'crampon1923','Je vous le dis, en vérité, cette génération ne passera point, que tout ne soit accompli.'),
('lc',21,33,'crampon1923','Le ciel et la terre passeront, mais mes paroles ne passeront point.'),
('lc',21,34,'crampon1923','Prenez garde à vous-mêmes, de peur que vos cœurs ne s''appesantissent par l''excès du manger et du boire, et par les soucis de la vie, et que ce jour ne fonde sur vous à l''improviste;'),
('lc',21,35,'crampon1923','car il viendra comme un filet sur tous ceux qui habitent la face de la terre entière.'),
('lc',21,36,'crampon1923','Veillez donc et priez sans cesse, afin que vous soyez trouvés dignes d''échapper à tous ces maux qui doivent arriver, et de paraître debout devant le Fils de l''homme. "'),
('lc',21,37,'crampon1923','Pendant le jour, Jésus enseignait dans le temple, et il en sortait pour aller passer la nuit sur la montagne qu''on appelle des Oliviers.'),
('lc',21,38,'crampon1923','Et tout le peuple, dès le matin, venait à lui pour l''écouter dans le temple.'),
('lc',22,1,'crampon1923','La fête des Azymes, qu''on appelle la Pâque, approchait;'),
('lc',22,2,'crampon1923','et les Princes des prêtres et les Scribes cherchaient comment ils feraient mourir Jésus; car ils craignaient le peuple.'),
('lc',22,3,'crampon1923','Or, Satan entra dans Judas, surnommé Iscariote, du nombre des Douze;'),
('lc',22,4,'crampon1923','et celui-ci alla s''entendre avec les Princes des prêtres et les magistrats, sur la manière de le leur livrer.'),
('lc',22,5,'crampon1923','Eux, pleins de joie, promirent de lui donner de l''argent.'),
('lc',22,6,'crampon1923','Il s''engagea de son côté, et il cherchait une occasion favorable de leur livrer Jésus à l''insu de la foule.'),
('lc',22,7,'crampon1923','Arriva le jour des Azymes, où l''on devait immoler la Pâque.'),
('lc',22,8,'crampon1923','Jésus envoya Pierre et Jean: " Allez, leur dit-il, nous préparer le repas pascal. "'),
('lc',22,9,'crampon1923','Ils lui dirent: " Où voulez-vous que nous le préparions? "'),
('lc',22,10,'crampon1923','Il leur répondit: " En entrant dans la ville, vous rencontrerez un homme portant une cruche d''eau; suivez-le dans la maison où il entrera,'),
('lc',22,11,'crampon1923','et vous direz au maître de cette maison: Le Maître te fait dire: Où est la salle où je mangerai la Pâque avec mes disciples?'),
('lc',22,12,'crampon1923','Et il vous montrera un grand cénacle meublé: préparez-y ce qu''il faut. "'),
('lc',22,13,'crampon1923','Ils partirent, et trouvèrent les choses comme il le leur avait dit; et ils préparèrent la Pâque.'),
('lc',22,14,'crampon1923','L''heure étant venue, Jésus se mit à table, et les douze Apôtres avec lui;'),
('lc',22,15,'crampon1923','et il leur dit: " J''ai désiré d''un grand désir de manger cette Pâque avec vous avant de souffrir.'),
('lc',22,16,'crampon1923','Car, je vous le dis, je ne la mangerai plus jusqu''à la Pâque parfaite, célébrée dans le royaume de Dieu. "'),
('lc',22,17,'crampon1923','Et prenant une coupe, il rendit grâces et dit: " Prenez et partagez entre vous.'),
('lc',22,18,'crampon1923','Car, je vous le dis, je ne boirai plus du fruit de la vigne, jusqu''à ce que le royaume de Dieu soit venu. "'),
('lc',22,19,'crampon1923','Puis il prit du pain, et ayant rendu grâces, il le rompit et le leur donna, en disant: " Ceci est mon corps, qui est donné pour vous: faites ceci en mémoire de moi. "'),
('lc',22,20,'crampon1923','Il fit de même pour la coupe, après le souper, disant: " Cette coupe est la nouvelle alliance en mon sang, lequel est versé pour vous.'),
('lc',22,21,'crampon1923','Cependant voici que la main de celui qui me trahit est avec moi à cette table.'),
('lc',22,22,'crampon1923','Quant au Fils de l''homme, il va selon ce qui a été décrété; mais malheur à l''homme par qui il est trahi! "'),
('lc',22,23,'crampon1923','Et les disciples se mirent à se demander les uns aux autres quel était celui d''entre eux qui devait faire cela.'),
('lc',22,24,'crampon1923','Il s''éleva aussi parmi eux une dispute, pour savoir lequel d''entre eux devait être estimé le plus grand.'),
('lc',22,25,'crampon1923','Jésus leur dit: " Les rois des nations dominent sur elles, et ceux qui leur commandent sont appelés Bienfaiteurs.'),
('lc',22,26,'crampon1923','Pour vous, ne faites pas ainsi; mais que le plus grand parmi vous soit comme le dernier, et celui qui gouverne comme celui qui sert.'),
('lc',22,27,'crampon1923','Car quel est le plus grand, de celui qui est à table, ou de celui qui sert? N''est-ce pas celui qui est à table? Et moi, cependant, je suis au milieu de vous comme celui qui sert.'),
('lc',22,28,'crampon1923','Vous, vous êtes demeurés avec moi dans mes épreuves;'),
('lc',22,29,'crampon1923','et moi, je vous prépare un royaume, comme mon Père me l''a préparé,'),
('lc',22,30,'crampon1923','afin que vous mangiez et buviez à ma table dans mon royaume, et que vous soyez assis sur des trônes, pour juger les douze tribus d''Israël. "'),
('lc',22,31,'crampon1923','Et le Seigneur dit: " Simon, Simon, voici que Satan vous a réclamés pour vous cribler comme le froment;'),
('lc',22,32,'crampon1923','mais j''ai prié pour toi, afin que ta foi ne défaille point; et toi, quand tu seras converti, affermis tes frères. —'),
('lc',22,33,'crampon1923','Seigneur, lui dit Pierre, je suis prêt à aller avec vous et en prison et à la mort. "'),
('lc',22,34,'crampon1923','Jésus lui répondit: " Je te le dis, Pierre, le coq ne chantera pas aujourd''hui, que tu n''aies nié trois fois de me connaître. "'),
('lc',22,35,'crampon1923','Il dit encore à ses disciples: " Quand je vous ai envoyés sans bourse, ni sac, ni chaussures, avez-vous manqué de quelque chose? —'),
('lc',22,36,'crampon1923','De rien, " lui dirent-ils. Il ajouta: " Mais maintenant, que celui qui a une bourse la prenne, et de même celui qui a un sac; et que celui qui n''a point d''épée vende son manteau, et en achète une.'),
('lc',22,37,'crampon1923','Car, je vous le dis, il faut encore que cette parole de l''Écriture s''accomplisse en moi: Il a été mis au rang des malfaiteurs. En effet, ce qui me concerne touche à sa fin. "'),
('lc',22,38,'crampon1923','Ils lui dirent: " Seigneur, il y a ici deux épées. " Il leur répondit: " C''est assez. "'),
('lc',22,39,'crampon1923','Etant sorti, il s''en alla, selon sa coutume, vers le mont des Oliviers, et ses disciples le suivirent.'),
('lc',22,40,'crampon1923','Lorsqu''il fut arrivé dans ce lieu, il leur dit: " Priez, afin de ne point tomber en tentation. "'),
('lc',22,41,'crampon1923','Puis il s''éloigna d''eux à la distance d''un jet de pierre; et s''étant mis à genoux, il priait,'),
('lc',22,42,'crampon1923','disant: " Père, si vous voulez, éloignez de moi ce calice! Cependant que ce ne soit pas ma volonté, mais la vôtre qui se fasse. "'),
('lc',22,43,'crampon1923','Alors lui apparut du ciel un ange qui le fortifiait.'),
('lc',22,44,'crampon1923','Et se trouvant en agonie, il priait plus instamment, et sa sueur devint comme des gouttes de sang découlant jusqu''à terre.'),
('lc',22,45,'crampon1923','Après avoir prié, il se leva et vint vers les disciples, qu''il trouva endormis de tristesse.'),
('lc',22,46,'crampon1923','Et il leur dit: " Pourquoi dormez-vous? Levez-vous et priez, afin de ne point entrer en tentation. "'),
('lc',22,47,'crampon1923','Comme il parlait encore, voici qu''une troupe de gens parut; celui qu''on appelait Judas, l''un des Douze, marchait en tête. Il s''approcha de Jésus pour le baiser.'),
('lc',22,48,'crampon1923','Et Jésus lui dit: " Judas, tu livres le Fils de l''homme par un baiser! "'),
('lc',22,49,'crampon1923','Ceux qui étaient avec Jésus, voyant ce qui allait arriver, lui dirent: " Seigneur, si nous frappions de l''épée? "'),
('lc',22,50,'crampon1923','Et l''un d''eux frappa le serviteur du grand prêtre, et lui emporta l''oreille droite.'),
('lc',22,51,'crampon1923','Mais Jésus dit: " Restez-en là. " Et, ayant touché l''oreille de cet homme, il le guérit.'),
('lc',22,52,'crampon1923','Puis, s''adressant aux Princes des prêtres, aux officiers du temple et aux Anciens qui étaient venus pour le prendre, il leur dit: " Vous êtes venus comme après un brigand, avec des épées et des bâtons.'),
('lc',22,53,'crampon1923','J''étais tous les jours avec vous dans le temple, et vous n''avez mis pas la main sur moi. Mais voici votre heure et la puissance des ténèbres. "'),
('lc',22,54,'crampon1923','S''étant saisis de lui, ils l''emmenèrent et le conduisirent dans la maison du grand prêtre; Pierre suivait de loin.'),
('lc',22,55,'crampon1923','Ayant allumé du feu au milieu de la cour, ils s''assirent autour, et Pierre s''assit parmi eux.'),
('lc',22,56,'crampon1923','Une servante, qui le vit assis devant le feu, l''ayant regardé fixement, dit: " Cet homme était aussi avec lui. "'),
('lc',22,57,'crampon1923','Mais Pierre renia Jésus, en disant: " Femme, je ne le connais point. "'),
('lc',22,58,'crampon1923','Peu après, un autre l''ayant vu, dit: " Tu es aussi de ces gens-là. " Pierre répondit: " Mon ami, je n''en suis point. "'),
('lc',22,59,'crampon1923','Une heure s''était écoulée, lorsqu''un autre se mit à dire avec assurance: " Certainement cet homme était aussi avec lui, car il est de la Galilée. "'),
('lc',22,60,'crampon1923','Pierre répondit: " Mon ami, je ne sais ce que tu veux dire. " Et aussitôt, comme il parlait encore, le coq chanta.'),
('lc',22,61,'crampon1923','Et le Seigneur, s''étant retourné, regarda Pierre, et Pierre se souvint de la parole que le Seigneur lui avait dite: " Avant que le coq chante, tu me renieras trois fois. "'),
('lc',22,62,'crampon1923','Et étant sorti de la maison, Pierre pleura amèrement.'),
('lc',22,63,'crampon1923','Or, ceux qui tenaient Jésus se moquaient de lui et le frappaient.'),
('lc',22,64,'crampon1923','Ils lui bandèrent les yeux, et, le frappant au visage, ils l''interrogeaient, disant: " Devine qui t''a frappé. "'),
('lc',22,65,'crampon1923','Et ils proféraient contre lui beaucoup d''autres injures.'),
('lc',22,66,'crampon1923','Dès qu''il fit jour, les Anciens du peuple, les Princes des prêtres et les Scribes se réunirent, et amenèrent Jésus dans leur assemblée. Ils dirent: " Si tu es le Christ, dis-le-nous. "'),
('lc',22,67,'crampon1923','Il leur répondit: " Si je vous le dis, vous ne le croirez pas;'),
('lc',22,68,'crampon1923','et si je vous interroge, vous ne me répondrez pas et ne me relâcherez pas.'),
('lc',22,69,'crampon1923','Désormais le Fils de l''homme sera assis à la droite de la puissance de Dieu. "'),
('lc',22,70,'crampon1923','Alors ils dirent tous: " Tu es donc le Fils de Dieu? " Il leur répondit: " Vous le dites, je le suis. "'),
('lc',22,71,'crampon1923','Et ils dirent: " Qu''avons-nous encore besoin de témoignage? Nous l''avons nous-mêmes entendu de sa bouche. "'),
('lc',23,1,'crampon1923','Alors toute l''assemblée s''étant levée, ils menèrent Jésus devant Pilate,'),
('lc',23,2,'crampon1923','et ils se mirent à l''accuser, en disant: " Nous avons trouvé cet homme qui poussait notre nation à la révolte, et défendait de payer les tributs à César, se disant lui-même le Christ roi. "'),
('lc',23,3,'crampon1923','Pilate l''interrogea, disant: " Es-tu le roi des Juifs? " Jésus lui répondit: " Tu le dis. "'),
('lc',23,4,'crampon1923','Pilate dit aux Princes des prêtres et au peuple: " Je ne trouve rien de criminel en cet homme. "'),
('lc',23,5,'crampon1923','Mais redoublant leurs instances, ils dirent: " Il soulève le peuple, répandant sa doctrine dans toute la Judée, depuis la Galilée, où il a commencé, jusqu''ici. "'),
('lc',23,6,'crampon1923','Quand Pilate entendit nommer la Galilée, il demanda si cet homme était Galiléen;'),
('lc',23,7,'crampon1923','et ayant appris qu''il était de la juridiction d''Hérode, il le renvoya à Hérode, qui se trouvait aussi à Jérusalem, en ces jours-là.'),
('lc',23,8,'crampon1923','Hérode eut une grande joie de voir Jésus; car depuis longtemps il en avait le désir, parce qu''il avait entendu beaucoup parler de lui, et il espérait lui voir opérer quelque prodige.'),
('lc',23,9,'crampon1923','Il lui adressa beaucoup de questions, mais Jésus ne lui répondit rien.'),
('lc',23,10,'crampon1923','Or, les Princes des prêtres et les Scribes se trouvaient là, l''accusant avec opiniâtreté.'),
('lc',23,11,'crampon1923','Mais Hérode, avec ses gardes, le traita avec mépris; après s''être moqué de lui et l''avoir revêtu d''une robe éclatante, il le renvoya à Pilate.'),
('lc',23,12,'crampon1923','Le jour même, Hérode et Pilate devinrent amis, d''ennemis qu''ils étaient auparavant.'),
('lc',23,13,'crampon1923','Pilate, ayant assemblé les Princes des prêtres, les magistrats et le peuple,'),
('lc',23,14,'crampon1923','leur dit: " Vous m''avez amené cet homme comme excitant le peuple à la révolte; je l''ai interrogé devant vous, et je n''ai trouvé en lui aucun des crimes dont vous l''accusez;'),
('lc',23,15,'crampon1923','ni Hérode non plus, car je vous ai renvoyés à lui, et, vous le voyez, rien qui mérite la mort n''a été prouvé contre lui.'),
('lc',23,16,'crampon1923','Je le relâcherai donc après l''avoir fait châtier. "'),
('lc',23,17,'crampon1923','[Pilate était obligé, au jour de la fête, de leur accorder la délivrance d''un prisonnier].'),
('lc',23,18,'crampon1923','Mais la foule tout entière s''écria: " Fais mourir celui-ci, et relâche-nous Barabbas: " —'),
('lc',23,19,'crampon1923','lequel avait été mis en prison à cause d''une sédition qui avait eu lieu dans la ville, et d''un meurtre.'),
('lc',23,20,'crampon1923','Pilate, qui désirait relâcher Jésus, les harangua de nouveau;'),
('lc',23,21,'crampon1923','mais ils répondirent par ce cri: " Crucifie-le! crucifie-le! "'),
('lc',23,22,'crampon1923','Pour la troisième fois, Pilate leur dit: " Qu''a-t-il donc fait de mal? Je n''ai rien trouvé en lui qui mérite la mort. Ainsi je le ferai châtier et je le renverrai. "'),
('lc',23,23,'crampon1923','Mais ils insistèrent, demandant à grands cris qu''il fût crucifié, et leurs clameurs allaient grandissant.'),
('lc',23,24,'crampon1923','Pilate prononça donc qu''il serait fait comme ils demandaient.'),
('lc',23,25,'crampon1923','Il relâcha celui qu''ils réclamaient, et qui avait été mis en prison pour sédition et meurtre, et il livra Jésus à leur volonté.'),
('lc',23,26,'crampon1923','Comme ils l''emmenaient, ils arrêtèrent un nommé Simon, de Cyrène, qui revenait de la campagne, et ils le chargèrent de la croix; pour qu''il la portât derrière Jésus.'),
('lc',23,27,'crampon1923','Or, il était suivi d''une grande foule de peuple et de femmes qui se frappaient la poitrine et se lamentaient sur lui.'),
('lc',23,28,'crampon1923','Se tournant vers elles, Jésus dit: " Filles de Jérusalem, ne pleurez pas sur moi, mais pleurez sur vous-mêmes et sur vos enfants;'),
('lc',23,29,'crampon1923','car voici que des jours viennent où l''on dira: Heureuses les stériles, et les entrailles qui n''ont point enfanté et les mamelles qui n''ont point allaité!'),
('lc',23,30,'crampon1923','Alors les hommes commenceront à dire aux montagnes: Tombez sur nous, et aux collines: Couvrez-nous.'),
('lc',23,31,'crampon1923','Car, si l''on traite ainsi le bois vert, que fera-t-on du bois sec? "'),
('lc',23,32,'crampon1923','Et l''on conduisait en outre deux malfaiteurs, pour les mettre à mort avec Jésus.'),
('lc',23,33,'crampon1923','Lorsqu''ils furent arrivés au lieu appelé Calvaire, ils l''y crucifièrent, ainsi que les malfaiteurs, l''un à droite, l''autre à gauche.'),
('lc',23,34,'crampon1923','Mais Jésus disait: " Père, pardonnez-leur, car ils ne savent ce qu''ils font. " Se partageant ensuite ses vêtements, ils les tirèrent au sort.'),
('lc',23,35,'crampon1923','Le peuple se tenait là et regardait. Les magistrats se joignaient à lui pour railler Jésus en disant: " Il en a sauvé d''autres; qu''il se sauve lui-même, s''il est le Christ, l''élu de Dieu. "'),
('lc',23,36,'crampon1923','Les soldats aussi se moquaient de lui; s''approchant et lui présentant du vinaigre;'),
('lc',23,37,'crampon1923','ils disaient: " Si tu es le roi des Juifs, sauve-toi toi-même. "'),
('lc',23,38,'crampon1923','Il y avait encore au-dessus de sa tête une inscription portant, en caractères grecs, latins et hébraïques: " Celui-ci est le roi des Juifs. "'),
('lc',23,39,'crampon1923','Or, l''un des malfaiteurs pendus à la croix l''injuriait, disant: " Puisque tu es le Christ, sauve-toi toi-même et sauve-nous! "'),
('lc',23,40,'crampon1923','Mais l''autre le reprenait, en disant: " Ne crains-tu donc pas Dieu, toi non plus, condamné que tu es au même supplice?'),
('lc',23,41,'crampon1923','Pour nous, c''est justice, car nous recevons ce qu''ont mérité nos crimes; mais lui, il n''a rien fait de mal. "'),
('lc',23,42,'crampon1923','Et il dit à Jésus: " Seigneur, souvenez-vous de moi, quand vous serez parvenu dans votre royaume. "'),
('lc',23,43,'crampon1923','Jésus lui répondit: " Je te le dis en vérité, aujourd''hui tu seras avec moi dans le Paradis. "'),
('lc',23,44,'crampon1923','Il était environ la sixième heure, quand des ténèbres couvrirent toute la terre jusqu''à la neuvième heure.'),
('lc',23,45,'crampon1923','Le soleil s''obscurcit, et le voile du temple se déchira par le milieu.'),
('lc',23,46,'crampon1923','Et Jésus s''écria d''une voix forte: " Père, je remets mon esprit entre vos mains. " En disant ces mots, il expira.'),
('lc',23,47,'crampon1923','Le centurion, voyant ce qui était arrivé, glorifia Dieu, et dit: " Certainement, cet homme était juste. "'),
('lc',23,48,'crampon1923','Et toutes la multitude qui s''était rassemblée pour ce spectacle, considérant ce qui était arrivé, s''en retournait en se frappant la poitrine.'),
('lc',23,49,'crampon1923','Mais tous les amis de Jésus se tenaient à distance, avec les femmes qui l''avaient suivi de Galilée et contemplaient tout cela.'),
('lc',23,50,'crampon1923','Or, il y avait un homme, appelé Joseph, membre du conseil, homme bon et juste,'),
('lc',23,51,'crampon1923','qui n''avait donné son assentiment ni au dessein des autres, ni à leurs actes; — il était d''Arimathie, ville de Judée, et attendait, lui aussi, le royaume de Dieu.'),
('lc',23,52,'crampon1923','Cet homme alla trouver Pilate, lui demanda le corps de Jésus,'),
('lc',23,53,'crampon1923','et l''ayant descendu, il l''enveloppa d''un linceul, et le déposa dans un sépulcre taillé dans le roc, où personne n''avait encore été mis.'),
('lc',23,54,'crampon1923','C''était le jour de la Préparation, et le sabbat allait commencer.'),
('lc',23,55,'crampon1923','Les femmes qui étaient venues de la Galilée avec Jésus, ayant accompagné Joseph, considérèrent le sépulcre, et la manière dont le corps de Jésus y avait été déposé.'),
('lc',23,56,'crampon1923','S''en étant donc retournées, elles préparèrent des aromates et des parfums; et le jour du sabbat, elles demeurèrent en repos, selon le précepte.'),
('lc',24,1,'crampon1923','Mais, le premier jour de la semaine, de grand matin, elles se rendirent au sépulcre, avec les aromates qu''elles avaient préparés.'),
('lc',24,2,'crampon1923','Elles virent que la pierre avait été roulée loin du sépulcre;')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('lc',24,3,'crampon1923','et, étant entrées, elles ne trouvèrent pas le corps du Seigneur Jésus.'),
('lc',24,4,'crampon1923','Tandis qu''elles étaient remplies d''anxiété à ce sujet, voici que deux hommes, vêtus de robes resplendissantes, parurent debout auprès d''elles.'),
('lc',24,5,'crampon1923','Comme, dans leur épouvante, elles inclinaient le visage vers la terre, ils leur dirent: " Pourquoi cherchez-vous parmi les morts celui qui est vivant?'),
('lc',24,6,'crampon1923','Il n''est point ici, mais il est ressuscité. Souvenez-vous de ce qu''il vous a dit, lorsqu''il était encore en Galilée:'),
('lc',24,7,'crampon1923','Il faut que le Fils de l''homme soit livré entre les mains des pécheurs, qu''il soit crucifié, et qu''il ressuscite le troisième jour. "'),
('lc',24,8,'crampon1923','Elles se ressouvinrent alors des paroles de Jésus,'),
('lc',24,9,'crampon1923','et, à leur retour du sépulcre, elles rapportèrent toutes ces choses aux Onze et à tous les autres.'),
('lc',24,10,'crampon1923','Celles qui dirent ces choses aux Apôtres étaient Marie-Madeleine, Jeanne, Marie, mère de Jacques, et leurs autres compagnes.'),
('lc',24,11,'crampon1923','Mais ils regardèrent leurs discours comme vain racontage, et ils ne crurent pas ces femmes.'),
('lc',24,12,'crampon1923','Toutefois Pierre se leva et courut au sépulcre; et, s''étant penché, il ne vit que les linges par terre, et il s''en alla chez lui, dans l''admiration de ce qui était arrivé.'),
('lc',24,13,'crampon1923','Or, ce même jour, deux disciples étaient en route vers un village nommé Emmaüs, distant de Jérusalem de soixante stades,'),
('lc',24,14,'crampon1923','et ils s''entretenaient de tous ces événements.'),
('lc',24,15,'crampon1923','Pendant qu''ils discouraient, échangeant leurs pensées, Jésus lui-même les joignit et fit route avec eux;'),
('lc',24,16,'crampon1923','mais leurs yeux étaient retenus de sorte qu''ils ne le reconnaissaient pas.'),
('lc',24,17,'crampon1923','Il leur dit: " De quoi vous entretenez-vous ainsi en marchant, que vous soyez tout tristes? "'),
('lc',24,18,'crampon1923','L''un d''eux, nommé Cléophas, lui répondit: " Tu es bien le seul étranger venu à Jérusalem, qui ne sache pas les choses qui y sont arrivées ces jours-ci? —'),
('lc',24,19,'crampon1923','Quelles choses? " leur dit-il. Ils répondirent: " Les faits concernant Jésus de Nazareth, qui était un prophète puissant en œuvres et en parole devant Dieu et devant tout le peuple:'),
('lc',24,20,'crampon1923','comment les Princes des prêtres et nos magistrats l''ont livré pour être condamné à mort, et l''ont crucifié.'),
('lc',24,21,'crampon1923','Quant à nous, nous espérions que ce serait lui qui délivrerait Israël; mais, avec tout cela, c''est aujourd''hui le troisième jour que ces choses sont arrivées.'),
('lc',24,22,'crampon1923','A la vérité, quelques-unes des femmes qui sont avec nous, nous ont fort étonnés: étant allées avant le jour au sépulcre,'),
('lc',24,23,'crampon1923','et n''ayant pas trouvé son corps, elles sont venues dire que des anges leur ont apparu et ont annoncé qu''il est vivant.'),
('lc',24,24,'crampon1923','Quelques-uns des nôtres sont allés au sépulcre, et ont trouvé toutes choses comme les femmes l''avaient dit; mais lui, ils ne l''ont point vu. "'),
('lc',24,25,'crampon1923','Alors Jésus leur dit: " O hommes sans intelligence, et dont le cœur est lent à croire tout ce qu''ont dit les Prophètes!'),
('lc',24,26,'crampon1923','Ne fallait-il pas que le Christ souffrit toutes ces choses pour entrer dans sa gloire? "'),
('lc',24,27,'crampon1923','Puis, commençant par Moïse, et parcourant tous les prophètes, il leur expliqua, dans toutes les Écritures, ce qui le concernait.'),
('lc',24,28,'crampon1923','Lorsqu''ils se trouvèrent près du village où ils allaient, lui fit semblant d''aller plus loin.'),
('lc',24,29,'crampon1923','Mais ils le pressèrent, en disant: " Reste avec nous, car il se fait tard, et déjà le jour baisse. " Et il entra pour rester avec eux.'),
('lc',24,30,'crampon1923','Or, pendant qu''il était à table avec eux, il prit le pain, prononça une bénédiction, puis le rompit, et le leur donna.'),
('lc',24,31,'crampon1923','Alors leurs yeux s''ouvrirent, et ils le reconnurent; mais lui devint invisible à leurs yeux.'),
('lc',24,32,'crampon1923','Et ils se dirent l''un à l''autre: " N''est-il pas vrai que notre cœur était tout brûlant au dedans de nous, lorsqu''il nous parlait en chemin, et qu''il nous expliquait les Ecritures? "'),
('lc',24,33,'crampon1923','Se levant à l''heure même, ils retournèrent à Jérusalem; où ils trouvèrent réunis les Onze et leurs compagnons,'),
('lc',24,34,'crampon1923','qui disaient: " Le Seigneur est vraiment ressuscité, et il est apparu à Simon. "'),
('lc',24,35,'crampon1923','Eux-mêmes, à leur tour, racontèrent ce qui leur était arrivé en chemin, et comment ils l''avaient reconnu à la fraction du pain.'),
('lc',24,36,'crampon1923','Pendant qu''ils s''entretenaient ainsi, Jésus se présenta au milieu d''eux, et leur dit: " La paix soit avec vous! c''est moi, ne craignez point. "'),
('lc',24,37,'crampon1923','Saisis de stupeur et d''effroi, ils pensaient voir un esprit.'),
('lc',24,38,'crampon1923','Mais il leur dit: " Pourquoi vous troublez-vous, et pourquoi des doutes s''élèvent-ils dans vos cœurs?'),
('lc',24,39,'crampon1923','Voyez mes mains et mes pieds; c''est bien moi. Touchez-moi, et considérez qu''un esprit n''a ni chair ni os, comme vous voyez que j''en ai. "'),
('lc',24,40,'crampon1923','Ayant ainsi parlé, il leur montra ses mains et ses pieds.'),
('lc',24,41,'crampon1923','Comme dans leur joie, ils hésitaient encore à croire, et ne revenaient pas de leur étonnement, il leur dit: " Avez-vous ici quelque chose à manger? "'),
('lc',24,42,'crampon1923','Ils lui présentèrent un morceau de poisson rôti et un rayon de miel.'),
('lc',24,43,'crampon1923','Il les prit, et en mangea devant eux.'),
('lc',24,44,'crampon1923','Puis il leur dit: " C''est là ce que je vous disais, étant encore avec vous, qu''il fallait que tout ce qui est écrit de moi dans la loi de Moïse, dans les Prophètes et dans les Psaumes s''accomplît. "'),
('lc',24,45,'crampon1923','Alors il leur ouvrit l''esprit, pour comprendre les Ecritures;'),
('lc',24,46,'crampon1923','et il leur dit: " Ainsi il est écrit: et ainsi il fallait que le Christ souffrît, qu''il ressuscitât des morts le troisième jour,'),
('lc',24,47,'crampon1923','et que le repentir et la rémission des péchés soient prêchés en son nom à toutes les nations, à commencer par Jérusalem.'),
('lc',24,48,'crampon1923','Vous êtes témoins de ces choses.'),
('lc',24,49,'crampon1923','Moi, je vais envoyer sur vous le don promis par mon Père; et vous, restez dans la ville, jusqu''à ce que vous soyez revêtus d''une force d''en haut. "'),
('lc',24,50,'crampon1923','Puis il les conduisit hors de la ville, jusque vers Béthanie, et, ayant levé les mains, il les bénit.'),
('lc',24,51,'crampon1923','Pendant qu''il les bénissait, il se sépara d''eux et il fut enlevé au ciel.'),
('lc',24,52,'crampon1923','Pour eux, après l''avoir adoré, ils retournèrent à Jérusalem avec une grande joie.'),
('lc',24,53,'crampon1923','Et ils étaient continuellement dans le temple, louant et bénissant Dieu. [Amen!]'),
('jn',1,1,'crampon1923','Au commencement était le Verbe, et le Verbe était en Dieu, et le Verbe était Dieu.'),
('jn',1,2,'crampon1923','Il était au commencement en Dieu.'),
('jn',1,3,'crampon1923','Tout par lui a été fait, et sans lui n''a été fait rien de ce qui existe.'),
('jn',1,4,'crampon1923','En lui était la vie, et la vie était la lumière des hommes,'),
('jn',1,5,'crampon1923','Et la lumière luit dans les ténèbres, et les ténèbres ne l''ont point reçue.'),
('jn',1,6,'crampon1923','Il y eut un homme, envoyé de Dieu; son nom était Jean.'),
('jn',1,7,'crampon1923','Celui-ci vint en témoignage, pour rendre témoignage à la lumière, afin que tous crussent par lui:'),
('jn',1,8,'crampon1923','non que celui-ci fût la lumière, mais il avait à rendre témoignage à la lumière.'),
('jn',1,9,'crampon1923','La lumière, la vraie, celle qui éclaire tout homme, venait dans le monde.'),
('jn',1,10,'crampon1923','Il (le Verbe) était dans le monde, et le monde par lui a été fait, et le monde ne l''a pas connu.'),
('jn',1,11,'crampon1923','Il vint chez lui, et les siens ne l''ont pas reçu.'),
('jn',1,12,'crampon1923','Mais quant à tous ceux qui l''ont reçu, Il leur a donné le pouvoir de devenir enfants de Dieu, à ceux qui croient en son nom,'),
('jn',1,13,'crampon1923','Qui non du sang, ni de la volonté de la chair, ni de la volonté de l''homme, mais de Dieu sont nés.'),
('jn',1,14,'crampon1923','Et le Verbe s''est fait chair, et il a habité parmi nous, (et nous avons vu sa gloire, gloire comme celle qu''un fils unique tient de son Père) tout plein de grâce et de vérité.'),
('jn',1,15,'crampon1923','Jean lui rend témoignage, et s''écrie en ces termes: " Voici celui dont je disais: Celui qui vient après moi, est passé devant moi, parce qu''il était avant moi. "'),
('jn',1,16,'crampon1923','Et c''est de sa plénitude, que nous avons tous reçu, et grâce sur grâce;'),
('jn',1,17,'crampon1923','parce que la loi a été donnée par Moïse, la grâce et la vérité sont venues par Jésus-Christ.'),
('jn',1,18,'crampon1923','Dieu, personne ne le vit jamais: le Fils unique, qui est dans le sein du Père, c''est lui qui l''a fait connaître.'),
('jn',1,19,'crampon1923','Et voici le témoignage que rendit Jean, lorsque les Juifs envoyèrent de Jérusalem des prêtres et des lévites pour lui demander: " Qui êtes-vous? "'),
('jn',1,20,'crampon1923','Il déclara, et ne le nia point; il déclara: " Je ne suis point le Christ. "'),
('jn',1,21,'crampon1923','Et ils lui demandèrent: " Quoi donc! Etes-vous Elie? " Il dit: " Je ne le suis point — Etes-vous le prophète? " Il répondit: " Non. —'),
('jn',1,22,'crampon1923','Qui êtes-vous donc, lui dirent-ils, afin que nous donnions une réponse à ceux qui nous ont envoyés. Que dites-vous de vous-même? "'),
('jn',1,23,'crampon1923','Il répondit: " Je suis la voix de celui qui crie dans le désert: Aplanissez le chemin du Seigneur, comme l''a dit le prophète Isaïe. "'),
('jn',1,24,'crampon1923','Or ceux qu''on lui avait envoyés étaient des Pharisiens.'),
('jn',1,25,'crampon1923','Et ils l''interrogèrent, et lui dirent: " Pourquoi donc baptisez-vous, si vous n''êtes ni le Christ, ni Elie, ni le Prophète? "'),
('jn',1,26,'crampon1923','Jean leur répondit: " Moi je baptise dans l''eau; mais au milieu de vous il y a quelqu''un que vous ne connaissez pas,'),
('jn',1,27,'crampon1923','c''est celui qui vient après moi; je ne suis pas digne de délier la courroie de sa chaussure. "'),
('jn',1,28,'crampon1923','Cela se passait à Béthanie, au delà du Jourdain, où Jean baptisait.'),
('jn',1,29,'crampon1923','Le lendemain, Jean vit Jésus qui venait vers lui, et il dit: " Voici l''agneau de Dieu, voici celui qui ôte le péché du monde.'),
('jn',1,30,'crampon1923','C''est de lui que j''ai dit: un homme vient après moi, qui est passé devant moi, parce qu''il était avant moi.'),
('jn',1,31,'crampon1923','Et moi, je ne le connaissais pas, mais c''est afin qu''il fût manifesté à Israël, que je suis venu baptiser dans l''eau. "'),
('jn',1,32,'crampon1923','Et Jean rendit témoignage en disant: " J''ai vu l''Esprit descendre du ciel comme une colombe, et il s''est reposé sur lui.'),
('jn',1,33,'crampon1923','Et moi, je ne le connaissais pas; mais celui qui m''a envoyé baptiser dans l''eau m''a dit: Celui sur qui tu verras l''Esprit descendre et se reposer, c''est lui qui baptise dans l''Esprit-Saint.'),
('jn',1,34,'crampon1923','Et moi j''ai vu et j''ai rendu témoignage que celui-là est le Fils de Dieu. "'),
('jn',1,35,'crampon1923','Le lendemain, Jean se trouvait encore là, avec deux de ses disciples.'),
('jn',1,36,'crampon1923','Et ayant regardé Jésus qui passait, il dit: " Voici l''Agneau de Dieu. "'),
('jn',1,37,'crampon1923','Les deux disciples l''entendirent parler, et ils suivirent Jésus.'),
('jn',1,38,'crampon1923','Jésus s''étant retourné, et voyant qu''ils le suivaient, leur dit: " Que cherchez-vous? " Ils lui répondirent: " Rabbi (ce qui signifie Maître), où demeurez-vous? "'),
('jn',1,39,'crampon1923','Il leur dit: " Venez et vous verrez. " Ils allèrent, et virent où il demeurait, et ils restèrent auprès de lui ce jour-là. Or, c''était environ la dixième heure.'),
('jn',1,40,'crampon1923','Or, André, le frère de Simon-Pierre, était l''un des deux qui avaient entendu la parole de Jean, et qui avaient suivi Jésus.'),
('jn',1,41,'crampon1923','Il rencontra d''abord son frère Simon, et lui dit: " Nous avons trouvé le Messie (ce qui se traduit Christ). "'),
('jn',1,42,'crampon1923','Et il l''amena à Jésus. Jésus, l''ayant regardé dit: " Toi, tu es Simon, fils de Jean; tu seras appelé Céphas (ce qui se traduit Pierre). "'),
('jn',1,43,'crampon1923','Le jour suivant, Jésus résolut d''aller en Galilée. Et il rencontra Philippe. Et Jésus lui dit: " Suis-moi. "'),
('jn',1,44,'crampon1923','Philippe était de Bethsaïde, la ville d''André et de Pierre.'),
('jn',1,45,'crampon1923','Philippe rencontra Nathanaël et lui dit: " Nous avons trouvé celui dont Moïse a écrit dans la Loi, ainsi que les Prophètes: c''est Jésus, fils de Joseph de Nazareth. "'),
('jn',1,46,'crampon1923','Nathanaël lui répondit: " Peut-il sortir de Nazareth quelque chose de bon? " Philippe lui dit: " Viens et vois. "'),
('jn',1,47,'crampon1923','Jésus vit venir vers lui Nathanaël, et dit en parlant de lui: " Voici vraiment un Israélite, en qui il n''y a nul artifice. "'),
('jn',1,48,'crampon1923','Nathanaël lui dit: " D''où me connaissez-vous? " Jésus repartit et lui dit: " Avant que Philippe t''appelât, lorsque tu étais sous le figuier, je t''ai vu. "'),
('jn',1,49,'crampon1923','Nathanaël lui répondit: " Rabbi, vous êtes le Fils de Dieu, vous êtes le Roi d''Israël. "'),
('jn',1,50,'crampon1923','Jésus lui repartit: " Parce que je t''ai dit: Je t''ai vu sous le figuier, tu crois! Tu verras de plus grandes choses que celle-là. "'),
('jn',1,51,'crampon1923','Et il ajouta: " En vérité, en vérité, je vous le dis, vous verrez désormais le ciel ouvert, et les anges de Dieu montant et descendant sur le Fils de l''homme. "'),
('jn',2,1,'crampon1923','Et le troisième jour, il se fit des noces à Cana en Galilée; et la mère de Jésus y était.'),
('jn',2,2,'crampon1923','Jésus fut aussi convié aux noces avec ses disciples.'),
('jn',2,3,'crampon1923','Le vin étant venu à manquer, la mère de Jésus lui dit: " Ils n''ont point de vin. "'),
('jn',2,4,'crampon1923','Jésus lui répondit: " Femme, qu''est-ce que cela pour moi et vous? Mon heure n''est pas encore venue. "'),
('jn',2,5,'crampon1923','Sa mère dit aux serviteurs: " Faites tout ce qu''il vous dira. "'),
('jn',2,6,'crampon1923','Or, il y avait là six urnes de pierre destinées aux ablutions des Juifs, et contenant chacune deux ou trois mesures.'),
('jn',2,7,'crampon1923','Jésus leur dit: " Remplissez d''eau ces urnes. " Et ils les remplirent jusqu''au haut.'),
('jn',2,8,'crampon1923','Et il leur dit: " Puisez maintenant, et portez-en au maître du festin; " et ils en portèrent.'),
('jn',2,9,'crampon1923','Dès que le maître du festin eut goûté l''eau changée en vin (il ne savait pas d''où venait ce vin, mais les serviteurs qui avaient puisé l''eau le savaient), il interpella l''époux,'),
('jn',2,10,'crampon1923','et lui dit: " Tout homme sert d''abord le bon vin, et, après qu''on a bu abondamment, le moins bon; mais toi, tu as gardé le bon jusqu''à ce moment. " —'),
('jn',2,11,'crampon1923','Tel fut, à Cana de Galilée, le premier des miracles que fit Jésus, et il manifesta sa gloire, et ses disciples crurent en lui.'),
('jn',2,12,'crampon1923','Après cela, il descendit à Capharnaüm avec sa mère, ses frères et ses disciples, et ils n''y demeurèrent que peu de jours.'),
('jn',2,13,'crampon1923','Or la Pâque des Juifs était proche, et Jésus monta à Jérusalem.'),
('jn',2,14,'crampon1923','Il trouva dans le temple les marchands de bœufs, de brebis, et de colombes, et les changeurs assis.'),
('jn',2,15,'crampon1923','Et ayant fait un petit fouet avec des cordes, il les chassa tous du temple, avec les brebis et les bœufs; il jeta par terre l''argent des changeurs, et renversa leurs tables.'),
('jn',2,16,'crampon1923','Et il dit aux vendeurs de colombes: " Enlevez cela d''ici; ne faites pas de la maison de mon Père une maison de trafic. "'),
('jn',2,17,'crampon1923','Les disciples se ressouvinrent alors qu''il est écrit: " Le zèle de votre maison me dévore. "'),
('jn',2,18,'crampon1923','Les Juifs prenant la parole lui dirent: " Quel signe nous montrez-vous, pour agir de la sorte? "'),
('jn',2,19,'crampon1923','Jésus leur répondit: " Détruisez ce temple et je le relèverai en trois jours. "'),
('jn',2,20,'crampon1923','Les Juifs repartirent: " C''est en quarante-six ans que ce temple a été bâti, et vous, en trois jours vous le relèverez! "'),
('jn',2,21,'crampon1923','Mais lui, il parlait du temple de son corps.'),
('jn',2,22,'crampon1923','Lors donc qu''il fut ressuscité d''entre les morts, ses disciples se souvinrent qu''il avait dit cela, et ils crurent à l''Ecriture et à la parole que Jésus avait dite.'),
('jn',2,23,'crampon1923','Pendant que Jésus était à Jérusalem, à la fête de Pâque, beaucoup voyant les miracles qu''il faisait, crurent en son nom.'),
('jn',2,24,'crampon1923','Mais Jésus ne se fiait point à eux, parce qu''il les connaissait tous,'),
('jn',2,25,'crampon1923','et qu''il n''avait pas besoin qu''on lui rendit témoignage d''aucun homme; car il savait, lui, ce qu''il y avait dans l''homme.'),
('jn',3,1,'crampon1923','Or, il y avait parmi les Pharisiens un homme nommé Nicodème, un des principaux parmi les Juifs.'),
('jn',3,2,'crampon1923','Il vint de nuit trouver Jésus, et lui dit: " Maître, nous savons que vous êtes venu de la part de Dieu, comme docteur, car personne ne saurait faire les miracles que vous faites, si Dieu n''est pas avec lui. "'),
('jn',3,3,'crampon1923','Jésus lui répondit: " En vérité, en vérité, je te le dis, nul, s''il ne naît de nouveau, ne peut voir le royaume de Dieu. "'),
('jn',3,4,'crampon1923','Nicodème lui dit: " Comment un homme, quand il est déjà vieux, peut-il naître? Peut-il entrer une seconde fois dans le sein de sa mère, et naître de nouveau? "'),
('jn',3,5,'crampon1923','Jésus répondit: " En vérité, en vérité, je te le dis, nul, s''il ne renaît de l''eau et de l''Esprit, ne peut entrer dans le royaume de Dieu.'),
('jn',3,6,'crampon1923','Car ce qui est né de la chair est chair, et ce qui est né de l''Esprit est esprit.'),
('jn',3,7,'crampon1923','Ne t''étonne pas de ce que je t''ai dit: Il faut que vous naissiez de nouveau.'),
('jn',3,8,'crampon1923','Le vent souffle où il veut et tu entends sa voix; mais tu ne sais d''où il vient, ni où il va: ainsi en est-il de quiconque est né de l''Esprit. "'),
('jn',3,9,'crampon1923','Nicodème lui répondit: " Comment cela se peut-il faire? "'),
('jn',3,10,'crampon1923','Jésus lui dit: " Tu es le docteur d''Israël, et tu ignores ces choses!'),
('jn',3,11,'crampon1923','En vérité, en vérité, je te le dis, nous disons ce que nous savons, et nous attestons ce que nous avons vu, mais vous ne recevez point notre témoignage.'),
('jn',3,12,'crampon1923','Si vous ne croyez pas quand je vous parle des choses qui sont sur la terre, comment croirez-vous si je viens à vous parler de celles qui sont dans le ciel?'),
('jn',3,13,'crampon1923','Et nul n''est monté au ciel si ce n''est celui qui est descendu du ciel, le Fils de l''homme qui est dans le ciel.'),
('jn',3,14,'crampon1923','Comme Moïse a élevé le serpent dans le désert, il faut de même que le Fils de l''homme soit élevé,'),
('jn',3,15,'crampon1923','Afin que tout homme qui croit en lui [ne périsse point, mais qu''il] ait la vie éternelle.'),
('jn',3,16,'crampon1923','En effet, Dieu a tellement aimé le monde, qu''il a donné son Fils unique, afin que quiconque croit en lui ne périsse point mais ait la vie éternelle.'),
('jn',3,17,'crampon1923','Car Dieu n''a pas envoyé le Fils dans le monde pour juger le monde, mais pour que le monde soit sauvé par lui.'),
('jn',3,18,'crampon1923','Celui qui croit en lui n''est pas jugé; mais celui qui ne croit pas est déjà jugé, parce qu''il n''a pas cru au nom du Fils unique de Dieu.'),
('jn',3,19,'crampon1923','Or, voici quel est le jugement: c''est que la lumière est venue dans le monde, et que les hommes ont mieux aimé les ténèbres que la lumière, parce que leurs œuvres étaient mauvaises.'),
('jn',3,20,'crampon1923','Car quiconque fait le mal, hait la lumière, de peur que ses œuvres ne soient blâmées.'),
('jn',3,21,'crampon1923','Mais celui qui accomplit la vérité, vient à la lumière, de sorte que ses œuvres soient manifestées, parce qu''elles sont faites en Dieu. "'),
('jn',3,22,'crampon1923','Après cela, Jésus se rendit avec ses disciples au pays de Judée, et il y séjourna avec eux, et il baptisait.'),
('jn',3,23,'crampon1923','Jean aussi baptisait à Ennon, près de Salim, parce qu''il y avait là beaucoup d''eau, et l''on venait et l''on était baptisé,'),
('jn',3,24,'crampon1923','car Jean n''avait pas encore été jeté en prison.'),
('jn',3,25,'crampon1923','Or, il s''éleva une discussion entre les disciples de Jean et un Juif touchant la purification.'),
('jn',3,26,'crampon1923','Et ils vinrent trouver Jean, et lui dirent: " Maître, celui qui était avec vous au delà du Jourdain, et à qui vous avez rendu témoignage, le voilà qui baptise, et tous vont à lui. "'),
('jn',3,27,'crampon1923','Jean répondit: " Un homme ne peut prendre que ce qui lui a été donné du ciel.'),
('jn',3,28,'crampon1923','Vous m''êtes vous-mêmes témoins que j''ai dit: " Je ne suis point le Christ, mais j''ai été envoyé devant lui. "'),
('jn',3,29,'crampon1923','Celui qui a l''épouse est l''époux; mais l''ami de l''époux, qui se tient là et qui l''écoute, est ravi de joie à la voix de l''époux. Or cette joie qui est la mienne, elle est pleinement réalisée.'),
('jn',3,30,'crampon1923','Il faut qu''il croisse et que je diminue.'),
('jn',3,31,'crampon1923','Celui qui vient d''en haut est au-dessus de tous; celui qui est de la terre est terrestre, et son langage aussi. Celui qui vient du ciel est au-dessus de tous;'),
('jn',3,32,'crampon1923','et ce qu''il a vu et entendu, il l''atteste; mais personne ne reçoit son témoignage.'),
('jn',3,33,'crampon1923','Celui qui reçoit son témoignage, certifie que Dieu est véridique.'),
('jn',3,34,'crampon1923','Car celui que Dieu a envoyé dit les paroles de Dieu, parce que Dieu ne lui donne pas l''Esprit avec mesure.'),
('jn',3,35,'crampon1923','Le Père aime le Fils, et il lui a tout remis entre les mains.'),
('jn',3,36,'crampon1923','Celui qui croit au Fils a la vie éternelle; mais celui qui ne croit pas au Fils ne verra pas la vie; mais la colère de Dieu demeure sur lui. "'),
('jn',4,1,'crampon1923','Quand le Seigneur connut que les Pharisiens avaient appris que Jésus faisait plus de disciples et en baptisait plus que Jean,'),
('jn',4,2,'crampon1923','— toutefois ce n''était pas Jésus lui-même qui baptisait, mais ses disciples, —'),
('jn',4,3,'crampon1923','il quitta la Judée, et s''en alla de nouveau en Galilée.'),
('jn',4,4,'crampon1923','Or, il lui fallait passer par la Samarie.'),
('jn',4,5,'crampon1923','Il vint donc en une ville de Samarie, nommée Sichar, près du champ que Jacob avait donné à son fils Joseph.'),
('jn',4,6,'crampon1923','Or, là était le puits de Jacob. Jésus fatigué de la route, s''assit tout simplement au bord du puits: il était environ la sixième heure.'),
('jn',4,7,'crampon1923','Une femme de Samarie vint puiser de l''eau. Jésus lui dit: " Donnez-moi à boire. "'),
('jn',4,8,'crampon1923','Car ses disciples étaient allés à la ville pour acheter des vivres.'),
('jn',4,9,'crampon1923','La femme samaritaine lui dit: " Comment vous, qui êtes Juif, me demandez-vous à boire, à moi qui suis Samaritaine? " (les Juifs, en effet, n''ont pas de commerce avec les Samaritains).'),
('jn',4,10,'crampon1923','Jésus lui répondit: " Si vous connaissiez le don de Dieu, et qui est celui qui vous dit: Donnez-moi à boire, vous même lui en auriez fait la demande, et il vous aurait donné de l''eau vive. —'),
('jn',4,11,'crampon1923','Seigneur, lui dit la femme, vous n''avez rien pour puiser, et le puits est profond: d''où auriez-vous donc cette eau vive?'),
('jn',4,12,'crampon1923','Etes-vous plus grand que notre père Jacob, qui nous a donné ce puits, et en a bu lui-même, ainsi que ses fils et ses troupeaux? "'),
('jn',4,13,'crampon1923','Jésus lui répondit: " Quiconque boit de cette eau aura encore soif; mais celui qui boira de l''eau que je lui donnerai, n''aura plus jamais soif;'),
('jn',4,14,'crampon1923','au contraire l''eau que je lui donnerai deviendra en lui une source d''eau jaillissant jusqu''à la vie éternelle. "'),
('jn',4,15,'crampon1923','La femme lui dit: " Seigneur, donnez-moi de cette eau, afin que je n''aie plus soif, et que je ne vienne plus puiser ici. —'),
('jn',4,16,'crampon1923','Allez, lui dit Jésus, appelez votre mari, et venez ici. "'),
('jn',4,17,'crampon1923','La femme répondit: " Je n''ai point de mari. " Jésus lui dit: " Vous avez raison de dire: Je n''ai point de mari;'),
('jn',4,18,'crampon1923','car vous avez eu cinq maris, et celui que vous avez maintenant n''est pas à vous; en cela, vous avez dit vrai. "'),
('jn',4,19,'crampon1923','La femme dit: " Seigneur, je vois que vous êtes un prophète.'),
('jn',4,20,'crampon1923','Nos pères ont adoré sur cette montagne, et vous, vous dites que c''est à Jérusalem qu''est le lieu où il faut adorer. "'),
('jn',4,21,'crampon1923','Jésus dit: " Femme, croyez-moi, l''heure vient où ce ne sera ni sur cette montagne, ni dans Jérusalem, que vous adorerez le Père.'),
('jn',4,22,'crampon1923','Vous adorez ce que vous ne connaissez pas; nous, nous adorons ce que nous connaissons, car le salut vient des Juifs.'),
('jn',4,23,'crampon1923','Mais l''heure approche, et elle est déjà venue, où les vrais adorateurs adoreront le Père en esprit et en vérité; ce sont de tels adorateurs que le Père demande.'),
('jn',4,24,'crampon1923','Dieu est esprit, et ceux qui l''adorent, doivent l''adorer en esprit et en vérité. "'),
('jn',4,25,'crampon1923','La femme lui répondit: " Je sais que le Messie (celui qu''on appelle Christ) va venir; lorsqu''il sera venu, il nous instruira de toutes choses. "'),
('jn',4,26,'crampon1923','Jésus lui dit: " Je le suis, moi qui vous parle. "'),
('jn',4,27,'crampon1923','Et à ce moment arrivèrent ses disciples, et ils s''étonnèrent de ce qu''il parlait avec une femme; néanmoins, aucun ne dit: " Que demandez-vous? " ou: " Pourquoi parlez-vous avec elle? "'),
('jn',4,28,'crampon1923','La femme, alors, laissant là sa cruche, s''en alla dans la ville, et dit aux habitants:'),
('jn',4,29,'crampon1923','" Venez voir un homme qui m''a dit ce que j''ai fait; ne serait-ce point le Christ? "'),
('jn',4,30,'crampon1923','Ils sortirent de la ville, et vinrent à lui.'),
('jn',4,31,'crampon1923','Pendant l''intervalle, ses disciples le pressaient, en disant: " Maître, mangez. "'),
('jn',4,32,'crampon1923','Mais il leur dit: " J''ai à manger une nourriture que vous ne connaissez pas. "'),
('jn',4,33,'crampon1923','Et les disciples se disaient les uns aux autres: " Quelqu''un lui aurait-il apporté à manger? "'),
('jn',4,34,'crampon1923','Jésus leur dit: " Ma nourriture est de faire la volonté de celui qui m''a envoyé et d''accomplir son œuvre.'),
('jn',4,35,'crampon1923','Ne dites-vous pas vous-mêmes: Encore quatre mois, et ce sera la moisson? Moi, je vous dis: Levez les yeux, et voyez les champs qui déjà blanchissent pour la moisson.'),
('jn',4,36,'crampon1923','Le moissonneur reçoit son salaire et recueille du fruit pour la vie éternelle, afin que le semeur et le moissonneur se réjouissent ensemble.'),
('jn',4,37,'crampon1923','Car ici s''applique l''adage: Autre est le semeur et autre le moissonneur.'),
('jn',4,38,'crampon1923','Je vous ai envoyés moissonner ce que vous n''avez pas travaillé; d''autres ont travaillé et vous, vous êtes entrés dans leur travail. "'),
('jn',4,39,'crampon1923','Or, beaucoup de Samaritains de cette ville crurent en Jésus sur la parole de la femme qui avait rendu ce témoignage: " Il m''a dit tout ce que j''ai fait. "'),
('jn',4,40,'crampon1923','Les Samaritains étant donc venus vers lui, le prièrent de rester chez eux, et il y demeura deux jours.'),
('jn',4,41,'crampon1923','Et un plus grand nombre crurent en lui pour l''avoir entendu lui-même.'),
('jn',4,42,'crampon1923','Et ils disaient à la femme: " Maintenant ce n''est plus à cause de ce que vous avez dit que nous croyons; car nous l''avons entendu nous-mêmes, et nous savons qu''il est vraiment le Sauveur du monde. "'),
('jn',4,43,'crampon1923','Après ces deux jours, Jésus partit de là pour se rendre en Galilée.'),
('jn',4,44,'crampon1923','Car Jésus avait déclaré lui-même qu''un prophète n''est point honoré dans sa patrie.'),
('jn',4,45,'crampon1923','Lorsqu''il fut arrivé en Galilée, les Galiléens l''accueillirent, ayant vu tout ce qu''il avait fait à Jérusalem pendant la fête; car eux aussi étaient allés à la fête.'),
('jn',4,46,'crampon1923','Il retourna donc à Cana en Galilée, où il avait changé l''eau en vin. Or, il y avait un officier du roi dont le fils était malade à Capharnaüm.'),
('jn',4,47,'crampon1923','Ayant appris que Jésus arrivait de Judée en Galilée, il alla vers lui, et le pria de descendre, pour guérir son fils qui était à la mort.'),
('jn',4,48,'crampon1923','Jésus lui dit: " Si vous ne voyez des signes et des prodiges, vous ne croyez point. "'),
('jn',4,49,'crampon1923','L''officier du roi lui dit: " Seigneur, venez avant que mon enfant meure. —'),
('jn',4,50,'crampon1923','Va, lui répondit Jésus, ton enfant est plein de vie. " Cet homme crut à la parole que Jésus lui avait dite et partit.'),
('jn',4,51,'crampon1923','Comme il s''en retournait, ses serviteurs vinrent à sa rencontre, et lui apprirent que son enfant vivait.'),
('jn',4,52,'crampon1923','Il leur demanda à quelle heure il s''était trouvé mieux, et ils lui dirent: " Hier, à la septième heure, la fièvre l''a quitté. "'),
('jn',4,53,'crampon1923','Le père reconnut que c''était l''heure à laquelle Jésus lui avait dit: " Ton fils est plein de vie ", et il crut, lui et toute sa maison.'),
('jn',4,54,'crampon1923','Ce fut le second miracle que fit Jésus en revenant de Judée en Galilée.'),
('jn',5,1,'crampon1923','Après cela, il y eut une fête des Juifs, et Jésus monta à Jérusalem.'),
('jn',5,2,'crampon1923','Or, à Jérusalem, près de la porte des Brebis, il y a une piscine qui s''appelle en hébreu Béthesda, et qui a cinq portiques.'),
('jn',5,3,'crampon1923','Sous ces portiques étaient couchés un grand nombre de malades, d''aveugles, de boiteux et de paralytiques; [ils attendaient le bouillonnement de l''eau.'),
('jn',5,4,'crampon1923','Car un ange du Seigneur descendait à certains temps dans la piscine, et agitait l''eau: et celui qui y descendait le premier après l''agitation de l''eau, était guéri de son infirmité quelle qu''elle fût.]'),
('jn',5,5,'crampon1923','Là se trouvait un homme malade depuis trente-huit ans.'),
('jn',5,6,'crampon1923','Jésus l''ayant vu gisant, et sachant qu''il était malade depuis longtemps, lui dit: " Veux-tu être guéri? "'),
('jn',5,7,'crampon1923','Le malade lui répondit: " Seigneur, je n''ai personne pour me jeter dans la piscine dès que l''eau est agitée, et pendant que j''y vais, un autre descend avant moi. "'),
('jn',5,8,'crampon1923','Jésus lui dit: " Lève-toi, prends ton grabat et marche. "'),
('jn',5,9,'crampon1923','Et à l''instant cet homme fut guéri; il prit son grabat et se mit à marcher. C''était un jour de sabbat.'),
('jn',5,10,'crampon1923','Les Juifs dirent donc à celui qui avait été guéri: " C''est le sabbat, il ne t''est pas permis d''emporter ton grabat. "'),
('jn',5,11,'crampon1923','Il leur répondit: " Celui qui m''a guéri m''a dit: Prends ton grabat et marche. "'),
('jn',5,12,'crampon1923','Ils lui demandèrent: " Qui est l''homme qui t''a dit: Prends ton grabat et marche? "'),
('jn',5,13,'crampon1923','Mais celui qui avait été guéri ne savait pas qui c''était; car Jésus s''était esquivé, grâce à la foule qui était en cet endroit.'),
('jn',5,14,'crampon1923','Plus tard, Jésus le trouva dans le temple et lui dit: " Te voilà guéri; ne pèche plus, de peur qu''il ne t''arrive quelque chose de pire. "'),
('jn',5,15,'crampon1923','Cet homme s''en alla, et annonça aux Juifs que c''était Jésus qui l''avait guéri.'),
('jn',5,16,'crampon1923','C''est pourquoi les Juifs persécutaient Jésus, parce qu''il faisait ces choses le jour du sabbat.'),
('jn',5,17,'crampon1923','Mais Jésus leur dit: " Mon Père agit jusqu''à présent, et moi aussi j''agis. "'),
('jn',5,18,'crampon1923','Sur quoi, les Juifs cherchaient encore avec plus d''ardeur à le faire mourir, parce que, non content de violer le sabbat, il disait encore que Dieu était son père, se faisant égal à Dieu. Jésus reprit donc la parole et leur dit:'),
('jn',5,19,'crampon1923','" En vérité, en vérité, je vous le dis, le Fils ne peut rien faire de lui-même, mais seulement ce qu''il voit faire au Père; et tout ce que fait le Père, le Fils aussi le fait pareillement.'),
('jn',5,20,'crampon1923','Car le Père aime le Fils, et lui montre tout ce qu''il fait; et il lui montrera des œuvres plus grandes que celles-ci, qui vous jetteront dans l''étonnement.'),
('jn',5,21,'crampon1923','Car, comme le Père ressuscite les morts et donne la vie, aussi le Fils donne la vie à qui il veut.'),
('jn',5,22,'crampon1923','Le Père même ne juge personne, mais il a donné au Fils le jugement tout entier,'),
('jn',5,23,'crampon1923','afin que tous honorent le Fils comme ils honorent le Père. Celui qui n''honore pas le Fils n''honore pas le Père qui l''a envoyé.'),
('jn',5,24,'crampon1923','En vérité, en vérité, je vous le dis, celui qui écoute ma parole et croit à celui qui m''a envoyé a la vie éternelle, et n''encourt point la condamnation, mais il est passé de la mort à la vie.'),
('jn',5,25,'crampon1923','En vérité, en vérité, je vous le dis, l''heure vient, et elle est déjà venue, où les morts entendront la voix du Fils de Dieu, et ceux qui l''auront entendue vivront.'),
('jn',5,26,'crampon1923','Car, comme le Père a la vie en lui-même, ainsi il a donné au Fils d''avoir la vie en lui-même;'),
('jn',5,27,'crampon1923','et il lui a aussi donné le pouvoir de juger, parce qu''il est Fils de l''homme.'),
('jn',5,28,'crampon1923','Ne vous en étonnez pas; car l''heure vient où tous ceux qui sont dans les sépulcres entendront sa voix.'),
('jn',5,29,'crampon1923','Et ils en sortiront, ceux qui auront fait le bien, pour une résurrection de vie; ceux qui auront fait le mal, pour une résurrection de condamnation.'),
('jn',5,30,'crampon1923','Je ne puis rien faire de moi-même. Selon que j''entends, je juge; et mon jugement est juste, parce que je ne cherche pas ma propre volonté, mais la volonté de celui qui m''a envoyé.'),
('jn',5,31,'crampon1923','Si c''est moi qui rends témoignage de moi-même, mon témoignage n''est pas véridique.'),
('jn',5,32,'crampon1923','Il y en a un autre qui rend témoignage de moi, et je sais que le témoignage qu''il rend de moi est véridique.'),
('jn',5,33,'crampon1923','Vous avez envoyé vers Jean, et il a rendu témoignage à la vérité.'),
('jn',5,34,'crampon1923','Pour moi, ce n''est pas d''un homme que je reçois le témoignage; mais je dis cela afin que vous soyez sauvés.'),
('jn',5,35,'crampon1923','Jean était la lampe qui brûle et luit, mais vous n''avez voulu que vous réjouir un moment à sa lumière.'),
('jn',5,36,'crampon1923','Pour moi, j''ai un témoignage plus grand que celui de Jean; car les œuvres que le Père m''a donné d''accomplir, ces œuvres mêmes que je fais, rendent témoignage de moi, que c''est le Père qui m''a envoyé.'),
('jn',5,37,'crampon1923','Et le Père qui m''a envoyé a rendu lui-même témoignage de moi. Vous n''avez jamais entendu sa voix, ni vu sa face,'),
('jn',5,38,'crampon1923','et vous n''avez point sa parole demeurant en vous, parce que vous ne croyez pas à celui qu''il a envoyé.'),
('jn',5,39,'crampon1923','Vous scrutez les Écritures, parce que vous pensez trouver en elles la vie éternelle;'),
('jn',5,40,'crampon1923','or, ce sont elles qui rendent témoignage de moi; et vous ne voulez pas venir à moi pour avoir la vie.'),
('jn',5,41,'crampon1923','Ce n''est point que je demande ma gloire aux hommes;'),
('jn',5,42,'crampon1923','mais je vous connais, je sais que vous n''avez pas en vous l''amour de Dieu.'),
('jn',5,43,'crampon1923','Je suis venu au nom de mon Père, et vous ne me recevez pas; qu''un autre vienne en son propre nom, vous le recevrez.'),
('jn',5,44,'crampon1923','Comment pouvez-vous croire, vous qui tirez votre gloire les uns des autres, et qui ne recherchez pas la gloire qui vient de Dieu seul?'),
('jn',5,45,'crampon1923','Ne pensez pas que ce soit moi qui vous accuserai devant le Père; votre accusateur, c''est Moïse, en qui vous avez mis votre espérance.'),
('jn',5,46,'crampon1923','Car si vous croyiez Moïse, vous me croiriez aussi, parce qu''il a écrit de moi.'),
('jn',5,47,'crampon1923','Mais si vous ne croyez pas à ses écrits, comment croirez-vous à mes paroles? "'),
('jn',6,1,'crampon1923','Jésus s''en alla ensuite de l''autre côté de la mer de Galilée ou de Tibériade.'),
('jn',6,2,'crampon1923','Et une foule nombreuse le suivait, parce qu''elle voyait les miracles qu''il opérait sur ceux qui étaient malades.'),
('jn',6,3,'crampon1923','Jésus monta sur la montagne, et là il s''assit avec ses disciples.'),
('jn',6,4,'crampon1923','Or la Pâque, la fête des Juifs, était proche.'),
('jn',6,5,'crampon1923','Jésus donc ayant levé les yeux, et voyant qu''une grande foule venait à lui, dit à Philippe: " Où achèterons-nous du pain pour que ces gens aient à manger? "'),
('jn',6,6,'crampon1923','Il disait cela pour l''éprouver, car lui, il savait ce qu''il devait faire.'),
('jn',6,7,'crampon1923','Philippe lui répondit: " Deux cents deniers de pain ne suffiraient pas pour que chacun en reçoive un morceau. "'),
('jn',6,8,'crampon1923','Un de ses disciples, André, frère de Simon-Pierre, lui dit:'),
('jn',6,9,'crampon1923','" Il y a ici un jeune homme qui a cinq pains d''orge et deux poissons; mais qu''est-ce que cela pour tant de monde? "'),
('jn',6,10,'crampon1923','Jésus dit: " Faites les asseoir. " Il y avait beaucoup d''herbe en ce lieu. Ils s''assirent donc, au nombre d''environ cinq mille.'),
('jn',6,11,'crampon1923','Jésus prit les pains, et ayant rendu grâces, il les distribua à ceux qui étaient assis; il leur donna de même des deux poissons, autant qu''ils en voulurent.'),
('jn',6,12,'crampon1923','Lorsqu''ils furent rassasiés, il dit à ses disciples: " Recueillez les morceaux qui restent, afin que rien ne se perde. "'),
('jn',6,13,'crampon1923','Ils les recueillirent, et remplirent douze corbeilles des morceaux qui étaient restés des cinq pains d''orge, après qu''ils eurent mangé.'),
('jn',6,14,'crampon1923','Ces hommes ayant vu le miracle que Jésus avait fait, disaient: " Celui-ci est vraiment le Prophète qui doit venir dans le monde. "'),
('jn',6,15,'crampon1923','Sachant donc qu''ils allaient venir l''enlever pour le faire roi, Jésus se retira de nouveau, seul, sur la montagne.'),
('jn',6,16,'crampon1923','Le soir venu, les disciples descendirent au bord de la mer;'),
('jn',6,17,'crampon1923','et étant montés dans une barque, ils traversaient la mer dans la direction de Capharnaüm. Il faisait déjà nuit, et Jésus ne les avait pas encore rejoints.'),
('jn',6,18,'crampon1923','Cependant la mer, soulevée par un grand vent, était agitée.'),
('jn',6,19,'crampon1923','Quand ils eurent ramé environ vingt-cinq à trente stades, ils virent Jésus marchant sur la mer et s''approchant de la barque; et ils eurent peur.'),
('jn',6,20,'crampon1923','Mais il leur dit: " C''est moi, ne craignez point. "'),
('jn',6,21,'crampon1923','Ils voulurent donc le prendre dans la barque, et aussitôt, la barque se trouva au lieu où ils allaient.'),
('jn',6,22,'crampon1923','Le jour suivant, la foule qui était restée de l''autre côté de la mer, avait remarqué qu''il n''y avait là qu''une seule barque, et que Jésus n''y était point entré avec ses disciples, mais que ceux-ci étaient partis seuls.'),
('jn',6,23,'crampon1923','— D''autres barques, cependant, étaient arrivées de Tibériade près du lieu où le Seigneur, après avoir rendu grâces, leur avait donné à manger. —'),
('jn',6,24,'crampon1923','La foule donc, ayant vu que Jésus n''était pas là, ni ses disciples non plus, entra dans ces barques et se rendit à Capharnaüm pour chercher Jésus.'),
('jn',6,25,'crampon1923','Et l''ayant trouvé de l''autre côté de la mer ils lui dirent: " Maître, quand êtes-vous venu ici? "'),
('jn',6,26,'crampon1923','Jésus leur repartit et leur dit: " En vérité, en vérité je vous le dis, vous me cherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains et que vous avez été rassasiés.'),
('jn',6,27,'crampon1923','Travaillez, non pour la nourriture qui périt, mais pour celle qui demeure pour la vie éternelle, et que le Fils de l''homme vous donnera. Car c''est lui que le Père, Dieu, a marqué d''un sceau. "'),
('jn',6,28,'crampon1923','Ils lui dirent: " Que devons-nous faire, pour faire les œuvres de Dieu? "'),
('jn',6,29,'crampon1923','Jésus leur répondit: " Voici l''œuvre que Dieu demande, c''est que vous croyiez en celui qu''il a envoyé. "'),
('jn',6,30,'crampon1923','Ils lui dirent: " Quel miracle faites-vous donc afin que nous le voyions et que nous croyions en vous? Quelles sont vos œuvres?'),
('jn',6,31,'crampon1923','Nos pères ont mangé la manne dans le désert, ainsi qu''il est écrit: Il leur a donné à manger le pain du ciel. "'),
('jn',6,32,'crampon1923','Jésus leur répondit: " En vérité, en vérité, je vous le dis, Moïse ne vous a pas donné le pain du ciel; c''est mon Père qui donne le vrai pain du ciel.'),
('jn',6,33,'crampon1923','Car le pain de Dieu, c''est le pain qui descend du ciel et qui donne la vie au monde. "'),
('jn',6,34,'crampon1923','Ils lui dirent donc: " Seigneur, donnez-nous toujours de ce pain. "'),
('jn',6,35,'crampon1923','Jésus leur répondit: " Je suis le pain de vie: celui qui vient à moi n''aura jamais faim, et celui qui croit en moi n''aura jamais soif.'),
('jn',6,36,'crampon1923','Mais, je vous l''ai dit, vous m''avez vu, et vous ne croyez point.'),
('jn',6,37,'crampon1923','Tout ce que le Père me donne viendra à moi, et celui qui vient à moi, je ne le jetterai point dehors;'),
('jn',6,38,'crampon1923','car je suis descendu du ciel pour faire, non ma volonté, mais la volonté de celui qui m''a envoyé.'),
('jn',6,39,'crampon1923','Or la volonté de celui qui m''a envoyé, est que je ne perde aucun de ceux qu''il m''a donnés, mais que je les ressuscite au dernier jour.'),
('jn',6,40,'crampon1923','Car c''est la volonté de mon Père [qui m''a envoyé], que quiconque voit le Fils et croit en lui, ait la vie éternelle; et moi je le ressusciterai au dernier jour. "'),
('jn',6,41,'crampon1923','Les Juifs murmuraient à son sujet, parce qu''il avait dit: " Je suis le pain vivant, qui est descendu du ciel. "'),
('jn',6,42,'crampon1923','Et ils disaient: " N''est-ce pas là Jésus, le fils de Joseph, dont nous connaissons le père et la mère? Comment donc dit-il: Je suis descendu du ciel? "'),
('jn',6,43,'crampon1923','Jésus leur répondit: " Ne murmurez point entre vous.'),
('jn',6,44,'crampon1923','Nul ne peut venir à moi, si le Père qui m''a envoyé ne l''attire; et moi, je le ressusciterai au dernier jour.'),
('jn',6,45,'crampon1923','Il est écrit dans les Prophètes: Ils seront tous enseignés par Dieu. Quiconque a entendu le Père et a reçu son enseignement, vient à moi.'),
('jn',6,46,'crampon1923','Ce n''est pas que personne ait vu le Père, sinon celui qui est de Dieu; celui-là a vu le Père.'),
('jn',6,47,'crampon1923','En vérité, en vérité, je vous le dis, celui qui croit en moi a la vie éternelle.'),
('jn',6,48,'crampon1923','Je suis le pain de vie.'),
('jn',6,49,'crampon1923','Vos pères ont mangé la manne dans le désert, et ils sont morts.'),
('jn',6,50,'crampon1923','Voici le pain descendu du ciel, afin qu''on en mange et qu''on ne meure point.'),
('jn',6,51,'crampon1923','Je suis le pain vivant qui est descendu du ciel. Si quelqu''un mange de ce pain, il vivra éternellement; et le pain que je donnerai, c''est ma chair, pour le salut du monde. "'),
('jn',6,52,'crampon1923','Là-dessus, les Juifs disputaient entre eux, disant: " Comment cet homme peut-il donner sa chair à manger? "'),
('jn',6,53,'crampon1923','Jésus leur dit: " En vérité, en vérité, je vous le dis, si vous ne mangez la chair du Fils de l''homme, et ne buvez son sang, vous n''avez point la vie en vous-mêmes.'),
('jn',6,54,'crampon1923','Celui qui mange ma chair et boit mon sang a la vie éternelle, et moi, je le ressusciterai au dernier jour.'),
('jn',6,55,'crampon1923','Car ma chair est vraiment une nourriture, et mon sang est vraiment un breuvage.'),
('jn',6,56,'crampon1923','Celui qui mange ma chair et boit mon sang, demeure en moi, et moi en lui.'),
('jn',6,57,'crampon1923','Comme le Père qui est vivant m''a envoyé, et que je vis par le Père, ainsi celui qui me mange vivra aussi par moi.'),
('jn',6,58,'crampon1923','C''est là le pain qui est descendu du ciel: il n''en est point comme de vos pères qui ont mangé la manne et sont morts; celui qui mange de ce pain vivra éternellement. "'),
('jn',6,59,'crampon1923','Jésus dit ces choses, enseignant dans la synagogue à Capharnaüm.'),
('jn',6,60,'crampon1923','Beaucoup de ses disciples, l''ayant entendu, dirent: " Cette parole est dure, et qui peut l''écouter? "'),
('jn',6,61,'crampon1923','Jésus, sachant en lui-même que ses disciples murmuraient à ce sujet, leur dit: " Cela vous scandalise?'),
('jn',6,62,'crampon1923','Et quand vous verrez le Fils de l''homme monter où il était auparavant?...'),
('jn',6,63,'crampon1923','C''est l''esprit qui vivifie; la chair ne sert de rien. Les paroles que je vous ai dites sont esprit et vie.'),
('jn',6,64,'crampon1923','Mais il y en a parmi vous quelques-uns qui ne croient point. " Car Jésus savait, dès le commencement, qui étaient ceux qui ne croyaient point, et qui était celui qui le trahirait.'),
('jn',6,65,'crampon1923','Et il ajouta: " C''est pourquoi je vous ai dit que nul ne peut venir à moi, si cela ne lui a été donné par mon Père. "'),
('jn',6,66,'crampon1923','Dès ce moment, beaucoup de ses disciples se retirèrent, et ils n''allaient plus avec lui.'),
('jn',6,67,'crampon1923','Jésus donc dit aux Douze: " Et vous, ne voulez-vous pas aussi vous en aller? "'),
('jn',6,68,'crampon1923','Simon-Pierre lui répondit: " Seigneur, à qui irions-nous? Vous avez les paroles de la vie éternelle.'),
('jn',6,69,'crampon1923','Et nous, nous avons cru et nous avons connu que vous êtes le Saint de Dieu. "'),
('jn',6,70,'crampon1923','Jésus leur répondit: " N''est-ce pas moi qui vous ai choisis, vous les Douze? Et l''un de vous est un démon. "'),
('jn',6,71,'crampon1923','Il parlait de Judas, fils de Simon Iscariote, car c''était lui qui devait le trahir, lui, l''un des Douze.'),
('jn',7,1,'crampon1923','Après cela, Jésus parcourut la Galilée, ne voulant pas aller en Judée, parce que les Juifs cherchaient à le faire mourir.'),
('jn',7,2,'crampon1923','Or, la fête des Juifs, celle des Tabernacles, était proche.'),
('jn',7,3,'crampon1923','Ses frères lui dirent donc: " Partez d''ici, et allez en Judée, afin que vos disciples aussi voient les œuvres que vous faites;'),
('jn',7,4,'crampon1923','car personne ne fait une chose en secret, lorsqu''il désire qu''elle paraisse. Si vous faites ces choses, montrez-vous au monde. "'),
('jn',7,5,'crampon1923','Car ses frères mêmes ne croyaient pas en lui.'),
('jn',7,6,'crampon1923','Jésus leur dit: " Mon temps n''est pas encore venu; mais votre temps à vous est toujours prêt.'),
('jn',7,7,'crampon1923','Le monde ne saurait vous haïr; moi, il me hait, parce que je rends de lui ce témoignage, que ses œuvres sont mauvaises.'),
('jn',7,8,'crampon1923','Montez, vous, à cette fête; pour moi, je n''y vais point, parce que mon temps n''est pas encore venu. "'),
('jn',7,9,'crampon1923','Après avoir dit cela, il resta en Galilée.'),
('jn',7,10,'crampon1923','Mais lorsque ses frères furent partis, lui-même monta aussi à la fête, non publiquement, mais en secret.'),
('jn',7,11,'crampon1923','Les Juifs donc le cherchaient durant la fête, et disaient: " Où est-il? "'),
('jn',7,12,'crampon1923','Et il y avait dans la foule une grande rumeur à son sujet. Les uns disaient: " C''est un homme de bien. — Non, disaient les autres, il trompe le peuple. "'),
('jn',7,13,'crampon1923','Cependant personne ne s''exprimait librement sur son compte, par crainte des Juifs.'),
('jn',7,14,'crampon1923','On était déjà au milieu de la fête, lorsque Jésus monta au temple, et il se mit à enseigner.'),
('jn',7,15,'crampon1923','Les Juifs étonnés disaient: " Comment connaît-il les Écritures, lui qui n''a point fréquenté les écoles? "'),
('jn',7,16,'crampon1923','Jésus leur répondit: " Ma doctrine n''est pas de moi, mais de celui qui m''a envoyé.'),
('jn',7,17,'crampon1923','Si quelqu''un veut faire la volonté de Dieu, il saura si ma doctrine est de Dieu, ou si je parle de moi-même.'),
('jn',7,18,'crampon1923','Celui qui parle de soi-même, cherche sa propre gloire; mais celui qui cherche la gloire de celui qui l''a envoyé, est véridique, et il n''y a point en lui d''imposture.'),
('jn',7,19,'crampon1923','Est-ce que Moïse ne vous a point donné la Loi? Et nul de vous n''accomplit la loi.'),
('jn',7,20,'crampon1923','Pourquoi cherchez-vous à me faire mourir? " La foule répondit: " Vous êtes possédé du démon; qui est-ce qui cherche à vous faire mourir? "'),
('jn',7,21,'crampon1923','Jésus leur dit: " J''ai fait une seule œuvre, et vous voilà tous hors de vous-mêmes?'),
('jn',7,22,'crampon1923','Moïse vous a donné la circoncision (non qu''elle vienne de Moïse, mais des Patriarches), et vous la pratiquez le jour du sabbat.'),
('jn',7,23,'crampon1923','Que si, pour ne pas violer la loi de Moïse, on circoncit le jour du sabbat, comment vous indignez-vous contre moi, parce que, le jour du sabbat, j''ai guéri un homme dans tout son corps?'),
('jn',7,24,'crampon1923','Ne jugez point sur l''apparence, mais jugez selon la justice. "'),
('jn',7,25,'crampon1923','Alors quelques habitants de Jérusalem dirent: " N''est-ce pas là celui qu''ils cherchent à faire mourir?'),
('jn',7,26,'crampon1923','Et le voilà qui parle publiquement sans qu''on lui dise rien. Est-ce que vraiment les chefs du peuple auraient reconnu qu''il est le Christ?'),
('jn',7,27,'crampon1923','Celui-ci, néanmoins, nous savons d''où il est; mais quand le Christ viendra, personne ne saura d''où il est. "'),
('jn',7,28,'crampon1923','Jésus, enseignant dans le temple, dit donc à haute voix: " Vous me connaissez et vous savez d''où je suis!... et pourtant ce n''est pas de moi-même que je suis venu: mais celui qui m''a envoyé est vrai: vous ne le connaissez point;'),
('jn',7,29,'crampon1923','moi, je le connais, parce que je suis de lui, et c''est lui qui m''a envoyé. "'),
('jn',7,30,'crampon1923','Ils cherchèrent donc à le saisir; et personne ne mit la main sur lui, parce que son heure n''était pas encore venue.'),
('jn',7,31,'crampon1923','Mais beaucoup, parmi le peuple, crurent en lui, et ils disaient: " Quand le Christ viendra, fera-t-il plus de miracles que n''en a fait celui-ci? "'),
('jn',7,32,'crampon1923','Les Pharisiens entendirent la foule murmurant ces choses au sujet de Jésus; alors les Princes des prêtres et les Pharisiens envoyèrent des satellites pour l''arrêter.'),
('jn',7,33,'crampon1923','Jésus dit: " Je suis encore avec vous un peu de temps, puis je m''en vais à celui qui m''a envoyé.'),
('jn',7,34,'crampon1923','Vous me chercherez, et vous ne me trouverez point, et où je suis vous ne pouvez venir. "'),
('jn',7,35,'crampon1923','Sur quoi les Juifs se dirent entre eux: " Où donc ira-t-il, que nous ne le trouverons point? Ira-t-il vers ceux qui sont dispersés parmi les Gentils, et ira-t-il les instruire?'),
('jn',7,36,'crampon1923','Que signifie cette parole qu''il a dite: Vous me chercherez et vous ne me trouverez point, et où je suis, vous ne pouvez venir? "'),
('jn',7,37,'crampon1923','Le dernier jour de la fête, qui en est le jour le plus solennel, Jésus debout, dit à haute voix: " Si quelqu''un a soif, qu''il vienne à moi, et qu''il boive.'),
('jn',7,38,'crampon1923','Celui qui croit en moi, de son sein, comme dit l''Ecriture, couleront des fleuves d''eau vive. "'),
('jn',7,39,'crampon1923','Il disait cela de l''Esprit que devaient recevoir ceux qui croient en lui; car l''Esprit n''était pas encore donné, parce que Jésus n''avait pas encore été glorifié.'),
('jn',7,40,'crampon1923','Parmi la foule, quelques-uns, qui avaient entendu ces paroles, disaient: " C''est vraiment le prophète. "'),
('jn',7,41,'crampon1923','D''autres: " C''est le Christ. — Mais, disaient les autres, est-ce de la Galilée que doit venir le Christ?'),
('jn',7,42,'crampon1923','L''Écriture ne dit-elle pas que c''est de la race de David, et du bourg de Bethléem, où était David, que le Christ doit venir? "'),
('jn',7,43,'crampon1923','C''est ainsi que le peuple était partagé à son sujet.'),
('jn',7,44,'crampon1923','Quelques-uns voulaient l''arrêter; mais personne ne mit la main sur lui.'),
('jn',7,45,'crampon1923','Les satellites étant donc revenus vers les Pontifes et les Pharisiens, ceux-ci leur dirent: " Pourquoi ne l''avez-vous pas amené? "'),
('jn',7,46,'crampon1923','Les satellites répondirent: " Jamais homme n''a parlé comme cet homme. "'),
('jn',7,47,'crampon1923','Les Pharisiens leur répliquèrent: " Vous aussi, vous êtes-vous laissés séduire?'),
('jn',7,48,'crampon1923','Y a-t-il quelqu''un parmi les Princes du peuple qui ait cru en lui? Y en a-t-il parmi les Pharisiens?'),
('jn',7,49,'crampon1923','Mais cette populace qui ne connaît pas la Loi, ce sont des maudits! "'),
('jn',7,50,'crampon1923','Nicodème, l''un d''eux, celui qui était venu de nuit à Jésus, leur dit:'),
('jn',7,51,'crampon1923','" Notre loi condamne-t-elle un homme sans qu''on l''ait d''abord entendu, et sans qu''on sache ce qu''il a fait? "'),
('jn',7,52,'crampon1923','Ils lui répondirent: " Toi aussi, es-tu Galiléen? Examine avec soin les Écritures, et tu verras qu''il ne sort point de prophète de la Galilée. "'),
('jn',7,53,'crampon1923','Et ils s''en retournèrent chacun dans sa maison.'),
('jn',8,1,'crampon1923','Jésus s''en alla sur la montagne des Oliviers;'),
('jn',8,2,'crampon1923','mais, dès le point du jour, il retourna dans le temple, et tout le peuple vint à lui. Et s''étant assis, il les enseignait.'),
('jn',8,3,'crampon1923','Alors les Scribes et les Pharisiens lui amenèrent une femme surprise en adultère, et l''ayant fait avancer,'),
('jn',8,4,'crampon1923','ils dirent à Jésus: " Maître, cette femme a été surprise en flagrant délit d''adultère.'),
('jn',8,5,'crampon1923','Or Moïse, dans la Loi, nous a ordonné de lapider de telles personnes. Vous donc, que dites-vous? "'),
('jn',8,6,'crampon1923','C''était pour l''éprouver qu''ils l''interrogeaient ainsi, afin de pouvoir l''accuser. Mais Jésus, s''étant baissé, écrivait sur la terre avec le doigt.'),
('jn',8,7,'crampon1923','Comme ils continuaient à l''interroger, il se releva et leur dit: " Que celui de vous qui est sans péché lui jette la première pierre. "'),
('jn',8,8,'crampon1923','Et s''étant baissé de nouveau, il écrivait sur la terre.'),
('jn',8,9,'crampon1923','Ayant entendu cette parole, [et se sentant repris par leur conscience,] ils se retirèrent les uns après les autres, les plus âgés d''abord, [puis tous les autres,] de sorte que Jésus resta seul avec la femme qui était au milieu.'),
('jn',8,10,'crampon1923','Alors Jésus s''étant relevé, et ne voyant plus que la femme, lui dit: " Femme, où sont ceux qui vous accusaient? Est-ce que personne ne vous a condamnée? "'),
('jn',8,11,'crampon1923','Elle répondit: " Personne, Seigneur "; Jésus lui dit: " Je ne vous condamne pas non plus. Allez, et ne péchez plus. "'),
('jn',8,12,'crampon1923','Jésus leur parla de nouveau, disant: " Je suis la lumière du monde. Celui qui me suit ne marchera pas dans les ténèbres, mais il aura la lumière de la vie. "'),
('jn',8,13,'crampon1923','Sur quoi les Pharisiens lui dirent: " Vous rendez témoignage de vous-même; votre témoignage n''est pas digne de foi. "'),
('jn',8,14,'crampon1923','Jésus leur répondit: " Quoique je rende témoignage de moi-même, mon témoignage est véridique, parce que je sais d''où je suis venu et où je vais; mais vous, vous ne savez d''où je viens, ni ou je vais.'),
('jn',8,15,'crampon1923','Vous jugez selon la chair; moi je ne juge personne.'),
('jn',8,16,'crampon1923','Et si je juge, mon jugement est véridique, car je ne suis pas seul, mais moi, et le Père qui m''a envoyé.'),
('jn',8,17,'crampon1923','Il est écrit dans votre Loi, que le témoignage de deux hommes est digne de foi.'),
('jn',8,18,'crampon1923','Or, je rends témoignage de moi-même, et le Père qui m''a envoyé rend aussi témoignage de moi. "'),
('jn',8,19,'crampon1923','Ils lui dirent donc: " Où est votre Père? " Jésus répondit: " Vous ne connaissez ni moi, ni mon Père: si vous me connaissiez, vous connaîtriez aussi mon Père. "'),
('jn',8,20,'crampon1923','Jésus parla de la sorte dans le parvis du Trésor, lorsqu''il enseignait dans le temple; et personne ne mit la main sur lui, parce que son heure n''était pas encore venue.'),
('jn',8,21,'crampon1923','Jésus leur dit encore: " Je m''en vais, et vous me chercherez, et vous mourrez dans votre péché. Où je vais, vous ne pouvez venir. "'),
('jn',8,22,'crampon1923','Les Juifs disaient donc: " Est-ce qu''il va se tuer lui-même, puisqu''il dit: Où je vais, vous ne pouvez venir? "'),
('jn',8,23,'crampon1923','Et il leur dit: " Vous, vous êtes d''en bas, moi, je suis d''en haut; vous êtes de ce monde, moi, je ne suis pas de ce monde.'),
('jn',8,24,'crampon1923','C''est pourquoi je vous ai dit que vous mourrez dans votre péché; car si vous ne croyez pas que je suis le Messie, vous mourrez dans votre péché. " —'),
('jn',8,25,'crampon1923','" Qui êtes-vous? " lui dirent-ils. Jésus leur répondit: " Absolument ce que je vous déclare.'),
('jn',8,26,'crampon1923','J''ai beaucoup de choses à dire de vous et à condamner en vous, mais celui qui m''a envoyé est véridique, et ce que j''ai entendu de lui, je le dis au monde. "'),
('jn',8,27,'crampon1923','Ils ne comprirent point qu''il leur parlait du Père.'),
('jn',8,28,'crampon1923','Jésus donc leur dit: " Lorsque vous aurez élevé le Fils de l''homme, alors vous connaîtrez qui je suis, et que je ne fais rien de moi-même, mais que je dis ce que mon Père m''a enseigné.'),
('jn',8,29,'crampon1923','Et celui qui m''a envoyé est avec moi, et il ne m''a pas laissé seul, parce que je fais toujours ce qui lui plaît. " —'),
('jn',8,30,'crampon1923','Comme il disait ces choses, beaucoup crurent en lui.'),
('jn',8,31,'crampon1923','Jésus dit donc aux Juifs qui avaient cru en lui: " Si vous demeurez dans ma parole, vous êtes vraiment mes disciples;'),
('jn',8,32,'crampon1923','vous connaîtrez la vérité, et la vérité vous rendra libres. "'),
('jn',8,33,'crampon1923','Il lui répondirent: " Nous sommes la race d''Abraham, et nous n''avons jamais été esclaves de personne; comment dites-vous: Vous deviendrez libres? "'),
('jn',8,34,'crampon1923','Jésus leur répondit: " En vérité, en vérité, je vous le dis, quiconque se livre au péché est esclave du péché.'),
('jn',8,35,'crampon1923','Or, l''esclave ne demeure pas toujours dans la maison; mais le fils y demeure toujours.'),
('jn',8,36,'crampon1923','Si donc le Fils vous affranchit, vous serez vraiment libres.'),
('jn',8,37,'crampon1923','Je sais que vous êtes enfants d''Abraham; mais vous cherchez à me faire mourir, parce que ma parole ne pénètre pas en vous.'),
('jn',8,38,'crampon1923','Moi je vous dis ce que j''ai vu chez mon Père; et vous, vous faites ce que vous avez vu chez votre père. "'),
('jn',8,39,'crampon1923','Ils lui répondirent: " Notre père, c''est Abraham. " Jésus leur dit: " Si vous étiez enfants d''Abraham, vous feriez les œuvres d''Abraham.'),
('jn',8,40,'crampon1923','Mais maintenant vous cherchez à me faire mourir, moi qui vous ai dit la vérité que j''ai entendue de Dieu: ce n''est point ce qu''a fait Abraham.'),
('jn',8,41,'crampon1923','Vous faites les œuvres de votre père. " Ils lui dirent: " Nous ne sommes pas des enfants de fornication; nous avons un seul Père, qui est Dieu. "'),
('jn',8,42,'crampon1923','Jésus leur dit: " Si Dieu était votre Père, vous m''aimeriez, car c''est de Dieu que je suis sorti et que je viens; et je ne suis pas venu de moi-même, mais c''est lui qui m''a envoyé.'),
('jn',8,43,'crampon1923','Pourquoi ne reconnaissez-vous pas mon langage? Parce que vous ne pouvez entendre ma parole.'),
('jn',8,44,'crampon1923','Le père dont vous êtes issus, c''est le diable, et vous voulez accomplir les désirs de votre père. Il a été homicide dès le commencement, et n''est point demeuré dans la vérité, parce qu''il n''y a point de vérité en lui. Lorsqu''il profère le mensonge, il parle de son propre fonds; car il est menteur, et le père du mensonge.'),
('jn',8,45,'crampon1923','Et moi, parce que je vous dis la vérité, vous ne me croyez pas.'),
('jn',8,46,'crampon1923','Qui de vous me convaincra de péché? Si je dis la vérité, pourquoi ne me croyez-vous pas?'),
('jn',8,47,'crampon1923','Celui qui est de Dieu entend la parole de Dieu; c''est parce que vous n''êtes pas de Dieu que vous ne l''entendez pas. "'),
('jn',8,48,'crampon1923','Les Juifs lui répondirent: " N''avons-nous pas raison de dire que vous êtes un Samaritain et que vous êtes possédé d''un démon? "'),
('jn',8,49,'crampon1923','Jésus répondit: " Il n''y a point en moi de démon; mais j''honore mon Père, et vous, vous m''outragez.'),
('jn',8,50,'crampon1923','Pour moi, je n''ai pas souci de ma gloire: il est quelqu''un qui en prend soin et qui fera justice.'),
('jn',8,51,'crampon1923','En vérité, en vérité, je vous le dis, si quelqu''un garde ma parole, il ne verra jamais la mort. "'),
('jn',8,52,'crampon1923','Les Juifs lui dirent: " Nous voyons maintenant qu''un démon est en vous. Abraham est mort, les prophètes aussi, et vous, vous dites: Si quelqu''un garde ma parole, il ne verra jamais la mort.'),
('jn',8,53,'crampon1923','Etes-vous plus grand que notre père Abraham, qui est mort? Les Prophètes aussi sont morts; qui prétendez-vous être? "'),
('jn',8,54,'crampon1923','Jésus répondit: " Si je me glorifie moi-même, ma gloire n''est rien; c''est mon Père qui me glorifie, lui dont vous dites qu''il est votre Dieu;'),
('jn',8,55,'crampon1923','et pourtant vous ne le connaissez pas; mais moi, je le connais; et si je disais que je ne le connais pas, je serais menteur comme vous. Mais je le connais et je garde sa parole.'),
('jn',8,56,'crampon1923','Abraham votre père, a tressailli de joie de ce qu''il devait voir mon jour; il l''a vu, et il s''est réjoui. "'),
('jn',8,57,'crampon1923','Les Juifs lui dirent: " Vous n''avez pas encore cinquante ans, et vous avez vu Abraham! "'),
('jn',8,58,'crampon1923','Jésus leur répondit: " En vérité, en vérité, je vous le dis, avant qu''Abraham fût, je suis. "'),
('jn',8,59,'crampon1923','Alors ils prirent des pierres pour les lui jeter; mais Jésus se cacha, et sortit du temple.'),
('jn',9,1,'crampon1923','Jésus vit, en passant, un aveugle de naissance.'),
('jn',9,2,'crampon1923','" Maître, lui demandèrent ses disciples, est-ce que cet homme a péché, ou ses parents, pour qu''il soit né aveugle? "'),
('jn',9,3,'crampon1923','Jésus répondit: " Ni lui, ni ses parents n''ont péché, mais c''est afin que les œuvres de Dieu soient manifestées en lui.'),
('jn',9,4,'crampon1923','Il faut, tandis qu''il est jour, que je fasse les œuvres de celui qui m''a envoyé; la nuit vient, où personne ne peut travailler.'),
('jn',9,5,'crampon1923','Pendant que je suis dans le monde, je suis la lumière du monde. " —'),
('jn',9,6,'crampon1923','Ayant ainsi parlé, il cracha à terre, fit de la boue avec sa salive, puis il l''étendit sur les yeux de l''aveugle,'),
('jn',9,7,'crampon1923','et lui dit: " Va, lave-toi dans la piscine de Siloé (mot qui se traduit: Envoyé). " Il partit, se lava, et s''en retourna voyant clair.'),
('jn',9,8,'crampon1923','Les voisins, et ceux qui l''avaient vu auparavant demander l''aumône, disaient: " N''est-ce pas là celui qui était assis et mendiait? "'),
('jn',9,9,'crampon1923','Les uns répondaient: " C''est lui "; d''autres: " Non, mais il lui ressemble. " Mais lui disait: " C''est moi. "'),
('jn',9,10,'crampon1923','Ils lui dirent donc: " Comment tes yeux ont-ils été ouverts? "'),
('jn',9,11,'crampon1923','Il répondit: " Un homme, celui qu''on appelle Jésus, a fait de la boue, il l''a étendue sur mes yeux, et m''a dit: Va à la piscine de Siloé et lave-toi. J''y ai été, et, m''étant lavé, j''ai recouvré la vue. —'),
('jn',9,12,'crampon1923','Où est cet homme? " lui dirent-ils. Il répondit: " Je ne sais pas. "'),
('jn',9,13,'crampon1923','Ils menèrent aux Pharisiens celui qui avait été aveugle.'),
('jn',9,14,'crampon1923','Or, c''était un jour de sabbat que Jésus avait ainsi fait de la boue et ouvert les yeux de l''aveugle.'),
('jn',9,15,'crampon1923','A leur tour, les Pharisiens lui demandèrent comment il avait recouvré la vue, et il leur dit: " Il m''a mis sur les yeux de la boue, je me suis lavé, et je vois. "'),
('jn',9,16,'crampon1923','Sur cela, quelques-uns des Pharisiens disaient: " Cet homme n''est pas envoyé de Dieu, puisqu''il n''observe pas le sabbat. " D''autres disaient: " Comment un pécheur peut-il faire de tels prodiges? " Et la division était entre eux.'),
('jn',9,17,'crampon1923','Ils dirent donc de nouveau à l''aveugle: " Et toi, que dis-tu de lui, de ce qu''il t''a ouvert les yeux? " Il répondit: " C''est un prophète. "'),
('jn',9,18,'crampon1923','Les Juifs ne voulurent donc pas croire que cet homme eut été aveugle et qu''il eût recouvré la vue, jusqu''à ce qu''ils eussent fait venir les parents de celui qui avait recouvré la vue.'),
('jn',9,19,'crampon1923','Ils leur demandèrent: " Est-ce là votre fils, que vous dites être né aveugle? Comment donc voit-il maintenant? "'),
('jn',9,20,'crampon1923','Ses parents répondirent: " Nous savons que c''est bien là notre fils, et qu''il est né aveugle;'),
('jn',9,21,'crampon1923','mais comment il voit maintenant, nous l''ignorons, et qui lui a ouvert les yeux, nous ne le savons pas. Interrogez-le lui-même; il a de l''âge, lui-même parlera de ce qui le concerne. "'),
('jn',9,22,'crampon1923','Ses parents parlèrent ainsi, parce qu''ils craignaient les Juifs. Car déjà les Juifs étaient convenus que quiconque reconnaîtrait Jésus pour le Christ serait exclu de la synagogue.'),
('jn',9,23,'crampon1923','C''est pourquoi ses parents dirent: " Il a de l''âge, interrogez-le. "'),
('jn',9,24,'crampon1923','Les Pharisiens firent venir une seconde fois l''homme qui avait été aveugle, et lui dirent: " Rends gloire à Dieu. Nous savons que cet homme est un pécheur. "'),
('jn',9,25,'crampon1923','Celui-ci répondit: " S''il est un pécheur, je l''ignore; je sais seulement que j''étais aveugle, et qu''à présent je vois. "'),
('jn',9,26,'crampon1923','Ils lui dirent: " Qu''est-ce qu''il t''a fait? Comment t''a-t-il ouvert les yeux? "'),
('jn',9,27,'crampon1923','Il leur répondit: " Je vous l''ai déjà dit et vous ne l''avez pas écouté: pourquoi voulez-vous l''entendre encore? Est-ce que, vous aussi, vous voulez devenir ses disciples? "'),
('jn',9,28,'crampon1923','Ils le chargèrent alors d''injures, et dirent: " C''est toi qui es son disciple; pour nous, nous sommes disciples de Moïse.'),
('jn',9,29,'crampon1923','Nous savons que Dieu a parlé à Moïse; mais celui-ci, nous ne savons d''où il est. "'),
('jn',9,30,'crampon1923','Cet homme leur répondit: " Il est étonnant que vous ne sachiez pas d''où il est, et cependant il m''a ouvert les yeux.'),
('jn',9,31,'crampon1923','Nous savons que Dieu n''exauce point les pécheurs; mais si quelqu''un l''honore et fait sa volonté, c''est celui-là qu''il exauce.'),
('jn',9,32,'crampon1923','Jamais on n''a ouï dire que quelqu''un ait ouvert les yeux d''un aveugle-né.'),
('jn',9,33,'crampon1923','Si cet homme n''était pas de Dieu, il ne pourrait rien faire. "'),
('jn',9,34,'crampon1923','Ils lui répondirent: " Tu es né tout entier dans le péché, et tu nous fais la leçon? " Et ils le chassèrent.'),
('jn',9,35,'crampon1923','Jésus apprit qu''ils l''avaient ainsi chassé, et l''ayant rencontré, il lui dit: " Crois-tu au Fils de l''homme? "'),
('jn',9,36,'crampon1923','Il répondit: " Qui est-il, Seigneur, afin que je croie en lui? "'),
('jn',9,37,'crampon1923','Jésus lui dit: " Tu l''as vu; et celui qui te parle, c''est lui-même. " —'),
('jn',9,38,'crampon1923','" Je crois, Seigneur " dit-il; et se jetant à ses pieds, il l''adora.'),
('jn',9,39,'crampon1923','Alors Jésus dit: " Je suis venu dans ce monde pour un jugement, afin que ceux qui ne voient pas voient, et que ceux qui voient deviennent aveugles. "'),
('jn',9,40,'crampon1923','Quelques Pharisiens qui étaient avec lui, lui dirent: " Sommes-nous, nous aussi des aveugles? "'),
('jn',9,41,'crampon1923','Jésus leur répondit: " Si vous étiez des aveugles, vous n''auriez point de péché; mais maintenant vous dites: Nous voyons; votre péché demeure. "'),
('jn',10,1,'crampon1923','" En vérité, en vérité, je vous le dis, celui qui n''entre point par la porte dans la bergerie, mais qui y monte par ailleurs, est un voleur et un brigand.'),
('jn',10,2,'crampon1923','Mais celui qui entre par la porte est le pasteur des brebis.'),
('jn',10,3,'crampon1923','C''est à lui que le portier ouvre, et les brebis entendent sa voix; il appelle par leur nom ses brebis, et il les mène aux pâturages.'),
('jn',10,4,'crampon1923','Quand il a fait sortir toutes ses brebis, il marche devant elles, et les brebis le suivent, parce qu''elles connaissent sa voix.'),
('jn',10,5,'crampon1923','Elles ne suivront point un étranger, mais elles le fuiront, parce qu''elles ne connaissent pas la voix des étrangers. "'),
('jn',10,6,'crampon1923','Jésus leur dit cette allégorie; mais ils ne comprirent pas de quoi il leur parlait.'),
('jn',10,7,'crampon1923','Jésus donc leur dit encore: " En vérité, en vérité, je vous le dis, je suis la porte des brebis.'),
('jn',10,8,'crampon1923','Tous ceux qui sont venus avant moi sont des voleurs et des brigands; mais les brebis ne les ont point écoutés.'),
('jn',10,9,'crampon1923','Je suis la porte: si quelqu''un entre par moi, il sera sauvé; il entrera, et il sortira, et il trouvera des pâturages.'),
('jn',10,10,'crampon1923','Le voleur ne vient que pour dérober, égorger et détruire; moi, je suis venu pour que les brebis aient la vie, et qu''elles soient dans l''abondance.'),
('jn',10,11,'crampon1923','Je suis le bon pasteur. Le bon pasteur donne sa vie pour ses brebis.'),
('jn',10,12,'crampon1923','Mais le mercenaire, qui n''est pas le pasteur, et à qui les brebis n''appartiennent pas, voit venir le loup, laisse là les brebis et prend la fuite; et le loup les ravit et les disperse.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jn',10,13,'crampon1923','Le mercenaire s''enfuit, parce qu''il est mercenaire et qu''il n''a nul souci des brebis.'),
('jn',10,14,'crampon1923','Je suis le bon pasteur; je connais mes brebis, et mes brebis me connaissent,'),
('jn',10,15,'crampon1923','comme mon Père me connaît, et que je connais mon Père, et je donne ma vie pour mes brebis.'),
('jn',10,16,'crampon1923','J''ai encore d''autres brebis, qui ne sont pas de cette bergerie; il faut aussi que je les amène, et elles entendront ma voix, et il y aura une seule bergerie, un seul pasteur.'),
('jn',10,17,'crampon1923','C''est pour cela que mon Père m''aime, parce que je donne ma vie pour la reprendre.'),
('jn',10,18,'crampon1923','Personne ne me la ravit, mais je la donne de moi-même; j''ai le pouvoir de la donner, et le pouvoir de la reprendre: tel est l''ordre que j''ai reçu de mon Père. "'),
('jn',10,19,'crampon1923','Il s''éleva de nouveau une division parmi les Juifs à l''occasion de ce discours.'),
('jn',10,20,'crampon1923','Plusieurs d''entre eux disaient: " Il est possédé d''un démon, il a perdu le sens: Pourquoi l''écoutez-vous? "'),
('jn',10,21,'crampon1923','D''autres disaient: " Ce ne sont pas là les paroles d''un possédé; est-ce qu''un démon peut ouvrir les yeux des aveugles? "'),
('jn',10,22,'crampon1923','On célébrait à Jérusalem la fête de la Dédicace; c''était l''hiver;'),
('jn',10,23,'crampon1923','et Jésus se promenait dans le temple, sous le portique de Salomon.'),
('jn',10,24,'crampon1923','Les Juifs l''entourèrent donc et lui dirent: " Jusques à quand tiendrez-vous notre esprit en suspens? Si vous êtes le Christ dites-le-nous franchement. "'),
('jn',10,25,'crampon1923','Jésus leur répondit: " Je vous l''ai dit, et vous ne me croyez pas: les œuvres que je fais au nom de mon Père rendent témoignage de moi;'),
('jn',10,26,'crampon1923','mais vous ne me croyez point, parce que vous n''êtes pas de mes brebis.'),
('jn',10,27,'crampon1923','Mes brebis entendent ma voix; je les connais, et elles me suivent.'),
('jn',10,28,'crampon1923','Et je leur donne une vie éternelle, et elles ne périront jamais, et nul ne les ravira de ma main;'),
('jn',10,29,'crampon1923','mon Père, qui me les a données, est plus grand que tous, et nul ne peut les ravir de la main de mon Père.'),
('jn',10,30,'crampon1923','Mon père et moi nous sommes un. "'),
('jn',10,31,'crampon1923','Les Juifs ramassèrent de nouveau des pierres pour le lapider.'),
('jn',10,32,'crampon1923','Jésus leur dit: " J''ai fait devant vous beaucoup d''œuvres bonnes qui venaient de mon Père: pour laquelle de ces œuvres me lapidez-vous? "'),
('jn',10,33,'crampon1923','Les Juifs lui répondirent: " Ce n''est pas pour une bonne œuvre que nous vous lapidons, mais pour un blasphème, et parce que, étant homme, vous vous faites Dieu. "'),
('jn',10,34,'crampon1923','Jésus leur répondit: " N''est-il pas écrit dans votre Loi: J''ai dit: vous êtes des dieux?'),
('jn',10,35,'crampon1923','Si la Loi appelle dieux ceux à qui la parole de Dieu a été adressée, et si l''Écriture ne peut être anéantie,'),
('jn',10,36,'crampon1923','comment dites-vous à celui que le Père a sanctifié et envoyé dans le monde: Vous blasphémez, parce que j''ai dit: Je suis le Fils de Dieu?'),
('jn',10,37,'crampon1923','Si je ne fais pas les œuvres de mon Père, ne me croyez pas.'),
('jn',10,38,'crampon1923','Mais si je les fais, lors même que vous ne voudriez pas me croire, croyez à mes œuvres: afin que vous sachiez et reconnaissiez que le Père est en moi, et que je suis dans le Père. "'),
('jn',10,39,'crampon1923','Là-dessus, ils cherchèrent de nouveau à se saisir de lui, mais il s''échappa de leurs mains.'),
('jn',10,40,'crampon1923','Il s''en retourna au delà du Jourdain, dans le lieu où Jean avait commencé à baptiser; et il y demeura.'),
('jn',10,41,'crampon1923','Et beaucoup venaient à lui, disant: " Jean n''a fait aucun miracle;'),
('jn',10,42,'crampon1923','mais tout ce qu''il a dit de celui-ci était vrai. " Et il y en eut là beaucoup qui crurent en lui.'),
('jn',11,1,'crampon1923','Il y avait un malade, Lazare, de Béthanie, village de Marie et de Marthe, sa sœur.'),
('jn',11,2,'crampon1923','— Marie est celle qui oignit de parfum le Seigneur, et lui essuya les pieds avec ses cheveux; et c''était son frère Lazare qui était malade. —'),
('jn',11,3,'crampon1923','Les sœurs envoyèrent dire à Jésus: " Seigneur, celui que vous aimez est malade. "'),
('jn',11,4,'crampon1923','Ce qu''ayant entendu, Jésus dit: " Cette maladie ne va pas à la mort, mais elle est pour la gloire de Dieu, afin que le Fils de Dieu soit glorifié par elle. "'),
('jn',11,5,'crampon1923','Or, Jésus aimait Marthe, et sa sœur Marie, et Lazare.'),
('jn',11,6,'crampon1923','Ayant donc appris qu''il était malade, il resta deux jours encore au lieu où il était.'),
('jn',11,7,'crampon1923','Il dit ensuite à ses disciples: " Retournons en Judée. "'),
('jn',11,8,'crampon1923','Les disciples lui dirent: " Maître, tout à l''heure les Juifs voulaient vous lapider, et vous retournez là? "'),
('jn',11,9,'crampon1923','Jésus répondit: " N''y a-t-il pas douze heures dans le jour? Si quelqu''un marche pendant le jour, il ne se heurte point, parce qu''il voit la lumière de ce monde.'),
('jn',11,10,'crampon1923','Mais s''il marche pendant la nuit, il se heurte, parce qu''il manque de lumière. "'),
('jn',11,11,'crampon1923','Il parla ainsi, et ajouta: " Notre ami Lazare dort, mais je me mets en route pour le réveiller. "'),
('jn',11,12,'crampon1923','Ses disciples lui dirent: " S''il dort, il guérira. "'),
('jn',11,13,'crampon1923','Mais Jésus avait parlé de sa mort, et ils pensaient que c''était du repos du sommeil.'),
('jn',11,14,'crampon1923','Alors Jésus leur dit clairement: " Lazare est mort;'),
('jn',11,15,'crampon1923','et je me réjouis à cause de vous de n''avoir pas été là, afin que vous croyiez; mais allons vers lui. "'),
('jn',11,16,'crampon1923','Et Thomas, appelé Didyme, dit aux autres disciples: " Allons-y, nous aussi, afin de mourir avec lui. "'),
('jn',11,17,'crampon1923','Jésus vint donc et trouva Lazare depuis quatre jours dans le sépulcre.'),
('jn',11,18,'crampon1923','Or Béthanie était près de Jérusalem, à quinze stades environ.'),
('jn',11,19,'crampon1923','Beaucoup de Juifs étaient venus près de Marthe et de Marie pour les consoler au sujet de leur frère.'),
('jn',11,20,'crampon1923','Dès que Marthe eut appris que Jésus arrivait, elle alla au-devant de lui, tandis que Marie se tenait assise à la maison.'),
('jn',11,21,'crampon1923','Marthe dit donc à Jésus: " Seigneur, si vous aviez été ici, mon frère ne serait pas mort.'),
('jn',11,22,'crampon1923','Mais maintenant encore, je sais que tout ce que vous demanderez à Dieu, Dieu vous l''accordera. "'),
('jn',11,23,'crampon1923','Jésus lui dit: " Votre frère ressuscitera. —'),
('jn',11,24,'crampon1923','Je sais, lui répondit Marthe, qu''il ressuscitera lors de la résurrection, au dernier jour. "'),
('jn',11,25,'crampon1923','Jésus lui dit: " Je suis la résurrection et la vie; celui qui croit en moi, fût-il mort, vivra;'),
('jn',11,26,'crampon1923','et quiconque vit et croit en moi, ne mourra point pour toujours. Le croyez-vous? —'),
('jn',11,27,'crampon1923','Oui, Seigneur, lui dit-elle, je crois que vous êtes le Christ, le Fils de Dieu, qui devait venir en ce monde. "'),
('jn',11,28,'crampon1923','Lorsqu''elle eut ainsi parlé, elle s''en alla, et appela en secret Marie, sa sœur, disant: " Le Maître est là, et il t''appelle. "'),
('jn',11,29,'crampon1923','Dès que celle-ci l''eut entendu, elle se leva promptement et alla vers lui.'),
('jn',11,30,'crampon1923','Car Jésus n''était pas encore entré dans le village; il n''avait pas quitté le lieu où Marthe l''avait rencontré.'),
('jn',11,31,'crampon1923','Les Juifs qui étaient avec Marie, et la consolaient, l''ayant vue se lever en hâte et sortir, la suivirent en pensant: " Elle va au sépulcre pour y pleurer. "'),
('jn',11,32,'crampon1923','Lorsque Marie fut arrivée au lieu où était Jésus, le voyant, elle tomba à ses pieds, et lui dit: " Seigneur, si vous aviez été ici, mon frère ne serait pas mort. "'),
('jn',11,33,'crampon1923','Jésus la voyant pleurer, elle et les Juifs qui l''accompagnaient, frémit en son esprit, et se laissa aller à son émotion.'),
('jn',11,34,'crampon1923','Et il dit: " Où l''avez-vous mis? — Seigneur, lui répondirent-ils, venez et voyez. "'),
('jn',11,35,'crampon1923','Et Jésus pleura.'),
('jn',11,36,'crampon1923','Les Juifs dirent: " Voyez comme il l''aimait! "'),
('jn',11,37,'crampon1923','Mais quelques-uns d''entre eux dirent: " Ne pouvait-il pas, lui qui a ouvert les yeux d''un aveugle-né, faire aussi que cet homme ne mourût point? "'),
('jn',11,38,'crampon1923','Jésus donc, frémissant de nouveau en lui-même, se rendit au sépulcre: c''était un caveau, et une pierre était posée dessus.'),
('jn',11,39,'crampon1923','" Otez la pierre ", dit Jésus. Marthe, la sœur de celui qui était mort, lui dit: " Seigneur, il sent déjà, car il y a quatre jours qu''il est là. "'),
('jn',11,40,'crampon1923','Jésus lui dit: " Ne vous ai-je pas dit que si vous croyez, vous verrez la gloire de Dieu? "'),
('jn',11,41,'crampon1923','Ils ôtèrent donc la pierre; et Jésus leva les yeux en haut et dit: " Père, je vous rends grâces de ce que vous m''avez exaucé.'),
('jn',11,42,'crampon1923','Pour moi, je savais que vous m''exaucez toujours; mais j''ai dit cela à cause de la foule qui m''entoure, afin qu''ils croient que c''est vous qui m''avez envoyé. "'),
('jn',11,43,'crampon1923','Ayant parlé ainsi, il cria d''une voix forte: " Lazare, sors! "'),
('jn',11,44,'crampon1923','Et le mort sortit, les pieds et les mains liés de bandelettes, et le visage enveloppé d''un suaire. Jésus leur dit: " Déliez-le, et laissez-le aller. "'),
('jn',11,45,'crampon1923','Beaucoup d''entre les Juifs qui étaient venus près de Marie et de Marthe, et qui avaient vu ce qu''avait fait Jésus, crurent en lui.'),
('jn',11,46,'crampon1923','Mais quelques-uns d''entre eux allèrent trouver les Pharisiens, et leur racontèrent ce que Jésus avait fait.'),
('jn',11,47,'crampon1923','Les Pontifes et les Pharisiens assemblèrent donc le Sanhédrin et dirent: " Que ferons-nous? Car cet homme opère beaucoup de miracles.'),
('jn',11,48,'crampon1923','Si nous le laissons faire, tous croiront en lui, et les Romains viendront détruire notre ville et notre nation. "'),
('jn',11,49,'crampon1923','L''un d''eux, Caïphe, qui était grand prêtre cette année-là, leur dit: " Vous n''y entendez rien;'),
('jn',11,50,'crampon1923','vous ne réfléchissez pas qu''il est de votre intérêt qu''un seul homme meure pour le peuple, et que toute la nation ne périsse pas. "'),
('jn',11,51,'crampon1923','Il ne dit pas cela de lui-même; mais étant grand prêtre cette année-là, il prophétisa que Jésus devait mourir pour la nation; —'),
('jn',11,52,'crampon1923','et non seulement pour la nation, mais aussi afin de réunir en un seul corps les enfants de Dieu qui sont dispersés.'),
('jn',11,53,'crampon1923','Depuis ce jour, ils délibérèrent sur les moyens de le faire mourir.'),
('jn',11,54,'crampon1923','C''est pourquoi Jésus ne se montrait plus en public parmi les Juifs; mais il se retira dans la contrée voisine du désert, dans une ville nommée Ephrem, et il y séjourna avec ses disciples.'),
('jn',11,55,'crampon1923','Cependant la Pâque des Juifs était proche, et beaucoup montèrent de cette contrée à Jérusalem, avant la Pâque, pour se purifier.'),
('jn',11,56,'crampon1923','Ils cherchaient Jésus et ils se disaient les uns aux autres, se tenant dans le temple: " Que vous en semble? Pensez-vous qu''il ne viendra pas à la fête? " Or, les Pontifes et les Pharisiens avaient donné l''ordre que, si quelqu''un savait où il était, il le déclarât, afin qu''ils le fissent prendre.'),
('jn',11,57,'crampon1923',''),
('jn',12,1,'crampon1923','Six jours avant la Pâque, Jésus vint à Béthanie, où était Lazare, le mort qu''il avait ressuscité.'),
('jn',12,2,'crampon1923','Là, on lui fit un souper, et Marthe servait. Or, Lazare était de ceux qui se trouvaient à table avec lui.'),
('jn',12,3,'crampon1923','Marie, ayant pris une livre d''un parfum de nard pur très précieux, en oignit les pieds de Jésus, et les essuya avec ses cheveux; et la maison fut remplie de l''odeur du parfum.'),
('jn',12,4,'crampon1923','Alors un de ses disciples, Judas Iscariote, celui qui devait le trahir, dit:'),
('jn',12,5,'crampon1923','" Pourquoi n''a-t-on pas vendu ce parfum trois cents deniers, pour les donner aux pauvres? "'),
('jn',12,6,'crampon1923','Il dit cela, non qu''il se souciât des pauvres, mais parce qu''il était voleur, et qu''ayant la bourse, il dérobait ce qu''on y mettait.'),
('jn',12,7,'crampon1923','Jésus lui dit donc: " Laisse-la; elle a gardé ce parfum pour le jour de ma sépulture.'),
('jn',12,8,'crampon1923','Car vous aurez toujours des pauvres avec vous; mais moi, vous ne m''aurez pas toujours! "'),
('jn',12,9,'crampon1923','Un grand nombre de Juifs surent que Jésus était à Béthanie, et ils vinrent, non seulement à cause de Jésus, mais aussi pour voir Lazare qu''il avait ressuscité des morts.'),
('jn',12,10,'crampon1923','Mais les Princes des prêtres délibérèrent de faire mourir aussi Lazare,'),
('jn',12,11,'crampon1923','parce que beaucoup de Juifs se retiraient à cause de lui, et croyaient en Jésus.'),
('jn',12,12,'crampon1923','Le lendemain, une multitude de gens qui étaient venus pour la fête, ayant appris que Jésus se rendait à Jérusalem,'),
('jn',12,13,'crampon1923','prirent des rameaux de palmiers, et allèrent au-devant de lui, en criant: " Hosanna! Béni soit celui qui vient au nom du Seigneur, le Roi d''Israël! "'),
('jn',12,14,'crampon1923','Jésus, ayant trouvé un ânon, monta dessus, selon ce qui est écrit:'),
('jn',12,15,'crampon1923','" Ne crains point, fille de Sion, voici ton Roi qui vient, assis sur le petit d''une ânesse. "'),
('jn',12,16,'crampon1923','— Ses disciples ne comprirent pas d''abord ces choses; mais lorsque Jésus fut glorifié, ils se souvinrent qu''elles avaient été écrites de lui, et qu''il les avait accomplies en ce qui le regarde. —'),
('jn',12,17,'crampon1923','La foule donc qui était avec lui lorsqu''il appela Lazare du tombeau et le ressuscita des morts lui rendait témoignage;'),
('jn',12,18,'crampon1923','et c''est aussi parce qu''elle avait appris qu''il avait fait ce miracle, que la multitude s''était portée à sa rencontre.'),
('jn',12,19,'crampon1923','Les Pharisiens se dirent donc entre eux: " Vous voyez bien que vous ne gagnez rien; voilà que tout le monde court après lui. "'),
('jn',12,20,'crampon1923','Or, il y avait quelques Gentils parmi ceux qui étaient montés pour adorer, lors de la fête.'),
('jn',12,21,'crampon1923','Ils s''approchèrent de Philippe, qui était de Bethsaïde en Galilée, et lui firent cette demande: " Seigneur, nous voudrions bien voir Jésus. "'),
('jn',12,22,'crampon1923','Philippe alla le dire à André, puis André et Philippe allèrent le dire à Jésus.'),
('jn',12,23,'crampon1923','Jésus leur répondit: " L''heure est venue où le Fils de l''homme doit être glorifié.'),
('jn',12,24,'crampon1923','En vérité, en vérité, je vous le dis, si le grain de blé tombé en terre ne meurt pas,'),
('jn',12,25,'crampon1923','il demeure seul; mais s''il meurt, il porte beaucoup de fruit. Celui qui aime sa vie, la perdra; et celui qui hait sa vie en ce monde, la conservera pour la vie éternelle.'),
('jn',12,26,'crampon1923','Si quelqu''un veut être mon serviteur, qu''il me suive, et là où je suis, là aussi sera mon serviteur. Si quelqu''un me sert, mon Père l''honorera.'),
('jn',12,27,'crampon1923','Maintenant mon âme est troublée; et que dirai-je?... Père, délivrez-moi de cette heure... Mais c''est pour cela que je suis arrivé à cette heure.'),
('jn',12,28,'crampon1923','Père, glorifiez votre nom. " Et une voix vint du ciel: " Je l''ai glorifié et je le glorifierai encore. "'),
('jn',12,29,'crampon1923','La foule qui était là et qui avait entendu, disait: " C''est le tonnerre "; d''autres disaient: " Un ange lui a parlé. "'),
('jn',12,30,'crampon1923','Jésus dit: " Ce n''est pas pour moi que cette voix s''est fait entendre, mais pour vous.'),
('jn',12,31,'crampon1923','C''est maintenant le jugement de ce monde; c''est maintenant que le Prince de ce monde va être jeté dehors.'),
('jn',12,32,'crampon1923','Et moi, quand j''aurai été élevé de la terre, j''attirerai tous les hommes à moi. "'),
('jn',12,33,'crampon1923','Ce qu''il disait, pour marquer de quelle mort il devait mourir.'),
('jn',12,34,'crampon1923','La foule lui répondit: " Nous avons appris par la Loi que le Christ demeure éternellement: comment donc dites-vous: il faut que le Fils de l''homme soit élevé? Qui est ce Fils de l''homme? "'),
('jn',12,35,'crampon1923','Jésus leur dit: " La lumière n''est plus que pour un temps au milieu de vous. Marchez, pendant que vous avez la lumière, de peur que les ténèbres ne vous surprennent: celui qui marche dans les ténèbres ne sait où il va.'),
('jn',12,36,'crampon1923','Pendant que vous avez la lumière, croyez en la lumière, afin que vous soyez des enfants de lumière. " Jésus dit ces choses, puis s''en allant il se déroba à leurs yeux.'),
('jn',12,37,'crampon1923','Quoiqu''il eût fait tant de miracles en leur présence, ils ne croyaient point en lui:'),
('jn',12,38,'crampon1923','afin que fût accompli l''oracle du prophète Isaïe, disant: " Seigneur, qui a cru à notre parole? et à qui le bras du Seigneur a-t-il été révélé? "'),
('jn',12,39,'crampon1923','Ils ne pouvaient donc croire, parce qu''Isaïe a dit encore:'),
('jn',12,40,'crampon1923','" Il a aveuglé leurs yeux et endurci leur cœur, de peur qu''ils ne voient des yeux, qu''ils ne comprennent du cœur, qu''ils ne se convertissent, et que je ne les guérisse. "'),
('jn',12,41,'crampon1923','Isaïe dit ces choses, lorsqu''il vit la gloire du Seigneur et qu''il parla de lui.'),
('jn',12,42,'crampon1923','Beaucoup, toutefois, même parmi les membres du Sanhédrin, crurent en lui; mais, à cause des Pharisiens, ils ne le confessaient pas, de peur d''être chassés de la synagogue.'),
('jn',12,43,'crampon1923','Car ils aimèrent la gloire des hommes plus que la gloire de Dieu.'),
('jn',12,44,'crampon1923','Or, Jésus éleva la voix et dit: " Celui qui croit en moi, croit, non pas en moi, mais en celui qui m''a envoyé;'),
('jn',12,45,'crampon1923','et celui qui me voit, voit celui qui m''a envoyé.'),
('jn',12,46,'crampon1923','Je suis venu dans le monde comme une lumière, afin que celui qui croit en moi, ne demeure pas dans les ténèbres.'),
('jn',12,47,'crampon1923','Si quelqu''un entend ma parole, et ne la garde pas, moi je ne le juge point; car je suis venu, non pour juger le monde, mais pour sauver le monde.'),
('jn',12,48,'crampon1923','Celui qui me méprise et ne reçoit pas ma parole, il a son juge: c''est la parole même que j''ai annoncée; elle le jugera au dernier jour.'),
('jn',12,49,'crampon1923','Car je n''ai point parlé de moi-même; mais le Père, qui m''a envoyé, m''a prescrit lui-même ce que je dois dire et ce que je dois enseigner.'),
('jn',12,50,'crampon1923','Et je sais que son commandement est la vie éternelle. Les choses donc que je dis, je les dis comme mon Père me les a enseignées. "'),
('jn',13,1,'crampon1923','Avant la fête de Pâque, Jésus, sachant que son heure était venue de passer de ce monde à son Père, après avoir aimé les siens qui étaient dans le monde, les aima jusqu''à la fin.'),
('jn',13,2,'crampon1923','Pendant le souper, lorsque déjà le diable avait mis dans le cœur de Judas, fils de Simon Iscariote, le dessein de le livrer,'),
('jn',13,3,'crampon1923','Jésus, qui savait que son Père avait remis toutes choses entre ses mains, et qu''il était sorti de Dieu et s''en allait à Dieu,'),
('jn',13,4,'crampon1923','se leva de table, posa son manteau, et, ayant pris un linge, il s''en ceignit.'),
('jn',13,5,'crampon1923','Puis il versa de l''eau dans le bassin et se mit à laver les pieds de ses disciples, et à les essuyer avec le linge dont il était ceint.'),
('jn',13,6,'crampon1923','Il vint donc à Simon-Pierre; et Pierre lui dit: " Quoi, vous Seigneur, vous me lavez les pieds! "'),
('jn',13,7,'crampon1923','Jésus lui répondit: " Ce que je fais, tu ne le sais pas maintenant, mais tu le comprendras bientôt. "'),
('jn',13,8,'crampon1923','Pierre lui dit: " Non, jamais vous ne me laverez les pieds. " Jésus lui répondit: " Si je ne te lave, tu n''auras point de part avec moi. "'),
('jn',13,9,'crampon1923','Simon-Pierre lui dit: " Seigneur, non seulement les pieds, mais encore les mains et la tête! "'),
('jn',13,10,'crampon1923','Jésus lui dit: " Celui qui a pris un bain n''a besoin que de laver ses pieds; il est pur tout entier. Et vous aussi, vous êtes purs, mais non pas tous. "'),
('jn',13,11,'crampon1923','Car il savait quel était celui qui allait le livrer; c''est pourquoi il dit: " Vous n''êtes pas tous purs. "'),
('jn',13,12,'crampon1923','Après qu''il leur eut lavé les pieds, et repris son manteau, il se remit à table et leur dit: " Comprenez-vous ce que je vous ai fait?'),
('jn',13,13,'crampon1923','Vous m''appelez le Maître et le Seigneur: et vous dites bien, car je le suis.'),
('jn',13,14,'crampon1923','Si donc moi, le Seigneur et le Maître, je vous ai lavé les pieds, vous devez aussi vous laver les pieds les uns aux autres.'),
('jn',13,15,'crampon1923','Car je vous ai donné l''exemple, afin que, comme je vous ai fait, vous fassiez aussi vous-mêmes.'),
('jn',13,16,'crampon1923','En vérité, en vérité, je vous le dis, le serviteur n''est pas plus grand que son maître, ni l''apôtre plus grand que celui qui l''a envoyé.'),
('jn',13,17,'crampon1923','Si vous savez ces choses vous êtes heureux, pourvu que vous les pratiquiez.'),
('jn',13,18,'crampon1923','Je ne dis pas cela de vous tous; je connais ceux que j''ai élus; mais il faut que l''Écriture s''accomplisse: Celui qui mange le pain avec moi, a levé le talon contre moi.'),
('jn',13,19,'crampon1923','Je vous le dis dès maintenant, avant que la chose arrive, afin que, lorsqu''elle sera arrivée, vous reconnaissiez qui je suis.'),
('jn',13,20,'crampon1923','En vérité, en vérité, je vous le dis, quiconque me reçoit, reçoit celui qui m''a envoyé. "'),
('jn',13,21,'crampon1923','Ayant ainsi parlé, Jésus fut troublé en son esprit; et il affirma expressément: " En vérité, en vérité, je vous le dis, un de vous me livrera. "'),
('jn',13,22,'crampon1923','Les disciples se regardaient les uns les autres, ne sachant de qui il parlait.'),
('jn',13,23,'crampon1923','Or, l''un d''eux était couché sur le sein de Jésus; c''était celui que Jésus aimait.'),
('jn',13,24,'crampon1923','Simon-Pierre lui fit donc signe pour lui dire: " Qui est celui dont il parle? "'),
('jn',13,25,'crampon1923','Le disciple, s''étant penché sur le sein de Jésus, lui dit: " Seigneur, qui est-ce? "'),
('jn',13,26,'crampon1923','Jésus répondit: " C''est celui à qui je présenterai le morceau trempé. " Et ayant trempé du pain, il le donna à Judas Iscariote, fils de Simon.'),
('jn',13,27,'crampon1923','Aussitôt que Judas l''eut pris, Satan entra en lui; et Jésus lui dit: " Ce que tu fais, fais-le vite. "'),
('jn',13,28,'crampon1923','Aucun de ceux qui étaient à table ne comprit pourquoi il lui disait cela.'),
('jn',13,29,'crampon1923','Quelques-uns pensaient que, Judas ayant la bourse, Jésus voulait lui dire: " Achète ce qu''il faut pour la fête, " ou: " Donne quelque chose aux pauvres. "'),
('jn',13,30,'crampon1923','Judas ayant pris le morceau de pain, se hâta de sortir. Il était nuit.'),
('jn',13,31,'crampon1923','Lorsque Judas fut sorti, Jésus dit: " Maintenant le Fils de l''homme a été glorifié, et Dieu a été glorifié en lui.'),
('jn',13,32,'crampon1923','Si Dieu a été glorifié en lui, Dieu aussi le glorifiera en lui-même, et il le glorifiera bientôt.'),
('jn',13,33,'crampon1923','Mes petits enfants, je ne suis plus avec vous que pour un peu de temps. Vous me chercherez et comme j''ai dit aux Juifs qu''ils ne pouvaient venir où je vais, je vous le dis aussi maintenant.'),
('jn',13,34,'crampon1923','Je vous donne un commandement nouveau: que vous vous aimiez les uns les autres; que comme je vous ai aimés, vous vous aimiez aussi les uns les autres.'),
('jn',13,35,'crampon1923','C''est à cela que tous connaîtront que vous êtes mes disciples, si vous avez de l''amour les uns pour les autres. "'),
('jn',13,36,'crampon1923','Simon-Pierre lui dit: " Seigneur, où allez-vous? " Jésus répondit: " Où je vais, tu ne peux me suivre à présent; mais tu me suivras plus tard. —'),
('jn',13,37,'crampon1923','Seigneur, lui dit Pierre, pourquoi ne puis-je vous suivre à présent? Je donnerai ma vie pour vous. "'),
('jn',13,38,'crampon1923','Jésus lui répondit: " Tu donneras ta vie pour moi! En vérité, en vérité, je te le dis, le coq ne chantera pas, avant que tu ne m''aies renié trois fois. "'),
('jn',14,1,'crampon1923','" Que votre cœur ne se trouble point. Vous croyez en Dieu, croyez aussi en moi.'),
('jn',14,2,'crampon1923','Il y a beaucoup de demeures dans la maison de mon Père; s''il en était autrement, je vous l''aurais dit, car je vais vous y préparer une place.'),
('jn',14,3,'crampon1923','Et lorsque je m''en serai allé et que je vous aurai préparé une place, je reviendrai, et je vous prendrai avec moi, afin que là où je suis, vous y soyez aussi;'),
('jn',14,4,'crampon1923','et là où je vais, vous en savez le chemin. "'),
('jn',14,5,'crampon1923','Thomas lui dit: " Seigneur, nous ne savons où vous allez; comment donc en saurions-nous le chemin? "'),
('jn',14,6,'crampon1923','Jésus lui dit: " Je suis le chemin, la vérité et la vie; nul ne vient au Père que par moi.'),
('jn',14,7,'crampon1923','Si vous m''aviez connu, vous auriez aussi connu mon Père... dès à présent vous le connaissez, et vous l''avez vu. "'),
('jn',14,8,'crampon1923','Philippe lui dit: " Seigneur, montrez-nous le Père, et cela nous suffit. "'),
('jn',14,9,'crampon1923','Jésus lui répondit: " Il y a longtemps que je suis avec vous, et tu ne m''as pas connu? Philippe, celui qui m''a vu, a vu aussi le Père. Comment peux-tu dire: Montrez-nous le Père!'),
('jn',14,10,'crampon1923','Ne crois-tu pas que je suis dans le Père, et que le Père est en moi? Les paroles que je vous dis, je ne les dis pas de moi-même: le Père qui demeure en moi fait lui-même ces œuvres.'),
('jn',14,11,'crampon1923','Croyez sur ma parole que je suis dans le Père, et que le Père est en moi.'),
('jn',14,12,'crampon1923','Croyez-le du moins à cause de ces œuvres. En vérité, en vérité, je vous le dis, celui qui croit en moi fera aussi les œuvres que je fais, et il en fera de plus grandes, parce que je m''en vais au Père,'),
('jn',14,13,'crampon1923','et que tout ce que vous demanderez au Père en mon nom, je le ferai, afin que le Père soit glorifié dans le Fils.'),
('jn',14,14,'crampon1923','Si vous me demandez quelque chose en mon nom, je le ferai.'),
('jn',14,15,'crampon1923','Si vous m''aimez, gardez mes commandements.'),
('jn',14,16,'crampon1923','Et moi, je prierai le Père, et il vous donnera un autre Consolateur, pour qu''il demeure toujours avec vous;'),
('jn',14,17,'crampon1923','c''est l''Esprit de vérité, que le monde ne peut recevoir, parce qu''il ne le voit point et ne le connaît point; mais vous, vous le connaissez, parce qu''il demeure au milieu de vous; et il sera en vous.'),
('jn',14,18,'crampon1923','Je ne vous laisserai point orphelins; je viendrai à vous.'),
('jn',14,19,'crampon1923','Encore un peu de temps, et le monde ne me verra plus; mais vous, vous me verrez, parce que je vis, et que vous vivrez.'),
('jn',14,20,'crampon1923','En ce jour-là, vous connaîtrez que je suis en mon Père, et vous en moi, et moi en vous.'),
('jn',14,21,'crampon1923','Celui qui a mes commandements et qui les garde, c''est celui-là qui m''aime; et celui qui m''aime sera aimé de mon Père; et moi je l''aimerai et je me manifesterai à lui. "'),
('jn',14,22,'crampon1923','Judas, non pas l''Iscariote, lui dit: " Seigneur, comment se fait-il que vous vouliez vous manifester à nous, et non au monde? "'),
('jn',14,23,'crampon1923','Jésus lui répondit: " Si quelqu''un m''aime, il gardera ma parole, et mon Père l''aimera, et nous viendrons à lui, et nous ferons chez lui notre demeure.'),
('jn',14,24,'crampon1923','Celui qui ne m''aime pas, ne gardera pas mes paroles. Et la parole que vous entendez n''est pas de moi, mais du Père qui m''a envoyé.'),
('jn',14,25,'crampon1923','Je vous ai dit ces choses pendant que je demeure avec vous.'),
('jn',14,26,'crampon1923','Mais le Consolateur, l''Esprit-Saint, que mon Père enverra en mon nom, lui, vous enseignera toutes choses, et vous rappellera tout ce que je vous ai dit.'),
('jn',14,27,'crampon1923','Je vous laisse la paix, je vous donne ma paix; je ne la donne pas comme la donne le monde. Que votre cœur ne se trouble point et ne s''effraye point.'),
('jn',14,28,'crampon1923','Vous avez entendu que je vous ai dit: Je m''en vais, et je reviens à vous. Si vous m''aimiez, vous vous réjouiriez de ce que je vais au Père, car mon Père est plus grand que moi.'),
('jn',14,29,'crampon1923','Et maintenant, je vous ai dit ces choses avant qu''elles n''arrivent, afin que, quand elles seront arrivées, vous croyiez.'),
('jn',14,30,'crampon1923','Je ne m''entretiendrai plus guère avec vous, car le Prince de ce monde vient et il n''a rien en moi.'),
('jn',14,31,'crampon1923','Mais afin que le monde sache que j''aime mon Père, et que j''agis selon le commandement que mon Père m''a donné, levez-vous, partons d''ici. "'),
('jn',15,1,'crampon1923','" Je suis la vraie vigne, et mon Père est le vigneron.'),
('jn',15,2,'crampon1923','Tout sarment qui en moi ne porte pas de fruit, il le retranche; et tout sarment qui porte du fruit, il l''émonde, afin qu''il en porte davantage.'),
('jn',15,3,'crampon1923','Déjà vous êtes purs, à cause de la parole que je vous ai annoncée.'),
('jn',15,4,'crampon1923','Demeurez en moi, et moi en vous. Comme le sarment ne peut de lui-même porter du fruit, s''il ne demeure uni à la vigne, ainsi vous ne le pouvez non plus, si vous ne demeurez en moi.'),
('jn',15,5,'crampon1923','Je suis la vigne, vous êtes les sarments. Celui qui demeure en moi, et en qui je demeure, porte beaucoup de fruits: car, séparés de moi, vous ne pouvez rien faire.'),
('jn',15,6,'crampon1923','Si quelqu''un ne demeure pas en moi, il est jeté dehors, comme le sarment, et il sèche; puis on ramasse ces sarments, on les jette au feu, et ils brûlent.'),
('jn',15,7,'crampon1923','Si vous demeurez en moi, et que mes paroles demeurent en vous, vous demanderez ce que vous voudrez, et cela vous sera accordé.'),
('jn',15,8,'crampon1923','C''est la gloire de mon Père que vous portiez beaucoup de fruits, et que vous soyez mes disciples.'),
('jn',15,9,'crampon1923','Comme mon Père m''a aimé, moi aussi je vous ai aimés: demeurez dans mon amour.'),
('jn',15,10,'crampon1923','Si vous gardez mes commandements, vous demeurerez dans mon amour, comme moi-même j''ai gardé les commandements de mon Père, et comme je demeure dans son amour.'),
('jn',15,11,'crampon1923','Je vous ai dit ces choses, afin que ma joie soit en vous, et que votre joie soit parfaite.'),
('jn',15,12,'crampon1923','Ceci est mon commandement, que vous vous aimiez les uns les autres, comme je vous ai aimés.'),
('jn',15,13,'crampon1923','Il n''y a pas de plus grand amour que de donner sa vie pour ses amis.'),
('jn',15,14,'crampon1923','Vous êtes mes amis, si vous faites ce que je vous commande.'),
('jn',15,15,'crampon1923','Je ne vous appelle plus serviteurs, parce que le serviteur ne sait pas ce que fait son maître; mais je vous ai appelés amis, parce que tout ce que j''ai entendu de mon Père, je vous l''ai fait connaître.'),
('jn',15,16,'crampon1923','Ce n''est pas vous qui m''avez choisi; mais c''est moi qui vous ai choisis et qui vous ai établis, pour que vous alliez et que vous portiez du fruit, que votre fruit demeure, et que le Père vous accorde ce que vous lui demanderez en mon nom.'),
('jn',15,17,'crampon1923','Ce que je vous commande, c''est de vous aimer les uns les autres.'),
('jn',15,18,'crampon1923','Si le monde vous hait, sachez qu''il m''a haï le premier.'),
('jn',15,19,'crampon1923','Si vous étiez du monde, le monde aimerait ce qui lui appartiendrait en propre; mais parce que vous n''êtes pas du monde, et que je vous ai choisis du milieu du monde, à cause de cela le monde vous hait.'),
('jn',15,20,'crampon1923','Souvenez-vous de la parole que je vous ai dite: Le serviteur n''est pas plus grand que le maître. S''ils m''ont persécuté, ils vous persécuteront, vous aussi; s''ils ont gardé ma parole, ils garderont aussi la vôtre.'),
('jn',15,21,'crampon1923','Mais ils vous feront toutes ces choses à cause de mon nom, parce qu''ils ne connaissent pas celui qui m''a envoyé.'),
('jn',15,22,'crampon1923','Si je n''étais pas venu, et que je ne leur eusse point parlé, ils seraient sans péché; mais maintenant leur péché est sans excuse.'),
('jn',15,23,'crampon1923','Celui qui me hait, hait aussi mon Père.'),
('jn',15,24,'crampon1923','Si je n''avais pas fait au milieu d''eux des œuvres que nul autre n''a faites, ils seraient sans péché; mais maintenant ils ont vu, et ils me haïssent, moi et mon Père.'),
('jn',15,25,'crampon1923','Mais cela est arrivé afin que s''accomplît la parole qui est écrite dans leur Loi: ils m''ont haï sans sujet.'),
('jn',15,26,'crampon1923','Lorsque le Consolateur que je vous enverrai d''auprès du Père, l''Esprit de vérité qui procède du Père, sera venu, il rendra témoignage de moi.'),
('jn',15,27,'crampon1923','Et vous aussi, vous me rendrez témoignage, parce que vous êtes avec moi dès le commencement. "'),
('jn',16,1,'crampon1923','" Je vous ai dit ces choses, afin que vous ne soyez pas scandalisés.'),
('jn',16,2,'crampon1923','Ils vous chasseront des synagogues; et même l''heure vient où quiconque vous fera mourir, croira faire à Dieu un sacrifice agréable.'),
('jn',16,3,'crampon1923','Et ils agiront ainsi, parce qu''ils n''ont connu ni mon Père, ni moi.'),
('jn',16,4,'crampon1923','Mais je vous l''ai dit afin que, lorsque l''heure sera venue, vous vous souveniez que je vous l''ai annoncé.'),
('jn',16,5,'crampon1923','Je ne vous en ai pas parlé dès le commencement, parce que j''étais avec vous. Et maintenant que je m''en vais à celui qui m''a envoyé, aucun de vous ne me demande: " Où allez-vous? "'),
('jn',16,6,'crampon1923','Mais parce que je vous ai dit ces choses, la tristesse a rempli votre cœur.'),
('jn',16,7,'crampon1923','Cependant je vous dis la vérité: il vous est bon que je m''en aille; car, si je ne m''en vais pas, le Consolateur ne viendra pas en vous; mais si je m''en vais, je vous l''enverrai.'),
('jn',16,8,'crampon1923','Et quand il sera venu, il convaincra le monde au sujet du péché, de la justice et du jugement:'),
('jn',16,9,'crampon1923','au sujet du péché, parce qu''ils n''ont pas cru en moi;'),
('jn',16,10,'crampon1923','au sujet de la justice, parce que je vais au Père, et que vous ne me verrez plus;'),
('jn',16,11,'crampon1923','au sujet du jugement, parce que le Prince de ce monde est [déjà] jugé.'),
('jn',16,12,'crampon1923','J''ai encore beaucoup de choses à vous dire; mais vous ne pouvez les porter à présent.'),
('jn',16,13,'crampon1923','Quand le Consolateur, l''Esprit de vérité, sera venu, il vous guidera dans toute la vérité. Car il ne parlera pas de lui-même, mais il dira tout ce qu''il aura entendu, et il vous annoncera les choses à venir.'),
('jn',16,14,'crampon1923','Celui-ci me glorifiera, parce qu''il recevra de ce qui est à moi, et il vous l''annoncera.'),
('jn',16,15,'crampon1923','Tout ce que le Père a est à moi. C''est pourquoi j''ai dit qu''il recevra ce qui est à moi, et qu''il vous l''annoncera.'),
('jn',16,16,'crampon1923','Encore un peu de temps, et vous ne me verrez plus; et encore un peu de temps, et vous me verrez, parce que je vais à mon Père. "'),
('jn',16,17,'crampon1923','Sur quoi, quelques-uns de ses disciples se dirent entre eux: " Que signifie ce qu''il nous dit: Encore un peu de temps, et vous ne me verrez plus; et encore un peu de temps, et vous me verrez, parce que je vais à mon Père? "'),
('jn',16,18,'crampon1923','Ils disaient donc: " Que signifie cet encore un peu de temps? Nous ne savons ce qu''il veut dire. "'),
('jn',16,19,'crampon1923','Jésus connut qu''ils voulaient l''interroger et leur dit: " Vous vous questionnez entre vous sur ce que j''ai dit: Encore un peu de temps et vous ne me verrez plus; et encore un peu de temps, et vous me verrez.'),
('jn',16,20,'crampon1923','En vérité, en vérité, je vous le dis, vous pleurerez et vous vous lamenterez, tandis que le monde se réjouira; vous serez affligés, mais votre affliction se changera en joie.'),
('jn',16,21,'crampon1923','La femme, lorsqu''elle enfante, est dans la souffrance parce que son heure est venue; mais lorsqu''elle a donné le jour à l''enfant, elle ne se souvient plus de ses douleurs, dans la joie qu''elle a de ce qu''un homme est né dans le monde.'),
('jn',16,22,'crampon1923','Vous donc aussi, vous êtes maintenant dans l''affliction; mais je vous reverrai, et votre cœur se réjouira, et nul ne vous ravira votre joie.'),
('jn',16,23,'crampon1923','En ce jour-là, vous ne m''interrogerez plus sur rien. En vérité, en vérité, je vous le dis, tout ce que vous demanderez à mon Père, il vous le donnera en mon nom.'),
('jn',16,24,'crampon1923','Jusqu''à présent vous n''avez rien demandé en mon nom: demandez, et vous recevrez, afin que votre joie soit parfaite.'),
('jn',16,25,'crampon1923','Je vous ai dit ces choses en paraboles. L''heure vient où je ne vous parlerai plus en paraboles, mais je vous parlerai ouvertement du Père.'),
('jn',16,26,'crampon1923','En ce jour-là, vous demanderez en mon nom, et je ne vous dis point que je prierai le Père pour vous.'),
('jn',16,27,'crampon1923','Car le Père lui-même vous aime, parce que vous m''avez aimé, et que vous avez cru que je suis sorti du Père.'),
('jn',16,28,'crampon1923','Je suis sorti du Père, et je suis venu dans le monde; maintenant je quitte le monde, et je vais au Père. "'),
('jn',16,29,'crampon1923','Ses disciples lui dirent; " Voilà que vous parlez ouvertement et sans vous servir d''aucune figure.'),
('jn',16,30,'crampon1923','Maintenant nous voyons que vous savez toutes choses, et que vous n''avez pas besoin que personne vous interroge; c''est pourquoi nous croyons que vous êtes sorti de Dieu. "'),
('jn',16,31,'crampon1923','Jésus leur répondit: " Vous croyez à présent... "'),
('jn',16,32,'crampon1923','Voici que l''heure vient, et déjà elle est venue, où vous serez dispersés, chacun de son côté, et vous me laisserez seul; pourtant je ne suis pas seul, parce que le Père est avec moi.'),
('jn',16,33,'crampon1923','Je vous ai dit ces choses, afin que vous ayez la paix en moi. Vous avez des tribulations dans le monde; mais prenez confiance, j''ai vaincu le monde.'),
('jn',17,1,'crampon1923','Ayant ainsi parlé, Jésus leva les yeux au ciel et dit: " Père, l''heure est venue, glorifiez votre Fils, afin que votre Fils vous glorifie,'),
('jn',17,2,'crampon1923','puisque vous lui avez donné autorité sur toute chair, afin qu''à tous ceux que vous lui avez donnés, il donne la vie éternelle.'),
('jn',17,3,'crampon1923','Or, la vie éternelle, c''est qu''ils vous connaissent, vous, le seul vrai Dieu, et celui que vous avez envoyé, Jésus-Christ.'),
('jn',17,4,'crampon1923','Je vous ai glorifié sur la terre, j''ai achevé l''œuvre que vous m''avez donnée à faire.'),
('jn',17,5,'crampon1923','Et maintenant à vous, Père, glorifiez-moi auprès de vous, de la gloire que j''avais auprès de vous, avant que le monde fût.'),
('jn',17,6,'crampon1923','J''ai manifesté votre nom aux hommes que vous m''avez donnés du milieu du monde. Ils étaient à vous, et vous me les avez donnés: et ils ont gardé votre parole.'),
('jn',17,7,'crampon1923','Ils savent à présent que tout ce que vous m''avez donné vient de vous;'),
('jn',17,8,'crampon1923','car les paroles que vous m''avez données, je les leur ai données; et ils les ont reçues, et ils ont vraiment reconnu que je suis sorti de vous, et ils ont cru que c''est vous qui m''avez envoyé.'),
('jn',17,9,'crampon1923','C''est pour eux que je prie. Je ne prie pas pour le monde, mais pour ceux que vous m''avez donnés; parce qu''ils sont à vous:'),
('jn',17,10,'crampon1923','car tout ce qui est à moi est à vous, et tout ce qui est à vous est à moi, et que je suis glorifié en eux.'),
('jn',17,11,'crampon1923','Je ne suis plus dans le monde; pour eux, ils sont dans le monde, et moi, je vais à vous. Père saint, gardez dans votre nom ceux que vous m''avez donnés, afin qu''ils ne fassent qu''un, comme nous.'),
('jn',17,12,'crampon1923','Lorsque j''étais avec eux, je les conservais dans votre nom. J''ai gardé ceux que vous m''avez donnés, et pas un d''eux ne s''est perdu, hormis le fils de perdition, afin que l''Ecriture fût accomplie.'),
('jn',17,13,'crampon1923','Maintenant je vais à vous, et je fais cette prière, pendant que je suis dans le monde, afin qu''ils aient en eux la plénitude de ma joie.'),
('jn',17,14,'crampon1923','Je leur ai donné votre parole, et le monde les a haïs, parce qu''ils ne sont pas du monde, comme moi-même je ne suis pas du monde.'),
('jn',17,15,'crampon1923','Je ne vous demande pas de les ôter du monde, mais de les garder du mal.'),
('jn',17,16,'crampon1923','Ils ne sont pas du monde, comme moi-même je ne suis pas du monde.'),
('jn',17,17,'crampon1923','Sanctifiez-les dans la vérité: votre parole est la vérité.'),
('jn',17,18,'crampon1923','Comme vous m''avez envoyé dans le monde, je les ai aussi envoyés dans le monde.'),
('jn',17,19,'crampon1923','Et je me sanctifie moi-même pour eux, afin qu''eux aussi soient sanctifiés en vérité.'),
('jn',17,20,'crampon1923','Je ne prie pas pour eux seulement, mais aussi pour ceux qui, par leur prédication, croiront en moi,'),
('jn',17,21,'crampon1923','pour que tous ils soient un, comme vous, mon Père, vous êtes en moi, et moi en vous, — pour que, eux aussi, ils soient [un] en nous, afin que le monde croie que vous m''avez envoyé.'),
('jn',17,22,'crampon1923','Et je leur ai donné la gloire que vous m''avez donnée, afin qu''ils soient un comme nous sommes un,'),
('jn',17,23,'crampon1923','moi en eux, et vous en moi, afin qu''ils soient parfaitement un, et que le monde connaisse que vous m''avez envoyé, et que vous les avez aimés comme vous m''avez aimé.'),
('jn',17,24,'crampon1923','Père, ceux que vous m''avez donnés, je veux que là où je suis, ils y soient avec moi, afin qu''ils voient la gloire que vous m''avez donnée, parce que vous m''avez aimé avant la création du monde.'),
('jn',17,25,'crampon1923','Père juste, le monde ne vous a pas connu; mais moi, je vous ai connu, et ceux-ci ont connu que c''est vous qui m''avez envoyé.'),
('jn',17,26,'crampon1923','Et je leur ai fait connaître votre nom, et je le leur ferai connaître, afin que l''amour dont vous m''avez aimé soit en eux, et que je sois moi aussi en eux. "'),
('jn',18,1,'crampon1923','Après avoir ainsi parlé, Jésus se rendit, accompagné de ses disciples, au delà du torrent de Cédron, où il y avait un jardin, dans lequel il entra lui et ses disciples.'),
('jn',18,2,'crampon1923','Judas, qui le trahissait, connaissait aussi ce lieu, parce que Jésus y était souvent allé avec ses disciples.'),
('jn',18,3,'crampon1923','Ayant donc pris la cohorte et des satellites fournis par les Pontifes et les Pharisiens, Judas y vint avec des lanternes, des torches et des armes.'),
('jn',18,4,'crampon1923','Alors Jésus, sachant tout ce qui devait lui arriver, s''avança et leur dit: " Qui cherchez-vous? "'),
('jn',18,5,'crampon1923','Ils lui répondirent: " Jésus de Nazareth. — Il leur dit: " Jésus de Nazareth, c''est moi. " Or, Judas, qui le trahissait, était là avec eux.'),
('jn',18,6,'crampon1923','Lors donc que Jésus leur eut dit: " C''est moi, " ils reculèrent et tombèrent par terre.'),
('jn',18,7,'crampon1923','Il leur demanda encore une fois: " Qui cherchez-vous? " Et ils dirent: " Jésus de Nazareth. "'),
('jn',18,8,'crampon1923','Jésus répondit: " Je vous l''ai dit, c''est moi; si donc c''est moi que vous cherchez, laissez aller ceux-ci. "'),
('jn',18,9,'crampon1923','Il dit cela, afin que fût accomplie la parole qu''il avait dite: " Je n''ai perdu aucun de ceux que vous m''avez donnés. "'),
('jn',18,10,'crampon1923','Alors Simon-Pierre, qui avait une épée, la tira, et frappant le serviteur du grand prêtre, il lui coupa l''oreille droite: ce serviteur s''appelait Malchus.'),
('jn',18,11,'crampon1923','Mais Jésus dit à Pierre: " Remets ton épée dans le fourreau. Ne boirai-je donc pas le calice que mon Père m''a donné? "'),
('jn',18,12,'crampon1923','Alors la cohorte, le tribun et les satellites des Juifs se saisirent de Jésus et le lièrent.'),
('jn',18,13,'crampon1923','Ils l''emmenèrent d''abord chez Anne parce qu''il était beau-père de Caïphe, lequel était grand-prêtre cette année-là.'),
('jn',18,14,'crampon1923','Or, Caïphe était celui qui avait donné ce conseil aux Juifs: " Il est avantageux qu''un seul homme meure pour le peuple. "'),
('jn',18,15,'crampon1923','Cependant Simon-Pierre suivait Jésus, avec un autre disciple. Ce disciple, étant connu du grand-prêtre, entra avec Jésus dans la cour du grand-prêtre,'),
('jn',18,16,'crampon1923','mais Pierre était resté près de la porte, en dehors. L''autre disciple, qui était connu du grand-prêtre sortit donc, parla à la portière, et fit entrer Pierre.'),
('jn',18,17,'crampon1923','Cette servante, qui gardait la porte, dit à Pierre: " N''es-tu pas, toi aussi, des disciples de cet homme? " Il dit: " Je n''en suis point. "'),
('jn',18,18,'crampon1923','Les serviteurs et les satellites étaient rangés autour d''un brasier, parce qu''il faisait froid, et ils se chauffaient; Pierre se tenait aussi avec eux, et se chauffait.'),
('jn',18,19,'crampon1923','Le grand-prêtre interrogea Jésus sur ses disciples et sur sa doctrine.'),
('jn',18,20,'crampon1923','Jésus lui répondit: " J''ai parlé ouvertement au monde; j''ai toujours enseigné dans la synagogue et dans le temple, où tous les Juifs s''assemblent, et je n''ai rien dit en secret.'),
('jn',18,21,'crampon1923','Pourquoi m''interroges-tu? Demande à ceux qui m''ont entendu, ce que je leur ai dit; eux, ils savent ce que j''ai enseigné. "'),
('jn',18,22,'crampon1923','A ces mots, un des satellites qui se trouvait là, donna un soufflet à Jésus, en disant: " Est-ce ainsi que tu réponds au grand-prêtre? "'),
('jn',18,23,'crampon1923','Jésus lui répondit: " Si j''ai mal parlé, fais voir ce que j''ai dit de mal; mais si j''ai bien parlé, pourquoi me frappes-tu? "'),
('jn',18,24,'crampon1923','Anne avait envoyé Jésus lié à Caïphe, le grand-prêtre.'),
('jn',18,25,'crampon1923','Or, Simon-Pierre était là, se chauffant. Ils lui dirent: " N''es-tu pas, toi aussi, de ses disciples? " Il le nia et dit: " Je n''en suis point. "'),
('jn',18,26,'crampon1923','Un des serviteurs du grand-prêtre, parent de celui à qui Pierre avait coupé l''oreille, lui dit: " Ne t''ai-je pas vu avec lui dans le jardin? "'),
('jn',18,27,'crampon1923','Pierre nia de nouveau et aussitôt le coq chanta.'),
('jn',18,28,'crampon1923','Ils conduisirent Jésus de chez Caïphe au prétoire: c''était le matin. Mais ils n''entrèrent pas eux-mêmes dans le prétoire, pour ne pas se souiller et afin de pouvoir manger la Pâque.'),
('jn',18,29,'crampon1923','Pilate sortit donc vers eux, et dit: " Quelle accusation portez-vous contre cet homme? "'),
('jn',18,30,'crampon1923','Ils lui répondirent: " Si ce n''était pas un malfaiteur, nous ne te l''aurions pas livré. "'),
('jn',18,31,'crampon1923','Pilate leur dit: " Prenez-le vous-mêmes, et jugez-le selon votre loi. " Les Juifs lui répondirent: " Il ne nous est pas permis de mettre personne à mort ":'),
('jn',18,32,'crampon1923','afin que s''accomplît la parole que Jésus avait dite, lorsqu''il avait indiqué de quelle mort il devait mourir.'),
('jn',18,33,'crampon1923','Pilate étant donc rentré dans le prétoire, appela Jésus, et lui dit: " Es-tu le roi des Juifs? "'),
('jn',18,34,'crampon1923','Jésus répondit: " Dis-tu cela de toi-même, ou d''autres te l''ont-ils dit de moi? "'),
('jn',18,35,'crampon1923','Pilate répondit: " Est-ce que je suis Juif? Ta nation et les chefs des prêtres t''ont livré à moi: qu''as-tu fait? "'),
('jn',18,36,'crampon1923','Jésus répondit: " Mon royaume n''est pas de ce monde; si mon royaume était de ce monde, mes serviteurs auraient combattu pour que je ne fusse pas livré aux Juifs, mais maintenant mon royaume n''est point d''ici-bas. "'),
('jn',18,37,'crampon1923','Pilate lui dit: " Tu es donc roi? " Jésus répondit: " Tu le dis, je suis roi. Je suis né et je suis venu dans le monde pour rendre témoignage à la vérité: quiconque est de la vérité écoute ma voix. "'),
('jn',18,38,'crampon1923','Pilate lui dit: " Qu''est-ce que la vérité? " Ayant dit cela, il sortit de nouveau pour aller vers les Juifs, et il leur dit: " Pour moi, je ne trouve aucun crime en lui.'),
('jn',18,39,'crampon1923','Mais c''est la coutume qu''à la fête de Pâque je vous délivre quelqu''un. Voulez-vous que je vous délivre le roi des Juifs? "'),
('jn',18,40,'crampon1923','Alors tous crièrent de nouveau: " Non pas lui, mais Barabbas. " Or, Barabbas était un brigand.'),
('jn',19,1,'crampon1923','Alors Pilate prit Jésus et le fit flageller.'),
('jn',19,2,'crampon1923','Et les soldats ayant tressé une couronne d''épines, la mirent sur sa tête, et le revêtirent d''un manteau de pourpre;'),
('jn',19,3,'crampon1923','puis, s''approchant de lui, ils disaient: " Salut, roi des Juifs! " et ils le souffletaient.'),
('jn',19,4,'crampon1923','Pilate sortit encore une fois et dit aux Juifs: " Voici que je vous l''amène dehors, afin que vous sachiez que je ne trouve en lui aucun crime. "'),
('jn',19,5,'crampon1923','Jésus sortit donc, portant la couronne d''épines et le manteau d''écarlate; et Pilate leur dit: " Voici l''homme. "'),
('jn',19,6,'crampon1923','Lorsque les Princes des prêtres et les satellites le virent, ils s''écrièrent: " Crucifie-le! crucifie-le! " Pilate leur dit: " Prenez-le vous-mêmes, et crucifiez-le; car, pour moi, je ne trouve aucun crime en lui. "'),
('jn',19,7,'crampon1923','Les Juifs lui répondirent: " Nous avons une loi, et, d''après notre loi, il doit mourir, parce qu''il s''est fait Fils de Dieu. "'),
('jn',19,8,'crampon1923','Ayant entendu ces paroles, Pilate fut encore plus effrayé.'),
('jn',19,9,'crampon1923','Et rentrant dans le prétoire, il dit à Jésus: " D''où es-tu? " Mais Jésus ne lui fit aucune réponse.'),
('jn',19,10,'crampon1923','Pilate lui dit: " C''est à moi que tu ne parles pas? Ignores-tu que j''ai le pouvoir de te délivrer et le pouvoir de te crucifier? "'),
('jn',19,11,'crampon1923','Jésus répondit: " Tu n''aurais sur moi aucun pouvoir, s''il ne t''avait pas été donné d''en haut. C''est pourquoi celui qui m''a livré à toi a un plus grand péché. "'),
('jn',19,12,'crampon1923','Dès ce moment, Pilate cherchait à le délivrer. Mais les Juifs criaient disant: " Si tu le délivres, tu n''es point ami de César; quiconque se fait roi, se déclare contre César. "'),
('jn',19,13,'crampon1923','Pilate, ayant entendu ces paroles, fit conduire Jésus dehors, et il s''assit sur son tribunal, au lieu appelé Lithostrotos, et en hébreu Gabbatha.'),
('jn',19,14,'crampon1923','— C''était la Préparation de la Pâque, et environ la sixième heure. — Pilate dit aux Juifs: " Voici votre roi. "'),
('jn',19,15,'crampon1923','Mais ils se mirent à crier: " Qu''il meure! Qu''il meure! Crucifie-le. " Pilate leur dit: " Crucifierai-je votre roi? " les Princes des prêtres répondirent: " Nous n''avons de roi que César. "'),
('jn',19,16,'crampon1923','Alors il le leur livra pour être crucifié. Et ils prirent Jésus et l''emmenèrent.'),
('jn',19,17,'crampon1923','Jésus, portant sa croix, arriva hors de la ville au lieu nommé Calvaire, en Hébreu Golgotha;'),
('jn',19,18,'crampon1923','c''est là qu''ils le crucifièrent, et deux autres avec lui, un de chaque côté, et Jésus au milieu.'),
('jn',19,19,'crampon1923','Pilate fit aussi une inscription, et la fit mettre au haut de la croix; elle portait ces mots: " Jésus de Nazareth, le roi des Juifs. "'),
('jn',19,20,'crampon1923','Beaucoup de Juifs lurent cet écriteau, car le lieu où Jésus avait été crucifié était près de la ville, et l''inscription était en hébreu, en grec et en latin.'),
('jn',19,21,'crampon1923','Or, les princes des prêtres des Juifs dirent à Pilate: " Ne mets pas: Le roi des Juifs; mais que lui-même a dit: Je suis le roi des Juifs. "'),
('jn',19,22,'crampon1923','Pilate répondit: " Ce que j''ai écrit, je l''ai écrit. "'),
('jn',19,23,'crampon1923','Les soldats, après avoir crucifié Jésus, prirent ses vêtements, et ils en firent quatre parts, une pour chacun d''eux. Ils prirent aussi sa tunique: c''était une tunique sans couture, d''un seul tissu depuis le haut jusqu''en bas.'),
('jn',19,24,'crampon1923','Ils se dirent donc entre eux: " Ne la déchirons pas, mais tirons au sort à qui elle sera ": afin que s''accomplît cette parole de l''Écriture: " Ils se sont partagé mes vêtements, et ils ont tiré ma robe au sort. " C''est ce que firent les soldats.'),
('jn',19,25,'crampon1923','Près de la croix de Jésus se tenaient sa mère et la sœur de sa mère, Marie, femme de Clopas, et Marie-Madeleine.'),
('jn',19,26,'crampon1923','Jésus, ayant vu sa mère, et auprès d''elle le disciple qu''il aimait, dit à sa mère: " Femme, voilà votre fils. "'),
('jn',19,27,'crampon1923','Ensuite il dit au disciple: " Voilà votre mère. " Et depuis cette heure-là, le disciple la prit chez lui.'),
('jn',19,28,'crampon1923','Après cela, Jésus sachant que tout était maintenant consommé, afin que l''Écriture s''accomplît, dit: " J''ai soif. "'),
('jn',19,29,'crampon1923','Il y avait là un vase plein de vinaigre; les soldats en remplirent une éponge, et l''ayant fixée au bout d''une tige d''hysope, ils l''approchèrent de sa bouche.'),
('jn',19,30,'crampon1923','Quand Jésus eut pris le vinaigre, il dit: " Tout est consommé "; et baissant la tête, il rendit l''esprit.'),
('jn',19,31,'crampon1923','Or, comme c''était la Préparation, de peur que les corps ne restassent sur la croix pendant le sabbat, — car le jour de ce sabbat était très solennel, — les Juifs demandèrent à Pilate qu''on rompît les jambes aux crucifiés et qu''on les détachât.'),
('jn',19,32,'crampon1923','Les soldats vinrent donc, et ils rompirent les jambes du premier, puis de l''autre qui avait été crucifié avec lui.'),
('jn',19,33,'crampon1923','Mais quand ils vinrent à Jésus, le voyant déjà mort, ils ne lui rompirent pas les jambes;'),
('jn',19,34,'crampon1923','mais un des soldats lui transperça le côté avec sa lance, et aussitôt il en sortit du sang et de l''eau.'),
('jn',19,35,'crampon1923','Et celui qui l''a vu en rend témoignage, et son témoignage est vrai; et il sait qu''il dit vrai, afin que vous aussi, vous croyiez.'),
('jn',19,36,'crampon1923','Car ces choses sont arrivées afin que l''Écriture fut accomplie: " Aucun de ses os ne sera rompu. "'),
('jn',19,37,'crampon1923','Et il est encore écrit ailleurs: " Ils regarderont celui qu''ils ont transpercé. "'),
('jn',19,38,'crampon1923','Après cela, Joseph d''Arimathie, qui était disciple de Jésus, mais en secret par crainte des Juifs, demanda à Pilate d''enlever le corps de Jésus. Et Pilate le permit. Il vint donc, et prit le corps de Jésus.'),
('jn',19,39,'crampon1923','Nicodème, qui était venu la première fois trouver Jésus de nuit, vint aussi, apportant un mélange de myrrhe et d''aloès, d''environ cent livres.'),
('jn',19,40,'crampon1923','Ils prirent donc le corps de Jésus, et l''enveloppèrent dans des linges, avec les aromates, selon la manière d''ensevelir en usage chez les Juifs.'),
('jn',19,41,'crampon1923','Or, au lieu où Jésus avait été crucifié, il y avait un jardin, et dans le jardin un sépulcre neuf, où personne n''avait encore été mis.'),
('jn',19,42,'crampon1923','C''est là, à cause de la Préparation des Juifs, qu''ils déposèrent Jésus, parce que le sépulcre était proche.'),
('jn',20,1,'crampon1923','Le premier jour de la semaine, Marie-Madeleine se rendit au sépulcre, dès le matin, avant que les ténèbres fussent dissipées, et elle vit la pierre enlevée du sépulcre.'),
('jn',20,2,'crampon1923','Elle courut donc, et vint trouver Simon-Pierre et l''autre disciple que Jésus aimait, et leur dit: " Ils ont enlevé du sépulcre le Seigneur, et nous ne savons où ils l''ont mis. "'),
('jn',20,3,'crampon1923','Pierre sortit avec l''autre disciple, et ils allèrent au sépulcre.'),
('jn',20,4,'crampon1923','Ils couraient tous deux ensemble, mais l''autre disciple courut plus vite que Pierre, et arriva le premier au sépulcre.'),
('jn',20,5,'crampon1923','Et s''étant penché, il vit les linceuls posés à terre; mais il n''entra pas.'),
('jn',20,6,'crampon1923','Simon-Pierre qui le suivait, arriva à son tour et entra dans le sépulcre; il vit les linges posés à terre,'),
('jn',20,7,'crampon1923','et le suaire qui couvrait la tête de Jésus, non pas posé avec les linges, mais roulé dans un autre endroit.'),
('jn',20,8,'crampon1923','Alors l''autre disciple qui était arrivé le premier au sépulcre, entra aussi; et il vit, et il crut:'),
('jn',20,9,'crampon1923','car ils ne comprenaient pas encore l''Ecriture, d''après laquelle il devait ressusciter d''entre les morts.'),
('jn',20,10,'crampon1923','Les disciples s''en retournèrent donc chez eux.'),
('jn',20,11,'crampon1923','Cependant Marie se tenait près du sépulcre, en dehors, versant des larmes; et en pleurant elle se pencha vers le sépulcre;'),
('jn',20,12,'crampon1923','et elle vit deux anges vêtus de blanc, assis à la place où avait été mis le corps de Jésus, l''un à la tête, l''autre aux pieds.'),
('jn',20,13,'crampon1923','Et ceux-ci lui dirent: " Femme, pourquoi pleurez-vous? " Elle leur dit: " Parce qu''ils ont enlevé mon Seigneur, et je ne sais où ils l''ont mis. "'),
('jn',20,14,'crampon1923','Ayant dit ces mots, elle se retourna et vit Jésus debout; et elle ne savait pas que c''était Jésus.'),
('jn',20,15,'crampon1923','Jésus lui dit: " Femme, pourquoi pleurez-vous? Qui cherchez-vous? " Elle, pensant que c''était le jardinier, lui dit: " Seigneur, si c''est vous qui l''avez emporté, dites-moi où vous l''avez mis, et j''irai le prendre. "'),
('jn',20,16,'crampon1923','Jésus lui dit: " Marie! " Elle se retourna et lui dit en hébreu: " Rabboni! " c''est à dire Maître.'),
('jn',20,17,'crampon1923','Jésus lui dit: " Ne me touchez point, car je ne suis pas encore remonté vers mon Père. Mais allez à mes frères, et dites-leur: Je monte vers mon Père et votre Père, vers mon Dieu et votre Dieu. "'),
('jn',20,18,'crampon1923','Marie-Madeleine alla annoncer aux disciples qu''elle avait vu le Seigneur, et qu''il lui avait dit ces choses.'),
('jn',20,19,'crampon1923','Le soir de ce même jour, le premier de la semaine, les portes du lieu où se trouvaient les disciples étant fermées, parce qu''ils craignaient les Juifs, Jésus vint, et se présentant au milieu d''eux, il leur dit: " Paix avec vous! "'),
('jn',20,20,'crampon1923','Ayant ainsi parlé, il leur montra ses mains et son côté. Les disciples furent remplis de joie en voyant le Seigneur.'),
('jn',20,21,'crampon1923','Il leur dit une seconde fois: " Paix avec vous! " Comme mon Père m''a envoyé, moi aussi je vous envoie. "'),
('jn',20,22,'crampon1923','Après ces paroles, il souffla sur eux et leur dit: " Recevez l''Esprit-Saint.'),
('jn',20,23,'crampon1923','Ceux à qui vous remettrez les péchés, ils leur seront remis; et ceux à qui vous les retiendrez, ils leur seront retenus. "'),
('jn',20,24,'crampon1923','Mais Thomas, l''un des douze, celui qu''on appelle Didyme, n''était pas avec eux lorsque Jésus vint.'),
('jn',20,25,'crampon1923','Les autres disciples lui dirent donc: " Nous avons vu le Seigneur. " Mais il leur dit: " Si je ne vois dans ses mains la marque des clous, et si je ne mets mon doigt à la place des clous, et ma main dans son côté, je ne croirai point. "'),
('jn',20,26,'crampon1923','Huit jours après, les disciples étant encore dans le même lieu, et Thomas avec eux, Jésus vint, les portes étant fermées, et se tenant au milieu d''eux, il leur dit: " Paix avec vous! "'),
('jn',20,27,'crampon1923','Puis il dit à Thomas: " Mets ici ton doigt, et regarde mes mains; approche aussi ta main, et mets-la dans mon côté; et ne sois pas incrédule, mais croyant. "'),
('jn',20,28,'crampon1923','Thomas lui répondit: " Mon Seigneur, et mon Dieu! "'),
('jn',20,29,'crampon1923','Jésus lui dit: " Parce que tu m''as vu, [Thomas,] tu as cru. Heureux ceux qui n''ont pas vu et qui ont cru. "'),
('jn',20,30,'crampon1923','Jésus a fait encore, en présence de ses disciples, beaucoup d''autres miracles qui ne sont pas écrits dans ce livre.'),
('jn',20,31,'crampon1923','Mais ceux-ci ont été écrits, afin que vous croyiez que Jésus est le Christ, le Fils de Dieu, et qu''en croyant vous ayez la vie en son nom.'),
('jn',21,1,'crampon1923','Après cela, Jésus se montra de nouveau à ses disciples sur les bords de la mer de Tibériade: et il se montra ainsi:'),
('jn',21,2,'crampon1923','Simon-Pierre, Thomas appelé Didyme, Nathanaël, qui était de Cana en Galilée, les fils de Zébédée et deux autres de ses disciples, étaient ensemble.'),
('jn',21,3,'crampon1923','Simon-Pierre leur dit: " Je vais pêcher. " Ils lui dirent: " Nous y allons nous aussi avec toi. " Ils sortirent donc et montèrent dans la barque; mais ils ne prirent rien cette nuit-là.'),
('jn',21,4,'crampon1923','Le matin venu, Jésus se trouva sur le rivage; mais les disciples ne savaient pas que c''était Jésus.'),
('jn',21,5,'crampon1923','Et Jésus leur dit: " Enfants, n''avez-vous rien à manger? " — Non, répondirent-ils.'),
('jn',21,6,'crampon1923','Il leur dit: " Jetez le filet à droite de la barque, et vous trouverez. " Ils le jetèrent; et ils ne pouvaient plus le tirer à cause de la grande quantité de poissons.'),
('jn',21,7,'crampon1923','Alors le disciple que Jésus aimait dit à Pierre: " C''est le Seigneur! " Simon-Pierre, ayant entendu que c''était le Seigneur, mit son vêtement et sa ceinture, car il était nu, et se jeta dans la mer.'),
('jn',21,8,'crampon1923','Les autres disciples vinrent avec la barque (car ils n''étaient éloignés de la terre que d''environ deux cents coudées), en tirant le filet plein de poissons.'),
('jn',21,9,'crampon1923','Quand ils furent descendus à terre, ils virent là des charbons allumés, du poisson mis dessus, et du pain.'),
('jn',21,10,'crampon1923','Jésus leur dit: " Apportez de ces poissons que vous venez de prendre. "'),
('jn',21,11,'crampon1923','Simon-Pierre monta dans la barque, et tira à terre le filet qui était plein de cent cinquante-trois grands poissons; et quoiqu''il y en eût un si grand nombre, le filet ne se rompit point.'),
('jn',21,12,'crampon1923','Jésus leur dit: " Venez et mangez. " Et aucun des disciples n''osait lui demander: " Qui êtes-vous? " parce qu''ils savaient que c''était le Seigneur.'),
('jn',21,13,'crampon1923','Jésus s''approcha, et prenant le pain, il leur en donna; il fit de même du poisson.'),
('jn',21,14,'crampon1923','C''était déjà la troisième fois que Jésus apparaissait à ses disciples, depuis qu''il était ressuscité des morts.'),
('jn',21,15,'crampon1923','Lorsqu''ils eurent mangé, Jésus dit à Simon-Pierre: " Simon, fils de Jean, m''aimes-tu plus que ceux-ci? " Il lui répondit: " Oui, Seigneur, vous savez que je vous aime. " Jésus lui dit: " Pais mes agneaux. "'),
('jn',21,16,'crampon1923','Il lui dit une seconde fois: " Simon, fils de Jean, m''aimes-tu? " Pierre lui répondit: " Oui, Seigneur, vous savez bien que je vous aime. " Jésus lui dit: " Pais mes agneaux. "'),
('jn',21,17,'crampon1923','Il lui dit pour la troisième fois: " Simon, fils de Jean, m''aimes-tu? " Pierre fut contristé de ce que Jésus lui demandait pour la troisième fois: " M''aimes-tu? " et il lui répondit: " Seigneur, vous connaissez toutes choses, vous savez bien que je vous aime. " Jésus lui dit: " Pais mes brebis.'),
('jn',21,18,'crampon1923','En vérité, en vérité, je te le dis, quand tu étais plus jeune, tu te ceignais toi-même, et tu allais où tu voulais; mais quand tu seras vieux, tu étendras les mains, et un autre te ceindra, et te mènera où tu ne voudras pas. "'),
('jn',21,19,'crampon1923','— Il dit cela, indiquant par quelle mort Pierre devait glorifier Dieu. — Et après avoir ainsi parlé, il ajouta: " Suis-moi. "'),
('jn',21,20,'crampon1923','Pierre, s''étant retourné, vit venir derrière lui, le disciple que Jésus aimait, celui qui, pendant la cène, s''était penché sur son sein, et lui avait dit: " Seigneur, qui est celui qui vous trahit? "'),
('jn',21,21,'crampon1923','Pierre donc, l''ayant vu, dit à Jésus: " Seigneur, et celui-ci que deviendra-t-il? "'),
('jn',21,22,'crampon1923','Jésus lui dit: " Si je veux qu''il demeure jusqu''à ce que je vienne, que t''importe? Toi, suis-moi. "'),
('jn',21,23,'crampon1923','Le bruit courut donc parmi les frères que ce disciple ne mourrait point. Pourtant Jésus ne lui avait pas dit qu''il ne mourrait pas; mais: " Si je veux qu''il demeure jusqu''à ce que je vienne, que t''importe? "'),
('jn',21,24,'crampon1923','C''est ce même disciple qui rend témoignage de ces choses et qui les a écrites; et nous savons que son témoignage est vrai.'),
('jn',21,25,'crampon1923','Jésus a fait encore beaucoup d''autres choses; si on les rapportait en détail, je ne pense pas que le monde entier pût contenir les livres qu''il faudrait écrire.'),
('ac',1,1,'crampon1923','Théophile, j''ai raconté, dans mon premier livre, toute la suite des actions et des enseignements de Jésus,'),
('ac',1,2,'crampon1923','jusqu''au jour où, après avoir donné, par l''Esprit-Saint, ses instructions aux Apôtres qu''il avait choisis, il fut enlevé au ciel.'),
('ac',1,3,'crampon1923','A eux aussi, après sa passion, il s''était montré plein de vie, leur en donnant des preuves nombreuses, leur apparaissant pendant quarante jours, et les entretenant du royaume de Dieu.'),
('ac',1,4,'crampon1923','Un jour qu''il était à table avec eux, il leur recommanda de ne pas s''éloigner de Jérusalem, mais d''attendre ce que le Père avait promis, " ce que, leur dit-il, vous avez appris de ma bouche;'),
('ac',1,5,'crampon1923','car Jean a baptisé dans l''eau, mais vous, sous peu de jours, vous serez baptisés dans l''Esprit-Saint. "'),
('ac',1,6,'crampon1923','Eux donc, étant réunis, lui demandèrent: " Seigneur, le temps est-il venu où vous rétablirez le royaume d''Israël? "'),
('ac',1,7,'crampon1923','Il leur répondit: " Ce n''est pas à vous de connaître les temps ni les moments que le Père a fixés de sa propre autorité.'),
('ac',1,8,'crampon1923','Mais lorsque le Saint-Esprit descendra sur vous, vous serez revêtus de force et vous me rendrez témoignage à Jérusalem, dans toute la Judée, dans la Samarie, et jusqu''aux extrémités de la terre. "'),
('ac',1,9,'crampon1923','Après qu''il eut ainsi parlé, il fut élevé en leur présence, et une nuée le déroba à leurs yeux.'),
('ac',1,10,'crampon1923','Et comme ils avaient leurs regards fixés vers le ciel pendant qu''il s''éloignait, voici que deux hommes parurent auprès d''eux, vêtus de blanc,'),
('ac',1,11,'crampon1923','et dirent: " Hommes de Galilée, pourquoi vous arrêtez-vous à regarder au ciel? Ce Jésus qui, du milieu de vous, a été enlevé au ciel, en viendra de la même manière que vous l''avez vu monter. "'),
('ac',1,12,'crampon1923','Ils revinrent alors à Jérusalem, de la montagne appelée des Oliviers, laquelle est près de Jérusalem, à la distance du chemin d''un jour de sabbat.'),
('ac',1,13,'crampon1923','Quand ils furent arrivés, ils montèrent dans le cénacle, où ils se tenaient d''ordinaire: c''étaient Pierre et Jean, Jacques et André, Philippe et Thomas, Barthélemy et Matthieu, Jacques, fils d''Alphée, et Simon le Zélé, et Jude, frère de Jacques.'),
('ac',1,14,'crampon1923','Tous, dans un même esprit, persévéraient dans la prière, avec quelques femmes et Marie, mère de Jésus, et ses frères.'),
('ac',1,15,'crampon1923','En ces jours-là, Pierre se levant au milieu des frères (ils étaient réunis au nombre d''environ cent vingt), leur dit:'),
('ac',1,16,'crampon1923','" Mes frères, il fallait que s''accomplît ce que le Saint-Esprit, dans l''Ecriture, a prédit par la bouche de David au sujet de Judas, le guide de ceux qui ont arrêté Jésus;'),
('ac',1,17,'crampon1923','car il était un d''entre nous, et il avait part à notre ministère.'),
('ac',1,18,'crampon1923','(Cet homme acquit un champ avec le salaire de son crime, et s''étant précipité en avant, se rompit par le milieu, et toutes ses entrailles se répandirent.'),
('ac',1,19,'crampon1923','Ce fait est si connu de tous les habitants de Jérusalem, que ce champ a été nommé dans leur langue Haceldama, c''est-à-dire champ du sang.)'),
('ac',1,20,'crampon1923','Il est écrit, en effet, dans le livre des Psaumes: Que sa demeure devienne déserte, et que personne ne l''habite! Et ailleurs: Qu''un autre prenne sa charge!'),
('ac',1,21,'crampon1923','Il faut donc que, parmi les hommes qui nous ont accompagnés tout le temps que le Seigneur Jésus a vécu avec nous,'),
('ac',1,22,'crampon1923','à partir du baptême de Jean jusqu''au jour où il a été enlevé du milieu de nous, il y en ait un qui devienne avec nous témoin de sa résurrection. "'),
('ac',1,23,'crampon1923','Ils en présentèrent deux: Joseph, appelé Barsabas et surnommé le juste, et Mathias.'),
('ac',1,24,'crampon1923','Et s''étant mis en prière, ils dirent: " Seigneur, vous qui connaissez le cœur de tous, indiquez lequel de ces deux vous avez choisi'),
('ac',1,25,'crampon1923','pour occuper dans ce ministère de l''apostolat, la place que Judas a laissée par son crime pour s''en aller en son lieu. "'),
('ac',1,26,'crampon1923','On tira leurs noms au sort: et le sort tomba sur Mathias, qui fut associé aux onze Apôtres.'),
('ac',2,1,'crampon1923','Le jour de la Pentecôte étant arrivé, ils étaient tous ensemble en un même lieu.'),
('ac',2,2,'crampon1923','Tout à coup il vint du ciel un bruit comme celui d''un vent qui souffle avec force et il remplit toute la maison où ils étaient assis.'),
('ac',2,3,'crampon1923','Et ils virent paraître comme des langues de feu qui se partagèrent et se posèrent sur chacun d''eux.'),
('ac',2,4,'crampon1923','Ils furent tous remplis du Saint-Esprit, et ils se mirent à parler d''autres langues, selon que l''Esprit-Saint leur donnait de s''exprimer.'),
('ac',2,5,'crampon1923','Or, parmi les Juifs résidant à Jérusalem, il y avait des hommes pieux de toutes les nations qui sont sous le ciel.'),
('ac',2,6,'crampon1923','Au bruit qui se fit entendre, ils accoururent en foule, et ils étaient tout hors d''eux-mêmes, de ce que chacun les entendait parler sa propre langue.'),
('ac',2,7,'crampon1923','Surpris et étonnés, il disaient: " Ces gens qui parlent, ne sont-ils pas tous Galiléens?'),
('ac',2,8,'crampon1923','Comment se fait-il que nous les entendions parler chacun l''idiome particulier de notre pays natal?'),
('ac',2,9,'crampon1923','Nous tous, Parthes, Mèdes, Elamites, habitants de la Mésopotamie, de la Judée et de la Cappadoce, du Pont et de l''Asie,'),
('ac',2,10,'crampon1923','de la Phrygie et de la Pamphylie, de l''Egypte et des contrées de la Lybie voisine de Cyrène, Romains de passage ici,'),
('ac',2,11,'crampon1923','soit Juifs, soit prosélytes, Crétois et Arabes, nous les entendons annoncer dans nos langues les merveilles de Dieu. "'),
('ac',2,12,'crampon1923','Ils étaient tous dans l''étonnement, et, ne sachant que penser, ils se disaient les uns aux autres: " Qu''est-ce que cela pourrait bien être? "'),
('ac',2,13,'crampon1923','D''autres disaient en se moquant: " Ils sont pleins de vin nouveau. "'),
('ac',2,14,'crampon1923','Alors Pierre, se présentant avec les Onze, éleva la voix et leur dit: " Juifs, et vous tous qui séjournez à Jérusalem, sachez bien ceci, et prêtez l''oreille à mes paroles:'),
('ac',2,15,'crampon1923','Ces hommes ne sont pas ivres, comme vous le supposez, car c''est la troisième heure du jour.'),
('ac',2,16,'crampon1923','Ce que vous voyez, c''est ce qui a été annoncé par le prophète Joël:'),
('ac',2,17,'crampon1923','" Dans les derniers jours, dit le Seigneur, je répandrai de mon Esprit sur toute chair, et vos fils ainsi que vos filles prophétiseront, et vos jeunes gens auront des visions, et vos vieillards des songes.'),
('ac',2,18,'crampon1923','Oui, dans ces jours-là, je répandrai de mon Esprit sur mes serviteurs et sur mes servantes, et ils prophétiseront.'),
('ac',2,19,'crampon1923','Et je ferai paraître des prodiges en haut dans le ciel, et des miracles en bas sur la terre: du sang, du feu, et des tourbillons de fumée;'),
('ac',2,20,'crampon1923','le soleil se changera en ténèbres, et la lune en sang, avant que vienne le jour du Seigneur, le jour grand et glorieux.'),
('ac',2,21,'crampon1923','Alors quiconque invoquera le nom du Seigneur sera sauvé. —'),
('ac',2,22,'crampon1923','Enfants d''Israël, écoutez ces paroles: Jésus de Nazareth, cet homme à qui Dieu a rendu témoignage pour vous par les prodiges, les miracles et les signes qu''il a opérés par lui au milieu de vous, comme vous le savez vous-mêmes;'),
('ac',2,23,'crampon1923','cet homme ayant été livré selon le dessein immuable et la prescience de Dieu, vous l''avez attaché à la croix et mis à mort par la main des impies.'),
('ac',2,24,'crampon1923','Dieu l''a ressuscité, en le délivrant des douleurs de la mort, parce qu''il n''était pas possible qu''il fût retenu par elle.'),
('ac',2,25,'crampon1923','Car David dit de lui: " J''avais continuellement le Seigneur devant moi, parce qu''il est à ma droite, afin que je ne sois point ébranlé.'),
('ac',2,26,'crampon1923','C''est pourquoi mon cœur est dans la joie, et ma langue dans l''allégresse, et ma chair aussi reposera dans l''espérance;'),
('ac',2,27,'crampon1923','car vous ne laisserez pas mon âme dans le séjour des morts, et vous ne permettrez pas que votre Saint voie la corruption.'),
('ac',2,28,'crampon1923','Vous m''avez fait connaître les sentiers de la vie, et vous me remplirez de joie en me montrant votre visage. "'),
('ac',2,29,'crampon1923','Mes frères, qu''il me soit permis de vous dire en toute franchise, au sujet du patriarche David, qu''il est mort, qu''il a été enseveli, et que son sépulcre est encore aujourd''hui parmi nous.'),
('ac',2,30,'crampon1923','Comme il était prophète, et qu''il savait que Dieu lui avait promis avec serment de faire asseoir sur son trône un fils de son sang,'),
('ac',2,31,'crampon1923','c''est la résurrection du Christ qu''il a vue d''avance, en disant que son âme ne serait pas laissée dans le séjour des morts, et que sa chair ne verrait pas la corruption.'),
('ac',2,32,'crampon1923','C''est ce Jésus que Dieu a ressuscité; nous en sommes tous témoins.'),
('ac',2,33,'crampon1923','Et maintenant qu''il a été élevé au ciel par la droite de Dieu, et qu''il a reçu du Père la promesse du Saint-Esprit, il a répandu cet Esprit que vous voyez et entendez.'),
('ac',2,34,'crampon1923','Car David n''est pas monté au ciel; mais il a dit lui-même: " Le Seigneur a dit à mon Seigneur: Asseyez-vous à ma droite,'),
('ac',2,35,'crampon1923','jusqu''à ce que je fasse de vos ennemis l''escabeau de vos pieds. "'),
('ac',2,36,'crampon1923','Que toute la maison d''Israël sache donc avec certitude que Dieu a fait Seigneur et Christ ce Jésus que vous avez crucifié. "'),
('ac',2,37,'crampon1923','Le cœur transpercé par ce discours, ils dirent à Pierre et aux autres apôtres: " Frères, que ferons-nous? "'),
('ac',2,38,'crampon1923','Pierre leur répondit: " Repentez-vous, et que chacun de vous soit baptisé au nom de Jésus-Christ pour obtenir le pardon de vos péchés; et vous recevrez le don du Saint-Esprit.'),
('ac',2,39,'crampon1923','Car la promesse est pour vous, pour vos enfants, et pour tous ceux qui sont au loin, en aussi grand nombre que le Seigneur notre Dieu les appellera. "'),
('ac',2,40,'crampon1923','Et par beaucoup d''autres paroles il les pressait et les exhortait en disant: " Sauvez-vous du milieu de cette génération perverse. "'),
('ac',2,41,'crampon1923','Ceux qui reçurent la parole de Pierre furent baptisés; et ce jour-là le nombre des disciples s''augmenta de trois mille personnes environ.'),
('ac',2,42,'crampon1923','Ils étaient assidus aux prédications des Apôtres, aux réunions communes, à la fraction du pain et aux prières.'),
('ac',2,43,'crampon1923','Et la crainte était dans toutes les âmes, et beaucoup de prodiges et de miracles se faisaient par les Apôtres.'),
('ac',2,44,'crampon1923','Tous ceux qui croyaient vivaient ensemble, et ils avaient tout en commun.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ac',2,45,'crampon1923','Ils vendaient leurs terres et leurs biens, et ils en partageaient le prix entre tous, selon les besoins de chacun.'),
('ac',2,46,'crampon1923','Chaque jour, tous ensemble, ils fréquentaient le temple, et, rompant leur pain dans leurs maisons, ils prenaient leur nourriture avec joie et simplicité,'),
('ac',2,47,'crampon1923','louant Dieu et ayant la faveur de tout le peuple. Et le Seigneur ajoutait chaque jour au nombre de ceux qui étaient dans la voie du salut.'),
('ac',3,1,'crampon1923','Pierre et Jean montaient (ensemble) au temple pour la prière de la neuvième heure.'),
('ac',3,2,'crampon1923','Or, il y avait un homme, boiteux de naissance, qui se faisait transporter. On le posait chaque jour près de la porte du temple, appelée la Belle-Porte, pour qu''il pût demander l''aumône à ceux qui entraient dans le temple.'),
('ac',3,3,'crampon1923','Cet homme, ayant vu Pierre et Jean qui allaient y entrer, leur demanda l''aumône.'),
('ac',3,4,'crampon1923','Pierre, ainsi que Jean, fixa les yeux sur lui et dit: " Regarde-nous. "'),
('ac',3,5,'crampon1923','Il les regarda attentivement, s''attendant à recevoir d''eux quelque chose.'),
('ac',3,6,'crampon1923','Mais Pierre lui dit: " Je n''ai ni or ni argent; mais ce que j''ai, je te le donne: au nom de Jésus-Christ de Nazareth, lève-toi et marche. "'),
('ac',3,7,'crampon1923','Et le prenant par la main, il l''aida à se lever. Au même instant, ses jambes et ses pieds devinrent fermes;'),
('ac',3,8,'crampon1923','d''un bond il fut debout, et il se mit à marcher. Puis il entra avec eux dans le temple, marchant, sautant et louant Dieu.'),
('ac',3,9,'crampon1923','Tout le peuple le vit marcher et louer Dieu.'),
('ac',3,10,'crampon1923','Et reconnaissant que c''était celui-là même qui se tenait assis à la Belle-Porte du temple pour demander l''aumône, ils furent stupéfaits et hors d''eux-mêmes de ce qui lui était arrivé.'),
('ac',3,11,'crampon1923','Comme il ne quittait pas Pierre et Jean, tout le peuple étonné accourut vers eux, au portique dit de Salomon.'),
('ac',3,12,'crampon1923','Voyant cela, Pierre dit au peuple: " Enfants d''Israël, pourquoi vous étonnez-vous de cela? Et pourquoi tenez-vous les yeux fixés sur nous, comme si c''était par notre propre puissance ou par notre piété que nous eussions fait marcher cet homme?'),
('ac',3,13,'crampon1923','Le Dieu d''Abraham, d''Isaac et de Jacob, le Dieu de vos pères a glorifié son serviteur Jésus, que vous avez livré, et renié devant Pilate alors qu''il était d''avis qu''on le relâchât.'),
('ac',3,14,'crampon1923','Vous, vous avez renié le Saint et le Juste, et vous avez sollicité la grâce d''un meurtrier.'),
('ac',3,15,'crampon1923','Vous avez fait mourir l''Auteur de la vie, que Dieu a ressuscité des morts; nous en sommes tous témoins.'),
('ac',3,16,'crampon1923','C''est à cause de la foi reçue de lui que son nom a raffermi l''homme que vous voyez et connaissez; c''est la foi qui vient de lui qui a opéré devant vous tous cette parfaite guérison.'),
('ac',3,17,'crampon1923','Je sais bien, frères, que vous avez agi par ignorance, ainsi que vos magistrats.'),
('ac',3,18,'crampon1923','Mais Dieu a accompli de la sorte ce qu''il avait prédit par la bouche de tous les prophètes, que son Christ devait souffrir.'),
('ac',3,19,'crampon1923','Repentez-vous donc et convertissez-vous, pour que vos péchés soient effacés,'),
('ac',3,20,'crampon1923','afin que des temps de rafraîchissement viennent de la part du Seigneur, et qu''il envoie celui qui vous a été destiné, Jésus-Christ,'),
('ac',3,21,'crampon1923','que le ciel doit recevoir jusqu''aux jours du rétablissement de toutes choses, jours dont Dieu a parlé anciennement par la bouche de ses saints prophètes.'),
('ac',3,22,'crampon1923','Moïse a dit: " Le Seigneur votre Dieu vous suscitera d''entre vos frères un prophète semblable à moi; vous l''écouterez dans tout ce qu''il vous dira.'),
('ac',3,23,'crampon1923','Et quiconque n''écoutera pas ce prophète, sera exterminé du milieu du peuple. " —'),
('ac',3,24,'crampon1923','Tous les prophètes qui ont successivement parlé depuis Samuel ont aussi annoncé ces jours-là.'),
('ac',3,25,'crampon1923','Vous êtes, vous, les fils des prophètes et de l''alliance que Dieu a faite avec vos pères, lorsqu''il a dit à Abraham: " En ta postérité seront bénies toutes les nations de la terre. "'),
('ac',3,26,'crampon1923','C''est à vous premièrement que Dieu, ayant suscité son Fils, l''a envoyé pour vous bénir, lorsque chacun de vous se détournera de ses iniquités.'),
('ac',4,1,'crampon1923','Pendant que Pierre et Jean parlaient au peuple, survinrent les prêtres, le capitaine du temple et les Sadducéens,'),
('ac',4,2,'crampon1923','mécontents de ce qu''ils enseignaient le peuple et annonçaient en la personne de Jésus la résurrection des morts.'),
('ac',4,3,'crampon1923','Ils mirent la main sur eux, et ils les jetèrent en prison jusqu''au lendemain; car il était déjà soir.'),
('ac',4,4,'crampon1923','Cependant beaucoup de ceux qui avaient entendu ce discours crurent, et le nombre des hommes s''éleva à environ cinq mille.'),
('ac',4,5,'crampon1923','Le lendemain, leurs chefs, les Anciens et les Scribes, s''assemblèrent à Jérusalem,'),
('ac',4,6,'crampon1923','avec Anne, le grand prêtre, Caïphe, Jean, Alexandre, et tous ceux qui étaient de la famille pontificale.'),
('ac',4,7,'crampon1923','Et ayant fait comparaître les Apôtres devant eux, ils leur demandèrent: " Par quelle puissance ou au nom de qui avez-vous fait cela? "'),
('ac',4,8,'crampon1923','Alors Pierre, rempli du Saint-Esprit, leur dit: " Chefs du peuple et Anciens d''Israël:'),
('ac',4,9,'crampon1923','si l''on nous interroge aujourd''hui, sur un bienfait accordé à un infirme, pour savoir comment cet homme a été guéri,'),
('ac',4,10,'crampon1923','sachez-le bien, vous tous, et tout le peuple d''Israël: C''est par le nom de Jésus-Christ de Nazareth, que vous avez crucifié et que Dieu a ressuscité des morts, c''est par lui que cet homme se présente devant vous pleinement guéri.'),
('ac',4,11,'crampon1923','Ce Jésus est la pierre rejetée par vous de l''édifice, et qui est devenue la pierre angulaire.'),
('ac',4,12,'crampon1923','Et le salut n''est en aucun autre; car il n''y a pas sous le ciel un autre nom qui ait été donné aux hommes, par lequel nous devions être sauvés. "'),
('ac',4,13,'crampon1923','Lorsqu''ils virent l''assurance de Pierre et de Jean, sachant que c''étaient des hommes du peuple sans instruction, ils furent étonnés; ils les reconnurent en même temps pour avoir été avec Jésus.'),
('ac',4,14,'crampon1923','Mais, comme ils voyaient debout, près d''eux, l''homme qui avait été guéri, ils n''avaient rien à répliquer.'),
('ac',4,15,'crampon1923','Les ayant fait sortir du sanhédrin, ils se mirent à délibérer entre eux,'),
('ac',4,16,'crampon1923','disant: " Que ferons-nous à ces hommes? Qu''ils aient fait un miracle insigne, c''est ce qui est manifeste pour tous les habitants de Jérusalem, et nous ne pouvons le nier.'),
('ac',4,17,'crampon1923','Mais afin que la chose ne se répande pas davantage parmi le peuple, défendons-leur avec menaces de parler désormais en ce nom-là à qui que ce soit. "'),
('ac',4,18,'crampon1923','Et les ayant rappelés, ils leur interdirent absolument de parler et d''enseigner au nom de Jésus.'),
('ac',4,19,'crampon1923','Pierre et Jean leur répondirent: " Jugez s''il est juste devant Dieu de vous obéir plutôt qu''à Dieu.'),
('ac',4,20,'crampon1923','Pour nous, nous ne pouvons pas ne pas dire ce que nous avons vu et entendu. "'),
('ac',4,21,'crampon1923','Alors ils leur firent des menaces et les relâchèrent, ne sachant comment les punir, à cause du peuple, parce que tous glorifiaient Dieu de tout ce qui venait d''arriver.'),
('ac',4,22,'crampon1923','Car l''homme qui avait été guéri d''une manière si merveilleuse était âgé de plus de quarante ans.'),
('ac',4,23,'crampon1923','Mis en liberté, ils se rendirent auprès de leurs frères et leur racontèrent tout ce que les Princes des prêtres et les Anciens leur avaient dit.'),
('ac',4,24,'crampon1923','Ce qu''ayant entendu, les frères élevèrent tous ensemble la voix vers Dieu, en disant: " Maître souverain, c''est vous qui avez fait le ciel, la terre, la mer et tout ce qu''ils renferment.'),
('ac',4,25,'crampon1923','C''est vous qui avez dit [par l''Esprit-Saint], par la bouche de [notre père] David, votre serviteur: " Pourquoi les nations ont-elles frémi, et les peuples ont-ils formé de vains complots?'),
('ac',4,26,'crampon1923','Les rois de la terre se sont soulevés; les princes se sont ligués contre le Seigneur et contre son Christ. " —'),
('ac',4,27,'crampon1923','Voici qu''en vérité, dans cette ville, se sont ligués contre votre saint serviteur, Jésus, consacré par votre onction, Hérode et Ponce-Pilate avec les gentils et les peuples d''Israël,'),
('ac',4,28,'crampon1923','pour faire ce que votre main et votre conseil avaient arrêté d''avance.'),
('ac',4,29,'crampon1923','Et maintenant, Seigneur, considérez leurs menaces, et donnez à vos serviteurs d''annoncer votre parole avec une pleine assurance,'),
('ac',4,30,'crampon1923','en étendant votre main pour qu''il se fasse des guérisons, des miracles et des prodiges, par le nom de votre saint serviteur Jésus. "'),
('ac',4,31,'crampon1923','Quand ils eurent prié, le lieu où ils étaient réunis trembla: ils furent tous remplis du Saint-Esprit, et ils annoncèrent la parole de Dieu avec assurance.'),
('ac',4,32,'crampon1923','La multitude des fidèles n''avait qu''un cœur et qu''une âme; nul n''appelait sien ce qu''il possédait, mais tout était commun entre eux.'),
('ac',4,33,'crampon1923','Avec beaucoup de force les apôtres rendaient témoignage de la résurrection du Sauveur Jésus, et une grande grâce était sur eux tous.'),
('ac',4,34,'crampon1923','Car il n''y avait parmi eux aucun indigent: tous ceux qui possédaient des terres ou des maisons les vendaient'),
('ac',4,35,'crampon1923','et en apportaient le prix aux pieds des Apôtres; on le distribuait ensuite à chacun, selon ses besoins.'),
('ac',4,36,'crampon1923','Un lévite originaire de Chypre, Joseph, surnommé par les apôtres Barnabé (ce qui se traduit Fils de consolation),'),
('ac',4,37,'crampon1923','possédait un champ; il le vendit, en apporta l''argent et le déposa aux pieds des Apôtres.'),
('ac',5,1,'crampon1923','Mais un homme nommé Ananie, avec Saphire, sa femme, vendit une propriété,'),
('ac',5,2,'crampon1923','et ayant, de concert avec elle, retenu quelque chose du prix, il en apporta le reste et le mit aux pieds des Apôtres.'),
('ac',5,3,'crampon1923','Pierre lui dit: " Ananie, pourquoi Satan a-t-il rempli ton cœur au point que tu mentes au Saint-Esprit et que tu retiennes quelque chose du prix de ce champ?'),
('ac',5,4,'crampon1923','Ne pouvais-tu pas sans le vendre, en rester possesseur? et après l''avoir vendu, n''étais-tu pas maître de l''argent? Comment as-tu pu concevoir un pareil dessein? Ce n''est pas à des hommes que tu as menti, mais à Dieu. "'),
('ac',5,5,'crampon1923','En entendant ces paroles, Ananie tomba et expira, et tous ceux qui l''apprirent furent saisis d''une grande crainte.'),
('ac',5,6,'crampon1923','Les jeunes gens s''étant levés enveloppèrent le corps et l''emportèrent pour l''inhumer.'),
('ac',5,7,'crampon1923','Environ trois heures après, la femme d''Ananie entra, sans savoir ce qui était arrivé.'),
('ac',5,8,'crampon1923','Pierre lui demanda: " Dites-moi, est-ce tel prix que vous avez vendu votre champ? " — " Oui, répondit-elle, c''est ce prix-là. "'),
('ac',5,9,'crampon1923','Alors Pierre lui dit: " Comment vous êtes-vous accordés pour tenter l''Esprit du Seigneur? Voici que le pied des jeunes gens qui ont enterré votre mari heurte le seuil; ils vont aussi vous porter en terre. "'),
('ac',5,10,'crampon1923','Au même instant, elle tomba aux pieds de l''Apôtre, et expira. Les jeunes gens étant entrés la trouvèrent morte; ils l''emportèrent et l''inhumèrent auprès de son mari.'),
('ac',5,11,'crampon1923','Une grande crainte se répandit dans toute l''Eglise et parmi tous ceux qui apprirent cet événement.'),
('ac',5,12,'crampon1923','Beaucoup de miracles et de prodiges se faisaient parmi le peuple par les mains des Apôtres. Et ils se tenaient tous ensemble sous le portique de Salomon;'),
('ac',5,13,'crampon1923','aucune autre personne n''osait se joindre à eux, mais le peuple les louait hautement.'),
('ac',5,14,'crampon1923','Chaque jour voyait s''accroître la multitude d''hommes et de femmes qui croyaient au Seigneur,'),
('ac',5,15,'crampon1923','en sorte qu''on apportait les malades dans les rues, et qu''on les plaçait sur des lits ou des nattes, afin que, lorsque Pierre passerait, son ombre au moins couvrît quelqu''un d''entre eux.'),
('ac',5,16,'crampon1923','On venait ainsi en foule des villes voisines à Jérusalem, amenant des malades et des hommes tourmentés par des esprits impurs, et tous étaient guéris.'),
('ac',5,17,'crampon1923','Alors le grand prêtre et tous ses adhérents, savoir le parti des Sadducéens, se levèrent, remplis de jalousie;'),
('ac',5,18,'crampon1923','et ayant fait arrêter les Apôtres, ils les jetèrent dans une prison publique.'),
('ac',5,19,'crampon1923','Mais un ange du Seigneur, ayant ouvert pendant la nuit les portes de la prison, les fit sortir en disant:'),
('ac',5,20,'crampon1923','" Allez, tenez-vous dans le temple, et annoncez au peuple toutes ces paroles de vie. "'),
('ac',5,21,'crampon1923','Ce qu''ayant entendu, ils entrèrent dès le matin dans le temple, et se mirent à enseigner. Cependant le grand prêtre et ses adhérents s''étant réunis, assemblèrent le conseil et tous les Anciens des enfants d''Israël, et ils envoyèrent à la prison chercher les Apôtres.'),
('ac',5,22,'crampon1923','Les satellites allèrent, et ne les ayant pas trouvés dans la prison, ils revinrent et firent leur rapport,'),
('ac',5,23,'crampon1923','en disant: " Nous avons trouvé la prison soigneusement fermée, et les gardes debout devant les portes; mais après avoir ouvert, nous n''avons trouvé personne à l''intérieur. "'),
('ac',5,24,'crampon1923','Quand le grand prêtre, le commandant du temple et les princes des prêtres eurent entendu ces paroles, ils furent dans une grande perplexité au sujet des prisonniers, ne sachant ce que ce pouvait être.'),
('ac',5,25,'crampon1923','En ce moment quelqu''un vint leur dire: " Ceux que vous aviez mis en prison, les voilà dans le temple et ils enseignent le peuple. "'),
('ac',5,26,'crampon1923','Le commandant se rendit aussitôt avec ses agents, et les amena sans leur faire violence, car ils craignaient d''être lapidés par le peuple.'),
('ac',5,27,'crampon1923','Les ayant amenés, il les firent comparaître devant le Sanhédrin, et le grand prêtre les interrogea,'),
('ac',5,28,'crampon1923','en disant: " Nous vous avons expressément défendu d''enseigner ce nom-là, et voilà que vous avez rempli Jérusalem de votre doctrine, et vous voulez faire retomber sur nous le sang de cet homme! "'),
('ac',5,29,'crampon1923','Pierre et les Apôtres répondirent: " On doit obéir à Dieu plutôt qu''aux hommes.'),
('ac',5,30,'crampon1923','Le Dieu de nos pères a ressuscité Jésus, que vous avez fait mourir en le pendant au bois.'),
('ac',5,31,'crampon1923','Dieu l''a élevé par sa droite comme Prince et Sauveur, pour donner à Israël le repentir et le pardon des péchés.'),
('ac',5,32,'crampon1923','Et nous sommes ses témoins pour ces choses, avec le Saint-Esprit que Dieu a donné à ceux qui lui sont dociles. "'),
('ac',5,33,'crampon1923','Exaspérés de ce qu''ils venaient d''entendre, les membres du conseil étaient d''avis de les faire mourir.'),
('ac',5,34,'crampon1923','Mais un Pharisien, nommé Gamaliel, docteur de la loi, vénéré de tout le peuple, se leva dans le sanhédrin, et, ayant ordonné de faire sortir un instant les Apôtres,'),
('ac',5,35,'crampon1923','il dit: " Enfants d''Israël, prenez garde à ce que vous allez faire à l''égard de ces hommes.'),
('ac',5,36,'crampon1923','Car il n''y a pas longtemps parut Théodas, qui se donnait pour un personnage; environ quatre cents hommes s''attachèrent à lui: il fut tué, et tous ceux qui l''avaient suivi furent dispersés et réduits à néant.'),
('ac',5,37,'crampon1923','Après lui s''éleva Judas le Galiléen, à l''époque du recensement, et il attira du monde à son parti: il périt aussi, et tous ses partisans ont été dispersés.'),
('ac',5,38,'crampon1923','Voici maintenant le conseil que je vous donne: Ne vous occupez plus de ces gens-là, et laissez-les aller. Si cette idée ou cette œuvre vient des hommes, elle se détruira d''elle-même;'),
('ac',5,39,'crampon1923','mais si elle vient de Dieu, vous ne sauriez la détruire. Ne courez pas le risque d''avoir lutté contre Dieu même. "'),
('ac',5,40,'crampon1923','Ils se rendirent à son avis, et ayant rappelé les Apôtres, ils les firent battre de verges; puis ils leur défendirent de parler au nom de Jésus, et les relâchèrent.'),
('ac',5,41,'crampon1923','Les Apôtres sortirent du sanhédrin, joyeux d''avoir été jugés dignes de souffrir des opprobres pour le nom de Jésus.'),
('ac',5,42,'crampon1923','Et chaque jour, dans le temple et dans les maisons, ils ne cessaient d''annoncer Jésus comme le Christ.'),
('ac',6,1,'crampon1923','En ces jours-là, le nombre des disciples augmentant, les Hellénistes élevèrent des plaintes contre les Hébreux, parce que leurs veuves étaient négligées dans l''assistance de chaque jour.'),
('ac',6,2,'crampon1923','Alors les Douze ayant assemblé la multitude des disciples, leur dirent: " Il ne convient pas que nous laissions la parole de Dieu pour servir aux tables.'),
('ac',6,3,'crampon1923','Choisissez donc parmi vous, frères, sept hommes d''un bon témoignage, remplis de l''Esprit-Saint et de sagesse, à qui nous puissions confier cet office;'),
('ac',6,4,'crampon1923','et nous, nous serons tout entiers à la prière et au ministère de la parole. "'),
('ac',6,5,'crampon1923','Ce discours plut à toute l''assemblée, et ils élurent Etienne, homme plein de foi et du Saint-Esprit, Philippe, Prochore, Nicanor, Timon, Parménas et Nicolas, prosélyte d''Antioche.'),
('ac',6,6,'crampon1923','On les présenta aux apôtres, et ceux-ci, après avoir prié, leur imposèrent les mains.'),
('ac',6,7,'crampon1923','La parole de Dieu se répandait de plus en plus; le nombre des disciples s''augmentait considérablement à Jérusalem, et une multitude de prêtres obéissaient à la foi.'),
('ac',6,8,'crampon1923','Etienne, plein de grâce et de force, faisait des prodiges et de grands miracles parmi le peuple.'),
('ac',6,9,'crampon1923','Quelques membres de la synagogue dite des Affranchis, et de celle des Cyrénéens et des Alexandrins, avec des Juifs de Cilicie et d''Asie, vinrent disputer avec lui;'),
('ac',6,10,'crampon1923','mais ils ne purent résister à la sagesse et à l''Esprit avec lesquels il parlait.'),
('ac',6,11,'crampon1923','Alors ils subornèrent des gens qui dirent: " Nous l''avons entendu proférer des paroles blasphématoires contre Moïse et contre Dieu. "'),
('ac',6,12,'crampon1923','Ils ameutèrent ainsi le peuple, les Anciens et les scribes, et tous ensemble se jetant sur lui, ils le saisirent et l''entraînèrent au Sanhédrin.'),
('ac',6,13,'crampon1923','Et ils produisirent de faux témoins, qui dirent: " Cet homme ne cesse de proférer des paroles contre le lieu saint et contre la Loi.'),
('ac',6,14,'crampon1923','Car nous l''avons entendu dire que Jésus, ce Nazaréen, détruira ce lieu et changera les institutions que Moïse nous a données. "'),
('ac',6,15,'crampon1923','Comme tous ceux qui siégeaient dans le conseil avaient les yeux fixés sur Etienne, son visage leur parut comme celui d''un ange.'),
('ac',7,1,'crampon1923','Le grand prêtre lui demanda: " En est-il bien ainsi? "'),
('ac',7,2,'crampon1923','Etienne répondit: " Mes frères et mes pères, écoutez. Le Dieu de gloire apparut à notre père Abraham, lorsqu''il était en Mésopotamie, avant qu''il vint demeurer à Haran,'),
('ac',7,3,'crampon1923','et lui dit: " Quitte ton pays et ta famille, et va dans le pays que je te montrerai. "'),
('ac',7,4,'crampon1923','Alors il quitta le pays des Chaldéens et s''établit à Haran. De là, après la mort de son père, Dieu le fit émigrer dans ce pays que vous habitez maintenant.'),
('ac',7,5,'crampon1923','Et il ne lui donna aucune propriété dans ce pays, pas même où poser le pied; mais il lui promit, à une époque où le patriarche n''avait pas d''enfants, de lui en donner la possession, à lui et à sa postérité après lui.'),
('ac',7,6,'crampon1923','Dieu parla ainsi: " Sa postérité habitera en pays étranger; on la réduira en servitude, et on la maltraitera pendant quatre cents ans.'),
('ac',7,7,'crampon1923','Mais la nation qui les aura tenus en esclavage, c''est moi qui la jugerai, dit le Seigneur. Après quoi ils sortiront et me serviront en ce lieu. " —'),
('ac',7,8,'crampon1923','Puis il donna à Abraham l''alliance de la circoncision; et ainsi Abraham après avoir engendré Isaac le circoncit le huitième jour; Isaac engendra et circoncit Jacob, et Jacob les douze patriarches.'),
('ac',7,9,'crampon1923','Poussés par la jalousie, les patriarches vendirent Joseph pour être emmené en Egypte. Mais Dieu était avec lui,'),
('ac',7,10,'crampon1923','et il le délivra de toutes ses épreuves, et lui donna grâce et sagesse devant Pharaon, roi d''Egypte, qui le mit à la tête de l''Egypte et de toute sa maison.'),
('ac',7,11,'crampon1923','Or il survint une famine dans tout le pays d''Egypte et dans celui de Chanaan. La détresse était grande, et nos pères ne trouvaient pas de quoi se nourrir.'),
('ac',7,12,'crampon1923','Jacob, ayant appris qu''il y avait des vivres en Egypte, y envoya nos pères une première fois.'),
('ac',7,13,'crampon1923','Et la seconde fois, Joseph fut reconnu par ses frères, et Pharaon sut quelle était son origine.'),
('ac',7,14,'crampon1923','Alors Joseph envoya chercher son père Jacob et toute sa famille, composée de soixante-quinze personnes.'),
('ac',7,15,'crampon1923','Et Jacob descendit en Egypte, où il mourut, ainsi que nos pères.'),
('ac',7,16,'crampon1923','Et ils furent transportés à Sichem, et déposés dans le sépulcre qu''Abraham avait acheté à prix d''argent des fils d''Hémor, à Sichem.'),
('ac',7,17,'crampon1923','Comme le temps approchait où devait s''accomplir la promesse que Dieu avait jurée à Abraham, le peuple s''accrut et se multiplia en Egypte,'),
('ac',7,18,'crampon1923','jusqu''à ce que parut dans ce pays un autre roi qui n''avait pas connu Joseph.'),
('ac',7,19,'crampon1923','Ce roi, usant d''artifice envers notre race, maltraita nos pères, au point de leur faire exposer leurs enfants, afin qu''ils ne vécussent pas.'),
('ac',7,20,'crampon1923','A cette époque naquit Moïse, qui était beau aux yeux de Dieu; il fut nourri trois mois dans la maison de son père.'),
('ac',7,21,'crampon1923','Et quand il eut été exposé, la fille de Pharaon le recueillit et l''éleva comme son fils.'),
('ac',7,22,'crampon1923','Moïse fut instruit dans toute la sagesse des Egyptiens, et il était puissant en paroles et en œuvres.'),
('ac',7,23,'crampon1923','Quand il eut atteint l''âge de quarante ans, il lui vint dans l''esprit de visiter ses frères, les enfants d''Israël.'),
('ac',7,24,'crampon1923','Il en vit un qu''on outrageait; prenant sa défense, il vengea l''opprimé en tuant l''Egyptien.'),
('ac',7,25,'crampon1923','Or il pensait que ses frères comprendraient que Dieu leur accordait la délivrance par sa main; mais ils ne le comprirent pas.'),
('ac',7,26,'crampon1923','Le jour suivant, en ayant rencontré deux qui se battaient, il les exhorta à la paix en disant: " Hommes, vous êtes frères: pourquoi vous maltraiter l''un l''autre? "'),
('ac',7,27,'crampon1923','Mais celui qui maltraitait son prochain le repoussa, en disant: " Qui t''a établi chef et juge sur nous?'),
('ac',7,28,'crampon1923','Veux-tu me tuer, comme tu as tué hier l''Egyptien? "'),
('ac',7,29,'crampon1923','A cette parole, Moïse s''enfuit et alla habiter dans la terre de Madian, où il engendra deux fils.'),
('ac',7,30,'crampon1923','Quarante ans après, au désert du mont Sinaï, un ange lui apparut dans la flamme d''un buisson en feu.'),
('ac',7,31,'crampon1923','A cette vue, Moïse fut saisi d''étonnement, et comme il s''approchait pour examiner, la voix du Seigneur se fit entendre [à lui]:'),
('ac',7,32,'crampon1923','" Je suis le Dieu de tes pères, le Dieu d''Abraham, d''Isaac et de Jacob. " — Et Moïse tout tremblant n''osait regarder.'),
('ac',7,33,'crampon1923','Alors le seigneur lui dit: " Ote la chaussure de tes pieds, car le lieu que tu foules est une terre sainte.'),
('ac',7,34,'crampon1923','J''ai vu l''affliction de mon peuple qui est en Egypte, j''ai entendu ses gémissements, et je suis descendu pour le délivrer. Viens donc maintenant et je t''enverrai en Egypte. " —'),
('ac',7,35,'crampon1923','Ce Moïse qu''ils avaient renié en disant: Qui t''a établi chef et juge? c''est lui que Dieu a envoyé comme chef et libérateur, avec l''assistance de l''ange qui lui était apparu dans le buisson.'),
('ac',7,36,'crampon1923','C''est lui qui les a fait sortir, en opérant des prodiges et des miracles dans la terre d''Egypte, dans la mer Rouge et au désert pendant quarante ans.'),
('ac',7,37,'crampon1923','C''est ce Moïse qui dit aux enfants d''Israël: " Dieu vous suscitera d''entre vos frères un prophète comme moi [: écoutez-le]. "'),
('ac',7,38,'crampon1923','C''est lui qui, au milieu de l''assemblée, au désert, conférant avec l''ange qui lui parlait sur le mont Sinaï, et avec nos pères, a reçu des oracles vivants pour nous les transmettre.'),
('ac',7,39,'crampon1923','Nos pères, loin de vouloir lui obéir, le repoussèrent, et, retournant de cœur en Egypte,'),
('ac',7,40,'crampon1923','ils dirent à Aaron: " Fais-nous des dieux qui marchent devant nous; car ce Moïse qui nous a fait sortir du pays d''Egypte, nous ne savons ce qu''il est devenu. "'),
('ac',7,41,'crampon1923','Ils fabriquèrent alors un veau d''or, et ils offrirent un sacrifice à l''idole et se réjouirent de l''œuvre de leurs mains.'),
('ac',7,42,'crampon1923','Mais Dieu se détourna et les livra au culte de l''armée du ciel, selon qu''il est écrit au livre des prophètes: " M''avez-vous offert des victimes et des sacrifices pendant quarante ans au désert, maison d''Israël...?'),
('ac',7,43,'crampon1923','Vous avez porté la tente de Moloch et l''astre de votre dieu Raiphan, ces images que vous avez faites pour les adorer! C''est pourquoi je vous transporterai au delà de Babylone. " —'),
('ac',7,44,'crampon1923','Nos pères dans le désert avaient le tabernacle du témoignage, comme l''avait ordonné celui qui dit à Moïse de le construire selon le modèle qu''il avait vu.'),
('ac',7,45,'crampon1923','L''ayant reçu de Moïse, nos pères l''apportèrent, sous la conduite de Josué, lorsqu''ils firent la conquête du pays sur les nations que Dieu chassa devant eux, et il y subsista jusqu''aux jours de David.'),
('ac',7,46,'crampon1923','Ce roi trouva grâce devant Dieu, et demanda d''élever une demeure pour le Dieu de Jacob.'),
('ac',7,47,'crampon1923','Néanmoins ce fut Salomon qui lui bâtit un temple.'),
('ac',7,48,'crampon1923','Mais le Très-Haut n''habite pas dans les temples faits de main d''homme, selon la parole du prophète:'),
('ac',7,49,'crampon1923','" Le ciel est mon trône, et la terre l''escabeau de mes pieds. Quelle demeure me bâtirez-vous, dit le Seigneur, ou quel sera le lieu de mon repos?'),
('ac',7,50,'crampon1923','N''est-ce pas ma main qui a fait toutes ces choses? " —'),
('ac',7,51,'crampon1923','Hommes à la tête dure, incirconcis de cœur et d''oreilles, vous résistez toujours au Saint-Esprit; tels furent vos pères, tels vous êtes.'),
('ac',7,52,'crampon1923','Quel prophète vos pères n''ont-ils pas persécuté? Ils ont même tué ceux qui annonçaient d''avance la venue du Juste; et vous, aujourd''hui, vous l''avez trahi et mis à mort.'),
('ac',7,53,'crampon1923','Vous qui avez reçu la Loi, en considération des anges qui vous l''intimaient, et vous ne l''avez pas gardée!... "'),
('ac',7,54,'crampon1923','En entendant ces paroles, la rage déchirait leurs cœurs, et ils grinçaient des dents contre lui.'),
('ac',7,55,'crampon1923','Mais Etienne, qui était rempli de l''Esprit-Saint, ayant fixé les yeux au ciel, vit la gloire de Dieu, et Jésus debout à la droite de son Père.'),
('ac',7,56,'crampon1923','Et il dit: " Voici que je vois les cieux ouverts, et le Fils de l''homme debout à la droite de Dieu. "'),
('ac',7,57,'crampon1923','Les Juifs poussèrent alors de grands cris, en se bouchant les oreilles, et se jetèrent tous ensemble sur lui.'),
('ac',7,58,'crampon1923','Et l''ayant entraîné hors de la ville, ils le lapidèrent. Les témoins déposèrent leurs vêtements aux pieds d''un jeune homme nommé Saul.'),
('ac',7,59,'crampon1923','Pendant qu''ils le lapidaient, Etienne priait en disant: " Seigneur Jésus, recevez mon esprit! "'),
('ac',7,60,'crampon1923','Puis s''étant mis à genoux, il s''écria d''une voix forte: " Seigneur, ne leur imputez pas ce péché. " Après cette parole, il s''endormit [dans le Seigneur]. Or, Saul avait approuvé le meurtre d''Etienne.'),
('ac',8,1,'crampon1923','Le même jour, une violente persécution éclata contre l''Eglise de Jérusalem; et tous, sauf les apôtres se dispersèrent dans les campagnes de la Judée et de la Samarie.'),
('ac',8,2,'crampon1923','Des hommes pieux ensevelirent Etienne et firent sur lui de grandes lamentations.'),
('ac',8,3,'crampon1923','Et Saul ravageait l''Eglise; pénétrant dans les maisons, il en arrachait les hommes et les femmes, et les faisait jeter en prison.'),
('ac',8,4,'crampon1923','Ceux qui étaient dispersés parcouraient le pays annonçant la parole.'),
('ac',8,5,'crampon1923','Philippe étant descendu dans une ville de Samarie, y prêcha le Christ.'),
('ac',8,6,'crampon1923','Et les foules étaient attentives à ce que disait Philippe, en apprenant et en voyant les miracles qu''il faisait.'),
('ac',8,7,'crampon1923','Car les esprits impurs sortaient de beaucoup de démoniaques, en poussant de grands cris; beaucoup de paralytiques et de boiteux furent aussi guéris,'),
('ac',8,8,'crampon1923','et ce fut une grande joie dans cette ville.'),
('ac',8,9,'crampon1923','Or, il s''y trouvait déjà un homme nommé Simon, qui pratiquait la magie, et qui émerveillait le peuple de la Samarie, se donnant pour un grand personnage.'),
('ac',8,10,'crampon1923','Tous, petits et grands, s''étaient attachés à lui. Cet homme, disaient-ils, est la Vertu de Dieu, celle qu''on appelle la Grande.'),
('ac',8,11,'crampon1923','Ils s''étaient donc attachés à lui, parce que, depuis longtemps, il les avait séduits par ses enchantements.'),
('ac',8,12,'crampon1923','Mais quand ils eurent cru à Philippe, qui leur annonçait le royaume de Dieu et le nom de Jésus-Christ, hommes et femmes se firent baptiser.'),
('ac',8,13,'crampon1923','Simon lui-même crut, et, s''étant fait baptiser, il s''attacha à Philippe, et les miracles et les grands prodiges dont il était témoin le frappaient d''étonnement.'),
('ac',8,14,'crampon1923','Les Apôtres, qui étaient à Jérusalem, ayant appris que la Samarie avait reçu la parole de Dieu, y envoyèrent Pierre et Jean.'),
('ac',8,15,'crampon1923','Ceux-ci arrivés chez les Samaritains, prièrent pour eux, afin qu''ils reçussent le Saint-Esprit.'),
('ac',8,16,'crampon1923','Car il n''était encore descendu sur aucun d''eux; ils avaient seulement été baptisés au nom du Seigneur Jésus.'),
('ac',8,17,'crampon1923','Alors Pierre et Jean leur imposèrent les mains, et ils reçurent le Saint-Esprit.'),
('ac',8,18,'crampon1923','Lorsque Simon vit que le Saint-Esprit était donné par l''imposition des mains des Apôtres, il leur offrit de l''argent,'),
('ac',8,19,'crampon1923','en disant: " Donnez-moi aussi ce pouvoir, afin que tout homme à qui j''imposerai les mains reçoive le Saint-Esprit. "'),
('ac',8,20,'crampon1923','Mais Pierre lui dit: " Périsse ton argent avec toi, puisque tu as cru que le don de Dieu s''acquérait à prix d''argent!'),
('ac',8,21,'crampon1923','Il n''y a pour toi absolument aucune part dans cette faveur, car ton cœur n''est pas pur devant Dieu.'),
('ac',8,22,'crampon1923','Repens-toi donc de ton iniquité, et prie le Seigneur de te pardonner, s''il est possible, la pensée de ton cœur.'),
('ac',8,23,'crampon1923','Car je vois que tu es dans un fiel amer et dans les liens du péché. "'),
('ac',8,24,'crampon1923','Simon répondit: " Priez vous-mêmes le Seigneur pour moi, afin qu''il ne m''arrive rien de ce que vous avez dit. "'),
('ac',8,25,'crampon1923','Quant à eux, après avoir rendu témoignage et prêché la parole du Seigneur, ils retournèrent à Jérusalem, en annonçant la bonne nouvelle dans plusieurs villages des Samaritains.'),
('ac',8,26,'crampon1923','Un ange du Seigneur, s''adressant à Philippe, lui dit: " Lève-toi, et va du côté du midi, sur la route qui descend de Jérusalem à Gaza; celle qui est déserte. "'),
('ac',8,27,'crampon1923','Il se leva et partit. Et voici qu''un Ethiopien, un eunuque, ministre de Candace, reine d''Ethiopie, et surintendant de tous ses trésors, était venu à Jérusalem pour adorer.'),
('ac',8,28,'crampon1923','Il s''en retournait, et, assis sur un char, il lisait le prophète Isaïe.'),
('ac',8,29,'crampon1923','L''Esprit dit à Philippe: " Avance, et tiens-toi près de ce char. "'),
('ac',8,30,'crampon1923','Philippe accourut, et entendant l''Ethiopien lire le prophète Isaïe, il lui dit: " Comprends-tu bien ce que tu lis? "'),
('ac',8,31,'crampon1923','Celui-ci répondit: " Comment le pourrais-je, si quelqu''un ne me guide? " Et il pria Philippe de monter et de s''asseoir avec lui.'),
('ac',8,32,'crampon1923','Or le passage de l''Ecriture qu''il lisait était celui-ci: " Comme une brebis, il a été mené à la boucherie, et, comme un agneau muet devant celui qui le tond, il n''a pas ouvert la bouche.'),
('ac',8,33,'crampon1923','C''est dans son humiliation que son jugement s''est consommé. Quant à sa génération, qui la racontera? Car sa vie a été retranchée de la terre. "'),
('ac',8,34,'crampon1923','L''eunuque dit à Philippe: " Je t''en prie, de qui le prophète parle-t-il ainsi? Est-ce de lui-même ou de quelque autre? "'),
('ac',8,35,'crampon1923','Alors Philippe ouvrant la bouche, et commençant par ce passage, lui annonça Jésus.'),
('ac',8,36,'crampon1923','Chemin faisant, ils rencontrèrent de l''eau, et l''eunuque dit: " Voici de l''eau: qu''est-ce qui empêche que je ne sois baptisé? "'),
('ac',8,37,'crampon1923','[Philippe répondit: " Si tu crois de tout ton cœur, cela est possible. — Je crois, repartit l''eunuque, que Jésus Christ est le Fils de Dieu. "]'),
('ac',8,38,'crampon1923','Il fit donc arrêter son char, et Philippe, étant descendu avec lui dans l''eau, le baptisa.'),
('ac',8,39,'crampon1923','Quand ils furent sortis de l''eau, l''Esprit du Seigneur enleva Philippe, et l''eunuque ne le vit plus, et il continua tout joyeux son chemin.'),
('ac',8,40,'crampon1923','Quant à Philippe, il se trouva dans Azot, d''où il alla jusqu''à Césarée, en évangélisant toutes les villes par où il passait.'),
('ac',9,1,'crampon1923','Cependant Saul, respirant encore la menace et la mort contre les disciples du Seigneur, alla trouver le grand prêtre'),
('ac',9,2,'crampon1923','et lui demanda des lettres pour les synagogues de Damas, afin que, s''il trouvait des gens de cette croyance, hommes ou femmes, il les amenât enchaînés à Jérusalem.'),
('ac',9,3,'crampon1923','Comme il était en chemin et qu''il approchait de Damas, tout à coup une lumière venant du ciel resplendit autour de lui.'),
('ac',9,4,'crampon1923','Il tomba par terre, et entendit une voix qui lui disait: " Saul, Saul, pourquoi me persécutes-tu? "'),
('ac',9,5,'crampon1923','Il répondit: " Qui êtes-vous, Seigneur? " Et le Seigneur dit: " Je suis Jésus que tu persécutes. [Il n''est pas bon pour toi de regimber contre l''aiguillon. "'),
('ac',9,6,'crampon1923','Tremblant et saisi d''effroi, il dit: " Seigneur, que voulez-vous que je fasse? " Le Seigneur lui répondit:] " Lève-toi et entre dans la ville; là on te dira ce que tu dois faire. "'),
('ac',9,7,'crampon1923','Les hommes qui l''accompagnaient demeurèrent saisis de stupeur, car ils percevaient le son de la voix, mais ne voyaient personne.'),
('ac',9,8,'crampon1923','Saul se releva de terre, et bien que ses yeux fussent ouverts, il ne voyait rien; on le prit par la main et on le conduisit à Damas;'),
('ac',9,9,'crampon1923','et il y fut trois jours sans voir, et sans prendre ni nourriture ni boisson.'),
('ac',9,10,'crampon1923','Or il y avait à Damas un disciple nommé Ananie. Le Seigneur lui dit dans une vision: " Ananie! " Il répondit: " Me voici, Seigneur. "'),
('ac',9,11,'crampon1923','Et le Seigneur lui dit: " Lève-toi, va dans la rue qu''on appelle la Droite, et cherche dans la maison de Judas un nommé Saul, de Tarse; car il est en prière. "'),
('ac',9,12,'crampon1923','(Et il a vu en vision un homme nommé Ananie, qui entrait et lui imposait les mains afin qu''il recouvrât la vue.)'),
('ac',9,13,'crampon1923','Ananie répondit: " Seigneur, j''ai appris de plusieurs tout le mal que cet homme a fait à vos saints dans Jérusalem.'),
('ac',9,14,'crampon1923','Et il a ici, des princes des prêtres, plein pouvoir pour charger de chaînes tous ceux qui invoquent votre nom. "'),
('ac',9,15,'crampon1923','Mais le Seigneur lui dit: " Va, car cet homme est un instrument que j''ai choisi, pour porter mon nom devant les nations, devant les rois et devant les enfants d''Israël;'),
('ac',9,16,'crampon1923','et je lui montrerai tout ce qu''il doit souffrir pour mon nom. "'),
('ac',9,17,'crampon1923','Ananie s''en alla, et arrivé dans la maison, il imposa les mains à Saul, en disant: " Saul, mon frère, le Seigneur Jésus qui t''a apparu sur le chemin par lequel tu venais, m''a envoyé pour que tu recouvres la vue et que tu sois rempli du Saint-Esprit. "'),
('ac',9,18,'crampon1923','Au même instant, il tomba des yeux de Saul comme des écailles, et il recouvra la vue. Il se leva et fut baptisé;'),
('ac',9,19,'crampon1923','et après qu''il eut pris de la nourriture, ses forces lui revinrent. Saul passa quelques jours avec les disciples qui étaient à Damas,'),
('ac',9,20,'crampon1923','et aussitôt il se mit à prêcher dans les synagogues que Jésus est le Fils de Dieu.'),
('ac',9,21,'crampon1923','Tous ceux qui l''entendaient étaient dans l''étonnement et disaient: " N''est-ce pas lui qui persécutait à Jérusalem ceux qui invoquent ce nom, et n''est-il pas venu ici pour les conduire chargés de chaînes aux princes des prêtres? "'),
('ac',9,22,'crampon1923','Cependant Saul sentait redoubler son courage, et il confondait les Juifs de Damas, leur démontrant que Jésus est le Christ.'),
('ac',9,23,'crampon1923','Après un temps assez considérable, les Juifs formèrent le dessein de le tuer,'),
('ac',9,24,'crampon1923','mais leur complot parvint à la connaissance de Saul. On gardait les portes jour et nuit, afin de le mettre à mort.'),
('ac',9,25,'crampon1923','Mais les disciples le prirent pendant la nuit et le descendirent par la muraille, dans une corbeille.'),
('ac',9,26,'crampon1923','Il se rendit à Jérusalem, et il cherchait à se mettre en rapport avec les disciples; mais tous le craignaient, ne pouvant croire qu''il fût disciple de Jésus.'),
('ac',9,27,'crampon1923','Alors Barnabé, l''ayant pris avec lui, le mena aux Apôtres, et leur raconta comment sur le chemin Saul avait vu le Seigneur, qui lui avait parlé, et avec quel courage il avait, à Damas, prêché le nom de Jésus.'),
('ac',9,28,'crampon1923','Dès lors Saul allait et venait avec eux dans Jérusalem, et parlait avec assurance au nom du Seigneur.'),
('ac',9,29,'crampon1923','Il s''adressait aussi aux Hellénistes et disputait avec eux; mais ceux-ci cherchaient à le mettre à mort.'),
('ac',9,30,'crampon1923','Les frères, l''ayant su, l''emmenèrent à Césarée, d''où ils le firent partir pour Tarse.'),
('ac',9,31,'crampon1923','L''Eglise était en paix dans toute la Judée, la Galilée et la Samarie, se développant et progressant dans la crainte du Seigneur, et elle se multipliait par l''assistance du Saint-Esprit.'),
('ac',9,32,'crampon1923','Or il arriva que Pierre, visitant les saints de ville en ville, descendit vers ceux qui demeuraient à Lydda.'),
('ac',9,33,'crampon1923','Il y trouva un homme appelé Enée, couché sur un lit depuis huit ans: c''était un paralytique.'),
('ac',9,34,'crampon1923','Pierre lui dit: " Enée, Jésus-Christ te guérit; lève-toi, et fais toi-même ton lit. " Et aussitôt il se leva.'),
('ac',9,35,'crampon1923','Tous les habitants de Lydda et de Saron le virent, et ils se convertirent au Seigneur.'),
('ac',9,36,'crampon1923','Il y avait à Joppé, parmi les disciples, une femme nommée Tabitha, en grec Dorcas: elle était riche en bonnes œuvres et faisait beaucoup d''aumônes.'),
('ac',9,37,'crampon1923','Elle tomba malade en ce temps-là, et mourut. Après l''avoir lavée, on la déposa dans une chambre haute.'),
('ac',9,38,'crampon1923','Comme Lydda est près de Joppé, les disciples ayant appris que Pierre s''y trouvait, envoyèrent deux hommes vers lui pour lui adresser cette prière: " Ne tarde pas de venir jusque chez nous. "'),
('ac',9,39,'crampon1923','Pierre se leva et partit avec eux. Dès qu''il fut arrivé, on le conduisit dans la chambre haute, et toutes les veuves l''entourèrent en pleurant, et en lui montrant les tuniques et les vêtements que faisait Dorcas pendant qu''elle était avec elles.'),
('ac',9,40,'crampon1923','Pierre fit sortir tout le monde, se mit à genoux et pria; puis, se tournant vers le cadavre, il dit: " Tabitha, lève-toi! " Elle ouvrit les yeux, et ayant vu Pierre, elle se mit sur son séant.'),
('ac',9,41,'crampon1923','Pierre lui tendit la main et l''aida à se lever. Et ayant appelé les saints et les veuves, il la leur présenta vivante.'),
('ac',9,42,'crampon1923','Ce prodige fut connu dans toute la ville de Joppé, et un grand nombre crurent au Seigneur.'),
('ac',9,43,'crampon1923','Pierre demeura quelque temps à Joppé, chez un corroyeur nommé Simon.'),
('ac',10,1,'crampon1923','Il y avait à Césarée un homme nommé Corneille, centurion dans la cohorte Italique,'),
('ac',10,2,'crampon1923','Religieux et craignant Dieu, ainsi que toute sa maison, il faisait beaucoup d''aumônes au peuple et priait Dieu sans cesse.'),
('ac',10,3,'crampon1923','Dans une vision, vers la neuvième heure du jour, il vit clairement un ange de Dieu qui entra chez lui et lui dit: " Corneille! "'),
('ac',10,4,'crampon1923','Fixant les yeux sur l''ange et saisi d''effroi, il s''écria: " Qu''est-ce, Seigneur? " L''ange lui répondit: " Tes prières et tes aumônes sont montées devant Dieu comme un mémorial.'),
('ac',10,5,'crampon1923','Et maintenant envoie des hommes à Joppé, et fais venir un certain Simon, surnommé Pierre;'),
('ac',10,6,'crampon1923','il est logé chez un corroyeur, appelé Simon, dont la maison est située auprès de la mer. "'),
('ac',10,7,'crampon1923','L''ange qui lui parlait étant parti, Corneille appela deux de ses serviteurs et un soldat pieux parmi ceux qui étaient attachés à sa personne,'),
('ac',10,8,'crampon1923','et après leur avoir tout raconté, il les envoya à Joppé.'),
('ac',10,9,'crampon1923','Le jour suivant, comme les messagers étaient en route et qu''ils s''approchaient de la ville, Pierre monta sur le toit, vers la sixième heure, pour prier.'),
('ac',10,10,'crampon1923','Puis, ayant faim, il désirait manger. Pendant qu''on lui préparait son repas, il tomba en extase:'),
('ac',10,11,'crampon1923','il vit le ciel ouvert, et quelque chose en descendre, comme une grande nappe, attachée par les quatre coins et s''abaissant vers la terre;'),
('ac',10,12,'crampon1923','à l''intérieur se trouvaient tous les quadrupèdes et les reptiles de la terre, et les oiseaux du ciel.'),
('ac',10,13,'crampon1923','Et une voix lui dit: " Lèvre-toi, Pierre; tue et mange. "'),
('ac',10,14,'crampon1923','Pierre répondit: " Oh! non, Seigneur, car jamais je n''ai rien mangé de profane ni d''impur. "'),
('ac',10,15,'crampon1923','Et une voix lui parla de nouveau: " Ce que Dieu a déclaré pur, ne l''appelle pas profane. "'),
('ac',10,16,'crampon1923','Cela se fit par trois fois, et aussitôt après la nappe fut retirée dans le ciel.'),
('ac',10,17,'crampon1923','Or Pierre cherchait en lui-même ce que pouvait signifier la vision qu''il avait eue, et voici que les hommes envoyés par Corneille, s''étant informés de la maison de Simon, se présentèrent à la porte;'),
('ac',10,18,'crampon1923','et ayant appelé, ils demandèrent si c''était là qu''était logé Simon, surnommé Pierre.'),
('ac',10,19,'crampon1923','Et comme Pierre était à réfléchir sur la vision, l''Esprit lui dit: " Voici trois hommes qui te cherchent.'),
('ac',10,20,'crampon1923','Lève-toi, descends et pars avec eux sans crainte, car c''est moi qui les ai envoyés. "'),
('ac',10,21,'crampon1923','Aussitôt Pierre descendit vers eux: " Je suis, leur dit-il, celui que vous cherchez, quel est le motif qui vous amène? "'),
('ac',10,22,'crampon1923','Ils répondirent: " Le centurion Corneille, homme juste et craignant Dieu, à qui toute la nation juive rend témoignage, a été averti par un ange saint de te faire venir dans sa maison et d''écouter tes paroles. "'),
('ac',10,23,'crampon1923','Pierre les fit donc entrer et les logea. Le lendemain, s''étant levé, il partit avec eux, et quelques-uns des frères de Joppé l''accompagnèrent.'),
('ac',10,24,'crampon1923','Ils entrèrent à Césarée le jour suivant. Corneille les attendait, et il avait invité ses parents et ses amis intimes.'),
('ac',10,25,'crampon1923','Quand Pierre entra, Corneille alla au-devant de lui, et tombant à ses pieds il se prosterna.'),
('ac',10,26,'crampon1923','Mais Pierre le releva en disant: " Lève-toi; moi aussi je suis un homme. "'),
('ac',10,27,'crampon1923','Et tout en s''entretenant avec lui, il entra et trouva beaucoup de personnes réunies.'),
('ac',10,28,'crampon1923','Il leur dit: " Vous savez qu''il est défendu à un Juif de se lier avec un étranger ou d''entrer chez lui; mais Dieu m''a appris à ne regarder aucun homme comme souillé ou impur.'),
('ac',10,29,'crampon1923','Aussi suis-je venu sans hésitation, dès que vous m''avez envoyé chercher. Je vous prie donc de me dire pour quel motif vous m''avez fait venir. "'),
('ac',10,30,'crampon1923','Corneille répondit: " Il y a en ce moment quatre jours que je jeûnais et priais dans ma maison à la neuvième heure; tout à coup parut devant moi un homme revêtu d''une robe éclatante, qui me dit:'),
('ac',10,31,'crampon1923','" Corneille, ta prière a été exaucée, et Dieu s''est souvenu de tes aumônes.'),
('ac',10,32,'crampon1923','Envoie donc à Joppé, et fais appeler Simon, surnommé Pierre; il est logé dans la maison de Simon, corroyeur, près de la mer; [il viendra te parler]. " —'),
('ac',10,33,'crampon1923','Aussitôt j''ai envoyé vers toi, et tu as bien fait de venir. Maintenant nous sommes tous réunis devant Dieu pour entendre tout ce que Dieu t''a commandé de nous dire. "'),
('ac',10,34,'crampon1923','Alors Pierre, ouvrant la bouche, parla ainsi: " En vérité, je reconnais que Dieu ne fait point acception de personnes,'),
('ac',10,35,'crampon1923','mais qu''en toute nation celui qui le craint et pratique la justice lui est agréable.'),
('ac',10,36,'crampon1923','Il a envoyé la parole aux enfants d''Israël, en annonçant la paix par Jésus-Christ: c''est lui qui est le Seigneur de tous.'),
('ac',10,37,'crampon1923','Vous savez ce qui s''est passée dans toute la Judée, en commençant par la Galilée, après le baptême que Jean a prêché:'),
('ac',10,38,'crampon1923','comment Dieu a oint de l''Esprit-Saint et de force Jésus de Nazareth, qui allait de lieu en lieu, faisant du bien et guérissant tous ceux qui étaient sous l''empire du diable; car Dieu était avec lui.'),
('ac',10,39,'crampon1923','Pour nous, nous sommes témoins de tout ce qu''il a fait dans les campagnes de la Judée et à Jérusalem. Ensuite ils l''ont fait mourir, en le pendant au bois.'),
('ac',10,40,'crampon1923','Mais Dieu l''a ressuscité le troisième jour, et lui a donné de se faire voir,'),
('ac',10,41,'crampon1923','non à tout le peuple, mais aux témoins choisis d''avance par Dieu, à nous qui avons mangé et bu avec lui, après sa résurrection d''entre les morts.'),
('ac',10,42,'crampon1923','Et il nous a commandé de prêcher au peuple et d''attester que c''est lui que Dieu a établi juge des vivants et des morts.'),
('ac',10,43,'crampon1923','Tous les prophètes rendent de lui ce témoignage, que tout homme qui croit en lui reçoit par son nom la rémission de ses péchés. "'),
('ac',10,44,'crampon1923','Pierre parlait encore, lorsque le Saint-Esprit descendit sur tous ceux qui écoutaient la parole.'),
('ac',10,45,'crampon1923','Les fidèles venus de la circoncision qui accompagnaient Pierre étaient tout hors d''eux-mêmes en voyant que le don du Saint-Esprit était répandu même sur les Gentils.'),
('ac',10,46,'crampon1923','Car ils entendaient ceux-ci parler des langues et glorifier Dieu. Alors Pierre dit:'),
('ac',10,47,'crampon1923','" Peut-on refuser l''eau du baptême à ces hommes qui ont reçu le Saint-Esprit aussi bien que nous? "'),
('ac',10,48,'crampon1923','Et il commanda de les baptiser au nom du Seigneur Jésus-Christ. Après quoi ils le prièrent de rester quelques jours.'),
('ac',10,49,'crampon1923',''),
('ac',11,1,'crampon1923','Les apôtres et les frères qui étaient dans la Judée apprirent que les Gentils avaient aussi reçu la parole de Dieu.'),
('ac',11,2,'crampon1923','Et lorsque Pierre fut remonté à Jérusalem, les fidèles de la circoncision lui adressèrent des reproches,'),
('ac',11,3,'crampon1923','en disant: " Tu es entré chez des incirconcis, et tu as mangé avec eux! "'),
('ac',11,4,'crampon1923','Pierre, prenant la parole, se mit à leur exposer, d''une manière suivie, ce qui s''était passé.'),
('ac',11,5,'crampon1923','" J''étais en prière, dit-il, dans la ville de Joppé, et j''eus, en extase, une vision: un objet semblable à une grande nappe, tenue par les quatre coins, descendait du ciel et venait jusqu''à moi.'),
('ac',11,6,'crampon1923','Fixant les yeux sur cette nappe, je la considérai, et j''y vis les quadrupèdes de la terre, les bêtes sauvages, les reptiles et les oiseaux du ciel.'),
('ac',11,7,'crampon1923','J''entendis aussi une voix qui me disait: " Lève-toi, Pierre; tue et mange. —'),
('ac',11,8,'crampon1923','Je répondis: " Oh non, Seigneur, car jamais rien de profane et d''impur n''est entré dans ma bouche. —'),
('ac',11,9,'crampon1923','Pour la seconde fois une voix se fit entendre du ciel: Ce que Dieu a déclaré pur, ne l''appelle pas profane. —'),
('ac',11,10,'crampon1923','Cela arriva par trois fois; puis tout fut retiré dans le ciel.'),
('ac',11,11,'crampon1923','Au même instant trois hommes se présentèrent devant la maison où nous étions; on les avait envoyés de Césarée vers moi.'),
('ac',11,12,'crampon1923','L''Esprit me dit de partir avec eux sans hésiter. Les six frères que voici m''accompagnèrent, et nous entrâmes dans la maison de Corneille.'),
('ac',11,13,'crampon1923','Cet homme nous raconta comment il avait vu dans sa maison l''ange se présenter à lui, en disant: Envoie à Joppé, et fais venir Simon, surnommé Pierre;'),
('ac',11,14,'crampon1923','il te dira des paroles par lesquelles tu seras sauvé, toi et toute ta maison. —'),
('ac',11,15,'crampon1923','Lorsque j''eus commencé à leur parler, l''Esprit-Saint descendit sur eux, comme sur nous au commencement.'),
('ac',11,16,'crampon1923','Et je me souvins de cette parole du Seigneur: Jean a baptisé dans l''eau; mais vous, vous serez baptisés dans l''Esprit-Saint. —'),
('ac',11,17,'crampon1923','Si donc Dieu leur a donné la même grâce qu''à nous, qui avons cru au Seigneur Jésus-Christ, qui étais-je, moi, pour pouvoir m''opposer à Dieu! "'),
('ac',11,18,'crampon1923','Ayant entendu ce discours, ils se calmèrent, et ils glorifièrent Dieu en disant: " Dieu a donc accordé aussi aux Gentils la pénitence, afin qu''ils aient la vie. "'),
('ac',11,19,'crampon1923','Cependant ceux qui avaient été dispersés par la persécution survenue à l''occasion d''Etienne, allèrent jusqu''en Phénicie, dans l''île de Chypre et à Antioche, n''annonçant la parole à personne si ce n''est aux seuls Juifs.'),
('ac',11,20,'crampon1923','Il y eut cependant parmi eux quelques hommes de Chypre et de Cyrène qui, étant venus à Antioche, s''adressèrent aussi aux Grecs, et leur annoncèrent le Seigneur Jésus.'),
('ac',11,21,'crampon1923','Et la main du Seigneur était avec eux, et un grand nombre de personnes crurent et se convertirent au Seigneur.'),
('ac',11,22,'crampon1923','Le bruit en étant venu aux oreilles des fidèles de l''Eglise de Jérusalem, ils envoyèrent Barnabé jusqu''à Antioche.'),
('ac',11,23,'crampon1923','Lorsqu''il fut arrivé et qu''il eut vu la grâce de Dieu, il s''en réjouit, et il les exhorta tous à demeurer d''un cœur ferme dans le Seigneur.'),
('ac',11,24,'crampon1923','Car c''était un homme de bien rempli de l''Esprit-Saint, et de foi. Et une foule assez considérable se joignit au Seigneur.'),
('ac',11,25,'crampon1923','Barnabé se rendit ensuite à Tarse pour chercher Saul, et l''ayant trouvé, il l''amena à Antioche.'),
('ac',11,26,'crampon1923','Or, il advint que, pendant une année entière, ils tinrent des réunions dans cette église et instruisirent une multitude nombreuse. Ce fut ainsi à Antioche que, pour la première fois, les disciples reçurent le nom de Chrétiens.'),
('ac',11,27,'crampon1923','En ces jours-là, des prophètes vinrent de Jérusalem à Antioche.'),
('ac',11,28,'crampon1923','L''un d''eux, nommé Agabus, s''étant levé, annonça par l''Esprit qu''il y aurait sur toute la terre une grande famine; elle eut lieu, en effet, sous Claude.'),
('ac',11,29,'crampon1923','Les disciples décidèrent d''envoyer, chacun selon ses moyens, un secours aux frères qui habitaient la Judée:'),
('ac',11,30,'crampon1923','ce qu''ils firent. Ce secours fut envoyé aux Anciens par les mains de Barnabé et de Saul.'),
('ac',12,1,'crampon1923','Vers ce temps-là, le roi Hérode fit arrêter quelques membres de l''Eglise pour les maltraiter;'),
('ac',12,2,'crampon1923','il fit mourir par le glaive Jacques, frère de Jean.'),
('ac',12,3,'crampon1923','Voyant que cela était agréable aux Juifs, il ordonna encore l''arrestation de Pierre: c''était pendant les jours des Azymes.'),
('ac',12,4,'crampon1923','Lorsqu''il l''eut en son pouvoir, il le jeta en prison, et le mit sous la garde de quatre escouades de quatre soldats chacune, avec l''intention de le faire comparaître devant le peuple après la Pâque.'),
('ac',12,5,'crampon1923','Pendant que Pierre était ainsi gardé dans la prison, l''Eglise ne cessait d''adresser pour lui des prières à Dieu.'),
('ac',12,6,'crampon1923','Or, la nuit même du jour où Hérode devait le faire comparaître, Pierre, lié de deux chaînes, dormait entre deux soldats, et des sentinelles devant la porte gardaient la prison.'),
('ac',12,7,'crampon1923','Tout à coup survint un ange du Seigneur, et une lumière resplendit dans la prison. L''ange, frappant Pierre au côté, le réveilla en disant: " Lève-toi promptement "; et les chaînes tombèrent de ses mains.'),
('ac',12,8,'crampon1923','L''ange lui dit: " Mets ta ceinture et tes sandales. " Il le fit, et l''ange ajouta: " Enveloppe-toi de ton manteau et suis-moi. "'),
('ac',12,9,'crampon1923','Pierre sortit et le suivit, ne sachant pas que ce qui se faisait par l''ange fût réel; il croyait avoir une vision.'),
('ac',12,10,'crampon1923','Lorsqu''ils eurent passé la première garde, puis la seconde, ils arrivèrent à la porte de fer qui donne sur la ville: elle s''ouvrit d''elle-même devant eux; ils sortirent et s''engagèrent dans une rue, et aussitôt l''ange le quitta.'),
('ac',12,11,'crampon1923','Alors revenu à lui-même, Pierre se dit: " Je vois maintenant que le Seigneur a réellement envoyé son ange et qu''il m''a délivré de la main d''Hérode et de tout ce qu''attendait le peuple Juif. "'),
('ac',12,12,'crampon1923','Après un moment de réflexion, il se dirigea vers la maison de Marie, la mère de Jean, surnommé Marc, où une nombreuse assemblée était en prière.'),
('ac',12,13,'crampon1923','Il frappa à la porte du vestibule et une servante, nommée Rhodé, s''approcha pour écouter.'),
('ac',12,14,'crampon1923','Dès qu''elle eut reconnu la voix de Pierre, dans sa joie, au lieu d''ouvrir, elle courut à l''intérieur annoncer que Pierre était devant la porte.'),
('ac',12,15,'crampon1923','Ils lui dirent: " Tu es folle. " Mais elle affirma qu''il en était ainsi; et ils dirent: " C''est son ange. "'),
('ac',12,16,'crampon1923','Cependant Pierre continuait à frapper; et lorsqu''ils lui eurent ouvert, en le voyant, ils furent saisis de stupeur.'),
('ac',12,17,'crampon1923','Mais Pierre, leur ayant fait de la main signe de se taire, leur raconta comment le Seigneur l''avait tiré de la prison, et il ajouta: " Allez porter cette nouvelle à Jacques et aux frères. " Puis il sortit et s''en alla dans un autre lieu.'),
('ac',12,18,'crampon1923','Quand il fit jour, il y eut une grande agitation parmi les soldats, pour savoir ce que Pierre était devenu.'),
('ac',12,19,'crampon1923','Hérode le fit chercher, et ne l''ayant pas découvert, il procéda à l''interrogatoire des gardes et les fit conduire au supplice. Ensuite il quitta la Judée pour retourner à Césarée, où il séjourna.'),
('ac',12,20,'crampon1923','Hérode était en hostilité avec les Tyriens et les Sidoniens; ceux-ci vinrent ensemble le trouver, et ayant gagné Blastus, son chambellan, ils lui demandèrent la paix, parce que leur pays tirait sa subsistance des terres du roi.'),
('ac',12,21,'crampon1923','Au jour fixé, Hérode, revêtu d''habits royaux, et assis sur son trône, les haranguait;'),
('ac',12,22,'crampon1923','et le peuple s''écria: " C''est la voix d''un Dieu, et non d''un homme! "'),
('ac',12,23,'crampon1923','Au même instant, un ange du Seigneur le frappa, parce qu''il n''avait pas rendu gloire à Dieu. Et il expira, rongé des vers.'),
('ac',12,24,'crampon1923','Cependant la parole de Dieu se répandait de plus en plus, et enfantait de nouveaux disciples.'),
('ac',12,25,'crampon1923','Barnabé et Saul, après s''être acquittés de leur ministère, s''en retournèrent de Jérusalem, emmenant avec eux Jean, surnommé Marc.'),
('ac',13,1,'crampon1923','Il y avait dans l''Eglise d''Antioche des prophètes et des docteurs, savoir, Barnabé, Siméon, appelé Niger, Lucius de Cyrène, Manahen, qui avait été élevé avec Hérode le tétrarque, et Saul.'),
('ac',13,2,'crampon1923','Comme ils vaquaient au service du Seigneur et qu''ils jeûnaient, l''Esprit-Saint leur dit: " Séparez-moi Saul et Barnabé pour l''œuvre à laquelle je les ai appelés. "'),
('ac',13,3,'crampon1923','Alors, après avoir jeûné et prié, ils leur imposèrent les mains et les laissèrent partir.'),
('ac',13,4,'crampon1923','Envoyés donc par le Saint-Esprit, Saul et Barnabé se rendirent à Séleucie, d''où ils firent voile pour l''île de Chypre.'),
('ac',13,5,'crampon1923','Arrivés à Salamine, ils annoncèrent la parole de Dieu dans les synagogues des Juifs. Ils avaient avec eux Jean pour les aider dans leur ministère.'),
('ac',13,6,'crampon1923','Ayant parcouru toute l''île jusqu''à Paphos, ils trouvèrent un certain magicien, faux prophète juif, nommé Barjésus,'),
('ac',13,7,'crampon1923','qui vivait auprès du proconsul Sergius Paulus, homme sage. Ce dernier, ayant fait appeler Barnabé et Saul, manifesta le désir d''entendre la parole de Dieu.'),
('ac',13,8,'crampon1923','Mais Elymas, le magicien — car telle est la signification de son nom — leur faisait opposition, cherchant à détourner de la foi le proconsul.'),
('ac',13,9,'crampon1923','Alors Saul, appelé aussi Paul, rempli du Saint-Esprit, fixant son regard sur le magicien,'),
('ac',13,10,'crampon1923','lui dit: " Homme plein de toute sorte de ruses et de fourberies, fils du diable, ennemi de toute justice, ne cesseras-tu pas de pervertir les voies droite du Seigneur?'),
('ac',13,11,'crampon1923','Maintenant voici que la main de Dieu est sur toi; tu seras aveugle, privé pour un temps de la vue du soleil. " Aussitôt d''épaisses ténèbres tombèrent sur lui, et il cherchait, en se tournant de tous côtés, quelqu''un qui lui donnât la main.'),
('ac',13,12,'crampon1923','A la vue de ce prodige, le proconsul crut, vivement frappé de la doctrine du Seigneur.'),
('ac',13,13,'crampon1923','Paul et ses compagnons, ayant fait voile de Paphos, se rendirent à Perge en Pamphylie; mais Jean les quitta et s''en retourna à Jérusalem.'),
('ac',13,14,'crampon1923','Eux, poussant au delà de Perge, se rendirent à Antioche de Pisidie, et étant entrés dans la synagogue le jour du sabbat, ils s''assirent.'),
('ac',13,15,'crampon1923','Après la lecture de la Loi et des Prophètes, les chefs de la synagogue leur envoyèrent dire: " Frères, si vous avez quelque exhortation à adresser au peuple, parlez. "'),
('ac',13,16,'crampon1923','Paul se leva, et, ayant fait signe de la main, il dit: " Enfants d''Israël, et vous qui craignez Dieu, écoutez.'),
('ac',13,17,'crampon1923','Le Dieu de ce peuple d''Israël a choisi nos pères. Il glorifia ce peuple pendant son séjour en Egypte, et l''en fit sortir par son bras puissant.'),
('ac',13,18,'crampon1923','Durant près de quarante ans, il en prit soin dans le désert.'),
('ac',13,19,'crampon1923','Puis, ayant détruit sept nations au pays de Chanaan, il le mit en possession de leur territoire.'),
('ac',13,20,'crampon1923','Après cela, durant quatre cent cinquante ans environ, il lui donna des juges jusqu''au prophète Samuel.'),
('ac',13,21,'crampon1923','Alors ils demandèrent un roi; et Dieu leur donna, pendant quarante ans, Saül, fils de Cis, de la tribu de Benjamin.'),
('ac',13,22,'crampon1923','Puis, l''ayant rejeté, il leur suscita pour roi David, auquel il a rendu ce témoignage: J''ai trouvé David, fils de Jessé, homme selon mon cœur, qui accomplira toutes mes volontés. —'),
('ac',13,23,'crampon1923','C''est de sa postérité que Dieu, selon sa promesse, a fait sortir pour Israël un Sauveur, Jésus.'),
('ac',13,24,'crampon1923','Avant sa venue, Jean avait prêché un baptême de pénitence à tout le peuple d''Israël;'),
('ac',13,25,'crampon1923','et arrivé au terme de sa course, il disait: Je ne suis pas celui que vous pensez; mais voici qu''après moi vient celui dont je ne suis pas digne de délier la chaussure.'),
('ac',13,26,'crampon1923','Mes frères, fils de la race d''Abraham, et vous qui craignez Dieu, c''est à vous que cette parole de salut a été envoyée.'),
('ac',13,27,'crampon1923','Car les habitants de Jérusalem et leurs magistrats ayant méconnu Jésus et les oracles des prophètes qui se lisent chaque sabbat, les ont accompli par leur jugement,'),
('ac',13,28,'crampon1923','et sans avoir rien trouvé en lui qui méritât la mort, ils ont demandé à Pilate de le faire mourir.'),
('ac',13,29,'crampon1923','Et quand ils eurent accompli tout ce qui est écrit de lui, ils le descendirent de la croix et le déposèrent dans un sépulcre.'),
('ac',13,30,'crampon1923','Mais Dieu l''a ressuscité des morts; et pendant plusieurs jours de suite il s''est montré à ceux'),
('ac',13,31,'crampon1923','qui étaient montés avec lui de la Galilée à Jérusalem, et qui sont maintenant ses témoins auprès du peuple.'),
('ac',13,32,'crampon1923','Nous aussi, nous vous annonçons que la promesse faite à nos pères,'),
('ac',13,33,'crampon1923','Dieu l''a accomplie pour nous, leurs enfants, en ressuscitant Jésus, selon ce qui est écrit dans le Psaume deuxième: Tu es mon Fils, je t''ai engendré aujourd''hui.'),
('ac',13,34,'crampon1923','Que Dieu l''ait ressuscité des morts de telle sorte qu''il ne retournera pas à la corruption, c''est ce qu''il a déclaré en disant: Je vous donnerai les faveurs divines promises à David, faveurs qui sont assurées.'),
('ac',13,35,'crampon1923','— C''est pourquoi il dit encore ailleurs: Tu ne permettras pas que ton Saint voie la corruption. —'),
('ac',13,36,'crampon1923','Or David, après avoir, pendant qu''il vivait, accompli les desseins de Dieu, s''est endormi, et il a été réuni à ses pères, et il a vu la corruption.'),
('ac',13,37,'crampon1923','Mais celui que Dieu a ressuscité n''a pas vu la corruption.'),
('ac',13,38,'crampon1923','Sachez-le donc, mes frères: c''est par lui que le pardon des péchés vous est annoncé; et de toutes les souillures, dont vous n''avez pu être justifiés par la loi de Moïse,'),
('ac',13,39,'crampon1923','quiconque croit en est justifié par lui.'),
('ac',13,40,'crampon1923','Prenez donc garde qu''il ne vous arrive ce qui est dit dans les Prophètes:'),
('ac',13,41,'crampon1923','" Voyez, hommes dédaigneux, soyez étonnés et disparaissez; car je vais faire en vos jours une œuvre, une œuvre que vous ne croiriez pas si on vous la racontait. "'),
('ac',13,42,'crampon1923','Lorsqu''ils sortirent, on les pria de parler sur le même sujet au sabbat suivant.'),
('ac',13,43,'crampon1923','Et à l''issue de l''assemblée, beaucoup de Juifs et de pieux prosélytes suivirent Paul et Barnabé, et ceux-ci, s''entretenant avec eux, les exhortèrent à persévérer dans la grâce de Dieu.'),
('ac',13,44,'crampon1923','Le sabbat suivant, la ville presque toute entière se rassembla pour entendre la parole de Dieu.'),
('ac',13,45,'crampon1923','Les Juifs, voyant tout ce concours, furent remplis de jalousie, et, en blasphémant, ils contredirent tout ce que disait Paul.'),
('ac',13,46,'crampon1923','Alors Paul et Barnabé dirent avec assurance: " C''est à vous les premiers que la parole de Dieu devait être annoncée; mais, puisque vous la repoussez, et que vous-mêmes vous vous jugez indignes de la vie éternelle, voici que nous nous tournons vers les Gentils.'),
('ac',13,47,'crampon1923','Car le Seigneur nous l''a ainsi ordonné: Je t''ai établi pour être la lumière des nations, pour porter le salut jusqu''aux extrémités de la terre. "'),
('ac',13,48,'crampon1923','En entendant ces paroles, les Gentils se réjouirent, et ils glorifiaient la parole du Seigneur; et tous ceux qui étaient destinés à la vie éternelle devinrent croyants.'),
('ac',13,49,'crampon1923','Et la parole du Seigneur se répandait dans tout le pays.'),
('ac',13,50,'crampon1923','Mais les Juifs, ayant excité les femmes prosélytes de la classe élevée et les principaux de la ville, soulevèrent une persécution contre Paul et Barnabé, et les chassèrent de leur territoire.'),
('ac',13,51,'crampon1923','Alors Paul et Barnabé secouèrent contre eux la poussière de leurs pieds et allèrent à Iconium.'),
('ac',13,52,'crampon1923','Cependant les disciples étaient remplis de joie et de l''Esprit-Saint.'),
('ac',14,1,'crampon1923','A Iconium, Paul et Barnabé entrèrent de même dans la synagogue des Juifs, et y parlèrent de telle sorte qu''une grande multitude de Juifs et de Grecs embrassèrent la foi.'),
('ac',14,2,'crampon1923','Mais les Juifs restés incrédules excitèrent et aigrirent l''esprit des Gentils contre leurs frères.'),
('ac',14,3,'crampon1923','Ils firent néanmoins un assez long séjour, parlant avec assurance, appuyés par le Seigneur, qui rendait témoignage à la parole de sa grâce, par les prodiges et les miracles qu''il leur donnait de faire.'),
('ac',14,4,'crampon1923','Toute la ville se divisa; les uns étaient pour les Juifs, les autres pour les Apôtres.'),
('ac',14,5,'crampon1923','Mais comme les Gentils et les Juifs, avec leurs chefs, se mettaient en mouvement pour les outrager et les lapider,'),
('ac',14,6,'crampon1923','les Apôtres, l''ayant su, se réfugièrent dans les villes de Lycaonie, Lystres et Derbé, et le pays d''alentour, et ils y annoncèrent la bonne nouvelle.'),
('ac',14,7,'crampon1923','Il y avait à Lystres un homme perclus des jambes, qui se tenait assis, car il était boiteux de naissance et n''avait jamais marché.'),
('ac',14,8,'crampon1923','Il écoutait Paul parler; et Paul, ayant arrêté les yeux sur lui et voyant qu''il avait la foi pour être guéri,'),
('ac',14,9,'crampon1923','dit d''une voix forte: " Lève-toi droit sur tes pieds. " Aussitôt il bondit et il marchait.'),
('ac',14,10,'crampon1923','A la vue de ce que Paul venait de faire, la foule éleva la voix et dit en lycaonien: " Les dieux sous une forme humaine sont descendus vers nous. "'),
('ac',14,11,'crampon1923','Et ils appelaient Barnabé Jupiter, et Paul Mercure, parce que c''était lui qui portait la parole.'),
('ac',14,12,'crampon1923','De plus, le prêtre du temple de Jupiter, qui était à l''entrée de la ville, amena devant les portes des taureaux avec des bandelettes, et voulait, ainsi que la foule, offrir un sacrifice.'),
('ac',14,13,'crampon1923','Les Apôtres Paul et Barnabé, l''ayant appris, déchirèrent leurs vêtements et se précipitèrent au milieu de la foule;'),
('ac',14,14,'crampon1923','et, d''une voix retentissante, ils disaient: " O hommes, pourquoi faites-vous cela? Nous aussi, nous sommes des hommes sujets aux mêmes faiblesses que vous; nous vous annonçons qu''il faut quitter ces vanités pour vous tourner vers le Dieu vivant, qui a fait le ciel et la terre, la mer, et tout ce qu''ils renferment.'),
('ac',14,15,'crampon1923','Ce Dieu, dans les siècles passés, a laissé toutes les nations suivre leurs voies,'),
('ac',14,16,'crampon1923','sans que toutefois il ait cessé de se rendre témoignage à lui-même, faisant du bien, dispensant du ciel les pluies et les saisons favorables, nous donnant la nourriture avec abondance et remplissant nos cœurs de joie. "'),
('ac',14,17,'crampon1923','Malgré ces paroles, ils ne parvinrent qu''avec peine à empêcher le peuple de leur offrir un sacrifice.'),
('ac',14,18,'crampon1923','Alors survinrent d''Antioche et d''Iconium des Juifs qui, ayant gagné le peuple, lapidèrent Paul et le traînèrent hors de la ville, le croyant mort.'),
('ac',14,19,'crampon1923','Mais les disciples l''ayant entouré, il se releva et rentra dans la ville. Le lendemain, il partit pour Derbé avec Barnabé.'),
('ac',14,20,'crampon1923','Quand ils eurent évangélisé cette ville et fait un assez grand nombre de disciples, ils retournèrent à Lystres, à Iconium et à Antioche,'),
('ac',14,21,'crampon1923','fortifiant l''esprit des disciples, les exhortant à persévérer dans la foi, et disant que c''est par beaucoup de tribulations qu''il nous faut entrer dans le royaume de Dieu.'),
('ac',14,22,'crampon1923','Ils instituèrent des Anciens dans chaque Eglise, après avoir prié et jeûné, et les recommandèrent au Seigneur, en qui ils avaient cru.'),
('ac',14,23,'crampon1923','Traversant ensuite la Pisidie, ils vinrent en Pamphylie,'),
('ac',14,24,'crampon1923','et après avoir annoncé la parole de Dieu à Perge, ils descendirent à Attalie.'),
('ac',14,25,'crampon1923','De là ils firent voile pour Antioche, d''où ils étaient partis, après avoir été recommandés à la grâce de Dieu, pour l''œuvre qu''ils venaient d''accomplir.'),
('ac',14,26,'crampon1923','Dès qu''ils furent arrivés, ils assemblèrent l''Eglise, et racontèrent tout ce que Dieu avait fait pour eux, et comment il avait ouvert aux nations la porte de la foi.'),
('ac',14,27,'crampon1923','Et ils demeurèrent à Antioche assez longtemps avec les disciples.'),
('ac',14,28,'crampon1923',''),
('ac',15,1,'crampon1923','Or quelques gens, venus de Judée, enseignaient aux frères cette doctrine: " Si vous n''êtes pas circoncis selon la loi de Moïse, vous ne pouvez pas être sauvés. "'),
('ac',15,2,'crampon1923','Paul et Barnabé ayant donc eu avec eux une contestation et une vive discussion, il fut décidé que Paul et Barnabé, avec quelques autres des leurs, monteraient à Jérusalem vers les Apôtres et les Anciens pour traiter cette question.'),
('ac',15,3,'crampon1923','Après avoir été accompagnés par l''Église, ils poursuivirent leur route à travers la Phénicie et la Samarie, racontant la conversion des Gentils, ce qui causa une grande joie à tous les frères.'),
('ac',15,4,'crampon1923','Arrivés à Jérusalem, ils furent reçus par l''Eglise, les Apôtres et les Anciens, et ils racontèrent tout ce que Dieu avait fait pour eux.'),
('ac',15,5,'crampon1923','Alors quelques-uns du parti des Pharisiens, qui avaient cru, se levèrent, en disant qu''il fallait circoncire les Gentils et leur enjoindre d''observer la loi de Moïse.'),
('ac',15,6,'crampon1923','Les Apôtres et les Anciens s''assemblèrent pour examiner cette affaire.'),
('ac',15,7,'crampon1923','Une longue discussion s''étant engagée, Pierre se leva et leur dit: " Mes frères, vous savez que Dieu, il y a longtemps déjà, m''a choisi parmi vous, afin que, par ma bouche, les Gentils entendent la parole de l''Evangile et qu''ils croient.'),
('ac',15,8,'crampon1923','Et Dieu, qui connaît les cœurs, a témoigné en leur faveur, en leur donnant le Saint-Esprit comme à nous;'),
('ac',15,9,'crampon1923','il n''a fait aucune différence entre eux et nous, ayant purifié leurs cœurs par la foi.'),
('ac',15,10,'crampon1923','Pourquoi donc tentez-vous Dieu maintenant, en imposant aux disciples un joug que ni nos pères ni nous n''avons pu porter?'),
('ac',15,11,'crampon1923','Mais c''est par la grâce du Seigneur Jésus-Christ que nous croyons être sauvés, de la même manière qu''eux. "'),
('ac',15,12,'crampon1923','Toute l''assemblée garda le silence, et l''on écouta Barnabé et Paul, qui racontèrent tous les miracles et les prodiges que Dieu avait faits par eux au milieu des Gentils.'),
('ac',15,13,'crampon1923','Lorsqu''ils eurent cessé de parler, Jacques prit la parole et dit: " Frères, écoutez-moi.'),
('ac',15,14,'crampon1923','Simon a raconté comment Dieu tout d''abord a pris soin de tirer du milieu des Gentils un peuple qui portât son nom.'),
('ac',15,15,'crampon1923','Avec ce dessein concordent les paroles des prophètes, selon qu''il est écrit:'),
('ac',15,16,'crampon1923','Après cela je reviendrai, et je rebâtirai la tente de David qui est renversée par terre; j''en réparerai les ruines et la relèverai,'),
('ac',15,17,'crampon1923','afin que le reste des hommes cherche le Seigneur, ainsi que toutes les nations qui sont appelées de mon nom, dit le Seigneur, qui exécute ces choses.'),
('ac',15,18,'crampon1923','L''œuvre du Seigneur est connue de toute éternité. —'),
('ac',15,19,'crampon1923','C''est pourquoi je suis d''avis qu''il ne faut pas inquiéter ceux d''entre les Gentils qui se convertissent à Dieu.'),
('ac',15,20,'crampon1923','Qu''on leur écrive seulement qu''ils ont à s''abstenir des souillures des idoles, de l''impureté, des viandes étouffées et du sang.'),
('ac',15,21,'crampon1923','Car, depuis bien des générations, Moïse a dans chaque ville des hommes qui le prêchent, puisqu''on le lit tous les jours de sabbat dans les synagogues. "'),
('ac',15,22,'crampon1923','Alors il parut bon aux Apôtres et aux Anciens, ainsi qu''à toute l''Eglise, de choisir quelques-uns d''entre eux pour les envoyer à Antioche avec Paul et Barnabé; on choisit Jude, surnommé Barsabas, et Silas, personnages éminents parmi les frères.'),
('ac',15,23,'crampon1923','Ils les chargèrent d''une lettre ainsi conçue: " Les Apôtres, les Anciens et les frères, aux frères d''entre les Gentils qui sont à Antioche, en Syrie et en Cilicie, salut!'),
('ac',15,24,'crampon1923','Ayant appris que quelques-uns des nôtres sont venus, sans aucun mandat de notre part, vous troubler par des discours qui ont bouleversé vos âmes,'),
('ac',15,25,'crampon1923','nous nous sommes assemblés et nous avons jugé à propos de choisir des délégués et de vous les envoyer avec nos bien-aimés Barnabé et Paul,'),
('ac',15,26,'crampon1923','ces hommes qui ont exposé leur vie pour le nom de notre Seigneur Jésus-Christ.'),
('ac',15,27,'crampon1923','Nous avons donc député Jude et Silas, qui vous diront de vive voix les mêmes choses.'),
('ac',15,28,'crampon1923','Il a semblé bon au Saint-Esprit et à nous de ne vous imposer aucun fardeau au-delà de ce qui est indispensable, savoir,'),
('ac',15,29,'crampon1923','de vous abstenir des viandes offertes aux idoles, du sang, de la chair étouffée et de l''impureté. En vous gardant de ces choses, vous ferez bien. Adieu. "'),
('ac',15,30,'crampon1923','Ayant donc pris congé, les députés se rendirent à Antioche, assemblèrent tous les fidèles et leurs remirent la lettre.'),
('ac',15,31,'crampon1923','On en fit lecture et tous furent heureux de la consolation qu''elle renfermait.'),
('ac',15,32,'crampon1923','Jude et Silas, qui étaient eux-mêmes prophètes, adressèrent plusieurs fois la parole aux frères, pour les exhorter et les affermir.'),
('ac',15,33,'crampon1923','Après un séjour de quelque temps, ils furent congédiés par les frères, avec des souhait de paix vers ceux qui les avaient envoyés.'),
('ac',15,34,'crampon1923','Toutefois, Silas trouva bon de rester, et Jude s''en alla seul à Jérusalem.'),
('ac',15,35,'crampon1923','Paul et Barnabé demeurèrent à Antioche, enseignant et annonçant avec plusieurs autres la parole du Seigneur.'),
('ac',15,36,'crampon1923','Au bout de quelques jours, Paul dit à Barnabé: " Retournons visiter les frères dans les différentes villes où nous avons annoncé la parole du Seigneur, pour voir dans quel état ils se trouvent. "'),
('ac',15,37,'crampon1923','Barnabé voulait emmener aussi Jean, surnommé Marc;'),
('ac',15,38,'crampon1923','mais Paul jugeait bon de ne pas prendre pour compagnon un homme qui les avait quittés depuis la Pamphylie, et qui n''avait pas été à l''œuvre avec eux.'),
('ac',15,39,'crampon1923','Ce dissentiment fut tel qu''ils se séparèrent l''un de l''autre; et Barnabé, prenant Marc, s''embarqua avec lui pour Chypre.'),
('ac',15,40,'crampon1923','Paul fit choix de Silas, et partit, recommandé par les frères à la grâce de Dieu.'),
('ac',15,41,'crampon1923','Il parcourut la Syrie et la Cilicie, fortifiant les Eglises.'),
('ac',16,1,'crampon1923','Paul se rendit ensuite à Derbé, puis à Lystres. Il y avait là un disciple nommé Timothée, fils d''une juive chrétienne et d''un père grec.'),
('ac',16,2,'crampon1923','Ses frères de Lystres et d''Iconium rendaient de lui un bon témoignage.'),
('ac',16,3,'crampon1923','Paul voulut l''emmener avec lui, et l''ayant pris, il le circoncit, à cause des Juifs qui étaient dans ces contrées; car tous savaient que son père était grec.'),
('ac',16,4,'crampon1923','En passant par les villes, ils enseignaient aux fidèles à observer les décisions des Apôtres et des Anciens de Jérusalem.'),
('ac',16,5,'crampon1923','Et les Eglises se fortifiaient dans la foi et croissaient de jour en jour.'),
('ac',16,6,'crampon1923','Lorsqu''ils eurent parcouru la Phrygie et le pays de Galatie, l''Esprit-Saint les ayant empêchés d''annoncer la parole dans l''Asie,'),
('ac',16,7,'crampon1923','ils arrivèrent aux confins de la Mysie, et ils se disposaient à entrer en Bithynie; mais l''Esprit de Jésus ne le leur permit pas.'),
('ac',16,8,'crampon1923','Alors, ayant traversé rapidement la Mysie, ils descendirent à Troas.'),
('ac',16,9,'crampon1923','Pendant la nuit, Paul eut une vision: un Macédonien se présenta devant lui, et lui fit cette prière: " Passe en Macédoine et viens à notre secours! "')
